def load_state_extension_bundle():
    global STATE_EXTENSION_BUNDLE
    if STATE_EXTENSION_BUNDLE is not None:
        return STATE_EXTENSION_BUNDLE
    if STATE_EXTENSION_BUNDLE_PATH is None:
        STATE_EXTENSION_BUNDLE = load_module_from_embedded_source(
            "charity_state_extension_bundle",
            EMBEDDED_STATE_EXTENSION_BUNDLE_B64,
        )
        return STATE_EXTENSION_BUNDLE
    if not STATE_EXTENSION_BUNDLE_PATH.exists():
        raise RuntimeError(f"State extension bundle not found: {STATE_EXTENSION_BUNDLE_PATH}")
    spec = importlib.util.spec_from_file_location("charity_state_extension_bundle", STATE_EXTENSION_BUNDLE_PATH)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Unable to load state extension bundle from {STATE_EXTENSION_BUNDLE_PATH}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    STATE_EXTENSION_BUNDLE = module
    return module


def state_extension_module(state: str):
    state = (state or "").upper()
    if state in STATE_EXTENSION_MODULES:
        return STATE_EXTENSION_MODULES[state]
    bundle = load_state_extension_bundle()
    module = bundle.load_module(state)
    STATE_EXTENSION_MODULES[state] = module
    return module


def load_module_from_path(module_name: str, module_path: Path):
    if not module_path.exists():
        raise RuntimeError(f"{module_name} module not found: {module_path}")
    spec = importlib.util.spec_from_file_location(module_name, module_path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Unable to load {module_name} from {module_path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def load_module_from_embedded_source(module_name: str, encoded_source: str):
    if not encoded_source or encoded_source.startswith("__EMBEDDED_"):
        raise RuntimeError(f"{module_name} embedded source is not available")
    source = gzip.decompress(base64.b64decode("".join(encoded_source.split()))).decode("utf-8-sig")
    module = ModuleType(module_name)
    module.__dict__["__file__"] = f"<embedded:{module_name}.py>"
    module.__dict__["__package__"] = ""
    sys.modules[module_name] = module
    exec(compile(source, module.__dict__["__file__"], "exec"), module.__dict__)
    return module


def load_state_batch_bundle():
    global STATE_BATCH_BUNDLE
    if STATE_BATCH_BUNDLE is None:
        if STATE_BATCH_BUNDLE_PATH is None:
            STATE_BATCH_BUNDLE = load_module_from_embedded_source(
                "charity_state_batch_bundle",
                EMBEDDED_STATE_BATCH_BUNDLE_B64,
            )
        else:
            STATE_BATCH_BUNDLE = load_module_from_path("charity_state_batch_bundle", STATE_BATCH_BUNDLE_PATH)
    return STATE_BATCH_BUNDLE


def state_batch_modules(states: list[str]):
    bundle = load_state_batch_bundle()
    requested = sorted({(state or "").upper() for state in states if state})
    missing = [state for state in requested if state not in STATE_BATCH_LOADED_STATES]
    if missing:
        STATE_BATCH_MODULES.update(bundle.load_modules(missing))
        STATE_BATCH_LOADED_STATES.update(missing)
    return STATE_BATCH_MODULES


