def artifact_safe_name(org_name: str) -> str:
    return re.sub(r"[^A-Za-z0-9]+", "_", org_name).strip("_")[:80] or "registry_snapshot"


def evidence_pdf_path(state: str, org_name: str) -> Path:
    return ARTIFACTS_DIR / state.upper() / f"{artifact_safe_name(org_name)}.pdf"


def evidence_png_path(state: str, org_name: str) -> Path:
    return ARTIFACTS_DIR / state.upper() / f"{artifact_safe_name(org_name)}.png"


def evidence_metadata_path(state: str, org_name: str) -> Path:
    return ARTIFACTS_DIR / state.upper() / f"{artifact_safe_name(org_name)}.evidence.json"


def ak_registration_pdf_path(org_name: str) -> Path:
    return ARTIFACTS_DIR / "AK" / f"{artifact_safe_name(org_name)}_registration.pdf"


def evidence_url(state: str, org_name: str, ein: str = "") -> str:
    url = f"{PUBLIC_BASE_URL}/evidence/{state.upper()}/{artifact_safe_name(org_name)}.pdf"
    query = []
    if ein:
        query.append(f"ein={quote(format_ein(ein), safe='')}")
    if org_name:
        query.append(f"org={quote(org_name, safe='')}")
    return f"{url}?{'&'.join(query)}" if query else url


def configure_browser_context(context) -> None:
    if not BLOCK_HEAVY_BROWSER_RESOURCES:
        return

    def route_handler(route):
        try:
            if route.request.resource_type in {"image", "media", "font"}:
                route.abort()
                return
        except Exception:
            pass
        route.continue_()

    try:
        context.route("**/*", route_handler)
    except Exception:
        pass


def wrap_text(draw: ImageDraw.ImageDraw, text: str, font: ImageFont.ImageFont, max_width: int) -> list[str]:
    words = str(text or "").split()
    if not words:
        return [""]
    lines = []
    current = words[0]
    for word in words[1:]:
        candidate = f"{current} {word}"
        if draw.textlength(candidate, font=font) <= max_width:
            current = candidate
        else:
            lines.append(current)
            current = word
    lines.append(current)
    return lines


def load_font(size: int, bold: bool = False) -> ImageFont.ImageFont:
    candidates = [
        "arialbd.ttf" if bold else "arial.ttf",
        "Calibri.ttf",
    ]
    for candidate in candidates:
        try:
            return ImageFont.truetype(candidate, size)
        except OSError:
            continue
    return ImageFont.load_default()


def evidence_summary_image(result, body: str, status: str, comments: str) -> Image.Image:
    width = 1700
    title_font = load_font(76, bold=True)
    ribbon_font = load_font(42, bold=True)
    section_font = load_font(42, bold=True)
    label_font = load_font(28, bold=True)
    text_font = load_font(34)
    small_font = load_font(27)
    navy = "#0B2A5B"
    red = "#C62828"
    slate = "#334155"
    muted = "#64748B"
    border = "#CBD5E1"
    light = "#F8FAFC"
    pale_blue = "#EEF6FF"

    scratch = Image.new("RGB", (width, 2600), "white")
    draw = ImageDraw.Draw(scratch)

    try:
        context = filing_context(result, body)
    except Exception as exc:
        log_error(f"Could not build filing context for evidence summary: {exc}")
        context = {}
    fiscal_end = context.get("fiscal_end")
    fiscal_end_text = f"{fiscal_end[0]}/{fiscal_end[1]}" if fiscal_end else "Not identified"
    due_date = context.get("due_date")
    base_due = context.get("base_due_date")
    extended_due = context.get("extended_due_date")
    rows = [
        ("Organization", result.organization_name),
        ("EIN", result.ein),
        ("State", result.state),
        ("Interpreted CE Status", status),
        ("CE Comment", comments),
        ("Most Recent Fiscal/Filing Year Read", context.get("represented_year") or "Not identified"),
        ("Fiscal Year End Used", fiscal_end_text),
        ("Base Due Date Used", format_date(base_due or due_date) if (base_due or due_date) else "Not identified"),
        ("Extension Date Scenario", format_date(extended_due) if extended_due else "Not applicable or not identified"),
        ("Raw Registry Status", result.raw_status_text or "Not shown"),
        ("Source Note", result.source_note or "Not provided"),
        ("Source URL", result.source_url),
    ]

    def clamp_lines(lines: list[str], max_lines: int) -> list[str]:
        if len(lines) <= max_lines:
            return lines
        clipped = lines[:max_lines]
        clipped[-1] = clipped[-1].rstrip(" .,:;") + "..."
        return clipped

    wrapped_rows = []
    x_value = 730
    value_width = width - x_value - 130
    for label, value in rows:
        lines = wrap_text(draw, str(value), text_font, value_width)
        max_lines = 10 if label == "CE Comment" else 4 if label in {"Source URL", "Source Note"} else 3
        wrapped_rows.append((label, clamp_lines(lines, max_lines)))

    row_heights = [max(112, 72 + (len(lines) * 46)) for _, lines in wrapped_rows]
    divider_gaps = 20 * max(0, len(row_heights) - 1)
    height = 500 + sum(row_heights) + divider_gaps + 240
    image = Image.new("RGB", (width, height), "white")
    draw = ImageDraw.Draw(image)

    y = 60
    draw.rounded_rectangle((60, y, width - 60, y + 230), radius=34, fill=pale_blue, outline=border, width=3)
    draw.text((105, y + 40), "Compliance", fill=navy, font=title_font)
    draw.text((520, y + 40), "Express", fill=red, font=title_font)
    draw.rounded_rectangle((105, y + 140, 855, y + 215), radius=0, fill=red, outline="#7F1D1D", width=3)
    draw.text((135, y + 158), "INSTANT COMPLIANCE SNAPSHOT", fill="white", font=ribbon_font)
    y += 280

    draw.text((80, y), "Status Basis", fill=navy, font=section_font)
    draw.text((80, y + 54), "Prepared from public registry information available at the time of lookup.", fill=muted, font=small_font)
    draw.line((80, y + 104, width - 80, y + 104), fill=red, width=6)
    y += 150

    card_top = y
    card_height = 74 + sum(row_heights) + divider_gaps
    draw.rounded_rectangle((70, card_top, width - 70, card_top + card_height), radius=28, fill=light, outline=border, width=3)
    y += 38
    for index, ((label, lines), row_height) in enumerate(zip(wrapped_rows, row_heights)):
        if index:
            draw.line((105, y, width - 105, y), fill="#E2E8F0", width=2)
            y += 20
        draw.text((110, y), label.upper(), fill=red, font=label_font)
        value_y = y
        for line in lines:
            draw.text((x_value, value_y), line, fill=slate, font=text_font)
            value_y += 46
        y += row_height

    footer_y = card_top + card_height + 46
    draw.text((90, footer_y), "Supporting Registry View", fill=navy, font=section_font)
    draw.text((90, footer_y + 56), "A source screenshot follows when available. This snapshot is informational and is not legal advice.", fill=slate, font=small_font)
    return image


def screenshot_to_pdf(state: str, org_name: str, result=None, body: str = "", status: str = "", comments: str = "") -> str | None:
    png_path = evidence_png_path(state, org_name)
    pdf_path = evidence_pdf_path(state, org_name)
    if not png_path.exists() and result is None:
        return None

    pdf_path.parent.mkdir(parents=True, exist_ok=True)
    output_buffer = io.BytesIO()
    append_images = []
    if png_path.exists():
        with Image.open(png_path) as image:
            if image.mode in {"RGBA", "P"}:
                image = image.convert("RGB")
            if image.width > 1400:
                ratio = 1400 / image.width
                image = image.resize((1400, max(1, int(image.height * ratio))), Image.Resampling.LANCZOS)
            append_images.append(image.copy())

    if result is not None:
        summary = evidence_summary_image(result, body, status, comments)
        summary.save(output_buffer, "PDF", resolution=144.0, save_all=True, append_images=append_images)
    elif append_images:
        append_images[0].save(output_buffer, "PDF", resolution=144.0, save_all=True, append_images=append_images[1:])
    else:
        return None

    ak_pdf = ak_registration_pdf_path(org_name)
    if state.upper() == "AK" and ak_pdf.exists() and PdfReader is not None and PdfWriter is not None:
        output_buffer.seek(0)
        writer = PdfWriter()
        for source in [output_buffer, ak_pdf]:
            reader = PdfReader(source)
            for page in reader.pages:
                writer.add_page(page)
        with pdf_path.open("wb") as f:
            writer.write(f)
    else:
        pdf_path.write_bytes(output_buffer.getvalue())
    return evidence_url(state, org_name, getattr(result, "ein", "") if result is not None else "")


def write_evidence_metadata(state: str, org_name: str, result_data: dict, body: str, status: str, comments: str) -> None:
    metadata_path = evidence_metadata_path(state, org_name)
    metadata_path.parent.mkdir(parents=True, exist_ok=True)
    safe_result = {
        key: value
        for key, value in result_data.items()
        if value is None or isinstance(value, (str, int, float, bool))
    }
    metadata = {
        "state": state.upper(),
        "org_name": org_name,
        "result": safe_result,
        "body": body,
        "status": status,
        "comments": comments,
        "created_at_epoch": int(time.time()),
    }
    try:
        metadata_path.write_text(json.dumps(metadata), encoding="utf-8")
    except Exception as exc:
        log_error(f"Could not write evidence metadata for {state} / {org_name}: {exc}")


def prepare_evidence_pdf(candidate: Path) -> bool:
    try:
        relative = candidate.relative_to(ARTIFACTS_DIR.resolve())
    except ValueError:
        return False
    if len(relative.parts) < 2:
        return False
    state = relative.parts[0].upper()
    org_name = candidate.stem
    metadata_path = candidate.with_suffix(".evidence.json")
    if not metadata_path.exists():
        return False
    try:
        metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
        result_data = metadata.get("result") or {}
        result = SimpleNamespace(**result_data)
        if not getattr(result, "state", ""):
            result.state = state
        if not getattr(result, "organization_name", ""):
            result.organization_name = metadata.get("org_name") or org_name
        if not getattr(result, "ein", ""):
            result.ein = result_data.get("ein", "")
        if not getattr(result, "source_url", ""):
            result.source_url = result_data.get("source_url", "")
        if (
            ON_DEMAND_EVIDENCE_SCREENSHOT
            and not evidence_png_path(state, org_name).exists()
            and getattr(result, "ein", "")
        ):
            try:
                refreshed = run_state_lookup(
                    getattr(result, "organization_name", "") or metadata.get("org_name") or org_name,
                    getattr(result, "ein", ""),
                    state,
                    capture_source_snapshot=True,
                )
                metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
                result_data = metadata.get("result") or refreshed or result_data
                result = SimpleNamespace(**result_data)
                if not getattr(result, "state", ""):
                    result.state = state
                if not getattr(result, "organization_name", ""):
                    result.organization_name = metadata.get("org_name") or org_name
            except Exception as exc:
                log_error(f"Could not capture on-demand source screenshot for {state} / {org_name}: {exc}")
        screenshot_to_pdf(
            state,
            org_name,
            result,
            metadata.get("body") or "",
            metadata.get("status") or result_data.get("status") or "",
            metadata.get("comments") or result_data.get("comments") or "",
        )
        return candidate.exists()
    except Exception as exc:
        log_error(f"Could not prepare lazy evidence PDF {candidate}: {exc}")
        return False


def focus_md_evidence_view(page) -> None:
    for label in ["Financial Information", "Financial Informati"]:
        try:
            page.get_by_role("button", name=re.compile(label, re.I)).click(timeout=5000)
            time.sleep(1)
            break
        except Exception:
            continue
    for pattern in [
        r"Year\s+Represented",
        r"Most\s+Recent\s+Fiscal\s+Year",
        r"Total\s+Charitable\s+Contributions",
        r"Registration\s+Status",
        r"SOS\s+Charity\s+Organization\s+Record",
    ]:
        try:
            page.get_by_text(re.compile(pattern, re.I)).first.scroll_into_view_if_needed(timeout=5000)
            page.locator("body").evaluate("window.scrollBy(0, -170)")
            time.sleep(1)
            return
        except Exception:
            continue


def save_focused_viewport_artifact(page, state: str, org_name: str) -> None:
    state_dir = ARTIFACTS_DIR / state.upper()
    state_dir.mkdir(parents=True, exist_ok=True)
    safe_name = artifact_safe_name(org_name)
    try:
        (state_dir / f"{safe_name}.html").write_text(page.content(), encoding="utf-8")
    except Exception:
        pass
    try:
        if state.upper() == "MD":
            focus_md_evidence_view(page)
    except Exception:
        pass
    try:
        page.screenshot(path=str(state_dir / f"{safe_name}.png"), full_page=False)
    except Exception:
        pass


def log_error(message: str) -> None:
    with LOG_PATH.open("a", encoding="utf-8") as f:
        f.write(f"\n[{time.strftime('%Y-%m-%d %H:%M:%S')}] {message}\n")
        f.write(traceback.format_exc())
        f.write("\n")


def log_event(message: str) -> None:
    with LOG_PATH.open("a", encoding="utf-8") as f:
        f.write(f"\n[{time.strftime('%Y-%m-%d %H:%M:%S')}] {message}\n")


def append_master_lead_log(rows: list[dict]) -> None:
    if not LEAD_LOG_WEBHOOK_URL or not rows:
        return
    payload = {
        "secret": LEAD_LOG_WEBHOOK_SECRET,
        "app_version": APP_VERSION,
        "rows": rows,
    }
    try:
        request = urllib.request.Request(
            LEAD_LOG_WEBHOOK_URL,
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Content-Type": "application/json",
                "User-Agent": "CharityClarityLeadLogger/1.0",
            },
            method="POST",
        )
        with urllib.request.urlopen(request, timeout=LEAD_LOG_WEBHOOK_TIMEOUT_SECONDS) as response:
            response.read(200)
    except Exception as exc:
        log_error(f"Master lead log webhook failed: {exc}")


def append_master_lead_log_async(rows: list[dict]) -> None:
    if not LEAD_LOG_WEBHOOK_URL or not rows:
        return
    thread = threading.Thread(target=append_master_lead_log, args=(rows,), daemon=True)
    thread.start()


def eastern_timestamp() -> tuple[str, str]:
    now = datetime.now(EASTERN_TZ) if EASTERN_TZ else datetime.now().astimezone()
    tz_name = now.tzname() or "Eastern"
    tz_label = "EDT" if "daylight" in tz_name.lower() else ("EST" if "standard" in tz_name.lower() else tz_name)
    return f"{now:%Y-%m-%d %H:%M:%S} {tz_label}", tz_label


def safe_audit_value(value: object, max_length: int = 500) -> str:
    return re.sub(r"[\r\n\t]+", " ", str(value or "")).strip()[:max_length]


def first_header_ip(headers) -> str:
    for name in ("CF-Connecting-IP", "X-Forwarded-For", "X-Real-IP"):
        value = headers.get(name, "")
        if value:
            return safe_audit_value(value.split(",")[0], 80)
    return ""


def request_audit_context(handler: BaseHTTPRequestHandler, payload: dict) -> dict:
    origin = safe_audit_value(payload.get("origin") or handler.headers.get("Origin", ""), 300)
    page_url = safe_audit_value(payload.get("page_url") or "", 500)
    referrer = safe_audit_value(payload.get("referrer") or handler.headers.get("Referer", ""), 500)
    environment = safe_audit_value(payload.get("environment") or "", 80)
    if not environment:
        environment = "staging" if "staging" in f"{origin} {page_url}".lower() else "production"
    remote_ip = first_header_ip(handler.headers)
    if not remote_ip and handler.client_address:
        remote_ip = safe_audit_value(handler.client_address[0], 80)
    return {
        "environment": environment,
        "origin": origin,
        "page_url": page_url,
        "referrer": referrer,
        "remote_ip": remote_ip,
        "user_agent": safe_audit_value(handler.headers.get("User-Agent", "") or payload.get("client_user_agent", ""), 500),
        "device_id": normalize_device_id(payload.get("device_id") or ""),
        "submission_id": secrets.token_hex(8),
    }


def ensure_lead_log_header(fieldnames: list[str]) -> None:
    if not LEAD_LOG_PATH.exists() or LEAD_LOG_PATH.stat().st_size == 0:
        return
    try:
        with LEAD_LOG_PATH.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            existing = reader.fieldnames or []
            if existing == fieldnames:
                return
            rows = list(reader)
        with LEAD_LOG_PATH.open("w", encoding="utf-8", newline="") as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames)
            writer.writeheader()
            for row in rows:
                writer.writerow({key: row.get(key, "") for key in fieldnames})
    except Exception as exc:
        log_error(f"Lead log header migration failed: {exc}")


def append_lead_log(email: str, results: list[dict], audit_context: dict | None = None) -> None:
    if not email or not results:
        return
    LEAD_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
    fieldnames = LEAD_LOG_FIELDNAMES
    ensure_lead_log_header(fieldnames)
    write_header = not LEAD_LOG_PATH.exists() or LEAD_LOG_PATH.stat().st_size == 0
    checked_at, checked_at_timezone = eastern_timestamp()
    domain = email_domain(email)
    audit_context = audit_context or {}
    master_rows = []
    with LEAD_LOG_PATH.open("a", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        if write_header:
            writer.writeheader()
        for result in results:
            row = {
                "checked_at": checked_at,
                "email": email.strip(),
                "domain": domain,
                "organization_name": result.get("organization_name", ""),
                "ein": result.get("ein", ""),
                "state": result.get("state", ""),
                "status": result.get("status", ""),
                "comments": result.get("comments", ""),
                "evidence_url": result.get("evidence_url", ""),
                "source_url": result.get("source_url", ""),
                "lookup_seconds": result.get("lookup_seconds", ""),
                "app_version": result.get("app_version", APP_VERSION),
                "checked_at_timezone": checked_at_timezone,
                "environment": audit_context.get("environment", ""),
                "origin": audit_context.get("origin", ""),
                "page_url": audit_context.get("page_url", ""),
                "referrer": audit_context.get("referrer", ""),
                "remote_ip": audit_context.get("remote_ip", ""),
                "user_agent": audit_context.get("user_agent", ""),
                "device_id": audit_context.get("device_id", ""),
                "submission_id": audit_context.get("submission_id", ""),
            }
            writer.writerow({key: row.get(key, "") for key in fieldnames})
            master_rows.append(row)
    append_master_lead_log_async(master_rows)


def append_submission_log(email: str, organizations: list[dict], states: list[str], audit_context: dict | None = None) -> None:
    """Capture valid usage before the slower registry lookups begin."""
    if not email or not organizations or not states:
        return
    rows = []
    for org in organizations:
        ein = org.get("ein", "")
        organization_name = org.get("organization_name") or f"EIN {ein}"
        for state in states:
            rows.append({
                "organization_name": organization_name,
                "ein": ein,
                "state": state,
                "status": "Lookup Started",
                "comments": "Submission received. CharityClarity started the public registry lookup.",
                "source_url": "",
                "lookup_seconds": "",
                "app_version": APP_VERSION,
            })
    append_lead_log(email, rows, audit_context)


def email_domain(email_address: str) -> str:
    parts = (email_address or "").strip().lower().split("@")
    return parts[1] if len(parts) == 2 and parts[1] else ""


def normalize_email(email_address: str) -> str:
    return (email_address or "").strip().lower()


def valid_email(email_address: str) -> bool:
    return bool(re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", normalize_email(email_address)))


def hash_pin(pin: str) -> str:
    return hashlib.sha256(pin.encode("utf-8")).hexdigest()


def cleanup_verification_state() -> None:
    now = time.time()
    for email_key in list(PIN_STORE):
        if PIN_STORE[email_key].get("expires_at", 0) < now:
            PIN_STORE.pop(email_key, None)
    for token in list(VERIFICATION_TOKENS):
        if VERIFICATION_TOKENS[token].get("expires_at", 0) < now:
            VERIFICATION_TOKENS.pop(token, None)


def send_pin_email(email_address: str, pin: str) -> str:
    smtp_host = os.environ.get("CE_SMTP_HOST", "").strip()
    smtp_port = int(os.environ.get("CE_SMTP_PORT", "587") or "587")
    smtp_user = os.environ.get("CE_SMTP_USER", "").strip()
    smtp_password = os.environ.get("CE_SMTP_PASSWORD", "").strip()
    smtp_from = os.environ.get("CE_SMTP_FROM", smtp_user or "no-reply@compliance-express.com").strip()

    if not smtp_host or not smtp_user or not smtp_password:
        PIN_LOG_PATH.write_text("", encoding="utf-8") if not PIN_LOG_PATH.exists() else None
        with PIN_LOG_PATH.open("a", encoding="utf-8") as f:
            f.write(f"{datetime.now().isoformat(timespec='seconds')} | {email_address} | {pin}\n")
        return "dev_log"

    message = EmailMessage()
    message["Subject"] = "Your Compliance Express passcode"
    message["From"] = smtp_from
    message["To"] = email_address
    message.set_content(
        "Your Compliance Express passcode is:\n\n"
        f"{pin}\n\n"
        "This passcode expires in 10 minutes. If you did not request it, you can ignore this email."
    )

    with smtplib.SMTP(smtp_host, smtp_port, timeout=20) as server:
        server.starttls()
        server.login(smtp_user, smtp_password)
        server.send_message(message)
    return "email"


def create_pin_for_email(email_address: str) -> str:
    cleanup_verification_state()
    pin = f"{secrets.randbelow(1_000_000):06d}"
    PIN_STORE[normalize_email(email_address)] = {
        "pin_hash": hash_pin(pin),
        "expires_at": time.time() + PIN_EXPIRY_SECONDS,
        "attempts": 0,
    }
    return pin


def verify_pin(email_address: str, pin: str) -> str | None:
    cleanup_verification_state()
    email_key = normalize_email(email_address)
    record = PIN_STORE.get(email_key)
    if not record:
        return None
    if record.get("attempts", 0) >= PIN_MAX_ATTEMPTS:
        PIN_STORE.pop(email_key, None)
        return None
    record["attempts"] = record.get("attempts", 0) + 1
    if hash_pin((pin or "").strip()) != record.get("pin_hash"):
        return None
    PIN_STORE.pop(email_key, None)
    token = secrets.token_urlsafe(32)
    VERIFICATION_TOKENS[token] = {
        "email": email_key,
        "expires_at": time.time() + VERIFICATION_TOKEN_SECONDS,
    }
    return token


def is_verified_email_token(email_address: str, token: str) -> bool:
    cleanup_verification_state()
    if not token:
        return False
    record = VERIFICATION_TOKENS.get(token)
    return bool(record and record.get("email") == normalize_email(email_address))


def is_verified_internal_passcode(email_address: str, passcode: str) -> bool:
    return is_exempt_domain(email_domain(email_address)) and (passcode or "").strip() == ADMIN_PASSCODE


def staging_access_error(email_address: str, passcode: str) -> str:
    if not STAGING_ACCESS_REQUIRED:
        return ""
    if not is_exempt_domain(email_domain(email_address)):
        return "Staging access requires a Compliance Express email address."
    if (passcode or "").strip() != ADMIN_PASSCODE:
        return "Enter the Compliance Express passcode to use staging."
    return ""


def is_exempt_domain(domain: str) -> bool:
    return domain.lower() == EXEMPT_EMAIL_DOMAIN


def is_exempt_email(email: str) -> bool:
    return (email or "").strip().lower() in EXEMPT_EMAIL_ADDRESSES


def is_privileged_request(email: str, domain: str) -> bool:
    return is_exempt_domain(domain) or is_exempt_email(email)


def state_limit_for_request(domain: str) -> int:
    if is_exempt_domain(domain):
        return MAX_STATES_PER_SNAPSHOT
    return 1


def org_limit_for_request(email: str, domain: str) -> int:
    if is_exempt_domain(domain):
        return 100
    if is_exempt_email(email):
        return MAX_EXTERNAL_EXEMPT_ORGS
    return 1


def load_domain_limits() -> dict:
    if not DOMAIN_LIMIT_PATH.exists():
        return {}
    try:
        return json.loads(DOMAIN_LIMIT_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}


def save_domain_limits(limits: dict) -> None:
    DOMAIN_LIMIT_PATH.write_text(json.dumps(limits, indent=2, sort_keys=True), encoding="utf-8")


def load_device_limits() -> dict:
    if not DEVICE_LIMIT_PATH.exists():
        return {}
    try:
        return json.loads(DEVICE_LIMIT_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}


def save_device_limits(limits: dict) -> None:
    DEVICE_LIMIT_PATH.write_text(json.dumps(limits, indent=2, sort_keys=True), encoding="utf-8")


def usage_limit_key(identifier: str, ein: str) -> str:
    ein_digits = re.sub(r"\D", "", ein or "")
    identifier = (identifier or "").strip().lower()
    if not identifier or len(ein_digits) != 9:
        return ""
    return f"{identifier}|{ein_digits}"


def domain_is_limited(domain: str, ein: str) -> bool:
    if not domain or is_exempt_domain(domain):
        return False
    key = usage_limit_key(domain, ein)
    if not key:
        return False
    limits = load_domain_limits()
    prior = int(limits.get(key, 0) or 0)
    if not prior:
        return False
    return int(time.time()) - prior < DOMAIN_LIMIT_DAYS * 24 * 60 * 60


def record_domain_check(domain: str, ein: str) -> None:
    if not domain or is_exempt_domain(domain):
        return
    key = usage_limit_key(domain, ein)
    if not key:
        return
    limits = load_domain_limits()
    limits[key] = int(time.time())
    save_domain_limits(limits)


def normalize_device_id(device_id: str) -> str:
    return re.sub(r"[^A-Za-z0-9_.:-]", "", (device_id or "").strip())[:120]


def device_is_limited(device_id: str, ein: str) -> bool:
    device_id = normalize_device_id(device_id)
    if not device_id:
        return False
    key = usage_limit_key(device_id, ein)
    if not key:
        return False
    limits = load_device_limits()
    prior = int(limits.get(key, 0) or 0)
    if not prior:
        return False
    return int(time.time()) - prior < DOMAIN_LIMIT_DAYS * 24 * 60 * 60


def record_device_check(device_id: str, ein: str) -> None:
    device_id = normalize_device_id(device_id)
    if not device_id:
        return
    key = usage_limit_key(device_id, ein)
    if not key:
        return
    limits = load_device_limits()
    limits[key] = int(time.time())
    save_device_limits(limits)


def should_record_domain_check(results: list[dict]) -> bool:
    if not results:
        return False
    return any((result.get("status") or "").strip().lower() != "site not reachable" for result in results)


def public_status(result) -> str:
    status = (result.status or "").strip()
    error = (result.error or "").strip().lower()

    if error:
        return "Site Not Reachable"

    normalized = status.lower()
    if normalized == "unknown":
        no_record_text = " ".join([
            result.raw_status_text or "",
            result.source_note or "",
        ])
        if re.search(r"\bexempt\b", no_record_text, re.I):
            return "Exempt"
        if re.search(r"no matching|no record|not found|no results|0 records|0 results", no_record_text, re.I):
            return "Not Registered"
        return "Unknown" if result.success else "Site Not Reachable"
    if normalized in {"not registered", "not found", "no record", "no record found"}:
        return "Not Registered"
    if "exempt" in normalized:
        return "Exempt"
    if "revoked" in normalized:
        return "Revoked"
    if "suspended" in normalized:
        return "Suspended"
    if re.search(r"\binactive\b", normalized, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(r"\bfailed\s+to\s+renew\b", normalized, re.I):
        return "Failed to Renew"
    if re.search(r"not\s+authorized\s+to\s+solicit|may\s+not\s+(?:solicit|raise\s+funds|operate)|cease\s+and\s+desist", normalized, re.I):
        return "Suspended"
    if re.search(r"\bpending\b", normalized, re.I):
        return "Pending"
    if re.search(r"\bin\s+process\b", normalized, re.I):
        return "Pending"
    if re.search(r"\b(withdrawn|retired|terminated|cancelled|canceled|voluntar(?:y|ily)\s+(?:deactivat(?:ed|ion)|surrender(?:ed)?))\b", normalized, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(r"\bclosed\b", normalized, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(r"\b(delinquent|non\W*compliant|not\s+current|expired|overdue)\b", normalized, re.I):
        return "Delinquent"
    if normalized in {"current", "active", "good standing", "compliant"} or re.search(r"\bgood\s+as\s+of\b", normalized):
        return "Current"
    if "upcoming" in normalized or "due" in normalized:
        return "Upcoming Filing"

    return status


def parse_due_date(value: str) -> date | None:
    formats = [
        "%m/%d/%Y",
        "%m/%d/%y",
        "%m-%d-%Y",
        "%m-%d-%y",
        "%Y-%m-%d",
        "%B %d, %Y",
        "%b %d, %Y",
        "%d-%b-%y",
        "%d-%b-%Y",
    ]
    cleaned = value.strip()
    for fmt in formats:
        try:
            return datetime.strptime(cleaned, fmt).date()
        except ValueError:
            continue
    return None


def parse_ce_date(value: str) -> date | None:
    for fmt in ("%d-%b-%y", "%d-%b-%Y", "%m/%d/%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(value.strip(), fmt).date()
        except ValueError:
            continue
    return None


def add_months(value: date, months: int) -> date:
    month_index = value.month - 1 + months
    year = value.year + month_index // 12
    month = month_index % 12 + 1
    day = min(value.day, calendar.monthrange(year, month)[1])
    return date(year, month, day)


def add_months_preserving_end_of_month(value: date, months: int) -> date:
    shifted = add_months(value, months)
    if value.day == calendar.monthrange(value.year, value.month)[1]:
        return shifted.replace(day=calendar.monthrange(shifted.year, shifted.month)[1])
    return shifted


def fifteenth_day_after_fiscal_year_end(fy_end: date, months_after_end_month: int) -> date:
    month_anchor = date(fy_end.year, fy_end.month, 1)
    return add_months(month_anchor, months_after_end_month).replace(day=15)


def md_automatic_extension_due_date(fy_end: date) -> date:
    return fifteenth_day_after_fiscal_year_end(fy_end, 11)


def fiscal_period_for_ein(ein: str) -> tuple[date | None, date | None]:
    target = re.sub(r"\D", "", ein or "")
    if not target or not CHARITY_OR_PATH.exists():
        return None, None

    with CHARITY_OR_PATH.open("r", encoding="utf-8", errors="ignore", newline="") as f:
        reader = csv.reader(f, delimiter="\t")
        for row in reader:
            if len(row) < 16:
                continue
            if re.sub(r"\D", "", row[4]) != target:
                continue
            period_start = parse_ce_date(row[14])
            period_end = parse_ce_date(row[15])
            return period_start, period_end
    return None, None


def organization_name_for_ein(ein: str) -> str:
    target = re.sub(r"\D", "", ein or "")
    if not target or not CHARITY_OR_PATH.exists():
        return ""
    with CHARITY_OR_PATH.open("r", encoding="utf-8", errors="ignore", newline="") as f:
        reader = csv.reader(f, delimiter="\t")
        for row in reader:
            if len(row) < 7:
                continue
            if re.sub(r"\D", "", row[4]) == target:
                return (row[6] or "").strip().strip('"')
    return ""


def or_snapshot_row_for_ein(ein: str) -> list[str] | None:
    target = re.sub(r"\D", "", ein or "")
    if len(target) != 9 or not CHARITY_OR_PATH.exists():
        return None
    with CHARITY_OR_PATH.open("r", encoding="utf-8", errors="ignore", newline="") as f:
        reader = csv.reader(f, delimiter="\t")
        for row in reader:
            if len(row) >= 16 and re.sub(r"\D", "", row[4]) == target:
                return row
    return None


def or_next_due_from_period_end(period_end: date | None) -> date | None:
    if not period_end:
        return None
    next_period_end = add_months_preserving_end_of_month(period_end, 12)
    return fifteenth_day_after_fiscal_year_end(next_period_end, 5)


def or_snapshot_result_for_ein(org):
    row = or_snapshot_row_for_ein(org.ein)
    if not row:
        return None
    registry_name = (row[6] or "").strip().strip('"')
    period_start = parse_ce_date(row[14]) if len(row) > 14 else None
    period_end = parse_ce_date(row[15]) if len(row) > 15 else None
    next_due = or_next_due_from_period_end(period_end)
    status = status_from_calendar_date(next_due) if next_due else "Current"
    result = checker.StateResult(
        org.organization_name,
        org.ein,
        "OR",
        status,
        "https://justice.oregon.gov/charities",
    )
    raw_parts = ["Status: Registered"]
    if period_end:
        raw_parts.append(f"Latest Fiscal Period End Year: {period_end.year}")
        raw_parts.append(f"Fiscal Period End: {format_date(period_end)}")
    if period_start:
        raw_parts.append(f"Fiscal Year Start: {format_date(period_start)}")
    if next_due:
        raw_parts.append(f"Next Due: {format_date(next_due)}")
    result.raw_status_text = " | ".join(raw_parts)
    result.source_note = (
        "Oregon public charity database export matched the requested EIN exactly; "
        "CharityClarity used that EIN match as the primary lookup before any name search."
    )
    result.matched_registry_name = registry_name
    result.matched_registry_identifier = format_ein(org.ein)
    result.success = True
    result.error = ""
    return result


def public_profile_for_ein(ein: str) -> dict:
    target = re.sub(r"\D", "", ein or "")
    if len(target) != 9:
        return {}
    if target in PUBLIC_PROFILE_CACHE:
        return PUBLIC_PROFILE_CACHE[target]
    try:
        url = f"https://projects.propublica.org/nonprofits/api/v2/organizations/{target}.json"
        request = urllib.request.Request(url, headers={"User-Agent": "ComplianceExpressRegistrySnapshot/1.0"})
        with urllib.request.urlopen(request, timeout=12) as response:
            payload = json.loads(response.read().decode("utf-8", errors="ignore"))
    except Exception:
        payload = {}
    PUBLIC_PROFILE_CACHE[target] = payload
    return payload


def public_profile_name_for_ein(ein: str) -> str:
    target = re.sub(r"\D", "", ein or "")
    if len(target) != 9:
        return ""
    if target in ORG_NAME_CACHE:
        return ORG_NAME_CACHE[target]
    payload = public_profile_for_ein(ein)
    name = ((payload.get("organization") or {}).get("name") or "").strip()
    ORG_NAME_CACHE[target] = name
    return name


def known_names_for_ein(ein: str) -> list[str]:
    return []


def public_profile_latest_tax_year_for_ein(ein: str) -> int | None:
    payload = public_profile_for_ein(ein)
    candidates = []
    raw_tax_period = str((payload.get("organization") or {}).get("tax_period") or "")
    match = re.match(r"(20\d{2})[-/]?\d{0,2}", raw_tax_period)
    if match:
        candidates.append(int(match.group(1)))
    for filing in payload.get("filings_with_data") or []:
        for key in ("tax_prd_yr", "tax_prd"):
            raw = str(filing.get(key) or "")
            match = re.match(r"(20\d{2})", raw)
            if match:
                candidates.append(int(match.group(1)))
    return max(candidates) if candidates else None


def public_profile_latest_tax_period_for_ein(ein: str) -> tuple[int, tuple[int, int]] | None:
    """Return the latest public profile tax year and fiscal year end, if available."""
    payload = public_profile_for_ein(ein)
    candidates: list[tuple[int, tuple[int, int]]] = []
    for filing in payload.get("filings_with_data") or []:
        raw_period = str(filing.get("tax_prd") or "")
        match = re.fullmatch(r"(20\d{2})(\d{2})", raw_period)
        if match:
            year = int(match.group(1))
            month = int(match.group(2))
            if 1 <= month <= 12:
                candidates.append((year, (month, calendar.monthrange(year, month)[1])))
        raw_year = str(filing.get("tax_prd_yr") or "")
        if re.fullmatch(r"20\d{2}", raw_year):
            candidates.append((int(raw_year), (12, 31)))
    if candidates:
        return max(candidates, key=lambda item: item[0])
    raw_tax_period = str((payload.get("organization") or {}).get("tax_period") or "")
    match = re.match(r"(20\d{2})[-/]?(\d{1,2})?", raw_tax_period)
    if match:
        year = int(match.group(1))
        month = int(match.group(2) or "12")
        if 1 <= month <= 12:
            candidates.append((year, (month, calendar.monthrange(year, month)[1])))
    return max(candidates, key=lambda item: item[0]) if candidates else None


def resolved_organization_name(ein: str, supplied_name: str = "") -> str:
    supplied_name = (supplied_name or "").strip()
    reference_name = organization_name_for_ein(ein)
    profile_name = public_profile_name_for_ein(ein)
    known_names = known_names_for_ein(ein)
    return supplied_name or profile_name or reference_name or (known_names[0] if known_names else "")


def canonical_ein_digits(value: str) -> str:
    digits = re.sub(r"\D", "", value or "")
    if len(digits) == 8:
        return f"0{digits}"
    return digits


def format_ein(value: str) -> str:
    digits = canonical_ein_digits(value)
    if len(digits) == 9:
        return f"{digits[:2]}-{digits[2:]}"
    return (value or "").strip()


def md_direct_ein_no_record_result(org):
    ein = canonical_ein_digits(getattr(org, "ein", ""))
    if len(ein) != 9:
        return None
    formatted_ein = f"{ein[:2]}-{ein[2:]}"
    base_url = "https://onestop.md.gov/list_views/62f3e1797f7e3200016a3dab"
    md_ein_filter_id = "a87e8739-62de-600d-728c-6300bf865f9e"
    entries_url = (
        f"{base_url}/entries?_method=get"
        f"&filter%5B{md_ein_filter_id}%5D={quote(formatted_ein)}"
        f"&filter%5Blimit%5D=20"
        f"&{md_ein_filter_id}={quote(formatted_ein)}"
        "&limit=20&fake=false&forceNewQuery=false&query%5Bpage%5D=1&page=1"
    )
    request = urllib.request.Request(
        entries_url,
        headers={
            "User-Agent": "ComplianceExpressRegression/1.0",
            "Accept": "*/*",
        },
    )
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            return None

    opener = urllib.request.build_opener(NoRedirect)
    try:
        with opener.open(request, timeout=MD_DIRECT_EIN_TIMEOUT_SECONDS) as response:
            body = response.read().decode("utf-8", "replace")
            if getattr(response, "status", None) == 204 or not body.strip():
                result = checker.StateResult(
                    getattr(org, "organization_name", ""),
                    getattr(org, "ein", ""),
                    "MD",
                    checker.STATUS_NOT_REGISTERED,
                    entries_url,
                )
                result.raw_status_text = "No record found"
                result.source_note = "Maryland exact-EIN entries endpoint returned no public registry record."
                result.success = True
                result.error = ""
                return result
    except urllib.error.HTTPError as exc:
        if exc.code == 204:
            result = checker.StateResult(
                getattr(org, "organization_name", ""),
                getattr(org, "ein", ""),
                "MD",
                checker.STATUS_NOT_REGISTERED,
                entries_url,
            )
            result.raw_status_text = "No record found"
            result.source_note = "Maryland exact-EIN entries endpoint returned no public registry record."
            result.success = True
            result.error = ""
            return result
    except Exception:
        return None
    return None


def fiscal_year_end_for_ein(ein: str) -> tuple[int, int] | None:
    payload = public_profile_for_ein(ein)
    filings = payload.get("filings_with_data") or []
    for filing in filings:
        raw_period = str(filing.get("tax_prd") or "")
        match = re.fullmatch(r"(\d{4})(\d{2})", raw_period)
        if match:
            year = int(match.group(1))
            month = int(match.group(2))
            if 1 <= month <= 12:
                return month, calendar.monthrange(year, month)[1]
    raw_tax_period = str((payload.get("organization") or {}).get("tax_period") or "")
    match = re.match(r"(\d{4})-(\d{1,2})-(\d{1,2})", raw_tax_period)
    if match:
        year = int(match.group(1))
        month = int(match.group(2))
        day = int(match.group(3))
        if 1 <= month <= 12:
            if day == 1:
                day = calendar.monthrange(year, month)[1]
            return month, min(day, calendar.monthrange(year, month)[1])
    _, period_end = fiscal_period_for_ein(ein)
    if period_end:
        return period_end.month, period_end.day
    return None


def format_date(value: date) -> str:
    return f"{value.month}/{value.day}/{value.year}"


def filing_due_date(state: str, report_year: int, fiscal_end: tuple[int, int]) -> tuple[date | None, str]:
    fy_end = date(report_year, fiscal_end[0], fiscal_end[1])
    state = state.upper()
    if state == "CA":
        if fiscal_end == (6, 30):
            base_due = date(report_year, 12, 31)
            extended_due = date(report_year + 1, 5, 15)
            effective_due = base_due if base_due >= date.today() else extended_due
            return effective_due, (
                f"California annual filing base due date is {format_date(base_due)}; "
                f"if an extension was applied, the extended due date is {format_date(extended_due)}"
            )
        base_due = fifteenth_day_after_fiscal_year_end(fy_end, 5)
        extended_due = add_months(base_due, 6)
        effective_due = base_due if base_due >= date.today() else extended_due
        return effective_due, (
            f"California annual filing base due date is {format_date(base_due)}; "
            f"if an extension was applied, the extended due date is {format_date(extended_due)}"
        )
    if state == "MD":
        base_due = add_months_preserving_end_of_month(fy_end, 6)
        extended_due = md_automatic_extension_due_date(fy_end)
        return base_due, (
            f"Maryland annual filing initial due date is {format_date(base_due)}; "
            f"if the automatic extension applies, the extension date is {format_date(extended_due)}"
        )
    if state == "MA":
        base_due = fifteenth_day_after_fiscal_year_end(fy_end, 5)
        extended_due = add_months(base_due, 6)
        return base_due, (
            f"Massachusetts Form PC base due date is {format_date(base_due)}; "
            f"if an extension applies, the extended due date is {format_date(extended_due)}"
        )
    if state == "NY":
        base_due = fifteenth_day_after_fiscal_year_end(fy_end, 5)
        extended_due = add_months(base_due, 6)
        return extended_due, (
            f"New York annual filing base due date is {format_date(base_due)}; "
            "the public guidance references a 180-day extension of time to file"
        )
    if state == "NJ":
        base_due = add_months(fy_end, 6)
        if fiscal_end == (6, 30):
            base_due = date(report_year, 12, 31)
            return date(report_year + 1, 5, 15), (
                f"New Jersey annual renewal base due date is {format_date(base_due)}; "
                f"if an extension applies, the extended due date is {format_date(date(report_year + 1, 5, 15))}"
            )
        return base_due, "based on New Jersey's six-month annual renewal cycle"
    if state == "PA":
        return add_months(fy_end, 11), "based on Pennsylvania's annual renewal cycle"
    if state == "VA":
        return add_months(fy_end, 4) + timedelta(days=15), "based on Virginia's 4.5-month annual renewal cycle"
    if state == "SC":
        return add_months(fy_end, 4) + timedelta(days=15), "based on South Carolina's 4.5-month annual renewal cycle"
    if state == "CO":
        return add_months(fy_end, 5) + timedelta(days=15), "based on Colorado's annual reporting cycle"
    if state == "HI":
        return add_months(fy_end, 4) + timedelta(days=15), "based on Hawaii's 4.5-month annual filing cycle"
    if state == "KY":
        return fifteenth_day_after_fiscal_year_end(fy_end, 5), "based on Kentucky's annual charitable organization filing cycle"
    if state == "ME":
        return add_months(fy_end, 5), "based on Maine's annual filing cycle"
    if state == "ND":
        return date(report_year - 1, 9, 1), "based on North Dakota's annual charitable organization renewal cycle"
    if state == "AK":
        return date(report_year, 9, 1), "based on Alaska's annual charitable registration cycle"
    return None, "state due-date rule is not encoded"


def filing_due_date_options(state: str, report_year: int, fiscal_end: tuple[int, int]) -> dict:
    state = state.upper()
    fy_end = date(report_year, fiscal_end[0], fiscal_end[1])
    if state == "CA":
        base_due = date(report_year, 12, 31) if fiscal_end == (6, 30) else fifteenth_day_after_fiscal_year_end(fy_end, 5)
    elif state == "MD":
        base_due = add_months_preserving_end_of_month(fy_end, 6)
    elif state in {"MA", "NY", "HI", "SC", "KY"}:
        base_due = fifteenth_day_after_fiscal_year_end(fy_end, 5)
    elif state == "PA":
        base_due = add_months(fy_end, 11)
    elif state == "NJ":
        base_due = date(report_year, 12, 31) if fiscal_end == (6, 30) else add_months(fy_end, 6)
    else:
        due_date, rule_note = filing_due_date(state, report_year, fiscal_end)
        return {
            "base_due": due_date,
            "effective_due": due_date,
            "extended_due": None,
            "uses_extension_assumption": False,
            "rule_note": rule_note,
        }

    if state == "MD":
        extended_due = md_automatic_extension_due_date(fy_end)
    else:
        extended_due = add_months_preserving_end_of_month(base_due, 6) if state in EXTENSION_SCENARIO_STATES else None
    effective_due = base_due
    if state == "MD":
        rule_note = "Maryland has an automatic extension process; CE Status is based on the base due date"
    elif state == "MA" and extended_due:
        rule_note = "Massachusetts allows a six-month Form PC extension; CE Status is based on the base due date and the extension impact is shown as a scenario"
    elif extended_due:
        rule_note = "CE Status is based on the base due date; extension impact is shown as a scenario"
    else:
        rule_note = filing_due_date(state, report_year, fiscal_end)[1]
    return {
        "base_due": base_due,
        "effective_due": effective_due,
        "extended_due": extended_due,
        "uses_extension_scenario": bool(extended_due),
        "uses_extension_assumption": False,
        "rule_note": rule_note,
    }


def next_base_due_from_fiscal_end(state: str, fiscal_end: tuple[int, int] | None) -> date | None:
    if not fiscal_end:
        return None
    state = (state or "").upper()
    today = date.today()
    future_due_dates = []
    for report_year in range(today.year - 2, today.year + 3):
        due_date = filing_due_date_options(state, report_year, fiscal_end).get("base_due")
        if due_date and due_date >= today:
            future_due_dates.append(due_date)
    return min(future_due_dates) if future_due_dates else None


def nj_inferred_latest_filing_year(fiscal_end: tuple[int, int]) -> int | None:
    """Infer the latest NJ filing year that should be on record for a compliant charity."""
    today = date.today()
    for report_year in range(today.year, today.year - 5, -1):
        try:
            due_options = filing_due_date_options("NJ", report_year, fiscal_end)
            due_date = due_options.get("base_due") or due_options.get("effective_due")
        except Exception:
            due_date = None
        if due_date and due_date <= today:
            return report_year
    return None


def latest_year_from_text(body: str, state: str) -> int | None:
    readable_body = html.unescape(re.sub(r"<[^>]+>", " ", body))
    if state == "HI":
        annual_section_match = re.search(
            r"(?:Annual\s+filing\s+documents|Annual\s+filings?|Documents)([\s\S]{0,5000}?)(?:Registration\s+documents|Other\s+Info|Current\s+CCV|Past\s+CCV|$)",
            readable_body,
            re.I,
        )
        annual_section = annual_section_match.group(1) if annual_section_match else ""
        hi_years = [
            int(match.group(1))
            for match in re.finditer(
                r"(?:Annual\s+Filing\s+for\s+Charitable\s+Organizations|Fiscal\s+year\s+end|FYE|Accounting\s+Period\s+End\s+Date)[\s\S]{0,180}\b(20\d{2})\b",
                annual_section,
                re.I,
            )
        ]
        # Hawaii often exposes the filing years as document tabs/list entries
        # rather than repeating "Annual Filing" beside each year.
        for match in re.finditer(r"\b(20\d{2})\b", annual_section):
            year = int(match.group(1))
            if 2000 <= year <= date.today().year:
                hi_years.append(year)
        return max(hi_years) if hi_years else None
    if state == "MD":
        md_patterns = [
            r"Most\s+Recent\s+Fiscal\s+Year\s*:?\s*(20\d{2})",
            r"Last\s+Year\s+Represented\s*:?\s*(20\d{2})",
            r"Year\s+Represented\s*:?\s*(20\d{2})",
        ]
        md_matches = []
        for pattern in md_patterns:
            for match in re.finditer(pattern, readable_body, re.I):
                md_matches.append((match.start(), int(match.group(1))))
        if md_matches:
            return sorted(md_matches, key=lambda item: item[0])[0][1]
        return None
    patterns = [
        r"Most\s+Recent\s+Fiscal\s+Year\s*:?\s*(20\d{2})",
        r"Last\s+Year\s+Represented\s*:?\s*(20\d{2})",
        r"Year\s+Represented\s*:?\s*(20\d{2})",
        r"Latest\s+FYE\s*:?\s*(20\d{2})",
        r"Fiscal\s+Year\s*:?\s*(20\d{2})",
        r"Registration\s+Year\s*:?\s*(20\d{2})",
        r"\b(20\d{2})\s+annual\s+(?:report|filing)\b",
        r"\b(20\d{2})\s+registration\b",
        r"Accounting\s+Period\s+End\s+Date\s*:?\s*\d{1,2}[/-]\d{1,2}[/-](20\d{2})",
        r"Period\s+End(?:ing)?\s*:?\s*\d{1,2}[/-]\d{1,2}[/-](20\d{2})",
    ]
    years = []
    if state == "MA":
        annual_match = re.search(
            r"Annual\s+Filings(?:\s+and\s+Documents)?([\s\S]{0,14000}?)(?:Charity\s+Registration\s+Documents|Registration\s+Documents|Other\s+Filed\s+Documents|$)",
            readable_body,
            re.I,
        )
        if annual_match:
            annual_section = annual_match.group(1)
            annual_years = []
            for match in re.finditer(r"\b(20\d{2})\b[\s\S]{0,140}\bForm[\s-]*PC\b", annual_section, re.I):
                annual_years.append(int(match.group(1)))
            for match in re.finditer(r"\bForm[\s-]*PC\b[\s\S]{0,140}\b(20\d{2})\b", annual_section, re.I):
                annual_years.append(int(match.group(1)))
            return max(annual_years) if annual_years else None
        return None
    if state == "CA":
        ca_years = ca_annual_renewal_years_from_text(readable_body)
        return ca_years.get("latest_submitted_year")
        return None
    for pattern in patterns:
        for match in re.finditer(pattern, readable_body, re.I):
            years.append(int(match.group(1)))
    if state == "HI":
        doc_match = re.search(r"\bDocuments\b([\s\S]{0,2500})", readable_body, re.I)
        if doc_match:
            for match in re.finditer(r"\b(20\d{2})\b", doc_match.group(1)):
                years.append(int(match.group(1)))
    if state == "NJ":
        for pattern in [
            r"(?:Filing|Fiscal|Financial|Renewal|Annual)[^0-9]{0,80}(20\d{2})",
            r"\b(20\d{2})\s+(?:annual|renewal|filing)",
        ]:
            for match in re.finditer(pattern, readable_body, re.I):
                years.append(int(match.group(1)))
    if state == "NY":
        ny_annual_match = re.search(r"Annual\s+filing\s+documents([\s\S]{0,5000}?)(?:Registration\s+documents|$)", readable_body, re.I)
        if ny_annual_match:
            ny_years = [
                int(match.group(1))
                for match in re.finditer(r"\b\d{1,2}[/-]\d{1,2}[/-](20\d{2})\b", ny_annual_match.group(1))
            ]
            if ny_years:
                return max(ny_years)
    return max(years) if years else None


def ca_annual_renewal_years_from_text(body: str) -> dict:
    readable_body = html.unescape(re.sub(r"<[^>]+>", " ", body or ""))
    readable_body = re.sub(r"\s+", " ", readable_body)
    annual_match = re.search(
        r"Annual\s+Renewal\s+Data([\s\S]{0,40000}?)(?:Fundraising\s+Platform\s+Data|Related\s+Registration|Filing\s+and\s+Correspondence|$)",
        readable_body,
        re.I,
    )
    if not annual_match:
        return {
            "latest_submitted_year": None,
            "latest_not_submitted_year": None,
            "latest_pending_year": None,
        }
    annual_section = annual_match.group(1)
    reporting_incomplete = bool(re.search(r"\b(reporting\s+incomplete|awaiting\s+reporting)\b", readable_body, re.I))
    blocks = re.split(r"(?=Status\s+of\s+Filing\s*:)", annual_section, flags=re.I)
    submitted_years = []
    not_submitted_years = []
    pending_years = []
    not_submitted_status_by_year = {}
    pending_status_by_year = {}
    for block in blocks:
        if not re.search(r"Status\s+of\s+Filing\s*:", block, re.I):
            continue
        status_match = re.search(
            r"Status\s+of\s+Filing\s*:?\s*(.*?)(?=(?:\s+)?Accounting\s+Period\s+Begin\s+Date|(?:\s+)?Accounting\s+Period\s+End\s+Date|(?:\s+)?Filing\s+Received\s+Date|$)",
            block,
            re.I,
        )
        status_text = re.sub(r"\s+", " ", status_match.group(1)).strip() if status_match else ""
        end_match = re.search(
            r"Accounting\s+Period\s+End\s+Date\s*:?\s*\d{1,2}\s*[/-]\s*\d{1,2}\s*[/-]\s*(20\d{2})",
            block,
            re.I,
        )
        if not end_match:
            continue
        filing_received_match = re.search(
            r"Filing\s+Received\s+Date\s*:?\s*\d{1,2}\s*[/-]\s*\d{1,2}\s*[/-]\s*20\d{2}",
            block,
            re.I,
        )
        year = int(end_match.group(1))
        if re.search(r"\b(?:in\s+process|pending)\b", status_text, re.I):
            pending_years.append(year)
            pending_status_by_year[year] = status_text or "In Process"
        elif re.search(r"\bnot\s+submitted\b", status_text, re.I):
            not_submitted_years.append(year)
            not_submitted_status_by_year[year] = status_text or "Not Submitted"
        elif reporting_incomplete and not status_text and not filing_received_match:
            not_submitted_years.append(year)
            not_submitted_status_by_year[year] = "Reporting Incomplete"
        elif (
            (
                re.search(r"\b(?:e-)?accepted\b", status_text, re.I)
                or (not status_text and filing_received_match)
            )
            and not re.search(r"\breject|incomplete|not\s+submitted\b", status_text, re.I)
        ):
            submitted_years.append(year)
    latest_not_submitted_year = max(not_submitted_years) if not_submitted_years else None
    latest_pending_year = max(pending_years) if pending_years else None
    return {
        "latest_submitted_year": max(submitted_years) if submitted_years else None,
        "latest_not_submitted_year": latest_not_submitted_year,
        "latest_not_submitted_status": not_submitted_status_by_year.get(latest_not_submitted_year) if latest_not_submitted_year else None,
        "latest_pending_year": latest_pending_year,
        "latest_pending_status": pending_status_by_year.get(latest_pending_year) if latest_pending_year else None,
    }


def fiscal_year_end_from_result(result) -> tuple[int, int] | None:
    """Prefer fiscal year ends that the state lookup itself exposed."""
    text = " ".join([
        result.raw_status_text or "",
        result.source_note or "",
    ])
    match = re.search(r"Latest\s+FYE\s*:?\s*(20\d{2})-(\d{1,2})-(\d{1,2})", text, re.I)
    if match:
        year = int(match.group(1))
        month = int(match.group(2))
        day = int(match.group(3))
        if 1 <= month <= 12:
            return month, min(day, calendar.monthrange(year, month)[1])
    match = re.search(r"Fiscal\s+Year\s+End\s*:?\s*(\d{1,2})[/-](\d{1,2})[/-](20\d{2})", text, re.I)
    if match:
        month = int(match.group(1))
        day = int(match.group(2))
        year = int(match.group(3))
        if 1 <= month <= 12:
            return month, min(day, calendar.monthrange(year, month)[1])
    return None


def md_represented_year_from_text(body: str, ein: str = "", organization_name: str = "") -> int | None:
    source = body or ""
    for escaped, replacement in {
        "\\u003c": "<",
        "\\u003C": "<",
        "\\u003e": ">",
        "\\u003E": ">",
        "\\u0026": "&",
        "\\u00a0": " ",
        "\\/": "/",
    }.items():
        source = source.replace(escaped, replacement)
    readable = html.unescape(re.sub(r"<[^>]+>", " ", source))
    readable = re.sub(r"\s+", " ", readable)
    patterns = [
        r"Most\s+Recent\s+Fiscal\s+Year\s*:?\s*(20\d{2})",
        r"Last\s+Year\s+Represented\s*:?\s*(20\d{2})",
        r"Year\s+Represented\s*:?\s*(20\d{2})",
    ]
    ein_digits = re.sub(r"\D", "", ein or "")
    normalize = getattr(checker, "normalize_name", lambda value: re.sub(r"\s+", " ", (value or "").lower()).strip())
    normalized_name = normalize(organization_name)
    candidates = []
    for pattern in patterns:
        for match in re.finditer(pattern, readable, re.I):
            start = match.start()
            window = readable[max(0, start - 1800): start + 1800]
            window_digits = re.sub(r"\D", "", window)
            score = 0
            if ein_digits and ein_digits in window_digits:
                score += 3
            if normalized_name and normalized_name in normalize(window):
                score += 2
            if re.search(r"Charity\s+Details|Organization\s+Income|Organization\s+Expenses|Charity\s+EIN", window, re.I):
                score += 1
            candidates.append({"year": int(match.group(1)), "start": start, "score": score})
    if not candidates:
        return None
    scored = [candidate for candidate in candidates if candidate["score"] > 0]
    if scored:
        best_score = max(candidate["score"] for candidate in scored)
        return max(candidate["year"] for candidate in scored if candidate["score"] == best_score)
    return sorted(candidates, key=lambda item: item["start"])[0]["year"]


def filing_context(result, body: str) -> dict:
    state = (result.state or "").upper()
    registry_text = " ".join([result.raw_status_text or "", body or ""])
    registry_latest_year = None
    registry_year_patterns = [
        r"\bLast\s+Year\s+(?:on\s+)?Record\s*:?\s*(20\d{2})\b",
        r"\bYr\s+Last\s+Filed\s*:\s*(20\d{2})\b",
        r"\bLatest\s+Report\s+Year\s*:\s*(20\d{2})\b",
        r"\bTax\s+Year\s+(20\d{2})\b",
        r"\bRegistration\s+Submitted\s+(20\d{2})\b",
        r"\bRegistration\s+Accepted\s+(20\d{2})\b",
        r"\bRenewal\s+Registration\s+[A-Za-z]+\s+\d{1,2},\s+(20\d{2})\b",
        r"\bExtension\s+Granted\s+[A-Za-z]+\s+\d{1,2},\s+(20\d{2})\b",
        r"\bRegistration\s+Issued\s+[A-Za-z]+\s+\d{1,2},\s+(20\d{2})\b",
    ]
    for pattern in registry_year_patterns:
        years = [int(match.group(1)) for match in re.finditer(pattern, registry_text, re.I)]
        if years:
            registry_latest_year = max(years) if registry_latest_year is None else max(registry_latest_year, max(years))
    if state == "MD":
        latest_year = md_represented_year_from_text(body, result.ein, result.organization_name)
    else:
        latest_year = registry_latest_year or latest_year_from_text(body, result.state)
    if state == "PA":
        latest_year = None
    if latest_year is None and state in {"MA", "CA", "HI", "NJ"}:
        raw_year = re.fullmatch(r"\s*(20\d{2})\s*", result.raw_status_text or "")
        if raw_year:
            latest_year = int(raw_year.group(1))
    if latest_year is None and re.search(r"registration\s+found|year\s+represented|latest|most\s+recent|filing\s+year", result.raw_status_text or "", re.I):
        year_match = re.search(r"(20\d{2})", result.raw_status_text or "")
        latest_year = int(year_match.group(1)) if year_match else None
    period_start, period_end = fiscal_period_for_ein(result.ein)
    if (
        state == "CA"
        and latest_year is not None
        and latest_year < date.today().year - 3
        and re.search(r"\bCurrent\b", " ".join([result.status or "", result.raw_status_text or ""]), re.I)
    ):
        latest_year = None
    if (
        latest_year is None
        and state == "NJ"
        and re.search(r"\b(compliant|current|active)\b", " ".join([result.status or "", result.raw_status_text or "", body or ""]), re.I)
    ):
        latest_year = public_profile_latest_tax_year_for_ein(result.ein)
    if (
        latest_year is not None
        and state == "NJ"
        and re.search(r"\b(compliant|current|active)\b", " ".join([result.status or "", result.raw_status_text or "", body or ""]), re.I)
    ):
        profile_latest_year = public_profile_latest_tax_year_for_ein(result.ein)
        _, ce_period_end = fiscal_period_for_ein(result.ein)
        ce_latest_year = ce_period_end.year if ce_period_end else None
        if profile_latest_year and profile_latest_year > latest_year:
            latest_year = profile_latest_year
        if ce_latest_year and ce_latest_year > latest_year:
            latest_year = ce_latest_year
    # For CA, use Annual Renewal Data only. Pulling a Form 990/profile year here
    # can create a filing year that the California registry did not show.
    if latest_year is None and period_end and state not in {"CA", "MA", "MD", "NJ", "PA"}:
        latest_year = period_end.year
    result_fiscal_end = fiscal_year_end_from_result(result)
    registry_fiscal_end = fiscal_year_end_from_body(body, state)
    profile_period = public_profile_latest_tax_period_for_ein(result.ein)
    profile_fiscal_end = profile_period[1] if profile_period else None
    fiscal_end = result_fiscal_end or registry_fiscal_end or profile_fiscal_end or fiscal_year_end_for_ein(result.ein)

    if (
        state == "NJ"
        and fiscal_end
        and re.search(r"\b(compliant|current|active)\b", " ".join([result.status or "", result.raw_status_text or "", body or ""]), re.I)
    ):
        inferred_latest_year = nj_inferred_latest_filing_year(fiscal_end)
        if inferred_latest_year and (latest_year is None or inferred_latest_year > latest_year):
            latest_year = inferred_latest_year

    if latest_year is None or fiscal_end is None:
        return {
            "represented_year": latest_year,
            "fiscal_end": fiscal_end,
            "next_report_year": None,
            "due_date": None,
            "comment": "Annual filing due date could not be determined from the available CharityClarity check."
        }

    next_report_year = latest_year + 1
    due_options = filing_due_date_options(result.state, next_report_year, fiscal_end)
    due_date = due_options["effective_due"]
    rule_note = due_options["rule_note"]
    if due_date is None:
        return {
            "represented_year": latest_year,
            "fiscal_end": fiscal_end,
            "next_report_year": next_report_year,
            "due_date": None,
            "base_due_date": due_options.get("base_due"),
            "extended_due_date": due_options.get("extended_due"),
            "uses_extension_assumption": due_options.get("uses_extension_assumption", False),
            "uses_extension_scenario": due_options.get("uses_extension_scenario", False),
            "comment": "Annual filing due date could not be determined from the available CharityClarity check."
        }
    comment = (
        f"{next_report_year} annual filing is due {format_date(due_date)} "
        f"based on a {fiscal_end[0]}/{fiscal_end[1]} fiscal year end; {rule_note}."
    )
    return {
        "represented_year": latest_year,
        "fiscal_end": fiscal_end,
        "next_report_year": next_report_year,
        "due_date": due_date,
        "base_due_date": due_options["base_due"],
        "extended_due_date": due_options["extended_due"],
        "uses_extension_assumption": due_options["uses_extension_assumption"],
        "uses_extension_scenario": due_options.get("uses_extension_scenario", False),
        "comment": comment
    }


def stale_represented_year_is_delinquent(represented_year: int | None) -> bool:
    return bool(represented_year and represented_year <= date.today().year - 2)


def current_cycle_already_filed(state: str, represented_year: int | None, registry_date: date | None = None) -> bool:
    """The filing year on record is recent enough to use next-due-date logic."""
    if represented_year is None:
        return False
    state = (state or "").upper()
    today = date.today()
    if state == "AK":
        return represented_year >= today.year and (registry_date is None or registry_date >= today)
    if state in {"CA", "HI", "MA", "MD"}:
        return represented_year >= today.year - 1
    return False


def status_for_filed_cycle(state: str, context: dict, registry_date: date | None = None) -> str:
    due_date = context.get("due_date")
    represented_year = context.get("represented_year")
    if due_date and represented_year:
        return status_from_calendar_date(due_date)
    if current_cycle_already_filed(state, represented_year, registry_date):
        return "Current"
    return ""


def represented_year_is_registry_evidenced(result, body: str, represented_year: int | None) -> bool:
    if represented_year is None:
        return False
    state = (result.state or "").upper()
    combined = combined_result_text(result, body)
    if latest_year_from_text(combined, state) == represented_year:
        return True
    if state == "AK" and re.search(rf"\b{represented_year}\s+registration\s+found\b", combined, re.I):
        return True
    return False


def md_financial_body(page) -> str:
    pieces = []
    try:
        pieces.append(page.locator("body").inner_text(timeout=5000))
    except Exception:
        pass
    for label in ["Financial Information", "Financial Informati"]:
        try:
            page.get_by_role("button", name=re.compile(label, re.I)).click(timeout=5000)
            time.sleep(3)
            break
        except Exception:
            continue
    try:
        page.locator("body").evaluate("window.scrollTo(0, document.body.scrollHeight)")
        time.sleep(1)
    except Exception:
        pass
    try:
        pieces.append(page.locator("body").inner_text(timeout=8000))
    except Exception:
        pass
    try:
        page.get_by_text(re.compile(r"Most\s+Recent\s+Fiscal\s+Year|Year\s+Represented", re.I)).first.scroll_into_view_if_needed(timeout=5000)
        page.locator("body").evaluate("window.scrollBy(0, -140)")
        time.sleep(1)
    except Exception:
        pass
    try:
        pieces.append(page.content())
    except Exception:
        pass
    return "\n".join(pieces)


def md_detail_body(page, deep: bool = False) -> str:
    pieces = []
    try:
        pieces.append(page.locator("body").inner_text(timeout=5000))
    except Exception:
        pass
    for label in ["General Information", "General Informati"]:
        try:
            page.get_by_role("button", name=re.compile(label, re.I)).click(timeout=5000)
            time.sleep(2)
            break
        except Exception:
            continue
    try:
        pieces.append(page.locator("body").inner_text(timeout=8000))
    except Exception:
        pass
    if deep:
        pieces.append(md_financial_body(page))
    return "\n".join(piece for piece in pieces if piece)


def md_no_results_body(page) -> str:
    pieces = []
    try:
        pieces.append(page.locator("body").inner_text(timeout=5000))
    except Exception:
        pass
    for pattern in [
        r"No\s+results\s+found",
        r"\b0\s+records\b",
        r"You'?ve\s+reached\s+the\s+end\s+of\s+the\s+list",
    ]:
        try:
            page.get_by_text(re.compile(pattern, re.I)).last.scroll_into_view_if_needed(timeout=5000)
            page.locator("body").evaluate("window.scrollBy(0, -160)")
            time.sleep(1)
            break
        except Exception:
            continue
    try:
        pieces.append(page.locator("body").inner_text(timeout=5000))
        pieces.append(page.content())
    except Exception:
        pass
    return "\n".join(pieces)


def registry_page_body(page) -> str:
    pieces = []
    try:
        pieces.append(page.locator("body").inner_text(timeout=8000))
    except Exception:
        pass
    try:
        pieces.append(page.content())
    except Exception:
        pass
    return "\n".join(pieces)


def safe_wait_for_network_idle(page, timeout: int = 15000) -> None:
    try:
        page.wait_for_load_state("networkidle", timeout=timeout)
    except Exception:
        pass


def scroll_to_latest_year_evidence(page, state: str, body: str) -> bool:
    latest_year = latest_year_from_text(body, state)
    if latest_year is None:
        return False
    patterns = [
        rf"Accounting\s+Period\s+End\s+Date\s*:?\s*\d{{1,2}}[/-]\d{{1,2}}[/-]{latest_year}",
        rf"Period\s+End(?:ing)?\s*:?\s*\d{{1,2}}[/-]\d{{1,2}}[/-]{latest_year}",
        rf"Year\s+Represented\s*:?\s*{latest_year}",
        rf"\b{latest_year}\b",
    ]
    for pattern in patterns:
        try:
            page.get_by_text(re.compile(pattern, re.I)).last.scroll_into_view_if_needed(timeout=5000)
            page.locator("body").evaluate("window.scrollBy(0, -180)")
            time.sleep(1)
            return True
        except Exception:
            continue
    return False


def extract_ak_signature_date(pdf_text: str) -> str:
    match = re.search(r"Signature[\s\S]{0,800}?\bDate\s*:?\s*([A-Za-z]+\s+\d{1,2},\s+\d{4})", pdf_text or "", re.I)
    return match.group(1).strip() if match else ""


def organization_name_variants(
    name: str,
    ein: str = "",
    include_ein_aliases: bool = True,
    include_name_segments: bool = False,
    include_and_segments: bool = True,
    include_compact_legal_suffixes: bool = True,
    include_leading_article_variants: bool = True,
    include_broad_query_prefixes: bool = True,
    include_institutional_reductions: bool = True,
) -> list[str]:
    variants = []

    def add(value: str) -> None:
        value = re.sub(r"\s+", " ", (value or "").strip())
        if value and value not in variants:
            variants.append(value)

    def final_substantive_number_variants(value: str) -> list[str]:
        if not re.search(r"\b(?:and|&)\b", value or "", re.I):
            return []
        legal_or_generic = {
            "the", "a", "an", "inc", "inc.", "incorporated", "corp", "corp.",
            "corporation", "llc", "ltd", "ltd.", "limited", "foundation",
            "fund", "charity", "charities", "association", "society",
            "institute", "center", "centre", "organization", "trust",
        }
        matches = list(re.finditer(r"[A-Za-z]{4,}", value or ""))
        for match in reversed(matches):
            word = match.group(0)
            if word.lower() in legal_or_generic:
                continue
            replacements = []
            if word.lower().endswith("ies"):
                replacements.append(f"{word[:-3]}y")
            elif word.lower().endswith("s") and not word.lower().endswith(("ss", "us")):
                replacements.append(word[:-1])
            else:
                replacements.append(f"{word}s")
            return [
                f"{value[:match.start()]}{replacement}{value[match.end():]}"
                for replacement in replacements
                if replacement and replacement.lower() != word.lower()
            ]
        return []

    seed_names = [name]
    if ein and include_ein_aliases:
        for alias in known_names_for_ein(ein):
            if compatible_ein_alias_for_name(name, alias):
                seed_names.append(alias)

    if include_name_segments:
        segmented_seeds = []
        and_segmented_seeds = []
        for seed in list(seed_names):
            segment_pattern = r"\s*(?:/|\\|,|\bd/?b/?a\b|\bdoing\s+business\s+as\b|\balso\s+soliciting\s+as\b|\bsoliciting\s+as\b|\balso\s+known\s+as\b|\baka\b|\bfka\b|\bformerly\b)\s*"
            for part in re.split(
                segment_pattern,
                seed or "",
                flags=re.I,
            ):
                part = re.sub(r"\s+", " ", part.strip(" ,;-"))
                if re.fullmatch(r"(?i)(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)", part):
                    continue
                if (len(part.split()) >= 2) or len(part) >= 4:
                    segmented_seeds.append(part)
            if include_and_segments and re.search(r"\s(?:&|and)\s", seed or "", re.I):
                for part in re.split(r"\s*(?:&|\band\b)\s*", seed or "", flags=re.I):
                    part = re.sub(r"\s+", " ", part.strip(" ,;-"))
                    if re.fullmatch(r"(?i)(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)", part):
                        continue
                    if (len(part.split()) >= 2) or len(part) >= 8:
                        and_segmented_seeds.append(part)
        # Try slash/DBA/AKA sides early. Several name-only registries do not
        # find "A / B" as a combined string, but do find the formal side by
        # itself. Keep the original name first, then the meaningful segments,
        # then any EIN-sourced aliases.
        seed_names = [seed_names[0], *segmented_seeds, *seed_names[1:], *and_segmented_seeds]
        if segmented_seeds:
            add(seed_names[0])
            for disease_seed in [seed_names[0]]:
                if re.search(r"\bTuberculosis\b", disease_seed or "", re.I):
                    abbreviated = re.sub(r"\bTuberculosis\b", "TB", disease_seed, flags=re.I).strip()
                    abbreviated = re.sub(r"^(?:the|a|an)\s+", "", abbreviated, flags=re.I).strip()
                    abbreviated_ampersand = re.sub(r"\s+and\s+", " & ", abbreviated, flags=re.I).strip()
                    abbreviated_no_punctuation = re.sub(r"[^\w\s]", " ", abbreviated_ampersand).strip()
                    abbreviated_no_punctuation = re.sub(r"\s+", " ", abbreviated_no_punctuation)
                    add(abbreviated_ampersand)
                    add(abbreviated_no_punctuation)
            for segmented_seed in segmented_seeds:
                add(segmented_seed)

    for seed in seed_names:
        base = re.sub(r"\s+", " ", (seed or "").strip())
        if not base:
            continue
        add(base)
        us_prefixed_variants = []
        if re.match(r"^us\s+", base, re.I):
            us_prefixed_variants.append(re.sub(r"^us\s+", "U.S. ", base, flags=re.I))
            us_prefixed_variants.append(re.sub(r"^us\s+", "United States ", base, flags=re.I))
        elif re.match(r"^u\.?\s*s\.?\s+", base, re.I):
            us_prefixed_variants.append(re.sub(r"^u\.?\s*s\.?\s+", "US ", base, flags=re.I))
            us_prefixed_variants.append(re.sub(r"^u\.?\s*s\.?\s+", "United States ", base, flags=re.I))
        without_trailing_the = re.sub(r",\s*the\s*$", "", base, flags=re.I).strip()
        leading_article_from_trailing = ""
        trailing_article_match = re.match(r"^(.*?),\s*the\s*$", base, flags=re.I)
        if trailing_article_match:
            leading_article_from_trailing = f"The {trailing_article_match.group(1).strip()}"
        without_leading_article = re.sub(r"^(?:the|a|an)\s+", "", base, flags=re.I).strip()
        without_comma_suffix = re.sub(r",\s*(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?)\s*$", "", base, flags=re.I).strip()
        without_suffix = re.sub(r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?)\s*$", "", without_comma_suffix, flags=re.I).strip()
        no_comma = re.sub(r",\s*", " ", base).strip()
        no_punctuation = re.sub(r"[^\w\s]", " ", base).strip()
        no_punctuation = re.sub(r"\s+", " ", no_punctuation)
        us_word_variants = []
        for us_source in [base, without_leading_article]:
            if re.search(r"\bu\.?\s*s\.?(?=\W|$)", us_source or "", re.I):
                compact = re.sub(r"\bu\.?\s*s\.?(?=\W|$)", "US", us_source, flags=re.I).strip()
                expanded = re.sub(r"\bu\.?\s*s\.?(?=\W|$)", "United States", us_source, flags=re.I).strip()
                us_word_variants.extend([compact, expanded])
                us_word_variants.extend([
                    re.sub(r"^(?:the|a|an)\s+", "", compact, flags=re.I).strip(),
                    re.sub(r"^(?:the|a|an)\s+", "", expanded, flags=re.I).strip(),
                ])
        slash_as_space = re.sub(r"\s*(?:/|\\)\s*", " ", base).strip()
        slash_as_space = re.sub(r"\s+", " ", slash_as_space)
        broad_query_prefixes = []
        broad_query_suffixes = []
        prefix_source = re.sub(r"^the\s+", "", no_punctuation, flags=re.I).strip()
        prefix_words = prefix_source.split()
        if include_broad_query_prefixes and len(prefix_words) >= 5:
            # Some name-only registries fail on long formal names but return
            # the right row from a shorter prefix. Candidate scoring still has
            # to match the full target name before any result is accepted.
            broad_query_prefixes.extend([
                " ".join(prefix_words[:4]),
                " ".join(prefix_words[:3]),
                " ".join(prefix_words[:2]),
            ])
            broad_query_suffixes.extend([
                " ".join(prefix_words[-3:]),
                " ".join(prefix_words[-2:]),
            ])
        institute_plural = re.sub(r"\bInstitute\s+of\b", "Institutes of", base, flags=re.I).strip()
        institute_singular = re.sub(r"\bInstitutes\s+of\b", "Institute of", base, flags=re.I).strip()
        hyphen_as_space = re.sub(r"[-\u2010-\u2015]+", " ", base).strip()
        hyphen_removed = re.sub(r"[-\u2010-\u2015]+", "", base).strip()
        title_hyphen_base = ""
        if re.match(r"^[A-Z]{2,8}[-\u2010-\u2015][A-Za-z]", base):
            # A few name-search registries are picky about casing for acronym-hyphen names.
            title_hyphen_base = re.sub(
                r"^[A-Z]{2,8}",
                lambda match: match.group(0).title(),
                base,
                count=1,
            )
        final_number_variants = []
        for number_source in [base, without_suffix, no_punctuation]:
            for number_variant in final_substantive_number_variants(number_source):
                final_number_variants.append(number_variant)
        ampersand_as_and = re.sub(r"\s*&\s*", " and ", base).strip()
        ampersand_removed = re.sub(r"\s*&\s*", " ", base).strip()
        apostrophe_removed = re.sub(r"[']", "", base).strip()
        possessive_removed = re.sub(r"\b([A-Za-z]+)'[sS]\b", r"\1s", base).strip()
        possessive_s_removed = re.sub(r"\b([A-Za-z]+)'[sS]\b", r"\1", base).strip()
        hyphen_space_possessive_removed = re.sub(r"[-\u2010-\u2015]+", " ", possessive_removed).strip()
        hyphen_space_possessive_removed = re.sub(r"\s+", " ", hyphen_space_possessive_removed)
        hyphen_space_possessive_s_removed = re.sub(r"[-\u2010-\u2015]+", " ", possessive_s_removed).strip()
        hyphen_space_possessive_s_removed = re.sub(r"\s+", " ", hyphen_space_possessive_s_removed)
        compact_alnum_token = re.sub(r"\b([A-Za-z]\d)\s+([A-Za-z])\b", r"\1\2", base).strip()
        compact_alnum_token = re.sub(r"\b([A-Za-z]+)\s+(\d+)\s+([A-Za-z]+)\b", r"\1\2\3", compact_alnum_token).strip()
        spaced_alnum_token = re.sub(r"\b([A-Za-z]+)(\d+)([A-Za-z]+)\b", r"\1 \2 \3", base).strip()
        saint_expanded = re.sub(r"\bSt\.?\s+", "Saint ", base, flags=re.I).strip()
        saint_abbreviated = re.sub(r"\bSaint\s+", "St. ", base, flags=re.I).strip()
        childrens_hospital = re.sub(
            r"\b(Children'?s?)\s+Foundation\b",
            r"\1 Hospital Foundation",
            base,
            flags=re.I,
        ).strip()
        childrens_hospital_no_punctuation = re.sub(
            r"\b(Children'?s?)\s+Foundation\b",
            r"\1 Hospital Foundation",
            no_punctuation,
            flags=re.I,
        ).strip()
        cancer_research_center = re.sub(
            r"\bCancer\s+Center\b",
            "Cancer Research Center",
            base,
            flags=re.I,
        ).strip()
        cancer_center = re.sub(
            r"\bCancer\s+Research\s+Center\b",
            "Cancer Center",
            base,
            flags=re.I,
        ).strip()
        of_america_removed = re.sub(r"\bof\s+(?:america|the\s+united\s+states|united\s+states)\b\.?\s*$", "", base, flags=re.I).strip(" ,;-")
        of_connector_removed = re.sub(r"\bof\s+(America|United\s+States)\b", r"\1", base, flags=re.I).strip()
        ms_expanded = re.sub(r"\bMS\s+Society\b", "Multiple Sclerosis Society", base, flags=re.I).strip()
        disease_abbreviated = re.sub(r"\bTuberculosis\b", "TB", base, flags=re.I).strip()
        disease_abbreviated_ampersand = re.sub(r"\s+and\s+", " & ", disease_abbreviated, flags=re.I).strip()
        disease_abbreviated_no_punctuation = re.sub(r"[^\w\s]", " ", disease_abbreviated_ampersand).strip()
        disease_abbreviated_no_punctuation = re.sub(r"\s+", " ", disease_abbreviated_no_punctuation)
        institution_descriptor_removed = institutional_tail_reduction(base) if include_institutional_reductions else ""
        and_no_punctuation = re.sub(r"[^\w\s]", " ", ampersand_as_and).strip()
        and_no_punctuation = re.sub(r"\s+", " ", and_no_punctuation)
        and_without_suffix = re.sub(
            r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?)\b",
            " ",
            and_no_punctuation,
            flags=re.I,
        ).strip()
        and_without_suffix = re.sub(r"\s+", " ", and_without_suffix)
        compact_legal_suffixes = re.sub(
            r"\b(the|inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?)\b",
            " ",
            no_punctuation,
            flags=re.I,
        ).strip()
        compact_legal_suffixes = re.sub(r"\s+", " ", compact_legal_suffixes)
        hyphenated_word_pairs = []
        words = base.split()
        if "-" not in base and 2 <= len(words) <= 8:
            for idx in range(len(words) - 1):
                pair_variant = words[:]
                pair_variant[idx] = f"{pair_variant[idx]}-{pair_variant[idx + 1]}"
                del pair_variant[idx + 1]
                hyphenated_word_pairs.append(" ".join(pair_variant))
        legal_suffix_additions = []
        if not re.search(r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\s*$", base, re.I):
            # Some public profiles omit the legal suffix even when name-search
            # registries require it to find the organization.
            legal_suffix_additions.extend([
                f"{base} Inc",
                f"{base} Inc.",
                f"{base}, Inc",
                f"{base}, Inc.",
                f"{hyphen_as_space} Inc" if hyphen_as_space and hyphen_as_space.lower() != base.lower() else "",
                f"{hyphen_as_space} Inc." if hyphen_as_space and hyphen_as_space.lower() != base.lower() else "",
                f"{hyphen_as_space}, Inc" if hyphen_as_space and hyphen_as_space.lower() != base.lower() else "",
                f"{hyphen_as_space}, Inc." if hyphen_as_space and hyphen_as_space.lower() != base.lower() else "",
                f"{title_hyphen_base} Inc" if title_hyphen_base else "",
                f"{title_hyphen_base} Inc." if title_hyphen_base else "",
                f"{title_hyphen_base}, Inc" if title_hyphen_base else "",
                f"{title_hyphen_base}, Inc." if title_hyphen_base else "",
            ])
        broad_variants = [and_without_suffix, compact_legal_suffixes] if include_compact_legal_suffixes else []
        with_leading_the = "" if re.match(r"^the\s+", base, re.I) else f"The {base}"
        article_variants = [with_leading_the, without_leading_article] if include_leading_article_variants else []
        for variant in [
            institution_descriptor_removed,
            without_leading_article,
            without_comma_suffix,
            without_suffix,
            no_comma,
            disease_abbreviated,
            disease_abbreviated_ampersand,
            disease_abbreviated_no_punctuation,
            *broad_query_prefixes,
            *broad_query_suffixes,
            *final_number_variants,
            childrens_hospital,
            childrens_hospital_no_punctuation,
            *hyphenated_word_pairs,
            *us_word_variants,
            no_punctuation,
            slash_as_space,
            institute_plural,
            institute_singular,
            hyphen_as_space,
            hyphen_removed,
            compact_alnum_token,
            spaced_alnum_token,
            ampersand_as_and,
            ampersand_removed,
            apostrophe_removed,
            possessive_removed,
            possessive_s_removed,
            hyphen_space_possessive_removed,
            hyphen_space_possessive_s_removed,
            saint_expanded,
            saint_abbreviated,
            cancer_research_center,
            cancer_center,
            of_america_removed,
            of_connector_removed,
            title_hyphen_base,
            ms_expanded,
            and_no_punctuation,
            *broad_variants,
            *us_prefixed_variants,
            leading_article_from_trailing,
            without_trailing_the,
            *article_variants,
            *legal_suffix_additions,
        ]:
            add(variant)
    return variants or [""]


def institutional_tail_reduction(value: str) -> str:
    """Trim narrow institutional suffixes used inconsistently by registries."""
    reduced = re.sub(
        r"\b(?:national\s+)?(?:medical\s+center|hospital\s+center|hospital)\b\.?\s*$",
        "",
        value or "",
        flags=re.I,
    ).strip(" ,;-")
    return re.sub(r"\s+", " ", reduced)


def prioritized_institutional_variants(variants: list[str]) -> list[str]:
    prioritized = []

    def add(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip())
        if cleaned and cleaned.lower() not in {existing.lower() for existing in prioritized}:
            prioritized.append(cleaned)

    for variant in variants:
        reduced = institutional_tail_reduction(variant)
        if reduced and reduced.lower() != (variant or "").strip().lower():
            add(reduced)
    for variant in variants:
        add(variant)
    return prioritized or variants


def compatible_ein_alias_for_name(original_name: str, alias_name: str) -> bool:
    """Only let EIN-resolved aliases accept rows when they remain specific.

    The query layer can stay flexible, but the acceptance layer should not let a
    broad alias such as "University of Missouri" certify a row for "The Curators
    of University of Missouri". That was the source of the recent name-only
    false positives.
    """
    normalize = getattr(checker, "normalize_name", lambda value: re.sub(r"\W+", " ", (value or "").lower()).strip())
    original = normalize(original_name)
    alias = normalize(alias_name)
    if not original or not alias:
        return False
    if original == alias:
        return True

    original_words = original.split()
    alias_words = alias.split()
    if not original_words or not alias_words:
        return False

    def acronym_from_words(words: list[str]) -> str:
        ignored = {"the", "a", "an", "of", "for", "and", "to", "in", "on", "at", "by", "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited"}
        return "".join(word[0] for word in words if word and word not in ignored)

    original_compact = re.sub(r"[^a-z0-9]+", "", original)
    alias_compact = re.sub(r"[^a-z0-9]+", "", alias)
    alias_acronym = acronym_from_words(alias_words)
    original_acronym = acronym_from_words(original_words)
    if acronym_prefix_expands_to_registry(original_name, alias_name) or acronym_prefix_expands_to_registry(alias_name, original_name):
        return True
    if 2 <= len(original_compact) <= 8 and original_compact == alias_acronym:
        return True
    if 2 <= len(alias_compact) <= 8 and alias_compact == original_acronym:
        return True

    def loose_word_stem(word: str) -> str:
        word = re.sub(r"[^a-z0-9]", "", word or "")
        if word.endswith("ies") and len(word) > 4:
            word = f"{word[:-3]}y"
        elif word.endswith("ier") and len(word) > 5:
            word = f"{word[:-3]}y"
        elif word.endswith("ing") and len(word) > 6:
            word = word[:-3]
        elif word.endswith("s") and len(word) > 4 and not word.endswith(("ss", "us")):
            word = word[:-1]
        return word

    def loose_word_overlap(left_words: list[str], right_words: list[str]) -> int:
        ignored = {
            "the", "a", "an", "of", "for", "and", "to", "in", "on", "at", "by",
            "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited",
            "local", "national",
        }
        left = [loose_word_stem(word) for word in left_words if word not in ignored]
        right = [loose_word_stem(word) for word in right_words if word not in ignored]
        count = 0
        matched_right: set[int] = set()
        for left_word in left:
            if len(left_word) < 4:
                continue
            for index, right_word in enumerate(right):
                if index in matched_right or len(right_word) < 4:
                    continue
                if left_word == right_word or left_word.startswith(right_word) or right_word.startswith(left_word):
                    matched_right.add(index)
                    count += 1
                    break
        return count

    alias_leading_token = alias_words[0] if alias_words else ""
    if (
        2 <= len(alias_leading_token) <= 6
        and alias_leading_token.isalpha()
        and original_acronym.startswith(alias_leading_token)
        and len(alias_words) >= 3
        and loose_word_overlap(original_words, alias_words[1:]) >= 2
    ):
        return True
    for index, word in enumerate(original_words):
        if not (2 <= len(word) <= 6 and word.isalpha()):
            continue
        for start in range(len(alias_words)):
            for end in range(start + 2, min(len(alias_words), start + 5) + 1):
                if acronym_from_words(alias_words[start:end]) != word:
                    continue
                expanded = original_words[:index] + alias_words[start:end] + original_words[index + 1:]
                if expanded == alias_words:
                    return True
                if (
                    len(expanded) == len(alias_words)
                    and expanded[:index] == alias_words[:index]
                    and expanded[index + (end - start):] == alias_words[end:]
                ):
                    return True

    governance_words = {"trustees", "curators", "regents", "board"}
    if original_words[0] in governance_words and alias_words[0] != original_words[0]:
        return False

    if alias in original or original in alias:
        shorter_words = alias_words if len(alias_words) <= len(original_words) else original_words
        if len(shorter_words) >= 3:
            return True
        # Allow established two-word fund aliases while
        # avoid broad two-word institution aliases such as "Allen Institute".
        if len(alias_words) == 2 and alias_words == original_words[:2] and alias_words[-1] == "fund":
            return True
        return False

    entity_words = {"foundation", "fund", "association", "society", "institute", "center", "centre", "network", "mission", "trust"}
    if (
        len(original_words) >= 3
        and len(alias_words) >= 3
        and original_words[:2] == alias_words[:2]
        and original_words[-1] == alias_words[-1]
        and original_words[-1] in entity_words
    ):
        generic_middle_words = {
            "the", "and", "of", "for", "to", "in", "on", "at", "by", "inc", "incorporated",
            "corp", "corporation", "llc", "ltd", "foundation", "fund", "charity", "charities",
            "association", "society", "center", "centre", "institute", "organization", "org",
            "university", "college", "school", "saint", "st",
        }
        original_middle = {word for word in original_words[2:-1] if word not in generic_middle_words}
        alias_middle = {word for word in alias_words[2:-1] if word not in generic_middle_words}
        if original_middle & alias_middle:
            return True

    generic_words = {
        "the", "and", "of", "for", "to", "in", "on", "at", "by", "inc", "incorporated",
        "corp", "corporation", "llc", "ltd", "foundation", "fund", "charity", "charities",
        "association", "society", "center", "centre", "institute", "organization", "org",
        "university", "college", "school", "saint", "st",
    }
    original_essential = {word for word in original_words if word not in generic_words}
    alias_essential = {word for word in alias_words if word not in generic_words}
    if original_essential and original_essential == alias_essential:
        return True
    shared_distinctive = original_essential & alias_essential
    union_distinctive = original_essential | alias_essential
    if len(shared_distinctive) >= 3 and union_distinctive and (len(shared_distinctive) / len(union_distinctive)) >= 0.8:
        return True

    return False


def short_acronym_prefix_registry_match(original_name: str, registry_name: str) -> bool:
    """Allow a short submitted acronym to match a longer registry legal name."""
    original_compact = re.sub(r"[^A-Za-z0-9]+", "", original_name or "")
    if not (2 <= len(original_compact) <= 6 and original_compact.upper() == original_compact):
        return False
    registry_words = re.findall(r"[A-Za-z0-9]+", registry_name or "")
    if len(registry_words) < 2:
        return False
    return registry_words[0].upper() == original_compact.upper()


def acronym_prefix_expands_to_registry(original_name: str, registry_name: str) -> bool:
    """Accept submitted forms like "ASEE / American Society..." safely.

    Some prospect lists include an acronym followed by the full legal name. If
    a state registry returns just the full legal name, the prefix is not a
    distinct organization term and should not trigger the missing-prefix guard.
    """
    original_norm = normalized_match_name(original_name)
    registry_norm = normalized_match_name(registry_name)
    if not original_norm or not registry_norm or not original_norm.endswith(registry_norm):
        return False
    original_words = original_norm.split()
    registry_words = registry_norm.split()
    if len(original_words) <= len(registry_words):
        return False
    prefix_words = original_words[: len(original_words) - len(registry_words)]
    if len(prefix_words) != 1:
        return False
    prefix = re.sub(r"[^a-z0-9]+", "", prefix_words[0])
    if not (2 <= len(prefix) <= 8 and prefix.isalpha()):
        return False
    ignored = {"the", "a", "an", "of", "for", "and", "to", "in", "on", "at", "by", "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited"}
    registry_acronym = "".join(word[0] for word in registry_words if word and word not in ignored)
    return prefix == registry_acronym[: len(prefix)]


def organization_match_target_variants(name: str, ein: str = "") -> list[str]:
    """Safe names used to accept a registry row after a broad search query.

    Name-only registries often need loose queries to find a row, but the row
    itself must still match the requested organization. These variants preserve
    safe aliases such as punctuation, leading/trailing "The", slash segments,
    hyphen variants, acronym expansion, and legal suffix differences while
    excluding broad two/three/four-word prefixes such as "Trustees Of".
    """
    variants = organization_name_variants(
        name,
        ein,
        include_ein_aliases=False,
        include_name_segments=True,
        include_and_segments=False,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
        include_broad_query_prefixes=False,
        include_institutional_reductions=False,
    )
    for alias in known_names_for_ein(ein):
        if compatible_ein_alias_for_name(name, alias):
            variants.extend(organization_name_variants(
                alias,
                "",
                include_ein_aliases=False,
                include_name_segments=True,
                include_and_segments=False,
                include_compact_legal_suffixes=True,
                include_leading_article_variants=True,
                include_broad_query_prefixes=False,
                include_institutional_reductions=False,
            ))
    return variants or [name]


def connector_light_name_variants(name: str) -> list[str]:
    variants: list[str] = []

    def add(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip(" ,;-"))
        if cleaned and cleaned.lower() not in {existing.lower() for existing in variants}:
            variants.append(cleaned)

    cleaned_name = re.sub(
        r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\b\.?\s*$",
        "",
        (name or "").strip(),
        flags=re.I,
    ).strip(" ,;-")
    parts = re.split(r"\s*(?:[/&+]|\band\b)\s*", cleaned_name, flags=re.I)
    if len(parts) < 2:
        return variants
    for left, right in zip(parts, parts[1:]):
        left_tokens = re.findall(r"[A-Za-z0-9]+", left or "")
        right_tokens = re.findall(r"[A-Za-z0-9]+", right or "")
        if not left_tokens or not right_tokens:
            continue
        left_token = left_tokens[-1]
        if len(left_token) <= 2 and len(left_tokens) >= 2:
            left_token = left_tokens[-2]
        normalized_left = re.sub(r"'?s$", "", left_token, flags=re.I)
        for token in [left_token, normalized_left]:
            if len(token) >= 3:
                add(" ".join([token, *right_tokens]))
                if len(right_tokens) > 1:
                    add(" ".join([token, *right_tokens[:-1]]))
        add(" ".join(right_tokens))
    return variants


def org_with_name(org, name: str):
    clone = SimpleNamespace(organization_name=name, ein=org.ein)
    clone.original_organization_name = getattr(org, "original_organization_name", getattr(org, "organization_name", ""))
    if hasattr(org, "match_target_names"):
        clone.match_target_names = getattr(org, "match_target_names")
    else:
        clone.match_target_names = organization_match_target_variants(getattr(org, "organization_name", ""), getattr(org, "ein", ""))
    if hasattr(org, "evidence_mode"):
        clone.evidence_mode = getattr(org, "evidence_mode")
    return clone


def result_registry_name_is_safe(result, original_name: str, ein: str = "") -> bool:
    registry_name = clean_registry_name(getattr(result, "matched_registry_name", "") or "")
    if not registry_name:
        return False
    return registry_name_is_safe_for_org(registry_name, original_name, ein)


def registry_name_is_safe_against_targets(registry_name: str, targets: list[str], original_name: str, ein: str = "") -> bool:
    registry_name = clean_registry_name(registry_name or "")
    if not registry_name:
        return False
    if registry_name_is_safe_for_org(registry_name, original_name, ein):
        return True
    if target_name_score(registry_name, targets) >= 700:
        return not (
            related_affiliate_or_chapter_mismatch(original_name, registry_name)
            or broad_governance_name_mismatch(original_name, registry_name)
            or incompatible_institutional_prefix_expansion(original_name, registry_name)
        )
    return False


def registry_name_is_safe_for_org(registry_name: str, original_name: str, ein: str = "") -> bool:
    registry_name = clean_registry_name(registry_name or "")
    if not registry_name:
        return False
    if related_affiliate_or_chapter_mismatch(original_name, registry_name):
        return False
    if legal_trustee_entity_match(original_name, registry_name):
        return True
    if shared_distinctive_core_match(original_name, registry_name):
        return True
    if charitable_wrapper_short_name_match(original_name, registry_name):
        return True
    if broad_governance_name_mismatch(original_name, registry_name):
        return False
    if incompatible_institutional_prefix_expansion(original_name, registry_name):
        return False
    if wrapped_supporting_foundation_match(registry_name, original_name):
        return True
    if parenthetical_descriptor_match(original_name, registry_name):
        return True
    if institutional_affiliation_suffix_match(original_name, registry_name):
        return True
    if descriptor_entity_extension_match(original_name, registry_name):
        return True
    if missing_distinctive_prefix_mismatch(original_name, registry_name):
        return False
    if distinctive_entity_extension_mismatch(original_name, registry_name):
        return False
    safe_targets = organization_match_target_variants(original_name, ein)
    if target_name_score(registry_name, safe_targets) >= 450:
        return True
    return compatible_ein_alias_for_name(original_name, registry_name)


def parenthetical_descriptor_match(original_name: str, registry_name: str) -> bool:
    match = re.search(r"\(([^)]{2,80})\)\s*$", registry_name or "")
    if not match:
        return False
    descriptor_norm = normalized_match_name(match.group(1))
    if not descriptor_norm:
        return False
    descriptor_words = descriptor_norm.split()
    allowed_descriptor_words = {
        "national", "headquarters", "headquarter", "hq", "main", "office",
        "principal", "central", "corporate",
    }
    if any(word not in allowed_descriptor_words for word in descriptor_words):
        return False
    base_name = re.sub(r"\s*\([^)]{2,80}\)\s*$", "", registry_name or "").strip()
    return normalized_match_name(base_name) == normalized_match_name(original_name)


def institutional_affiliation_suffix_match(original_name: str, registry_name: str) -> bool:
    """Allow exact full-name rows followed by a short institutional affiliation."""
    original_norm = normalized_match_name(original_name)
    registry_norm = normalized_match_name(registry_name)
    if not original_norm or not registry_norm or original_norm == registry_norm:
        return False
    original_words = original_norm.split()
    registry_words = registry_norm.split()
    if len(original_words) < 4 or len(registry_words) <= len(original_words):
        return False
    if registry_words[: len(original_words)] != original_words:
        return False
    suffix = registry_words[len(original_words):]
    if len(suffix) > 4 or suffix[0] not in {"of", "at"}:
        return False
    blocked = {"chapter", "affiliate", "auxiliary", "alumni", "booster", "foundation", "fund"}
    return not any(word in blocked for word in suffix)


def distinctive_core_words(value: str) -> list[str]:
    generic = {
        "the", "a", "an", "of", "for", "to", "and", "in", "on", "at", "by",
        "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited",
        "fund", "foundation", "association", "society", "organization", "charity",
        "charitable", "trust", "center", "centre", "national", "international",
        "global", "world", "worldwide",
    }
    return [
        word
        for word in normalized_match_name(value).split()
        if word not in generic and len(word) >= 3
    ]


def shared_distinctive_core_match(original_name: str, registry_name: str) -> bool:
    """Accept rows that share a long distinctive core with only descriptor-word differences."""
    original_core = distinctive_core_words(original_name)
    registry_core = distinctive_core_words(registry_name)
    if len(original_core) < 3 or len(registry_core) < 3:
        return False
    return original_core == registry_core


def charitable_wrapper_short_name_match(original_name: str, registry_name: str) -> bool:
    """Allow generic wrapper forms such as "Fund for the X" when X is the leading requested name."""
    registry_norm = normalized_match_name(registry_name)
    original_norm = normalized_match_name(original_name)
    if not registry_norm or not original_norm:
        return False
    wrapper_match = re.match(r"^(?:fund|foundation|friends)\s+(?:for|of)\s+(.+)$", registry_norm)
    if not wrapper_match:
        return False
    wrapper_target = re.sub(r"\s+", " ", wrapper_match.group(1)).strip()
    if not wrapper_target:
        return False
    wrapper_words = wrapper_target.split()
    if len(wrapper_words) < 2:
        return False
    return original_norm.startswith(f"{wrapper_target} ")


def wrapped_supporting_foundation_match(registry_name: str, original_name: str) -> bool:
    registry_norm = normalized_match_name(registry_name)
    original_norm = normalized_match_name(original_name)
    if not registry_norm or not original_norm or registry_norm == original_norm:
        return False
    original_words = original_norm.split()
    if len(original_words) < 4 or not registry_norm.endswith(original_norm):
        return False
    prefix_words = registry_norm[: -len(original_norm)].strip().split()
    if not prefix_words or len(prefix_words) > 5:
        return False
    return "foundation" in prefix_words and not any(
        word in {"chapter", "affiliate", "auxiliary", "alumni", "booster"}
        for word in prefix_words
    )


def descriptor_entity_extension_match(original_name: str, registry_name: str) -> bool:
    original_norm = normalized_match_name(original_name)
    registry_norm = normalized_match_name(registry_name)
    if not original_norm or not registry_norm or original_norm == registry_norm:
        return False
    original_words = original_norm.split()
    registry_words = registry_norm.split()
    ignored_words = {
        "the", "a", "an", "of", "for", "and", "to", "in", "on", "at", "by",
        "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited",
        "co", "company",
    }
    descriptor_words = {
        "national", "international", "global", "worldwide", "world", "america",
        "medical", "center", "centre", "hospital", "health", "system",
    }

    def safe_extra(words: list[str]) -> bool:
        extra = [word for word in words if word not in ignored_words]
        return bool(extra) and all(word in descriptor_words for word in extra)

    if len(registry_words) > len(original_words):
        if registry_words[: len(original_words)] == original_words:
            return safe_extra(registry_words[len(original_words):])
        if registry_words[-len(original_words):] == original_words:
            return safe_extra(registry_words[:-len(original_words)])
    if len(original_words) > len(registry_words):
        if original_words[: len(registry_words)] == registry_words:
            return safe_extra(original_words[len(registry_words):])
        if original_words[-len(registry_words):] == registry_words:
            return safe_extra(original_words[:-len(registry_words)])
    return False


def distinctive_entity_extension_mismatch(original_name: str, registry_name: str) -> bool:
    original_norm = normalized_match_name(original_name)
    registry_norm = normalized_match_name(registry_name)
    if not original_norm or not registry_norm or original_norm == registry_norm:
        return False
    original_words = original_norm.split()
    registry_words = registry_norm.split()
    if not original_words or not registry_words:
        return False

    ignored_extension_words = {
        "the", "a", "an", "of", "for", "and", "to", "in", "on", "at", "by",
        "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited",
        "co", "company",
    }
    safe_descriptor_extension_words = {
        "national", "international", "global", "worldwide", "world", "america",
        "medical", "center", "centre", "hospital", "health", "system",
    }

    def acronym(words: list[str]) -> str:
        return "".join(word[0] for word in words if word and word not in ignored_extension_words)

    def extension_is_safe(extra_words: list[str], base_words: list[str]) -> bool:
        extra = [word for word in extra_words if word not in ignored_extension_words]
        if not extra:
            return True
        if all(word in safe_descriptor_extension_words for word in extra):
            return True
        compact_extra = "".join(extra)
        base_acronym = acronym(base_words)
        if 2 <= len(compact_extra) <= 8 and compact_extra == base_acronym:
            return True
        if len(extra) == 1 and 2 <= len(extra[0]) <= 8 and extra[0] == base_acronym[: len(extra[0])]:
            return True
        return False

    if len(registry_words) > len(original_words):
        if registry_words[-len(original_words):] == original_words:
            return not extension_is_safe(registry_words[:-len(original_words)], original_words)
        if registry_words[:len(original_words)] == original_words:
            return not extension_is_safe(registry_words[len(original_words):], original_words)
    if len(original_words) > len(registry_words):
        if original_words[:len(registry_words)] == registry_words:
            return not extension_is_safe(original_words[len(registry_words):], registry_words)
        if original_words[-len(registry_words):] == registry_words:
            return not (
                extension_is_safe(original_words[:-len(registry_words)], registry_words)
                or acronym_prefix_expands_to_registry(original_name, registry_name)
            )
    return False


def missing_distinctive_prefix_mismatch(original_name: str, registry_name: str) -> bool:
    original_norm = normalized_match_name(original_name)
    registry_norm = normalized_match_name(registry_name)
    if not original_norm or not registry_norm or original_norm == registry_norm:
        return False
    if not original_norm.endswith(registry_norm):
        return False
    original_words = original_norm.split()
    registry_words = registry_norm.split()
    if len(original_words) <= len(registry_words):
        return False
    prefix_words = original_words[: len(original_words) - len(registry_words)]
    if acronym_prefix_expands_to_registry(original_name, registry_name):
        return False
    generic_prefix_words = {"the", "a", "an", "of", "for", "to", "and", "dba", "aka"}
    return any(word not in generic_prefix_words for word in prefix_words)


def related_affiliate_or_chapter_mismatch(original_name: str, registry_name: str) -> bool:
    original_norm = normalized_match_name(original_name)
    registry_norm = normalized_match_name(registry_name)
    if not original_norm or not registry_norm:
        return False
    related_terms = {"affiliate", "chapter"}
    original_terms = set(original_norm.split())
    registry_terms = set(registry_norm.split())
    return any(term in registry_terms and term not in original_terms for term in related_terms)


def legal_trustee_entity_match(original_name: str, registry_name: str) -> bool:
    original_norm = normalized_match_name(original_name)
    registry_norm = normalized_match_name(registry_name)
    if not original_norm or not registry_norm:
        return False
    match = re.match(r"^(?:the\s+)?trustees\s+of\s+(.+)$", original_norm)
    if not match:
        return False
    trustee_target = re.sub(r"\s+", " ", match.group(1)).strip()
    return bool(trustee_target) and registry_norm == trustee_target


def broad_governance_name_mismatch(original_name: str, registry_name: str) -> bool:
    original_norm = normalized_match_name(original_name)
    registry_norm = normalized_match_name(registry_name)
    if not original_norm or not registry_norm:
        return False
    original_words = original_norm.split()
    registry_words = registry_norm.split()
    governance_words = {"trustees", "curators", "regents", "board"}
    if not any(word in governance_words for word in original_words[:2]):
        return False
    if any(word in governance_words for word in registry_words):
        return False
    registry_terms = set(registry_words)
    original_terms = set(original_words)
    if registry_terms <= original_terms and len(original_words) - len(registry_words) >= 3:
        return True
    affiliate_terms = {"alumni", "booster", "chapter", "affiliate", "auxiliary"}
    return bool(registry_terms & affiliate_terms)


def incompatible_institutional_prefix_expansion(original_name: str, registry_name: str) -> bool:
    reduced = institutional_tail_reduction(original_name)
    if not reduced or reduced.lower() == (original_name or "").strip().lower():
        return False
    reduced_norm = normalized_match_name(reduced)
    original_norm = normalized_match_name(original_name)
    registry_norm = normalized_match_name(registry_name)
    if not reduced_norm or not original_norm or not registry_norm:
        return False
    if registry_norm == reduced_norm:
        return False
    return registry_norm.startswith(f"{reduced_norm} ") and not original_norm.startswith(registry_norm)


def copy_name_fallback_result(original_org, result):
    result.organization_name = original_org.organization_name
    result.ein = original_org.ein
    return result


def quick_registry_preflight(url: str, timeout_seconds: float) -> tuple[bool, str]:
    try:
        request = urllib.request.Request(
            url,
            headers={"User-Agent": "Mozilla/5.0 CharityClarity preflight"},
        )
        with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
            return response.status < 500, f"HTTP {response.status}"
    except urllib.error.HTTPError as exc:
        # Some older state sites prove reachability with redirects that urllib
        # treats as errors. A non-5xx HTTP response is still enough to continue.
        return exc.code < 500, f"HTTP {exc.code}"
    except Exception as exc:
        return False, str(exc)


def preflight_name_search_registry(org, state: str) -> tuple[bool, str, object | None]:
    state = state.upper()
    url = NAME_SEARCH_PREFLIGHT_URLS.get(state)
    if not url:
        return True, "", None
    timeout = SC_PREFLIGHT_TIMEOUT_SECONDS if state == "SC" else NAME_SEARCH_PREFLIGHT_TIMEOUT_SECONDS
    reachable, note = quick_registry_preflight(url, timeout)
    if reachable:
        return True, note, None
    result = checker.StateResult(org.organization_name, org.ein, state, "Site Not Reachable", url)
    result.raw_status_text = f"{state} registry preflight failed"
    result.source_note = f"{state} public registry did not respond to a quick preflight check: {note}"
    result.error = f"{state} preflight failed: {note}"
    result.success = False
    return False, note, result


def explicit_ar_registry_status(result) -> str:
    if (getattr(result, "state", "") or "").upper() != "AR":
        return ""
    text = " | ".join([
        getattr(result, "status", "") or "",
        getattr(result, "raw_status_text", "") or "",
        getattr(result, "source_note", "") or "",
    ])
    match = re.search(r"\bStatus\s*:\s*([^|;\n\r]+)", text, re.I)
    status_text = match.group(1) if match else text
    mapped = ar_status_from_text(status_text)
    return mapped if mapped != checker.STATUS_UNKNOWN else ""


def search_sc_resilient(page, org):
    reachable, _, preflight_result = preflight_name_search_registry(org, "SC")
    result = search_with_name_variants(
        page,
        org,
        checker.search_sc,
        max_variants=10,
        max_elapsed_seconds=SC_NAME_VARIANT_MAX_SECONDS,
        include_ein_aliases=True,
        include_name_segments=True,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
    )
    if not reachable and public_status(result) in {"Site Not Reachable", "Unknown", ""}:
        return preflight_result
    return result


def result_is_retryable_name_miss(result) -> bool:
    return public_status(result) == "Not Registered" or bool(re.search(
        r"no matching|no record found|no records found|not found|no results|0 records|0 results",
        " ".join([result.status or "", result.raw_status_text or "", result.source_note or ""]),
        re.I,
    ))


def is_leading_the_drop(original_name: str, variant: str) -> bool:
    original = re.sub(r"\s+", " ", (original_name or "").strip())
    candidate = re.sub(r"\s+", " ", (variant or "").strip())
    if not re.match(r"^the\s+", original, re.I):
        return False
    if re.match(r"^the\s+", candidate, re.I):
        return False
    without_the = re.sub(r"^the\s+", "", original, flags=re.I).strip()
    normalize = getattr(checker, "normalize_name", lambda value: re.sub(r"\W+", " ", (value or "").lower()).strip())
    without_the_norm = normalize(without_the)
    candidate_norm = normalize(candidate)
    return bool(candidate_norm and without_the_norm and (candidate_norm in without_the_norm or without_the_norm in candidate_norm))


def search_with_name_variants(
    page,
    org,
    search_func,
    max_variants: int | None = None,
    max_elapsed_seconds: float | None = None,
    reject_va_suspended_from_leading_the_drop: bool = False,
    include_ein_aliases: bool = True,
    include_name_segments: bool = False,
    include_and_segments: bool = True,
    include_compact_legal_suffixes: bool = True,
    include_leading_article_variants: bool = True,
    prioritize_institution_reductions: bool = False,
    require_safe_registry_name: bool = False,
    preferred_variants: list[str] | None = None,
):
    best_result = None
    original_name = org.organization_name
    variants = organization_name_variants(
        original_name,
        org.ein,
        include_ein_aliases=include_ein_aliases,
        include_name_segments=include_name_segments,
        include_and_segments=include_and_segments,
        include_compact_legal_suffixes=include_compact_legal_suffixes,
        include_leading_article_variants=include_leading_article_variants,
    )
    if include_ein_aliases:
        alias_priority = [
            alias for alias in known_names_for_ein(org.ein)
            if compatible_ein_alias_for_name(original_name, alias)
        ]
        prioritized = []
        for variant in [variants[0] if variants else original_name, *alias_priority, *variants[1:]]:
            cleaned = re.sub(r"\s+", " ", (variant or "").strip())
            if cleaned and cleaned.lower() not in {existing.lower() for existing in prioritized}:
                prioritized.append(cleaned)
        variants = prioritized or variants
    if include_leading_article_variants and re.match(r"^(?:the|a|an)\s+", original_name or "", re.I):
        article_drop = re.sub(r"^(?:the|a|an)\s+", "", original_name or "", flags=re.I).strip()
        article_drop_no_suffix = re.sub(
            r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?)\s*$",
            "",
            re.sub(r",\s*(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?)\s*$", "", article_drop, flags=re.I).strip(),
            flags=re.I,
        ).strip()
        prioritized = []
        for variant in [article_drop, article_drop_no_suffix, variants[0] if variants else "", *variants[1:]]:
            cleaned = re.sub(r"\s+", " ", (variant or "").strip())
            if cleaned and cleaned.lower() not in {existing.lower() for existing in prioritized}:
                prioritized.append(cleaned)
        variants = prioritized or variants
    if prioritize_institution_reductions:
        variants = prioritized_institutional_variants(variants)
    if preferred_variants:
        prioritized = []
        for variant in [*preferred_variants, *variants]:
            cleaned = re.sub(r"\s+", " ", (variant or "").strip())
            if cleaned and cleaned.lower() not in {existing.lower() for existing in prioritized}:
                prioritized.append(cleaned)
        variants = prioritized or variants
    safe_match_targets = organization_match_target_variants(original_name, org.ein)
    if max_variants:
        variants = variants[:max_variants]
    started = time.perf_counter()
    for variant in variants:
        if max_elapsed_seconds and best_result is not None and (time.perf_counter() - started) >= max_elapsed_seconds:
            if getattr(best_result, "organization_name", "") != original_name:
                best_result.organization_name = original_name
            return best_result
        variant_org = org_with_name(org, variant)
        variant_org.match_target_names = safe_match_targets
        result = search_func(page, variant_org)
        if getattr(result, "organization_name", "") != original_name:
            result.organization_name = original_name
        if public_status(result) == "Site Not Reachable":
            return result
        if (
            reject_va_suspended_from_leading_the_drop
            and public_status(result) == "Suspended"
            and is_leading_the_drop(original_name, variant)
        ):
            continue
        if (
            require_safe_registry_name
            and public_status(result) not in {"Not Registered", "Site Not Reachable"}
            and (getattr(result, "matched_registry_name", "") or "").strip()
            and not result_registry_name_is_safe(result, original_name, org.ein)
        ):
            replacement = checker.StateResult(
                original_name,
                org.ein,
                getattr(result, "state", "") or "",
                checker.STATUS_NOT_REGISTERED,
                getattr(result, "source_url", "") or "",
                raw_status_text="Registry name did not safely match the requested organization",
                source_note="The public registry returned a row, but CharityClarity rejected it because the registry name did not safely match the requested organization.",
                success=True,
            )
            best_result = replacement
            continue
        if not result_is_retryable_name_miss(result):
            return result
        best_result = result
    if best_result and getattr(best_result, "organization_name", "") != original_name:
        best_result.organization_name = original_name
    return best_result


def search_va_bounded(page, org):
    # Virginia's search helper already generates punctuation/article/name
    # variants internally. During no-match cases, trying the full internal list
    # for every outer variant can make a clean Not Registered result take more
    # than a minute. Limit the internal query list to the strongest few forms
    # while keeping the normal candidate matching and detail parsing.
    with VA_SEARCH_VARIANT_LOCK:
        original_variant_builder = checker.search_name_query_variants
        original_click_search_button = checker.click_va_search_button

        def bounded_variants(name: str, max_words: int = 5):
            generated = original_variant_builder(name, max_words=max_words)
            bounded = []

            def add(value: str) -> None:
                value = re.sub(r"\s+", " ", (value or "").strip())
                if value and value not in bounded:
                    bounded.append(value)

            for variant in generated[:3]:
                add(variant)
            for variant in generated:
                if "-" in variant or re.match(r"^(?:the|a|an)\s+", variant, re.I):
                    add(variant)
                if len(bounded) >= 6:
                    break
            return bounded or generated[:2]

        def robust_click_va_search_button(inner_page) -> bool:
            if original_click_search_button(inner_page):
                return True
            for sel in [
                'input[type="submit"][value="SEARCH"]',
                'input[name="submit"]',
                'input[type="submit"]',
            ]:
                try:
                    btn = inner_page.locator(sel).first
                    if btn.count():
                        btn.click(timeout=3000, force=True, no_wait_after=True)
                        return True
                except Exception:
                    continue
            try:
                inner_page.locator("#id_orgname").press("Enter", timeout=2000)
                return True
            except Exception:
                pass
            try:
                submitted = inner_page.evaluate(
                    """() => {
                        const form = document.querySelector('form');
                        if (!form) return false;
                        form.submit();
                        return true;
                    }"""
                )
                return bool(submitted)
            except Exception:
                return False

        checker.search_name_query_variants = bounded_variants
        checker.click_va_search_button = robust_click_va_search_button
        try:
            return checker.search_va(page, org)
        finally:
            checker.search_name_query_variants = original_variant_builder
            checker.click_va_search_button = original_click_search_button


def va_html_to_text(value: str) -> str:
    text = re.sub(r"(?i)<\s*br\s*/?\s*>", "\n", value or "")
    text = re.sub(r"(?i)</\s*(?:p|div|tr|li|h[1-6]|td|th)\s*>", "\n", text)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    lines = [re.sub(r"\s+", " ", line).strip() for line in text.splitlines()]
    return "\n".join(line for line in lines if line)


def va_labeled_value(text: str, label: str) -> str:
    pattern = rf"{re.escape(label)}\s*:?\s*(.*?)(?=\s+(?:Primary Name|Other Names|Current Registration Expires|Registration Extended Until|Registration Filing Status|Address)\s*:|$)"
    match = re.search(pattern, text or "", re.I | re.S)
    if not match:
        return ""
    return re.sub(r"\s+", " ", match.group(1)).strip()


def va_direct_request(url: str, data: dict[str, str] | None = None, timeout_seconds: float = 16.0) -> str:
    encoded = urlencode(data).encode("utf-8") if data is not None else None
    headers = {
        "User-Agent": BROWSER_USER_AGENT,
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Content-Type": "application/x-www-form-urlencoded",
        "Origin": "https://cos.vdacs.virginia.gov",
        "Referer": NAME_SEARCH_PREFLIGHT_URLS["VA"],
    }
    last_error = None
    for attempt in range(2):
        try:
            request = urllib.request.Request(url, data=encoded, headers=headers, method="POST" if data is not None else "GET")
            with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
                charset = response.headers.get_content_charset() or "utf-8"
                return response.read().decode(charset, errors="replace")
        except Exception as exc:
            last_error = exc
            if attempt == 0:
                time.sleep(0.8)
    raise last_error


def va_result_links(search_html: str) -> list[tuple[str, str, str]]:
    links = []
    for match in re.finditer(r"<a\s+[^>]*href=(?:\"([^\"]+)\"|'([^']+)'|([^>\s]+))[^>]*>(.*?)</a>", search_html or "", re.I | re.S):
        href = html.unescape((match.group(1) or match.group(2) or match.group(3) or "").strip())
        if "act=2" not in href or "sysorgno=" not in href:
            continue
        link_text = re.sub(r"<[^>]+>", " ", match.group(4) or "")
        link_text = re.sub(r"\s+", " ", html.unescape(link_text)).strip()
        parsed = urlparse(urljoin(NAME_SEARCH_PREFLIGHT_URLS["VA"], href))
        identifier = (parse_qs(parsed.query).get("sysorgno") or [""])[0].strip()
        links.append((href, link_text, identifier))
    return links


def va_registry_status_from_detail(detail_text: str) -> str:
    filing_status = va_labeled_value(detail_text, "Registration Filing Status")
    combined = " ".join([detail_text or "", filing_status])
    if re.search(r"\bnot\s+authorized\s+to\s+solicit|cease\s+and\s+desist|suspended\b", combined, re.I):
        return "Suspended"
    if re.search(r"\b(?:withdrawn|closed|cancel(?:ed|led)|terminated|inactive)\b", combined, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(r"\bpending|in\s+process\b", filing_status, re.I):
        return "Pending"

    extended_until = va_labeled_value(detail_text, "Registration Extended Until")
    expires = va_labeled_value(detail_text, "Current Registration Expires")
    extension_date = parse_due_date(extended_until) if not re.fullmatch(r"N/?A|None|Not Applicable", extended_until or "", re.I) else None
    expiration_date = parse_due_date(expires)
    effective_date = extension_date or expiration_date
    if effective_date:
        return status_from_calendar_date(effective_date)
    if re.search(r"\bfinancial\s+data\s+available|registers\s+annually|registered\b", filing_status, re.I):
        return "Current"
    return checker.STATUS_UNKNOWN


def va_detail_confirms_requested_ein(detail_text: str, org) -> bool:
    requested = canonical_ein_digits(getattr(org, "ein", "") or "")
    if len(requested) != 9:
        return False
    return requested in re.sub(r"\D", "", detail_text or "")


def va_expanded_other_name_matches_requested(alias: str, requested_name: str) -> bool:
    alias_key = normalized_match_name(alias)
    requested_key = normalized_match_name(requested_name)
    if not alias_key or not requested_key:
        return False
    alias_words = alias_key.split()
    requested_words = requested_key.split()
    if len(requested_words) < 2 or len(alias_words) <= len(requested_words):
        return False
    if alias_words[-len(requested_words):] != requested_words:
        return False
    extra_words = alias_words[:-len(requested_words)]
    return 1 <= len(extra_words) <= 2


def search_va_direct(org):
    url = NAME_SEARCH_PREFLIGHT_URLS["VA"]
    variants = []

    def add_variant(value: str) -> None:
        value = re.sub(r"\s+", " ", (value or "").strip())
        if value and value not in variants:
            variants.append(value)

    def add_va_core_forms(value: str) -> None:
        add_variant(value)
        stripped = re.sub(
            r"\s*,?\s+\b(?:inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\b\.?\s*$",
            "",
            value or "",
            flags=re.I,
        ).strip()
        add_variant(stripped)
        add_variant(re.sub(r"^(?:the|a|an)\s+", "", value or "", flags=re.I).strip())
        if stripped:
            add_variant(re.sub(r"^(?:the|a|an)\s+", "", stripped, flags=re.I).strip())

    add_va_core_forms(org.organization_name)
    for alias in known_names_for_ein(org.ein):
        if compatible_ein_alias_for_name(org.organization_name, alias):
            add_va_core_forms(alias)
    generated_variants = prioritized_institutional_variants(organization_name_variants(
        org.organization_name,
        org.ein,
        include_ein_aliases=True,
        include_name_segments=True,
        include_and_segments=False,
        include_compact_legal_suffixes=False,
        include_leading_article_variants=True,
        include_institutional_reductions=True,
    ))
    for generated in generated_variants:
        if len(variants) >= 8:
            break
        add_variant(generated)
    variants = variants[:8]
    targets = organization_match_target_variants(org.organization_name, org.ein)
    best_rejected_name = ""
    last_error = ""

    for variant in variants:
        try:
            search_html = va_direct_request(url, {"act": "1", "orgname": variant, "submit": "SEARCH"})
        except Exception as exc:
            last_error = str(exc)
            continue

        links = va_result_links(search_html)
        if not links:
            if re.search(r"No\s+record\s+found|No\s+records?\s+found|No\s+matching", search_html or "", re.I):
                continue
            continue

        safe_links = []
        identity_probe_links = []
        for href, link_text, identifier in links:
            if registry_name_is_safe_for_org(link_text, org.organization_name, org.ein) or short_acronym_prefix_registry_match(org.organization_name, link_text):
                safe_links.append((target_name_score(link_text, targets), href, link_text, identifier))
            elif not best_rejected_name:
                best_rejected_name = link_text
                identity_probe_links.append((-1, href, link_text, identifier))
            elif len(identity_probe_links) < 3:
                identity_probe_links.append((-1, href, link_text, identifier))

        candidate_links = safe_links + identity_probe_links
        if not candidate_links:
            continue

        accepted_details = []
        for order_index, (_, href, link_text, identifier) in enumerate(sorted(candidate_links, key=lambda item: item[0], reverse=True)):
            detail_url = urljoin(url, href)
            try:
                detail_html = va_direct_request(detail_url, timeout_seconds=16.0)
            except Exception as exc:
                last_error = str(exc)
                continue

            detail_text = va_html_to_text(detail_html)
            primary_name = va_labeled_value(detail_text, "Primary Name") or link_text
            other_names = va_labeled_value(detail_text, "Other Names")
            detail_ein_match = va_detail_confirms_requested_ein(detail_text, org)
            expanded_alias_match = any(
                va_expanded_other_name_matches_requested(alias, org.organization_name)
                for alias in re.split(r"\s*(?:;|\||/|, aka | aka | dba | doing business as | also soliciting as )\s*", other_names or "", flags=re.I)
                if alias.strip()
            )
            if primary_name and not (
                registry_name_is_safe_for_org(primary_name, org.organization_name, org.ein)
                or short_acronym_prefix_registry_match(org.organization_name, primary_name)
                or detail_ein_match
                or expanded_alias_match
            ):
                best_rejected_name = primary_name
                continue

            current_expires = va_labeled_value(detail_text, "Current Registration Expires")
            extended_until = va_labeled_value(detail_text, "Registration Extended Until")
            extension_date = parse_due_date(extended_until) if not re.fullmatch(r"N/?A|None|Not Applicable", extended_until or "", re.I) else None
            expiration_date = parse_due_date(current_expires)
            effective_date = extension_date or expiration_date
            raw_status = " | ".join(
                part for part in [
                    f"Primary Name: {primary_name}" if primary_name else "",
                    f"Other Names: {va_labeled_value(detail_text, 'Other Names')}" if va_labeled_value(detail_text, "Other Names") else "",
                    f"Current Registration Expires: {current_expires}" if current_expires else "",
                    f"Registration Extended Until: {extended_until}" if extended_until else "",
                    f"Registration Filing Status: {va_labeled_value(detail_text, 'Registration Filing Status')}" if va_labeled_value(detail_text, "Registration Filing Status") else "",
                ]
                if part
            ) or detail_text[:1000]
            accepted_details.append({
                "order": order_index,
                "effective_date": effective_date,
                "detail_url": detail_url,
                "raw_status": raw_status,
                "status": va_registry_status_from_detail(detail_text),
                "primary_name": primary_name,
                "display_name": other_names if expanded_alias_match and other_names else primary_name,
                "identifier": identifier,
                "detail_ein_match": detail_ein_match,
                "expanded_alias_match": expanded_alias_match,
            })

        if accepted_details:
            selected = max(
                accepted_details,
                key=lambda item: (item["effective_date"] or date.min, -item["order"]),
            )
            result = checker.StateResult(org.organization_name, org.ein, "VA", selected["status"], selected["detail_url"])
            result.raw_status_text = selected["raw_status"]
            result.source_note = (
                "Virginia public registry was searched directly by name; when multiple accepted links existed, "
                "CharityClarity selected the most recent accepted detail record."
            )
            if selected.get("detail_ein_match"):
                result.source_note += " The selected Virginia detail page exposed the requested EIN, so CharityClarity accepted the identity even though the visible registry name was an expanded form."
            if selected.get("expanded_alias_match"):
                result.source_note += " The selected Virginia detail listed an Other Names alias that expands the requested organization name."
            result.matched_registry_name = selected.get("display_name") or selected["primary_name"]
            result.matched_registry_identifier = selected["identifier"]
            result.success = True
            return result

    result = checker.StateResult(
        org.organization_name,
        org.ein,
        "VA",
        checker.STATUS_NOT_REGISTERED,
        url,
        raw_status_text=(
            "No matching Virginia organization record"
            if not best_rejected_name
            else f"Virginia returned rows, but none safely matched. First rejected row: {best_rejected_name}"
        ),
        source_note="Virginia public charity search returned no safely matching organization record for the generated name variants.",
        success=True,
    )
    if last_error:
        result.source_note += f" Last transient lookup error before no-match fallback: {last_error[:160]}"
    return result


def me_fast_direct_query_variants(org) -> list[str]:
    variants: list[str] = []

    def add(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip())
        if cleaned and cleaned.lower() not in {existing.lower() for existing in variants}:
            variants.append(cleaned)

    original_name = getattr(org, "organization_name", "")
    add(original_name)
    leading_article_removed = re.sub(r"^(?:the|a|an)\s+", "", original_name or "", flags=re.I).strip()
    add(leading_article_removed)
    for alias in known_names_for_ein(getattr(org, "ein", "")):
        if compatible_ein_alias_for_name(original_name, alias):
            add(alias)
            add(re.sub(r"^(?:the|a|an)\s+", "", alias or "", flags=re.I).strip())

    for variant in organization_name_variants(
        original_name,
        getattr(org, "ein", ""),
        include_ein_aliases=True,
        include_name_segments=True,
        include_and_segments=False,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
        include_broad_query_prefixes=False,
    ):
        add(variant)

    for alias in known_names_for_ein(getattr(org, "ein", "")):
        if not compatible_ein_alias_for_name(original_name, alias):
            continue
        for variant in organization_name_variants(
            alias,
            "",
            include_ein_aliases=False,
            include_name_segments=True,
            include_and_segments=False,
            include_compact_legal_suffixes=True,
            include_leading_article_variants=True,
            include_broad_query_prefixes=False,
        ):
            add(variant)
    return variants[:ME_FAST_DIRECT_CONFIRMATION_MAX_VARIANTS]


def me_fast_direct_search_rows(query: str) -> tuple[list[dict[str, str]], urllib.request.OpenerDirector]:
    url = NAME_SEARCH_PREFLIGHT_URLS["ME"]
    cookie_jar = http.cookiejar.CookieJar()
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cookie_jar))
    opener.addheaders = [
        ("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"),
        ("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8"),
        ("Accept-Language", "en-US,en;q=0.9"),
        ("Upgrade-Insecure-Requests", "1"),
    ]
    response = opener.open(url, timeout=ME_FAST_DIRECT_GET_TIMEOUT_SECONDS)
    html_text = response.read().decode("utf-8", "replace")
    fields: dict[str, str] = {}
    for hidden in re.finditer(r'<input[^>]+type="hidden"[^>]*>', html_text, re.I):
        tag = hidden.group(0)
        name_match = re.search(r'name="([^"]+)"', tag, re.I)
        value_match = re.search(r'value="([^"]*)"', tag, re.I)
        if name_match:
            fields[html.unescape(name_match.group(1))] = html.unescape(value_match.group(1) if value_match else "")
    fields.update({
        "ctl00$ctl00$mainContent$mainContent$scRegulator": "4076",
        "ctl00$ctl00$mainContent$mainContent$scCompanyName": query or "",
        "ctl00$ctl00$mainContent$mainContent$ctl24": "BW",
        "ctl00$ctl00$mainContent$mainContent$btnSearch": "Search",
    })
    request = urllib.request.Request(
        f"{url}?AspxAutoDetectCookieSupport=1",
        data=urlencode(fields).encode("utf-8"),
        method="POST",
    )
    request.add_header("Content-Type", "application/x-www-form-urlencoded")
    request.add_header("Origin", "https://www.pfr.maine.gov")
    request.add_header("Referer", url)
    posted = opener.open(request, timeout=ME_FAST_DIRECT_POST_TIMEOUT_SECONDS)
    result_html = posted.read().decode("utf-8", "replace")
    rows: list[dict[str, str]] = []
    for match in re.finditer(
        r'<tr[^>]*>\s*<td[^>]*>\s*<a\s+href="(?P<href>ShowDetail\.aspx[^"]+)"[^>]*>(?P<name>.*?)</a>\s*</td>\s*'
        r'<td[^>]*>(?P<number>.*?)</td>\s*<td[^>]*>(?P<location>.*?)</td>\s*'
        r'<td[^>]*>(?P<profession>.*?)</td>\s*<td[^>]*>(?P<status>.*?)</td>',
        result_html,
        re.I | re.S,
    ):
        rows.append({
            "href": html.unescape(match.group("href")),
            "name": re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", match.group("name")))).strip(),
            "number": re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", match.group("number")))).strip(),
            "location": re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", match.group("location")))).strip(),
            "profession": re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", match.group("profession")))).strip(),
            "status": re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", match.group("status")))).strip(),
        })
    return rows, opener


def me_fast_direct_confirmation_result(org):
    target_names = organization_match_target_variants(getattr(org, "organization_name", ""), getattr(org, "ein", ""))
    best_row = None
    best_opener = None
    best_score = (-999, -999)
    last_error = ""
    checked_any = False

    for query in me_fast_direct_query_variants(org):
        try:
            rows, opener = me_fast_direct_search_rows(query)
        except Exception as exc:
            last_error = f"{type(exc).__name__}: {str(exc)[:120]}"
            continue
        checked_any = True
        for row in rows:
            row_text = " ".join(row.get(key, "") for key in ["name", "number", "location", "profession", "status"])
            row_score = checker.candidate_selection_score_for_targets(row.get("name", ""), target_names, row_text)
            if row_score[0] < 0:
                continue
            if not registry_name_is_safe_for_org(row.get("name", ""), getattr(org, "organization_name", ""), getattr(org, "ein", "")):
                continue
            if row_score > best_score:
                best_score = row_score
                best_row = row
                best_opener = opener
        if best_row and best_opener:
            break

    if not best_row or not best_opener:
        if checked_any:
            result = checker.StateResult(
                getattr(org, "organization_name", ""),
                getattr(org, "ein", ""),
                "ME",
                checker.STATUS_NOT_REGISTERED,
                NAME_SEARCH_PREFLIGHT_URLS["ME"],
                raw_status_text="No matching organization record",
                source_note="Maine fast direct public registry search returned no matching organization record for the generated name variants.",
                success=True,
            )
            if last_error:
                result.source_note += f" Last non-fatal direct-confirmation error: {last_error}"
            setattr(result, "_cc_detail_body", "0 records found. Maine fast direct public registry search returned no matching organization record.")
            return result
        return None

    detail_url = urljoin("https://www.pfr.maine.gov/ALMSOnline/ALMSQuery/", best_row.get("href", ""))
    detail_text = ""
    try:
        detail_response = best_opener.open(detail_url, timeout=ME_FAST_DIRECT_DETAIL_TIMEOUT_SECONDS)
        detail_html = detail_response.read().decode("utf-8", "replace")
        detail_text = re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", detail_html))).strip()
    except Exception as exc:
        last_error = f"{type(exc).__name__}: {str(exc)[:120]}"

    status_text = ""
    expiration_text = ""
    if detail_text:
        status_match = re.search(r"\bStatus:\s*(.+?)\s+Expiration\s+Date:", detail_text, re.I)
        expiration_match = re.search(r"\bExpiration\s+Date:\s*(\d{1,2}/\d{1,2}/\d{4})", detail_text, re.I)
        status_text = (status_match.group(1).strip() if status_match else "") or checker.extract_labeled_value_from_text(detail_text, ["Status"])
        expiration_text = (expiration_match.group(1).strip() if expiration_match else "") or checker.extract_labeled_value_from_text(detail_text, ["Expiration Date", "Expiration"])
    if not status_text:
        status_text = best_row.get("status", "") or checker.STATUS_UNKNOWN

    result = checker.StateResult(
        getattr(org, "organization_name", ""),
        getattr(org, "ein", ""),
        "ME",
        status_text,
        detail_url or NAME_SEARCH_PREFLIGHT_URLS["ME"],
    )
    result.matched_registry_name = best_row.get("name", "")
    result.matched_registry_identifier = best_row.get("number", "")
    result.raw_status_text = "; ".join(
        part for part in [status_text, f"Expiration Date: {expiration_text}" if expiration_text else ""] if part
    )
    result.source_note = "Maine fast direct public registry confirmation found a safe matching row after an initial no-match response."
    if last_error:
        result.source_note += f" Last non-fatal direct-confirmation detail error: {last_error}"
    result.success = True
    result.error = ""
    setattr(result, "_cc_detail_body", " ".join(part for part in [detail_text, " ".join(best_row.values())] if part))
    return result


def search_me_serialized(page, org, confirm_no_match: bool = True):
    global ME_LAST_LOOKUP_FINISHED
    with ME_LOOKUP_LOCK:
        elapsed = time.perf_counter() - ME_LAST_LOOKUP_FINISHED
        if elapsed < ME_LOOKUP_MIN_INTERVAL_SECONDS:
            time.sleep(ME_LOOKUP_MIN_INTERVAL_SECONDS - elapsed)

        def run_lookup():
            preferred_variants = []
            if re.search(r"\bTuberculosis\b", org.organization_name or "", re.I):
                preferred_variants = [
                    variant for variant in organization_name_variants(
                        org.organization_name,
                        org.ein,
                        include_ein_aliases=True,
                        include_name_segments=True,
                        include_compact_legal_suffixes=False,
                        include_leading_article_variants=True,
                    )
                    if re.search(r"\bTB\b", variant or "", re.I)
                ][:3]
            return search_with_name_variants(
                page,
                org,
                checker.search_me,
                max_variants=6,
                max_elapsed_seconds=min(max(NAME_SEARCH_VARIANT_MAX_SECONDS, 25.0), 35.0),
                include_ein_aliases=True,
                include_name_segments=True,
                include_compact_legal_suffixes=True,
                include_leading_article_variants=True,
                require_safe_registry_name=True,
                preferred_variants=preferred_variants,
            )

        direct_first = me_fast_direct_confirmation_result(org)
        if direct_first:
            ME_LAST_LOOKUP_FINISHED = time.perf_counter()
            return direct_first

        result = run_lookup()
        if confirm_no_match and ME_CONFIRM_NOT_REGISTERED and public_status(result) == "Not Registered":
            direct_confirmation = me_fast_direct_confirmation_result(org)
            if direct_confirmation and public_status(direct_confirmation) != "Not Registered":
                result = direct_confirmation
                result.source_note = (
                    (result.source_note or "Maine public registry record found.")
                    + " CharityClarity did not accept the earlier no-match response because a fresh direct registry confirmation found this record."
                )
                ME_LAST_LOOKUP_FINISHED = time.perf_counter()
                return result
            confirmations = 1
            for _ in range(max(0, ME_NOT_REGISTERED_CONFIRMATION_ATTEMPTS - 1)):
                time.sleep(ME_NOT_REGISTERED_CONFIRMATION_DELAY_SECONDS)
                confirmation = run_lookup()
                confirmations += 1
                if public_status(confirmation) != "Not Registered":
                    result = confirmation
                    result.source_note = (
                        (result.source_note or "Maine public registry record found.")
                        + f" Maine no-match was rechecked {confirmations} times before returning this result."
                    )
                    break
            else:
                result.source_note = (
                    (result.source_note or "Maine search returned no matching organization result.")
                    + f" {confirmations} Maine searches returned no matching organization result."
                )
        ME_LAST_LOOKUP_FINISHED = time.perf_counter()
        return result


def external_status_to_checker_status(status: str) -> str:
    raw = (status or "").strip()
    normalized = raw.lower()
    if normalized in {"not registered", "not registered.", "not found", "no record", "no record found"}:
        return checker.STATUS_NOT_REGISTERED
    if normalized in {"delinquent/non-compliant", "delinquent", "non-compliant", "noncompliant", "expired"}:
        return checker.STATUS_DELINQUENT
    if normalized == "upcoming filing":
        return checker.STATUS_UPCOMING
    if normalized == "current":
        return checker.STATUS_CURRENT
    if normalized == "pending":
        return "Pending"
    if normalized in {"close", "closed", "withdrawn", "terminated", "inactive", "canceled", "cancelled"}:
        return "Closed / Withdrawn / Canceled"
    if normalized in {"revoked", "suspended", "exempt", "closed / withdrawn / canceled", "failed to renew"}:
        return raw
    return raw or checker.STATUS_UNKNOWN


def classify_mi_solicitation_status(raw_status: str) -> str:
    raw = re.sub(r"\s+", " ", raw_status or "").strip()
    if not raw or raw.upper() == "N/A":
        return ""
    if re.search(r"\bpending\b", raw, re.I):
        return "Pending"
    registered_expiration = re.search(
        r"\b(?:registered|active)\b[\s\S]{0,220}?\bExpiration\s+Date\s*:?\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})",
        raw,
        re.I,
    )
    if registered_expiration:
        return classify_expiration_date(parse_due_date(registered_expiration.group(1)))
    if re.search(r"\b(exempt)\b", raw, re.I):
        return "Exempt"
    if re.search(r"\b(revoked|suspended)\b", raw, re.I):
        return "Suspended"
    if re.search(r"\b(withdrawn|terminated|closed|cancel(?:ed|led)|inactive)\b", raw, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(r"\b(delinquent|non\W*compliant|expired)\b", raw, re.I):
        return checker.STATUS_DELINQUENT
    if re.search(r"\b(registered|active|current|compliant)\b", raw, re.I):
        return checker.STATUS_CURRENT
    return checker.STATUS_UNKNOWN


def mi_solicitation_raw_from_combined(raw_status: str) -> str:
    match = re.search(
        r"Solicitation\s+Registration\s+Status\s*:\s*(.*?)(?:\s*\|\s*Charitable\s+Trust\s+Registration\s+Status\s*:|$)",
        raw_status or "",
        re.I | re.S,
    )
    return re.sub(r"\s+", " ", match.group(1)).strip() if match else ""


def classify_nm_status_history(raw_status: str) -> str:
    raw = re.sub(r"\s+", " ", raw_status or "").strip()
    if not raw:
        return ""
    tax_years = [int(value) for value in re.findall(r"\bTax\s+Year\s+(20\d{2})\b", raw, re.I)]
    latest_tax_year = max(tax_years) if tax_years else None
    if re.search(r"\bExtension\s+Granted\b", raw, re.I):
        if latest_tax_year and latest_tax_year >= date.today().year - 1:
            return "Upcoming Filing"
        fye_match = re.search(r"\bFYE\s*:\s*([0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4})", raw, re.I)
        fye_date = parse_due_date(fye_match.group(1)) if fye_match else None
        if fye_date:
            return status_from_calendar_date(add_months(fye_date, 12))
    due_dates = [
        parsed
        for parsed in (
            parse_due_date(value)
            for value in re.findall(r"\bDue(?:\s+Date)?\s*:\s*([0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4})", raw, re.I)
        )
        if parsed
    ]
    if due_dates:
        return status_from_calendar_date(max(due_dates))
    if re.search(r"\bRegistration\s+Submission\s+Delinquent\b|\bdelinquent\b", raw, re.I):
        return "Delinquent"
    if latest_tax_year and latest_tax_year <= date.today().year - 2:
        return "Delinquent"
    if re.search(r"\bExtension\s+Granted\b", raw, re.I):
        return "Upcoming Filing"
    if re.search(r"\bRegistration\s+Submitted\b", raw, re.I):
        return checker.STATUS_CURRENT
    return ""


def classify_or_latest_report_status(raw_status: str) -> str:
    due_date = or_latest_report_base_due_date(raw_status)
    if due_date:
        return status_from_calendar_date(due_date)
    raw = re.sub(r"\s+", " ", raw_status or "").strip()
    if not raw:
        return ""
    if not re.search(r"\bLatest\s+Report\s+Year\s*:", raw, re.I):
        return ""
    year_values = [int(value) for value in re.findall(r"\bLatest\s+Report\s+Year\s*:\s*(20\d{2})\b", raw, re.I)]
    if year_values and max(year_values) <= date.today().year - 2:
        return checker.STATUS_DELINQUENT
    return ""


def or_latest_report_base_due_date(raw_status: str) -> date | None:
    raw = re.sub(r"\s+", " ", raw_status or "").strip()
    if not re.search(r"\bLatest\s+Report\s+Year\s*:", raw, re.I):
        return None
    fye_match = re.search(r"\bFiscal\s+Year\s+End\s*:\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})", raw, re.I)
    fye_date = parse_due_date(fye_match.group(1)) if fye_match else None
    return fifteenth_day_after_fiscal_year_end(fye_date, 5) if fye_date else None


def copy_external_result(org, state: str, external_result):
    status = external_status_to_checker_status(getattr(external_result, "status", ""))
    raw_status = getattr(external_result, "raw_status_text", "") or status
    normalized_error = getattr(external_result, "error", "") or ""
    external_organization_name = (getattr(external_result, "organization_name", "") or "").strip()
    state_upper = state.upper()
    if state_upper == "KS" and re.search(r"\b(withdrawn|terminated|closed|cancel(?:ed|led)|inactive|retired)\b", raw_status, re.I):
        status = "Closed / Withdrawn / Canceled"
    if state_upper == "AR" and re.search(r"\bStatus\s*:\s*(?:Close|Closed)\b|\b(?:Close|Closed|Withdrawn|Terminated|Cancel(?:ed|led)|Inactive)\b", raw_status, re.I):
        status = "Closed / Withdrawn / Canceled"
    if state_upper == "NM":
        nm_status = classify_nm_status_history(raw_status)
        if nm_status:
            status = nm_status
            normalized_error = ""
    if state_upper == "OR":
        or_status = classify_or_latest_report_status(raw_status)
        if or_status:
            status = or_status
            base_due = or_latest_report_base_due_date(raw_status)
            if base_due and "Base Due from Latest Report Period" not in raw_status:
                raw_status = f"{raw_status} | Base Due from Latest Report Period: {format_date(base_due)}"
    if state_upper == "MI":
        if re.search(r"Could not find the Michigan results frame", normalized_error, re.I):
            status = checker.STATUS_NOT_REGISTERED
            raw_status = "No results frame after Michigan EIN search"
            normalized_error = ""
        solicitation_raw = mi_solicitation_raw_from_combined(raw_status)
        solicitation_status = classify_mi_solicitation_status(solicitation_raw)
        if solicitation_status:
            status = solicitation_status
        solicitation_match = re.search(
            r"Solicitation\s+Registration\s+Status\s*:\s*Registered[\s\S]{0,160}?Expiration\s+Date\s*:\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{2,4})",
            raw_status,
            re.I,
        )
        if solicitation_match and status != "Pending":
            status = classify_expiration_date(parse_due_date(solicitation_match.group(1)))
            raw_status = f"Solicitation Registration Status: Registered - Expiration Date: {solicitation_match.group(1)}"
    result = checker.StateResult(
        org.organization_name,
        org.ein,
        state,
        status,
        getattr(external_result, "source_url", "") or "",
    )
    result.raw_status_text = raw_status
    result.source_note = getattr(external_result, "source_note", "") or ""
    matched_registry_name = (
        getattr(external_result, "matched_registry_name", "")
        or getattr(external_result, "matched_name", "")
        or ""
    )
    if (
        not matched_registry_name
        and external_organization_name
        and public_status(result) not in {"Not Registered", "Site Not Reachable"}
        and normalized_match_name(external_organization_name) != normalized_match_name(getattr(org, "organization_name", "") or "")
    ):
        matched_registry_name = external_organization_name
    result.matched_registry_identifier = (
        getattr(external_result, "matched_registry_identifier", "")
        or getattr(external_result, "contact_number", "")
        or getattr(external_result, "registration_number", "")
        or getattr(external_result, "record_id", "")
        or getattr(external_result, "page_number", "")
        or registry_identifier_from_raw(raw_status, state_upper)
        or ""
    )
    if registry_name_is_identifier_only(matched_registry_name, result.matched_registry_identifier):
        matched_registry_name = ""
    result.matched_registry_name = matched_registry_name
    if state_upper in {"AR", "KS", "KY", "MS", "NH", "OK"} and public_status(result) not in {"Not Registered", "Site Not Reachable"} and not result.matched_registry_name:
        result.matched_registry_name = useful_registry_name(external_organization_name or org.organization_name)
    if state_upper == "NM" and public_status(result) not in {"Not Registered", "Site Not Reachable"} and not result.matched_registry_name:
        result.matched_registry_name = useful_registry_name(external_organization_name or org.organization_name)
    result.success = bool(getattr(external_result, "success", False) or public_status(result) != "Site Not Reachable")
    result.error = normalized_error
    return result


def patch_mi_module_for_fast_lookups(module) -> None:
    """Keep MI on the same registry path, but avoid 30-60s waits per phase."""
    if getattr(module, "_cc_fast_lookup_patch", False):
        return

    def wait_for_search_form_fast(page) -> bool:
        deadline = time.time() + 4
        while time.time() < deadline:
            try:
                locator = page.locator("#ctl00_MainContent_txtEIN")
                if locator.count() > 0 and locator.first.is_visible(timeout=500):
                    return True
            except Exception:
                pass
            time.sleep(0.25)
        return False

    def open_search_form_fast(page) -> bool:
        for _ in range(1):
            page.goto(module.MI_DISCLAIMER_URL, wait_until="domcontentloaded", timeout=12000)
            if wait_for_search_form_fast(page):
                return True

            actions = [
                lambda: page.evaluate("__doPostBack('ctl00$MainContent$lblYes','')"),
                lambda: page.locator("#ctl00_MainContent_lblYes").click(timeout=3500, no_wait_after=True),
                lambda: page.locator("#ctl00_MainContent_lblYes").evaluate("el => el.click()"),
            ]
            for action in actions:
                try:
                    action()
                except Exception:
                    continue
                if wait_for_search_form_fast(page):
                    return True

            try:
                page.goto(module.MI_SEARCH_URL, wait_until="domcontentloaded", timeout=8000)
                if wait_for_search_form_fast(page):
                    return True
            except Exception:
                pass
        return False

    def find_results_frame_fast(page):
        deadline = time.time() + 24
        while time.time() < deadline:
            for frame in reversed(page.frames):
                text = re.sub(r"\s+", " ", module.body_text(frame, timeout=2500)).strip()
                if not text:
                    continue
                if "Results for the following input" in text or "record(s) found" in text or "No records found" in text:
                    return frame
            time.sleep(0.25)
        return None

    def find_detail_frame_fast(page):
        deadline = time.time() + 22
        while time.time() < deadline:
            for frame in reversed(page.frames):
                try:
                    if frame.locator("#ctl00_MainContent_fvCSForm_lblSolicitationRegistrationStatus").count() > 0:
                        return frame
                except Exception:
                    pass
                text = re.sub(r"\s+", " ", module.body_text(frame, timeout=2500)).strip()
                if "Solicitation Registration Status" in text and "Charitable Trust Registration Status" in text:
                    return frame
            time.sleep(0.25)
        return None

    def search_mi_fast(page, org, artifacts_dir, no_screenshot):
        formatted_ein = module.format_ein(org.ein)
        result = module.SearchResult(
            organization_name=org.organization_name or formatted_ein,
            ein=formatted_ein,
            status=module.STATUS_UNKNOWN,
            raw_status_text="",
        )

        if len(module.digits_only(org.ein)) != 9:
            result.error = "Michigan search requires a 9-digit EIN."
            return result

        try:
            if not open_search_form_fast(page):
                result.error = "Could not open the Michigan search form after the disclaimer."
                return result

            page.locator("#ctl00_MainContent_txtEIN").fill("")
            page.locator("#ctl00_MainContent_txtEIN").fill(formatted_ein)
            page.locator("#ctl00_MainContent_btnTextSearch").click(timeout=8000, no_wait_after=True)
            try:
                page.wait_for_load_state("domcontentloaded", timeout=3500)
            except Exception:
                pass
            time.sleep(4)

            results_frame = find_results_frame_fast(page)
            if not results_frame:
                result.error = "Could not find the Michigan results frame."
                return result

            results_text = re.sub(r"\s+", " ", module.body_text(results_frame, timeout=3500)).strip()
            if re.search(r"\b0 record\(s\) found\b|no records found|no results found|not found", results_text, re.I):
                result.status = module.STATUS_NOT_REGISTERED
                result.raw_status_text = "No results found"
                result.success = True
                result.source_note = "Michigan EIN search returned no matching result."
                return result

            chosen = module.choose_result_link(results_frame, org.organization_name)
            if not chosen:
                result.status = module.STATUS_NOT_REGISTERED
                result.raw_status_text = "No matching organization link"
                result.success = True
                result.source_note = "Michigan results did not contain a clickable organization summary link."
                return result

            _, clicked_name, link, href = chosen
            module.click_result_link(results_frame, link, href)
            try:
                page.wait_for_load_state("domcontentloaded", timeout=3500)
            except Exception:
                pass
            time.sleep(4)

            detail_frame = find_detail_frame_fast(page)
            if not detail_frame:
                result.error = "Could not load the Michigan detail page."
                return result

            site_name = module.extract_legal_name(detail_frame) or clicked_name or formatted_ein
            raw_status = module.extract_solicitation_status(detail_frame)
            charitable_trust_status = module.extract_charitable_trust_status(detail_frame)
            if not raw_status and not charitable_trust_status:
                result.organization_name = site_name
                result.status = module.STATUS_UNKNOWN
                result.raw_status_text = "Registration statuses not found"
                result.success = True
                result.source_note = (
                    "Michigan detail page loaded, but neither Solicitation Registration Status "
                    "nor Charitable Trust Registration Status could be extracted."
                )
                return result

            result.organization_name = site_name
            result.raw_status_text = (
                f"Solicitation Registration Status: {raw_status or 'N/A'} | "
                f"Charitable Trust Registration Status: {charitable_trust_status or 'N/A'}"
            )
            result.status = module.classify_mi_status(raw_status, charitable_trust_status)
            result.success = True
            return result
        except Exception as exc:
            result.error = f"MI error: {exc}"
            return result

    module.wait_for_search_form = wait_for_search_form_fast
    module.open_search_form = open_search_form_fast
    module.find_results_frame = find_results_frame_fast
    module.find_detail_frame = find_detail_frame_fast
    module.search_mi = search_mi_fast
    module._cc_fast_lookup_patch = True


def search_bundled_extension_state(page, org, state: str):
    state = state.upper()
    module = state_extension_module(state)
    if state == "MI":
        patch_mi_module_for_fast_lookups(module)
    try:
        bundle_org = module.Organization(organization_name=org.organization_name, ein=org.ein)
    except TypeError:
        bundle_org = module.Organization(organization_name=org.organization_name)
    if state == "MI":
        external_result = module.search_mi(page, bundle_org, ARTIFACTS_DIR / "MI", True)
        copied = copy_external_result(org, state, external_result)
        if public_status(copied) == "Not Registered" and re.search(
            r"clickable organization summary link|No matching organization link",
            " ".join([getattr(external_result, "raw_status_text", "") or "", getattr(external_result, "source_note", "") or ""]),
            re.I,
        ):
            # Michigan's EIN search is authoritative. If the exact EIN returns a
            # row under a registry/legal name that differs from the supplied
            # public-profile name, use the first EIN-confirmed row instead of
            # rejecting it on name alone.
            external_result = module.search_mi(page, module.Organization(organization_name="", ein=org.ein), ARTIFACTS_DIR / "MI", True)
        return copy_external_result(org, state, external_result)
    elif state == "OH":
        external_result = module.search_oh(page, bundle_org, ARTIFACTS_DIR / "OH", True)
    elif state == "LA":
        external_result = module.search_la(page, bundle_org)
    elif state == "AR":
        if hasattr(module, "AR_SEARCH_URL"):
            module.AR_SEARCH_URL = AR_SEARCH_URL
        external_result = module.search_ar(page, bundle_org)
    elif state == "OR":
        def or_detail_ein_mismatches(registry_name: str = "") -> bool:
            if registry_name:
                safe_targets = organization_match_target_variants(org.organization_name, org.ein)
                if target_name_score(registry_name, safe_targets) >= 450:
                    return False
            body_text = registry_page_body(page)
            registry_ein = checker.extract_labeled_value_from_text(body_text, ["Federal EIN", "EIN"])
            registry_digits = re.sub(r"\D", "", registry_ein or "")
            requested_digits = re.sub(r"\D", "", org.ein or "")
            return bool(registry_digits and requested_digits and registry_digits != requested_digits)

        def or_registry_name_from_detail() -> str:
            body_text = registry_page_body(page)
            before_address = re.split(r"\bMailing\s+Address\s*:", body_text, maxsplit=1, flags=re.I)[0]
            lines = [re.sub(r"\s+", " ", line).strip() for line in before_address.splitlines()]
            for line in reversed(lines):
                cleaned = useful_registry_name(line)
                if cleaned and not re.search(r"Search Oregon Charities|Charitable Organizations Registered|Download Charity database", cleaned, re.I):
                    return cleaned
            return ""

        def or_detail_name_mismatches(registry_name: str = "") -> bool:
            candidate_name = clean_registry_name(registry_name or or_registry_name_from_detail())
            if not candidate_name:
                return False
            return not registry_name_is_safe_for_org(candidate_name, org.organization_name, org.ein)

        def best_or_registry_name_from_page() -> str:
            try:
                row_candidates = page.evaluate(
                    """
                    () => Array.from(document.querySelectorAll('table tbody tr, table tr')).map((row) => {
                        const cells = Array.from(row.querySelectorAll('td')).map((cell) => (cell.innerText || cell.textContent || '').replace(/\\s+/g, ' ').trim());
                        const link = row.querySelector('a');
                        return { cells, text: (row.innerText || row.textContent || '').replace(/\\s+/g, ' ').trim(), linkText: link ? (link.innerText || link.textContent || '').replace(/\\s+/g, ' ').trim() : '' };
                    }).filter((row) => row.linkText && row.cells.length >= 1);
                    """
                )
            except Exception:
                row_candidates = []
            safe_targets = organization_match_target_variants(org.organization_name, org.ein)
            best_candidate_name = ""
            best_candidate_score = -10000
            for candidate in row_candidates:
                candidate_name = clean_registry_name(candidate.get("linkText") or (candidate.get("cells") or [""])[0])
                score = target_name_score(candidate_name, safe_targets)
                if score > best_candidate_score:
                    best_candidate_score = score
                    best_candidate_name = candidate_name
            return best_candidate_name if best_candidate_score >= 450 else ""

        variants = organization_name_variants(
            org.organization_name,
            org.ein,
            include_ein_aliases=True,
            include_name_segments=True,
            include_compact_legal_suffixes=True,
            include_leading_article_variants=True,
        )
        variants = prioritized_institutional_variants(variants)

        def or_variant_priority(value: str) -> tuple[int, int, str]:
            cleaned = re.sub(r"\s+", " ", value or "").strip()
            if cleaned == (org.organization_name or "").strip():
                return (0, 0, cleaned.lower())
            words = re.findall(r"[A-Za-z0-9]+", cleaned)
            has_separator_source = bool(re.search(r"[/\\]", org.organization_name or ""))
            has_legal_suffix = bool(re.search(r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\b", cleaned, re.I))
            has_article = bool(re.search(r"^(?:the|a|an)\s+", cleaned, re.I) or re.search(r",\s*(?:the|a|an)$", cleaned, re.I))
            if has_separator_source and len(words) >= 3 and not re.search(r"[/\\]", cleaned):
                return (1 + (1 if has_legal_suffix else 0) + (1 if has_article else 0), -len(words), cleaned.lower())
            if len(words) <= 1:
                return (3, len(words), cleaned.lower())
            return (4 + (1 if has_legal_suffix else 0) + (1 if has_article else 0), -len(words), cleaned.lower())

        variants = sorted(variants, key=or_variant_priority)
        expanded = []
        trailing_articles = []
        for variant in variants:
            if variant not in expanded:
                expanded.append(variant)
            for article in ("The", "A"):
                trailing = f"{variant}, {article}"
                if not re.search(rf",\s*{article}$", variant, re.I) and trailing not in trailing_articles:
                    trailing_articles.append(trailing)
        expanded.extend(item for item in trailing_articles if item not in expanded)
        best_result = None
        started = time.perf_counter()
        for variant in expanded[:10]:
            if best_result is not None and (time.perf_counter() - started) >= min(NAME_SEARCH_VARIANT_MAX_SECONDS, 30.0):
                return best_result
            active_org = org_with_name(org, variant)
            external_result = module.search_or(
                page,
                module.Organization(organization_name=active_org.organization_name, ein=active_org.ein),
            )
            result = copy_external_result(org, "OR", external_result)
            if public_status(result) == "Site Not Reachable":
                return result
            if not result_is_retryable_name_miss(result):
                registry_name = or_registry_name_from_detail() or best_or_registry_name_from_page() or variant
                if or_detail_ein_mismatches(registry_name):
                    best_result = checker.StateResult(
                        org.organization_name,
                        org.ein,
                        "OR",
                        checker.STATUS_NOT_REGISTERED,
                        getattr(external_result, "source_url", "") or "",
                        raw_status_text="Oregon detail EIN did not match the requested EIN",
                        source_note="Oregon returned a same/similar-name detail record, but its Federal EIN did not match the requested organization.",
                        success=True,
                    )
                    continue
                if registry_name and or_detail_name_mismatches(registry_name):
                    best_result = checker.StateResult(
                        org.organization_name,
                        org.ein,
                        "OR",
                        checker.STATUS_NOT_REGISTERED,
                        getattr(external_result, "source_url", "") or "",
                        raw_status_text="Oregon detail name did not safely match the requested organization",
                        source_note="Oregon returned an EIN/name detail record, but the registry name did not safely match the requested organization or a compatible public alias.",
                        success=True,
                    )
                    continue
                if not result.matched_registry_name:
                    result.matched_registry_name = registry_name
                return result
            best_candidate_name = best_or_registry_name_from_page()
            if best_candidate_name:
                external_result = module.search_or(
                    page,
                    module.Organization(organization_name=best_candidate_name, ein=org.ein),
                )
                result = copy_external_result(org, "OR", external_result)
                if not result.matched_registry_name:
                    result.matched_registry_name = or_registry_name_from_detail() or best_candidate_name
                if or_detail_ein_mismatches(result.matched_registry_name or best_candidate_name):
                    best_result = checker.StateResult(
                        org.organization_name,
                        org.ein,
                        "OR",
                        checker.STATUS_NOT_REGISTERED,
                        getattr(external_result, "source_url", "") or "",
                        raw_status_text="Oregon detail EIN did not match the requested EIN",
                        source_note="Oregon returned a same/similar-name detail record, but its Federal EIN did not match the requested organization.",
                        success=True,
                    )
                    continue
                if (result.matched_registry_name or best_candidate_name) and or_detail_name_mismatches(result.matched_registry_name or best_candidate_name):
                    best_result = checker.StateResult(
                        org.organization_name,
                        org.ein,
                        "OR",
                        checker.STATUS_NOT_REGISTERED,
                        getattr(external_result, "source_url", "") or "",
                        raw_status_text="Oregon detail name did not safely match the requested organization",
                        source_note="Oregon returned an EIN/name detail record, but the registry name did not safely match the requested organization or a compatible public alias.",
                        success=True,
                    )
                    continue
                if public_status(result) == "Site Not Reachable":
                    return result
                if not result_is_retryable_name_miss(result):
                    return result
            best_result = result
        return best_result or copy_external_result(org, "OR", module.search_or(page, bundle_org))
    else:
        raise ValueError(f"Unsupported bundled extension state: {state}")
    return copy_external_result(org, state, external_result)


def search_co_with_name_fallback(page, org):
    result = checker.search_co(page, org)
    if public_status(result) == "Site Not Reachable":
        api_result = co_api_fallback_result(org)
        if api_result is not None:
            return api_result
    if public_status(result) != "Not Registered":
        return result
    for variant in organization_name_variants(
        org.organization_name,
        org.ein,
        include_ein_aliases=True,
        include_name_segments=True,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
        include_broad_query_prefixes=False,
    )[:8]:
        variant_org = SimpleNamespace(organization_name=variant, ein="")
        fallback = checker.search_co(page, variant_org)
        if public_status(fallback) == "Site Not Reachable":
            return copy_name_fallback_result(org, fallback)
        if public_status(fallback) == "Not Registered":
            continue
        if result_registry_name_is_safe(fallback, org.organization_name, org.ein):
            fallback.source_note = (
                (fallback.source_note or "Colorado public search found a matching organization-name record.")
                + " CharityClarity used a name fallback after the EIN search returned no matching record."
            )
            return copy_name_fallback_result(org, fallback)
    return result


def co_api_fallback_result(org):
    ein = canonical_ein_digits(getattr(org, "ein", ""))
    if len(ein) != 9:
        return None
    formatted_ein = f"{ein[:2]}-{ein[2:]}"
    params = urlencode({
        "$limit": "10",
        "$where": f"fein='{formatted_ein}'",
        "$order": "registrationapproveddate DESC",
    })
    url = f"https://data.colorado.gov/resource/37wu-kn3g.json?{params}"
    try:
        request = urllib.request.Request(
            url,
            headers={"User-Agent": "ComplianceExpressRegistrySnapshot/1.0"},
        )
        with urllib.request.urlopen(request, timeout=18) as response:
            rows = json.loads(response.read().decode("utf-8", errors="replace"))
    except Exception:
        return None
    if not isinstance(rows, list) or not rows:
        result = checker.StateResult(org.organization_name, format_ein(ein), "CO", checker.STATUS_NOT_REGISTERED, url)
        result.raw_status_text = "No Colorado data.colorado.gov record found for this FEIN"
        result.source_note = "Colorado's public search page was unavailable, so CharityClarity checked the official Colorado Information Marketplace registration dataset by FEIN."
        result.success = True
        return result

    targets = organization_match_target_variants(org.organization_name, ein)
    safe_rows = [
        row for row in rows
        if result_registry_name_is_safe(
            SimpleNamespace(
                matched_registry_name=row.get("name") or "",
                matched_registry_identifier=row.get("entityid") or "",
                raw_status_text=" ".join(str(row.get(key) or "") for key in ("currentstatus", "filingtype", "expirationdate")),
            ),
            org.organization_name,
            ein,
        )
        or normalized_name(row.get("name") or "") in targets
    ]
    if not safe_rows:
        result = checker.StateResult(org.organization_name, format_ein(ein), "CO", checker.STATUS_NOT_REGISTERED, url)
        result.raw_status_text = "Colorado FEIN rows did not safely match the requested organization name"
        result.source_note = "Colorado's public search page was unavailable, and the official dataset did not expose a safe registry-name match for this FEIN."
        result.success = True
        return result

    row = safe_rows[0]
    raw_status = str(row.get("currentstatus") or "").strip()
    expiration = parse_due_date(str(row.get("expirationdate") or "").split("T", 1)[0])
    if re.search(r"\b(suspend|revok|notice\s*\d*|may\s+not|not\s+authorized)\b", raw_status, re.I):
        status = "Suspended"
    elif re.search(r"\b(withdraw|cancel|closed)\b", raw_status, re.I):
        status = "Closed / Withdrawn / Canceled"
    elif re.search(r"\b(delinquent|expired|lapsed)\b", raw_status, re.I):
        status = "Delinquent"
    elif expiration is not None:
        status = checker.status_from_due_date(expiration)
    elif raw_status:
        status = raw_status
    else:
        status = checker.STATUS_UNKNOWN

    result = checker.StateResult(org.organization_name, format_ein(ein), "CO", status, url)
    result.matched_registry_name = row.get("name") or ""
    result.matched_registry_identifier = row.get("entityid") or row.get("documentid") or ""
    raw_parts = []
    if raw_status:
        raw_parts.append(f"Current Status: {raw_status}")
    if expiration is not None:
        raw_parts.append(f"Expiration Date: {expiration.strftime('%m/%d/%Y')}")
    if row.get("nextrenewalregistrationdate"):
        renewal = parse_due_date(str(row.get("nextrenewalregistrationdate") or "").split("T", 1)[0])
        raw_parts.append(f"Next Renewal: {renewal.strftime('%m/%d/%Y') if renewal else row.get('nextrenewalregistrationdate')}")
    result.raw_status_text = " | ".join(raw_parts) or raw_status or "Colorado registration data row found"
    result.source_note = "Colorado's public search page was unavailable, so CharityClarity used Colorado's official Information Marketplace registration dataset by FEIN."
    result.success = True
    return result


def search_mi_name_fallback(page, org):
    module = state_extension_module("MI")
    result = checker.StateResult(org.organization_name, org.ein, "MI", checker.STATUS_NOT_REGISTERED, "")
    safe_targets = organization_match_target_variants(org.organization_name, org.ein)
    started = time.perf_counter()
    variants = []
    for variant in organization_name_variants(
        org.organization_name,
        org.ein,
        include_ein_aliases=True,
        include_name_segments=True,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
        include_broad_query_prefixes=False,
    ):
        variant_words = re.findall(r"[A-Za-z0-9]+", variant or "")
        substantive_variant_words = [
            word for word in variant_words
            if word.lower() not in {"the", "a", "an", "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited"}
        ]
        if len(substantive_variant_words) < 2:
            continue
        if variant not in variants:
            variants.append(variant)
    if not variants:
        result.status = checker.STATUS_NOT_REGISTERED
        result.raw_status_text = "No matching organization record"
        result.source_note = "Michigan EIN search returned no exact result, and no narrow structural name fallback was appropriate."
        result.success = True
        result.error = ""
        return result
    def mi_variant_priority(value: str) -> tuple[int, int, str]:
        cleaned = re.sub(r"\s+", " ", value or "").strip()
        has_legal_suffix = bool(re.search(r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\b", cleaned, re.I))
        has_comma = "," in cleaned
        has_generated_punctuation = bool(re.search(r"[-/\\]", cleaned))
        return (
            2 if has_legal_suffix or has_comma else (1 if has_generated_punctuation else 0),
            len(cleaned.split()),
            cleaned.lower(),
        )

    variants = sorted(variants, key=mi_variant_priority)

    for variant in variants[:2]:
        if time.perf_counter() - started > 8:
            result.status = checker.STATUS_NOT_REGISTERED
            result.raw_status_text = "No matching organization record"
            result.source_note = "Michigan EIN search returned no exact result, and the bounded organization-name fallback found no matching record before the safe retry limit."
            result.success = True
            result.error = ""
            return result
        try:
            if not module.open_search_form(page):
                result.error = "MI: Could not reopen search form for name fallback"
                return result
            page.locator("#ctl00_MainContent_txtName").fill("")
            page.locator("#ctl00_MainContent_txtName").fill(variant)
            page.locator("#ctl00_MainContent_txtEIN").fill("")
            page.locator("#ctl00_MainContent_btnTextSearch").click(timeout=5000, no_wait_after=True)
            try:
                page.wait_for_load_state("domcontentloaded", timeout=3500)
            except Exception:
                pass
            time.sleep(1)
            frame = module.find_results_frame(page)
            if not frame:
                continue
            results_text = re.sub(r"\s+", " ", module.body_text(frame, timeout=3500)).strip()
            if no_registry_results_seen(results_text):
                continue
            chosen = module.choose_result_link(frame, variant) or module.choose_result_link(frame, "")
            if not chosen:
                continue
            _, clicked_name, link, href = chosen
            clicked_name_score = target_name_score(clicked_name, safe_targets)
            if clicked_name_score < 0:
                try:
                    checker_score = checker.candidate_selection_score_for_targets(results_text, safe_targets, results_text)
                    if checker_score[0] < 0:
                        pass
                    else:
                        clicked_name_score = 450 + checker_score[0]
                except Exception:
                    pass
            if clicked_name_score >= 0:
                row_window_match = re.search(
                    rf"(?P<id>\b\d{{3,8}}\b)?\s*{re.escape(clicked_name)}[\s\S]{{0,220}}?(?P<date>\d{{1,2}}/\d{{1,2}}/\d{{2,4}})",
                    results_text,
                    re.I,
                )
                if row_window_match:
                    expiration_date = parse_due_date(row_window_match.group("date"))
                    if expiration_date:
                        result.status = classify_expiration_date(expiration_date)
                        result.raw_status_text = (
                            f"License / Registration Expiration: {format_date(expiration_date)} | "
                            "Matched by organization name after EIN search returned no exact result"
                        )
                        result.source_note = "MI tried EIN search first, then used the public organization-name search result row when the EIN field returned no exact result."
                        result.matched_registry_name = clean_registry_name(clicked_name)
                        result.matched_registry_identifier = row_window_match.group("id") or ""
                        result.success = True
                        result.error = ""
                        return result
            module.click_result_link(frame, link, href)
            try:
                page.wait_for_load_state("domcontentloaded", timeout=3500)
            except Exception:
                pass
            time.sleep(1)
            detail_frame = module.find_detail_frame(page)
            if not detail_frame:
                continue
            detail_text = re.sub(r"\s+", " ", module.body_text(detail_frame, timeout=3500)).strip()
            site_name = module.extract_legal_name(detail_frame) or clicked_name or org.organization_name
            ein_digits = re.sub(r"\D", "", org.ein or "")
            ein_confirmed = bool(ein_digits and ein_digits in re.sub(r"\D", "", detail_text))
            if not ein_confirmed and clicked_name_score < 0 and target_name_score(site_name, safe_targets) < 0:
                continue
            raw_status = module.extract_solicitation_status(detail_frame)
            charitable_trust_status = module.extract_charitable_trust_status(detail_frame)
            if not raw_status and not charitable_trust_status:
                continue
            result.status = classify_mi_solicitation_status(raw_status) or external_status_to_checker_status(module.classify_mi_status(raw_status, ""))
            result.raw_status_text = (
                f"Solicitation Registration Status: {raw_status or 'N/A'} | "
                f"Charitable Trust Registration Status: {charitable_trust_status or 'N/A'} | "
                "Matched by organization name after EIN search returned no exact result"
            )
            result.source_note = "MI tried EIN search first, then used the public organization-name search when the EIN field returned no exact result."
            result.matched_registry_name = clean_registry_name(site_name)
            result.success = True
            return result
        except Exception as exc:
            result.error = f"MI name fallback error: {exc}"
            return result
    result.status = checker.STATUS_NOT_REGISTERED
    result.raw_status_text = "No matching organization record"
    result.source_note = "Michigan EIN and organization-name searches returned no matching result."
    result.success = True
    result.error = ""
    return result


def classify_expiration_date(exp_date: date | None) -> str:
    if not exp_date:
        return checker.STATUS_UNKNOWN
    return status_from_calendar_date(exp_date)


def readable_page_text(page) -> str:
    try:
        return page.locator("body").inner_text(timeout=10000)
    except Exception:
        return registry_page_body(page)


def no_registry_results_seen(text: str) -> bool:
    return bool(re.search(
        r"\b(no\s+(?:matching\s+)?(?:records?|results?|organizations?|licenses?)\s+(?:found|match)|"
        r"showing\s+0\s+results?|0\s+(?:records?|results?)|your\s+search\s+returned\s+no|sorry,\s+there\s+are\s+no\s+matches|did\s+not\s+match\s+any)\b",
        text or "",
        re.I,
    ))


def first_date_near_label(text: str, labels: list[str]) -> date | None:
    readable = re.sub(r"\s+", " ", text or "")
    for label in labels:
        pattern = rf"{label}\s*:?\s*([A-Za-z]{{3,9}}\s+\d{{1,2}},\s+\d{{4}}|\d{{1,2}}[/-]\d{{1,2}}[/-]\d{{2,4}}|\d{{4}}-\d{{1,2}}-\d{{1,2}})"
        match = re.search(pattern, readable, re.I)
        if match:
            parsed = parse_due_date(match.group(1))
            if parsed:
                return parsed
    return None


def fl_fallback_cache() -> dict:
    return {}


def fl_status_from_cached_entry(entry: dict) -> str:
    raw_text = entry.get("raw_status_text", "") or ""
    cached_status = entry.get("status", "") or checker.STATUS_NOT_REGISTERED
    if re.search(r"\bSuspended\b", raw_text, re.I):
        return "Suspended"
    if re.search(r"\bRevoked\b", raw_text, re.I):
        return "Revoked"
    exp_date = first_date_near_label(raw_text, ["Expiration Date", "Expiration", "Expires"])
    if exp_date:
        return classify_expiration_date(exp_date)
    return cached_status


def fl_unavailable_fallback_result(org, preflight_note: str):
    ein_key = re.sub(r"\D", "", str(org.ein or ""))
    entry = fl_fallback_cache().get(ein_key) if ein_key else None
    if isinstance(entry, dict):
        cached_status = (entry.get("status") or "").strip()
        cached_name = entry.get("matched_registry_name", "") or ""
        if cached_status != checker.STATUS_NOT_REGISTERED and not registry_name_is_safe_for_org(cached_name, org.organization_name, org.ein):
            entry = None

    if isinstance(entry, dict):
        result = checker.StateResult(
            org.organization_name,
            org.ein,
            "FL",
            fl_status_from_cached_entry(entry),
            FL_CHECK_A_CHARITY_URL,
        )
        result.raw_status_text = entry.get("raw_status_text", "") or entry.get("status", "") or ""
        result.matched_registry_name = entry.get("matched_registry_name", "") or ""
        result.matched_registry_identifier = entry.get("matched_registry_identifier", "") or ""
        result.source_note = " ".join(part for part in [
            entry.get("comments", "") or "",
            f"Florida live Check-A-Charity preflight did not respond within {FL_PREFLIGHT_TIMEOUT_SECONDS:g}s ({preflight_note}); CharityClarity returned the latest cached public-registry observation from {entry.get('observed_at', 'a prior successful lookup')}.",
        ] if part).strip()
        result.success = True
        return result
    result = checker.StateResult(
        org.organization_name,
        org.ein,
        "FL",
        checker.STATUS_NOT_REGISTERED,
        FL_CHECK_A_CHARITY_URL,
    )
    result.raw_status_text = "No live Florida Check-A-Charity response within bounded preflight"
    result.source_note = (
        f"Florida live Check-A-Charity preflight did not respond within {FL_PREFLIGHT_TIMEOUT_SECONDS:g}s "
        f"({preflight_note}); no matching cached public-registry observation was available for this EIN."
    )
    result.success = True
    return result


def best_row_with_link_by_name(page, targets: list[str], link_pattern: str = r"details|view|select|license") -> tuple[object | None, str]:
    rows = page.locator("tr")
    best_row = None
    best_text = ""
    best_score = (-999, -999)
    try:
        count = min(rows.count(), 80)
    except Exception:
        count = 0
    for index in range(count):
        row = rows.nth(index)
        try:
            text = re.sub(r"\s+", " ", row.inner_text(timeout=1500)).strip()
        except Exception:
            continue
        if not text:
            continue
        try:
            if row.locator("a, button, input[type='submit'], input[type='button']").count() == 0:
                continue
        except Exception:
            continue
        try:
            score = checker.candidate_selection_score_for_targets(text, targets, text)
        except Exception:
            score = (1, len(text)) if any((target or "").lower() in text.lower() for target in targets) else (-1, len(text))
        if score[0] < 0:
            normalized_text = re.sub(r"\b(the|a|an)\b", " ", re.sub(r"[^a-z0-9]+", " ", text.lower()))
            normalized_text = re.sub(r"\s+", " ", normalized_text).strip()
            for target in targets:
                normalized_target = re.sub(r"\b(the|a|an)\b", " ", re.sub(r"[^a-z0-9]+", " ", (target or "").lower()))
                normalized_target = re.sub(r"\s+", " ", normalized_target).strip()
                if normalized_target and normalized_target in normalized_text:
                    score = (1, len(normalized_target))
                    break
        if score > best_score:
            best_score = score
            best_row = row
            best_text = text
    if best_row is None or best_score[0] < 0:
        return None, ""
    links = best_row.locator("a, button, input[type='submit'], input[type='button']")
    try:
        count = links.count()
    except Exception:
        count = 0
    for index in range(count):
        link = links.nth(index)
        try:
            label = " ".join([
                link.inner_text(timeout=750) if link.evaluate("el => el.tagName.toLowerCase() !== 'input'") else "",
                link.get_attribute("value") or "",
                link.get_attribute("title") or "",
                link.get_attribute("aria-label") or "",
            ])
        except Exception:
            label = ""
        if re.search(link_pattern, label or "", re.I):
            return link, best_text
    return best_row.locator("a, button").first if count else None, best_text


def normalized_match_name(value: str) -> str:
    normalized = checker.normalize_name(value or "") if hasattr(checker, "normalize_name") else re.sub(r"\W+", " ", (value or "").lower()).strip()
    normalized = re.sub(r"\b(the|a|an|inc|incorporated|corp|corporation|llc|ltd|limited)\b", " ", normalized, flags=re.I)
    return re.sub(r"\s+", " ", normalized).strip()


def single_plural_token_variant_match(left: str, right: str) -> bool:
    left_tokens = (left or "").split()
    right_tokens = (right or "").split()
    if len(left_tokens) != len(right_tokens) or len(left_tokens) < 3:
        return False
    mismatches = []
    for left_token, right_token in zip(left_tokens, right_tokens):
        if left_token == right_token:
            continue
        mismatches.append((left_token, right_token))
        if len(mismatches) > 1:
            return False
    if len(mismatches) != 1:
        return False
    left_token, right_token = mismatches[0]
    if min(len(left_token), len(right_token)) < 5:
        return False
    if left_token.endswith("ies") and right_token == f"{left_token[:-3]}y":
        return True
    if right_token.endswith("ies") and left_token == f"{right_token[:-3]}y":
        return True
    if left_token.endswith("s") and not left_token.endswith(("ss", "us")) and left_token[:-1] == right_token:
        return True
    if right_token.endswith("s") and not right_token.endswith(("ss", "us")) and right_token[:-1] == left_token:
        return True
    return False


def target_name_score(row_name: str, targets: list[str]) -> int:
    row_norm = normalized_match_name(row_name)
    if not row_norm:
        return -1000
    best = -1000
    for target in targets:
        target_norm = normalized_match_name(target)
        if not target_norm:
            continue
        if saint_university_canonical(row_norm) and saint_university_canonical(row_norm) == saint_university_canonical(target_norm):
            best = max(best, 1000)
        if row_norm == target_norm:
            best = max(best, 1000)
        elif single_plural_token_variant_match(row_norm, target_norm):
            best = max(best, 920)
        elif row_norm.startswith(target_norm) or target_norm.startswith(row_norm):
            shorter = min(len(row_norm.split()), len(target_norm.split()))
            if shorter >= 3:
                best = max(best, 700 + shorter)
        elif target_norm in row_norm or row_norm in target_norm:
            shorter = min(len(row_norm.split()), len(target_norm.split()))
            if shorter >= 3:
                best = max(best, 450 + shorter)
    return best


def clean_registry_name(value: str) -> str:
    cleaned = re.sub(r"\s+", " ", (value or "").strip())
    cleaned = re.sub(r"\s*/\s*DBA\s*/\s*Nickname\s*:?.*$", "", cleaned, flags=re.I).strip()
    cleaned = re.sub(
        r"\s+\d{5,}\s+(?:current|closed|expired|registered|not\s+registered|delinquent|pending)\b.*$",
        "",
        cleaned,
        flags=re.I,
    ).strip()
    cleaned = re.sub(
        r"\s+\b(?:aka|d/?b/?a|f/?k/?a|formerly(?:\s+known\s+as)?|doing\s+business\s+as|also\s+soliciting\s+as|soliciting\s+as|also\s+known\s+as)\b\s+.*$",
        "",
        cleaned,
        flags=re.I,
    ).strip()
    cleaned = re.sub(r"\b(Credential|License/Registration Number|Status|Expiration Date)\b.*$", "", cleaned, flags=re.I).strip()
    return cleaned.strip(" :-")


def useful_registry_name(value: str) -> str:
    cleaned = clean_registry_name(value)
    normalized = re.sub(r"[^a-z0-9]+", "", cleaned.lower())
    if not cleaned or len(normalized) < 4:
        return ""
    if re.fullmatch(r"s|name|names|organization|charity|dba|nickname|title", normalized, re.I):
        return ""
    if re.search(r"\b(search|advanced search|word phrase ein|no records?|results?)\b", cleaned, re.I):
        return ""
    if re.search(r"\b(Registration\s+Number|FEIN|Federal\s+EIN|Status|Expiration\s+Date)\b", cleaned, re.I):
        return ""
    return cleaned


def registry_identifier_from_raw(raw_status: str, state: str) -> str:
    patterns = [
        r"\b(?:KY|NH|KS|MS|OK|WV|AR)\s+ID\s*:\s*([A-Za-z0-9-]+)\b",
        r"\bRegistration\s+(?:Number|No\.?|#)\s*:\s*([A-Za-z0-9-]+)\b",
        r"\bCredential\s+(?:Number|No\.?|#)\s*:\s*([A-Za-z0-9-]+)\b",
        r"\bFiling\s+(?:Number|No\.?|#)\s*:\s*([A-Za-z0-9-]+)\b",
    ]
    for pattern in patterns:
        match = re.search(pattern, raw_status or "", re.I)
        if match:
            return match.group(1).strip()
    return ""


def registry_name_is_identifier_only(name: str, identifier: str = "") -> bool:
    cleaned = re.sub(r"\s+", " ", (name or "").strip())
    if not cleaned:
        return False
    if identifier and cleaned.lower() == identifier.strip().lower():
        return True
    return bool(re.fullmatch(r"(?:id\s*[:#]?\s*)?[A-Za-z]?\d{3,}(?:-\d+)?", cleaned, re.I))


def normalized_ein_key(value: str) -> str:
    digits = canonical_ein_digits(value)
    return digits.zfill(9) if digits else ""


def confirmed_feedback_correction_for_result(result):
    return None


def apply_confirmed_feedback_correction(result) -> str:
    return ""


def fill_registry_match_from_text(result, body: str, org) -> None:
    if (getattr(result, "matched_registry_name", "") or "").strip():
        result.matched_registry_name = useful_registry_name(result.matched_registry_name)
        return
    if public_status(result) == "Not Registered":
        return
    text_sources = [
        body or "",
        getattr(result, "raw_status_text", "") or "",
        getattr(result, "source_note", "") or "",
    ]
    combined_text = "\n".join(text_sources)
    readable = re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", combined_text or ""))).strip()
    if not readable:
        return
    candidates = []
    for label in ["Organization Name", "Organization name", "Charity Name", "Business Name", "Legal Name", "Entity Name", "Name"]:
        candidate = useful_registry_name(text_between_labels(readable, label, [
            "FEIN", "Federal EIN", "Federal ID", "EIN", "Status", "Registration Status",
            "Registration Number", "License Number", "License", "Credential",
            "Expiration Date", "Address", "City", "State",
        ]))
        if candidate:
            candidates.append(candidate)
    ein_digits = re.sub(r"\D", "", getattr(org, "ein", "") or getattr(result, "ein", "") or "")
    if ein_digits:
        for line in re.split(r"[\r\n]+|\s{2,}", combined_text or ""):
            line_text = re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", line))).strip()
            if not line_text or ein_digits not in re.sub(r"\D", "", line_text):
                continue
            line_name = ""
            ein_pattern = rf"{re.escape(ein_digits[:2])}-?{re.escape(ein_digits[2:])}"
            ein_match = re.search(ein_pattern, line_text)
            if ein_match:
                after_ein = line_text[ein_match.end():].strip(" :-")
                line_name = useful_registry_name(re.split(r"\s+\d{2,}\b|\b(?:Status|Registration|License|Expiration|Address|City|State)\b", after_ein, maxsplit=1, flags=re.I)[0])
            if not line_name:
                line_name = useful_registry_name(re.split(r"\b(?:FEIN|Federal\s+EIN|Federal\s+ID|EIN|Status|Registration)\b", line_text, maxsplit=1, flags=re.I)[0])
            if line_name:
                candidates.append(line_name)
    safe_targets = organization_match_target_variants(getattr(org, "organization_name", "") or getattr(result, "organization_name", ""), getattr(org, "ein", "") or getattr(result, "ein", ""))
    best_name = ""
    best_score = -10000
    for candidate in candidates:
        score = target_name_score(candidate, safe_targets)
        if score > best_score:
            best_name = candidate
            best_score = score
    if best_name and best_score >= 450:
        result.matched_registry_name = best_name
    elif (
        (getattr(result, "state", "") or "").upper() in {"AK", "MA", "MD", "MI", "MN", "PA"}
        and public_status(result) not in {"Not Registered", "Site Not Reachable"}
        and (getattr(org, "organization_name", "") or "").strip()
    ):
        result.matched_registry_name = re.sub(r"\s+", " ", getattr(org, "organization_name", "")).strip()


def normalize_registry_match_fields(result, org) -> None:
    matched_name = useful_registry_name(getattr(result, "matched_registry_name", "") or "")
    matched_identifier = (getattr(result, "matched_registry_identifier", "") or "").strip()
    submitted_name = re.sub(r"\s+", " ", (getattr(org, "organization_name", "") or getattr(result, "organization_name", "") or "").strip())

    if public_status(result) == "Not Registered":
        result.matched_registry_name = ""
        result.matched_registry_identifier = ""
        return

    if matched_name and registry_name_is_identifier_only(matched_name, matched_identifier):
        if not matched_identifier:
            matched_identifier = matched_name
        matched_name = ""

    if not matched_name and public_status(result) not in {"Not Registered", "Site Not Reachable"} and submitted_name:
        matched_name = submitted_name

    result.matched_registry_name = matched_name
    result.matched_registry_identifier = matched_identifier


def text_between_labels(text: str, start_label: str, end_labels: list[str]) -> str:
    compact = re.sub(r"\s+", " ", text or "").strip()
    if not compact:
        return ""
    end_pattern = "|".join(re.escape(label) for label in end_labels)
    match = re.search(rf"{re.escape(start_label)}\s*:?\s*(.*?)(?=\s+(?:{end_pattern})\s*:?\s|$)", compact, re.I)
    return re.sub(r"\s+", " ", match.group(1)).strip(" :-") if match else ""


def click_nth_details_control(page, index: int) -> bool:
    locator = page.locator("a, button, input[type='button'], input[type='submit']")
    try:
        count = locator.count()
    except Exception:
        return False
    seen = 0
    for item_index in range(count):
        item = locator.nth(item_index)
        try:
            label = " ".join([
                item.inner_text(timeout=500) if item.evaluate("el => el.tagName.toLowerCase() !== 'input'") else "",
                item.get_attribute("value") or "",
                item.get_attribute("title") or "",
                item.get_attribute("aria-label") or "",
            ])
        except Exception:
            continue
        if not re.search(r"details|view", label or "", re.I):
            continue
        if seen == index:
            try:
                item.click(timeout=5000)
            except Exception:
                item.click(force=True, timeout=5000)
            return True
        seen += 1
    return False


def html_fragment_text(fragment: str) -> str:
    return re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", fragment or ""))).strip()


def ct_direct_form_fields(page_html: str) -> dict[str, str]:
    fields: dict[str, str] = {}
    for match in re.finditer(r"<(?:input|select)\b[^>]*>", page_html or "", re.I):
        tag = match.group(0)
        name_match = re.search(r"\bname=[\"']([^\"']+)", tag, re.I)
        if not name_match:
            continue
        value_match = re.search(r"\bvalue=[\"']([^\"']*)", tag, re.I)
        fields[html.unescape(name_match.group(1))] = html.unescape(value_match.group(1) if value_match else "")
    return fields


def ct_direct_prepare_session(timeout_seconds: float | None = None):
    url = "https://www.elicense.ct.gov/lookup/licenselookup.aspx"
    timeout = max(2.0, min(float(timeout_seconds or CT_DIRECT_TIMEOUT_SECONDS), CT_DIRECT_TIMEOUT_SECONDS))
    headers = {
        "User-Agent": BROWSER_USER_AGENT,
        "Referer": url,
        "Origin": "https://www.elicense.ct.gov",
    }
    from curl_cffi import requests as curl_requests

    session = curl_requests.Session(impersonate="chrome")
    response = session.get(url, headers=headers, timeout=(min(3.0, timeout), timeout))
    response.raise_for_status()
    return session, ct_direct_form_fields(response.text), headers


def ct_direct_post_query(session, base_fields: dict[str, str], headers: dict[str, str], search_name: str, timeout_seconds: float | None = None) -> str:
    url = "https://www.elicense.ct.gov/lookup/licenselookup.aspx"
    timeout = max(2.0, min(float(timeout_seconds or CT_DIRECT_TIMEOUT_SECONDS), CT_DIRECT_TIMEOUT_SECONDS))
    fields = dict(base_fields)
    fields["ctl00$MainContentPlaceHolder$ucLicenseLookup$ctl03$tbDBA_Contact"] = search_name
    fields["__EVENTTARGET"] = "ctl00$MainContentPlaceHolder$ucLicenseLookup$UpdtPanelGridLookup"
    fields["__EVENTARGUMENT"] = "3"
    fields["ctl00$ScriptManager1"] = (
        "ctl00$MainContentPlaceHolder$ucLicenseLookup$UpdtPanelGridLookup|"
        "ctl00$MainContentPlaceHolder$ucLicenseLookup$UpdtPanelGridLookup"
    )
    fields["__ASYNCPOST"] = "true"
    response = session.post(
        url,
        data=fields,
        headers={
            **headers,
            "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
            "X-MicrosoftAjax": "Delta=true",
            "X-Requested-With": "XMLHttpRequest",
        },
        timeout=(min(3.0, timeout), timeout),
    )
    response.raise_for_status()
    return response.text


def ct_direct_query(search_name: str, timeout_seconds: float | None = None) -> str:
    try:
        session, fields, headers = ct_direct_prepare_session(timeout_seconds)
        return ct_direct_post_query(session, fields, headers, search_name, timeout_seconds)
    except Exception as exc:
        raise RuntimeError(f"Connecticut direct HTTP query failed: {exc}") from exc


def ct_direct_detail_text(row_html: str, timeout_seconds: float | None = None) -> str:
    match = re.search(r"DisplayLicenceDetail\((?:&#39;|')(.+?)(?:&#39;|')\)", row_html or "", re.I | re.S)
    if not match:
        return ""
    detail_id = html.unescape(match.group(1)).strip()
    if not detail_id:
        return ""
    timeout = max(2.0, min(float(timeout_seconds or CT_DIRECT_TIMEOUT_SECONDS), CT_DIRECT_TIMEOUT_SECONDS))
    url = "https://www.elicense.ct.gov/lookup/licensedetail.aspx?id=" + quote(detail_id, safe="")
    try:
        request = urllib.request.Request(
            url,
            headers={
                "User-Agent": BROWSER_USER_AGENT,
                "Referer": "https://www.elicense.ct.gov/lookup/licenselookup.aspx",
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            },
        )
        with urllib.request.urlopen(request, timeout=timeout) as response:
            detail_html = response.read().decode("utf-8", errors="replace")
        return html_fragment_text(detail_html)
    except Exception:
        return ""


def ct_direct_result_from_row(org, row_html: str, safe_targets: list[str], url: str):
    row_text = html_fragment_text(row_html)
    name_match = re.search(r"<b[^>]*headline6[^>]*>(.*?)</b>", row_html, re.I | re.S)
    row_name = clean_registry_name(html_fragment_text(name_match.group(1)) if name_match else re.split(r"\bCredential\b|\bStatus\b|\bLicense\b", row_text, maxsplit=1, flags=re.I)[0])
    name_score = target_name_score(row_name, safe_targets)
    if name_score < 0:
        return None, name_score
    detail_text = ct_direct_detail_text(row_html, timeout_seconds=3.0)
    pairs: dict[str, str] = {}
    for label_html, value_html in re.findall(r"<b[^>]*>(.*?)</b>\s*<p[^>]*>(.*?)</p>", row_html, re.I | re.S):
        label = html_fragment_text(label_html).strip(": ")
        value = html_fragment_text(value_html)
        if label and value:
            pairs[label] = value
    credential = pairs.get("Credential", "")
    credential_description = pairs.get("Credential Description", "")
    status_text = pairs.get("Status", "")
    status_reason = pairs.get("Status Reason", "")
    combined = " ".join([row_text, detail_text, credential, credential_description, status_text, status_reason])
    result = checker.StateResult(org.organization_name, org.ein, "CT", checker.STATUS_UNKNOWN, url)
    result.matched_registry_name = row_name
    credential_match = re.search(r"\b[A-Z]{2,5}\.[0-9A-Z.-]+", combined)
    result.matched_registry_identifier = credential or (credential_match.group(0) if credential_match else "")
    exp_date = first_date_near_label(" ".join([row_text, detail_text]), ["Expiration Date", "Expiration", "Expires", "Expire Date"])
    terminal_status_text = " ".join([status_text, status_reason, credential_description])
    if re.search(r"\bEXEMPT\b", " ".join([credential, credential_description]), re.I):
        result.status = "Exempt"
    elif re.search(r"\bINACTIVE\b|\bCLOSED\b|\bWITHDRAWN\b|\bCANCEL(?:ED|LED)\b", terminal_status_text, re.I):
        result.status = "Closed / Withdrawn / Canceled"
    elif re.search(r"\b(non\W*compliant|not\s+in\s+compliance)\b", combined, re.I):
        result.status = checker.STATUS_DELINQUENT
    elif exp_date:
        result.status = classify_expiration_date(exp_date)
    elif re.search(r"\bACTIVE\b", status_text, re.I) and (not status_reason or re.search(r"\b(CURRENT|ACTIVE)\b", status_reason, re.I)):
        result.status = checker.STATUS_CURRENT
    elif re.search(r"\bCURRENT\b", combined, re.I):
        result.status = checker.STATUS_CURRENT
    result.raw_status_text = " | ".join(
        item for item in [
            f"Status: {status_text}" if status_text else "",
            f"Status Reason: {status_reason}" if status_reason else "",
            f"Credential Description: {credential_description}" if credential_description else "",
            f"Expiration Date {format_date(exp_date)}" if exp_date else "",
        ]
    ) or row_text[:500]
    result.source_note = "Connecticut public registry AJAX search result row selected by strict organization-name match."
    result.success = True
    score = name_score
    if re.search(r"\bPUBLIC\s+CHARITY\b|\bCHR\.", combined, re.I):
        score += 80
    if re.search(r"\bACTIVE\b", status_text, re.I):
        score += 80
    if re.search(r"\bCURRENT\b", status_reason, re.I):
        score += 80
    if re.search(r"\bEXEMPT\b", combined, re.I):
        score += 10
    if re.search(r"\bINACTIVE\b|\bCLOSED\b|\bWITHDRAWN\b|\bCANCEL(?:ED|LED)\b", combined, re.I):
        score -= 100
    return result, score


def ct_prioritized_name_variants(original_name: str, variants: list[str]) -> list[str]:
    prioritized: list[str] = []
    seen: set[str] = set()

    def add(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip(" ,;-"))
        key = cleaned.lower()
        if cleaned and key not in seen:
            seen.add(key)
            prioritized.append(cleaned)

    base = re.sub(r"\s+", " ", (original_name or "").strip())
    add(base)
    if "&" in base:
        add(re.sub(r"\s*&\s*", " and ", base))
    if re.search(r"\band\b", base, re.I):
        add(re.sub(r"\band\b", "&", base, flags=re.I))
    if re.search(r"['\u2019]", base):
        add(re.sub(r"['\u2019]", "", base))
    no_punctuation_base = re.sub(r"[^\w\s&]", " ", base)
    add(no_punctuation_base)
    if re.search(r"[-\u2010-\u2015]", base):
        hyphen_as_space = re.sub(r"[-\u2010-\u2015]+", " ", base)
        hyphen_as_space = re.sub(r"\s+", " ", hyphen_as_space).strip()
        no_punctuation = re.sub(r"[^\w\s]", " ", base)
        no_punctuation = re.sub(r"\s+", " ", no_punctuation).strip()
        add(no_punctuation)
        add(hyphen_as_space)
        without_suffix = re.sub(
            r",?\s+\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\b\.?\s*$",
            "",
            hyphen_as_space,
            flags=re.I,
        ).strip(" ,;-")
        for legal in ("Inc", "Inc."):
            if without_suffix:
                add(f"{without_suffix} {legal}")
                add(f"{without_suffix}, {legal}")
        add(without_suffix)
    for variant in variants:
        add(variant)
    return prioritized


def search_ct_direct(org):
    url = "https://www.elicense.ct.gov/lookup/licenselookup.aspx"
    original_name = org.organization_name
    started = time.perf_counter()
    deadline = started + CT_DIRECT_MAX_SECONDS
    safe_targets = organization_match_target_variants(original_name, org.ein)
    for target in list(safe_targets):
        if not re.search(r"^\s*(the|a)\s+", target, re.I):
            for suffix in (f"{target} (THE)", f"{target}, THE", f"{target}, The"):
                if suffix not in safe_targets:
                    safe_targets.append(suffix)
    variants = ct_prioritized_name_variants(original_name, organization_name_variants(
        original_name,
        org.ein,
        include_ein_aliases=True,
        include_name_segments=True,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
    ))[:CT_NAME_VARIANT_LIMIT]
    best_result = None
    best_score = -10000
    saw_zero_results = False
    last_error = ""
    attempted_variants = 0
    completed_variants = 0
    session = None
    fields = None
    headers = None
    for variant in variants:
        remaining = deadline - time.perf_counter()
        if remaining <= 1.5:
            break
        attempted_variants += 1
        try:
            attempt_timeout = min(CT_DIRECT_TIMEOUT_SECONDS, max(4.0, remaining - 1.0))
            if session is None or fields is None or headers is None:
                session, fields, headers = ct_direct_prepare_session(attempt_timeout)
            body = ct_direct_post_query(session, fields, headers, variant, attempt_timeout)
        except Exception as exc:
            last_error = str(exc)
            session = None
            fields = None
            headers = None
            continue
        completed_variants += 1
        if re.search(r"Showing\s+0\s+result", body, re.I):
            saw_zero_results = True
            continue
        for row_match in re.finditer(r"<tr\b[^>]*>.*?</tr>", body, re.I | re.S):
            row_html = row_match.group(0)
            if not re.search(r"\b(PUBLIC\s+CHARITY|CHR\.)\b", html_fragment_text(row_html), re.I):
                continue
            result, score = ct_direct_result_from_row(org, row_html, safe_targets, url)
            if result and score > best_score:
                best_result = result
                best_score = score
        if best_result:
            return best_result
    if best_result:
        return best_result
    exhausted_budget = time.perf_counter() >= deadline - 0.25
    if not last_error and not exhausted_budget and completed_variants >= len(variants):
        return checker.StateResult(
            original_name,
            org.ein,
            "CT",
            checker.STATUS_NOT_REGISTERED,
            url,
            raw_status_text="No matching organization record",
            source_note="Connecticut public registry AJAX search returned no safely matching public-charity row for the generated name variants.",
            success=True,
        )
    result = checker.StateResult(original_name, org.ein, "CT", "Site Not Reachable", url)
    result.raw_status_text = "Connecticut direct registry lookup could not be completed"
    if saw_zero_results and (exhausted_budget or attempted_variants < len(variants)):
        result.source_note = "Connecticut public registry AJAX lookup ended before all prioritized name variants could be checked."
    else:
        result.source_note = "Connecticut public registry AJAX lookup did not return a usable response."
    result.error = last_error
    result.success = False
    return result


def search_ct(page, org):
    url = "https://www.elicense.ct.gov/lookup/licenselookup.aspx"
    original_name = org.organization_name
    started = time.perf_counter()
    deadline = started + CT_NAME_VARIANT_MAX_SECONDS

    def remaining_seconds() -> float:
        return max(0.0, deadline - time.perf_counter())

    def remaining_ms(default_ms: int, minimum_ms: int = 1000) -> int:
        remaining = int(remaining_seconds() * 1000)
        if remaining <= minimum_ms:
            return minimum_ms
        return min(default_ms, remaining)

    safe_targets = organization_match_target_variants(original_name, org.ein)
    for target in list(safe_targets):
        if not re.search(r"^\s*(the|a)\s+", target, re.I):
            for suffix in (f"{target} (THE)", f"{target}, THE", f"{target}, The"):
                if suffix not in safe_targets:
                    safe_targets.append(suffix)
    best_result = None
    variants = ct_prioritized_name_variants(original_name, organization_name_variants(
        original_name,
        org.ein,
        include_ein_aliases=True,
        include_name_segments=True,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
    ))[:CT_NAME_VARIANT_LIMIT]
    last_error = ""
    for variant in variants:
        if time.perf_counter() >= deadline:
            break
        result = checker.StateResult(original_name, org.ein, "CT", checker.STATUS_UNKNOWN, url)
        try:
            page.goto(url, wait_until="domcontentloaded", timeout=remaining_ms(18000, 2500))
            checker.safe_wait_for_network_idle(page, timeout=remaining_ms(3000, 1000))
            input_box = checker.find_visible_input(page, [
                '#ctl00_MainContentPlaceHolder_ucLicenseLookup_ctl03_tbDBA_Contact',
                'input[name*="tbDBA_Contact"]',
                'input[name*="Business" i]',
                'input[id*="Business" i]',
                'input[type="text"]',
            ])
            if not input_box:
                result.error = "CT: Could not find public registry search input"
                return result
            input_box.fill("")
            input_box.fill(variant)
            try:
                page.locator("#ctl00_MainContentPlaceHolder_ucLicenseLookup_btnLookup, input[type='submit']").first.click(timeout=remaining_ms(2500, 1000))
            except Exception:
                page.keyboard.press("Enter")
            checker.safe_wait_for_network_idle(page, timeout=remaining_ms(3000, 1000))
            try:
                page.get_by_text(re.compile(r"Showing\s+\d+\s+result", re.I)).wait_for(timeout=remaining_ms(3000, 1000))
            except Exception:
                time.sleep(min(1.0, remaining_seconds()))
            text = readable_page_text(page)
            if no_registry_results_seen(text):
                result.status = checker.STATUS_NOT_REGISTERED
                result.raw_status_text = "No matching organization record"
                result.source_note = "Connecticut public registry returned no matching record for the generated name variants."
                result.success = True
                best_result = result
                continue
            candidate_rows = page.evaluate(
                """
                () => Array.from(document.querySelectorAll('tr')).map((row, index) => {
                    const text = (row.innerText || row.textContent || '').replace(/\\s+/g, ' ').trim();
                    const detailControl = Array.from(row.querySelectorAll('a,button,input')).find((el) => {
                        const label = ((el.innerText || el.textContent || '') + ' ' + (el.value || '') + ' ' + (el.title || '')).trim();
                        return /details|view/i.test(label);
                    });
                    const hasDetails = Array.from(row.querySelectorAll('a,button,input')).some((el) => {
                        const label = ((el.innerText || el.textContent || '') + ' ' + (el.value || '') + ' ' + (el.title || '')).trim();
                        return /details|view/i.test(label);
                    });
                    return { index, text, hasDetails, detailHref: detailControl ? (detailControl.getAttribute('href') || '') : '' };
                }).filter((row) => row.hasDetails && row.text && /PUBLIC CHARITY|CHR\\./i.test(row.text));
                """
            )
            best_candidate = None
            best_score = -10000
            details_index = 0
            for candidate in candidate_rows:
                row_text = re.sub(r"\s+", " ", candidate.get("text") or "").strip()
                row_name = clean_registry_name(re.split(r"\bCredential\b|\bStatus\b|\bLicense\b", row_text, maxsplit=1, flags=re.I)[0])
                name_score = target_name_score(row_name, safe_targets)
                if name_score < 0:
                    details_index += 1
                    continue
                score = name_score
                if re.search(r"\bPUBLIC\s+CHARITY\b|\bCHR\.", row_text, re.I):
                    score += 80
                else:
                    score -= 250
                if re.search(r"\bStatus\s+ACTIVE\b|\bACTIVE\b|\bStatus\s+Reason\s+CURRENT\b", row_text, re.I):
                    score += 180
                if re.search(r"\bEXEMPT\b", row_text, re.I):
                    score += 10
                if re.search(r"\bINACTIVE\b|\bCLOSED\b|\bWITHDRAWN\b|\bCANCEL(?:ED|LED)\b", row_text, re.I):
                    score -= 180
                if re.search(r"\bSCIENTIFIC\s+RESEARCH\b|\bRESEARCH\s+CERTIFICATE\b", row_text, re.I):
                    score -= 300
                if score > best_score:
                    best_score = score
                    best_candidate = {**candidate, "details_index": details_index, "row_text": row_text, "row_name": row_name}
                details_index += 1
            if not best_candidate:
                continue
            row_text = best_candidate["row_text"]
            clicked_detail = False
            detail_href = (best_candidate.get("detailHref") or "").strip()
            if detail_href.lower().startswith("javascript:"):
                try:
                    clicked_detail = bool(page.evaluate("(href) => { eval(href.slice(11)); return true; }", detail_href))
                except Exception:
                    clicked_detail = False
            if not clicked_detail and not click_nth_details_control(page, best_candidate["details_index"]):
                continue
            checker.safe_wait_for_network_idle(page, timeout=remaining_ms(3000, 1000))
            try:
                page.get_by_text(re.compile(r"License\s+Details|Credential\s+Details", re.I)).wait_for(timeout=remaining_ms(3000, 1000))
            except Exception:
                time.sleep(min(1.0, remaining_seconds()))
            time.sleep(min(0.5, remaining_seconds()))
            detail_text = readable_page_text(page)
            detail_segment = detail_text
            for marker in ("License Details", "Lookup Detail View"):
                marker_index = detail_segment.rfind(marker)
                if marker_index >= 0:
                    detail_segment = detail_segment[marker_index:]
                    break
            if detail_segment == detail_text and not re.search(r"Registration\s+Information|Expiration\s+Date", detail_segment, re.I):
                detail_segment = row_text
            exp_date = first_date_near_label(detail_segment, ["Expiration Date", "Expiration", "Expires", "Expire Date"])
            matched_name = clean_registry_name(
                checker.extract_labeled_value_from_text(detail_segment, ["Business Name", "DBA Name", "Name and Address", "Name", "Licensee Name", "Organization Name"])
                or best_candidate.get("row_name", "")
            )
            credential = text_between_labels(detail_segment, "Credential", ["Credential Description", "Registration Type", "Status", "Effective Date", "Expiration Date"]) or text_between_labels(row_text, "Credential", ["Credential Description", "Registration Type", "Status", "Effective Date", "Expiration Date"])
            credential_description = text_between_labels(detail_segment, "Credential Description", ["Registration Type", "Status", "Effective Date", "Expiration Date"]) or text_between_labels(row_text, "Credential Description", ["Department", "Status", "Effective Date", "Expiration Date"])
            registration_type = text_between_labels(detail_segment, "Registration Type", ["Status", "Effective Date", "Expiration Date", "Status Reason"])
            status_text = text_between_labels(detail_segment, "Status", ["Status Reason", "Effective Date", "Expiration Date", "Credential", "Registration Type"]) or text_between_labels(row_text, "Status", ["Status Reason", "City", "DBA", "Details"])
            status_reason = text_between_labels(detail_segment, "Status Reason", ["Effective Date", "Expiration Date", "Credential", "Registration Type"]) or text_between_labels(row_text, "Status Reason", ["City", "DBA", "Details"])
            status_after_expiration = re.search(r"Expiration\s+Date\s+\d{1,2}/\d{1,2}/\d{2,4}\s+Status\s+([A-Z ]{3,40})(?:\s+\d{1,2}/\d{1,2}/\d{4}|$)", detail_segment, re.I)
            if status_after_expiration:
                status_text = re.sub(r"\s+", " ", status_after_expiration.group(1)).strip()
            combined_detail = " ".join([detail_segment, row_text, credential, credential_description, registration_type, status_text, status_reason])
            result.matched_registry_name = matched_name
            credential_match = re.search(r"\b[A-Z]{2,5}\.[0-9A-Z.-]+", " ".join([credential, row_text, detail_segment]))
            result.matched_registry_identifier = credential_match.group(0) if credential_match else (checker.extract_registry_identifier_from_text(detail_text, org.ein) if hasattr(checker, "extract_registry_identifier_from_text") else "")
            terminal_status_text = " ".join([status_text, status_reason, credential_description, registration_type])
            if re.search(r"\bEXEMPT\b", " ".join([credential, credential_description, registration_type, row_text]), re.I):
                result.status = "Exempt"
            elif re.search(r"\bINACTIVE\b|\bCLOSED\b|\bWITHDRAWN\b|\bCANCEL(?:ED|LED)\b", terminal_status_text, re.I):
                result.status = "Closed / Withdrawn / Canceled"
            elif re.search(r"\b(non\W*compliant|not\s+in\s+compliance)\b", combined_detail, re.I):
                result.status = checker.STATUS_DELINQUENT
            elif exp_date:
                result.status = classify_expiration_date(exp_date)
            elif re.search(r"\bStatus\s+ACTIVE\b|\bStatus\s+Reason\s+CURRENT\b|\bACTIVE\s+Status\s+Reason\s+CURRENT\b", detail_text, re.I):
                result.status = checker.STATUS_CURRENT
            else:
                result.status = checker.STATUS_UNKNOWN
            result.raw_status_text = " | ".join(
                item for item in [
                    f"Status: {status_text}" if status_text else "",
                    f"Status Reason: {status_reason}" if status_reason else "",
                    f"Registration Type: {registration_type}" if registration_type else "",
                    f"Credential Description: {credential_description}" if credential_description else "",
                    f"Expiration Date {format_date(exp_date)}" if exp_date else "",
                ]
            ) or "Connecticut registry record found"
            result.source_note = "CT uses the selected public-registry detail record, including exemption, noncompliance, and expiration fields."
            result.success = True
            return result
        except Exception as exc:
            last_error = f"CT error: {exc}"
            if best_result is not None:
                return best_result
            continue
    if best_result:
        return best_result
    if time.perf_counter() >= deadline:
        result = checker.StateResult(original_name, org.ein, "CT", "Site Not Reachable", url)
        result.raw_status_text = "Connecticut lookup reached the bounded lookup window"
        result.source_note = "Connecticut public registry lookup reached the bounded lookup window before all prioritized name variants could be checked."
        result.success = False
        return result
    if last_error:
        result = checker.StateResult(original_name, org.ein, "CT", "Site Not Reachable", url)
        result.raw_status_text = "Connecticut lookup could not be completed"
        result.source_note = "Connecticut public registry lookup could not be completed after retrying generated name variants."
        result.error = last_error
        result.success = False
        return result
    return checker.StateResult(original_name, org.ein, "CT", checker.STATUS_NOT_REGISTERED, url, raw_status_text="No matching organization record", source_note="Connecticut public registry returned no matching record for the generated name variants.", success=True)


def search_fl(page, org):
    url = FL_CHECK_A_CHARITY_URL
    original_name = org.organization_name
    safe_targets = organization_match_target_variants(original_name, org.ein)
    lookup_started = time.monotonic()
    deadline = lookup_started + FL_LOOKUP_MAX_SECONDS

    def remaining_seconds() -> float:
        return max(0.0, deadline - time.monotonic())

    def remaining_ms(default_ms: int, minimum_ms: int = 1000) -> int:
        remaining = int(remaining_seconds() * 1000)
        if remaining <= minimum_ms:
            return minimum_ms
        return min(default_ms, remaining)

    def deadline_expired() -> bool:
        return time.monotonic() >= deadline

    def clean_fl_registry_name(value: str) -> str:
        cleaned = clean_registry_name(value)
        cleaned = re.sub(r"\s+\bAlso\s+Soliciting\s+as\b.*$", "", cleaned, flags=re.I).strip()
        cleaned = re.sub(r"\s+\bPrint\b\s*$", "", cleaned, flags=re.I).strip()
        cleaned = re.sub(r",\s*[A-Z][A-Z .'-]+,\s*[A-Z]{2}\s*$", "", cleaned).strip()
        return cleaned.strip(" ,-")

    def florida_local_chapter_mismatch(row_name: str) -> bool:
        row_norm = normalized_match_name(row_name)
        target_norms = [normalized_match_name(target) for target in safe_targets]
        if not row_norm or not target_norms:
            return False
        if re.search(r"\bchapter\b", row_norm, re.I) and not any(re.search(r"\bchapter\b", target, re.I) for target in target_norms):
            return True
        if re.search(r"\bflorida\s+chapter\b|\bfl\s+chapter\b", row_norm, re.I) and not any(re.search(r"\bflorida\s+chapter\b|\bfl\s+chapter\b", target, re.I) for target in target_norms):
            return True
        return False

    def florida_related_entity_mismatch(row_name: str) -> bool:
        row_norm = normalized_match_name(row_name)
        target_norms = [normalized_match_name(target) for target in safe_targets]
        related_entity_terms = [
            "action fund",
            "political action",
            "pac",
            "auxiliary",
            "chapter",
        ]
        for term in related_entity_terms:
            term_norm = normalized_match_name(term)
            if term_norm and term_norm in row_norm and not any(term_norm in target for target in target_norms):
                return True
        return False

    def florida_nested_unrelated_entity_mismatch(row_name: str) -> bool:
        row_norm = normalized_match_name(row_name)
        target_norms = [normalized_match_name(target) for target in safe_targets]
        if not row_norm or not target_norms:
            return False
        generic = {
            "the", "a", "an", "of", "for", "and", "to", "in", "on", "at", "by",
            "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited",
            "foundation", "fund", "charity", "charities", "association", "society",
            "center", "centre", "institute", "organization", "university",
        }
        row_words = set(row_norm.split())
        for target_norm in target_norms:
            if not target_norm or target_norm == row_norm:
                return False
            if row_norm.startswith(target_norm + " "):
                return False
            if re.search(rf"\b(?:foundation|fund|friends)\s+of\s+(?:the\s+)?{re.escape(target_norm)}$", row_norm):
                return False
            if target_norm in row_norm:
                target_words = set(target_norm.split())
                extra_words = row_words - target_words - generic
                if len(extra_words) >= 2:
                    return True
        return False

    def useful_fl_search_variant(variant: str) -> bool:
        norm = normalized_match_name(variant)
        if not norm:
            return False
        generic = {
            "the", "a", "an", "of", "for", "and", "to", "in", "on", "at", "by",
            "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited",
            "co", "company", "foundation", "fund", "charity", "charities",
            "association", "society", "center", "centre", "institute",
            "organization",
        }
        meaningful = [word for word in norm.split() if word not in generic]
        if not meaningful:
            return False
        if len(meaningful) == 1 and len(meaningful[0]) < 4:
            return False
        return True

    def load_fl_search_page():
        last_error = None
        for attempt in range(2):
            if deadline_expired():
                raise TimeoutError("FL lookup exceeded its bounded search window")
            try:
                page.goto(url, wait_until="commit", timeout=remaining_ms(12000))
                return
            except Exception as exc:
                last_error = exc
                try:
                    page.evaluate("window.stop()")
                except Exception:
                    pass
                try:
                    page.goto("about:blank", wait_until="commit", timeout=remaining_ms(3000))
                except Exception:
                    pass
                if attempt == 0:
                    time.sleep(min(1, remaining_seconds()))
        raise last_error

    generated_variants = organization_name_variants(
        original_name,
        org.ein,
        include_ein_aliases=True,
        include_name_segments=True,
        include_and_segments=False,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
        include_broad_query_prefixes=False,
    )
    original_has_hyphen = "-" in (original_name or "")
    variants = []
    variant_keys = set()
    for variant in generated_variants:
        # Florida's partial-name search is slow and sometimes stalls when hit
        # repeatedly. Avoid synthetic hyphen probes unless the source name
        # actually contains a hyphen; legal suffix/article variants preserve
        # the useful coverage without multiplying no-match page loads.
        if not original_has_hyphen and "-" in variant:
            continue
        if not useful_fl_search_variant(variant):
            continue
        variant_key = (
            normalized_match_name(variant),
            bool(re.search(r"\b(?:inc|incorporated|corp|corporation|ltd|limited|llc)\.?\b", variant, re.I)),
        )
        if variant_key not in variant_keys:
            variant_keys.add(variant_key)
            variants.append(variant)
    best_result = None
    last_error = None
    search_variants = list(variants[:8])
    final_exact_retry_added = False
    for variant in search_variants:
        if deadline_expired():
            break
        result = checker.StateResult(original_name, org.ein, "FL", checker.STATUS_UNKNOWN, url)
        try:
            try:
                page.set_default_timeout(remaining_ms(8000))
                page.set_default_navigation_timeout(remaining_ms(12000))
            except Exception:
                pass
            load_fl_search_page()
            try:
                page.locator('input[name*="BusinessName" i], input[id*="BusinessName" i], input[type="text"]').first.wait_for(state="visible", timeout=remaining_ms(6000))
            except Exception:
                checker.safe_wait_for_network_idle(page, timeout=remaining_ms(3000))
            input_box = checker.find_visible_input(page, [
                'input[name*="BusinessName" i]',
                'input[id*="BusinessName" i]',
                'input[name*="Organization" i]',
                'input[type="text"]',
            ])
            if not input_box:
                result.error = "FL: Could not find Business Name input"
                return result
            input_box.fill("", timeout=remaining_ms(4000))
            input_box.fill(variant, timeout=remaining_ms(4000))
            try:
                page.get_by_role("button", name=re.compile("search", re.I)).click(timeout=remaining_ms(4000), no_wait_after=True)
            except Exception:
                page.keyboard.press("Enter")
            checker.safe_wait_for_network_idle(page, timeout=remaining_ms(5000))
            time.sleep(min(0.5, remaining_seconds()))
            text = readable_page_text(page)
            if no_registry_results_seen(text):
                result.status = checker.STATUS_NOT_REGISTERED
                result.raw_status_text = "No matching organization record"
                result.source_note = "Florida Check-A-Charity returned no matching record for the generated name variants."
                result.success = True
                best_result = result
                continue
            candidate_rows = page.evaluate(
                """
                () => Array.from(document.querySelectorAll('tr')).map((row) => {
                    const text = (row.innerText || row.textContent || '').replace(/\\s+/g, ' ').trim();
                    return { text };
                }).filter((row) => row.text && /License\\/Registration Number|Expiration Date|Solicitation|Business Name|CH\\d+/i.test(row.text));
                """
            )
            best_candidate = None
            best_score = -10000
            for candidate in candidate_rows:
                row_text = re.sub(r"\s+", " ", candidate.get("text") or "").strip()
                row_name = (
                    text_between_labels(row_text, "Business Name", ["License/Registration Number", "Registration Number", "Expiration Date", "Status"])
                    or clean_fl_registry_name(re.split(r"\bLicense/Registration Number\b|\bRegistration Number\b|\bExpiration Date\b", row_text, maxsplit=1, flags=re.I)[0])
                )
                row_name = clean_fl_registry_name(row_name)
                name_score = target_name_score(row_name, safe_targets)
                if name_score < 0:
                    continue
                if re.search(r"\bAdvanced\s+Search\b", row_name, re.I):
                    continue
                if florida_local_chapter_mismatch(row_name):
                    continue
                if florida_related_entity_mismatch(row_name):
                    continue
                if florida_nested_unrelated_entity_mismatch(row_name):
                    continue
                score = name_score
                if re.search(r"\bCH\d+\b", row_text, re.I):
                    score += 40
                if score > best_score:
                    best_score = score
                    best_candidate = {"row_text": row_text, "row_name": row_name}
            if not best_candidate:
                result.status = checker.STATUS_NOT_REGISTERED
                result.raw_status_text = "No matching organization record"
                result.source_note = "Florida Check-A-Charity returned search results, but none safely matched the requested organization."
                result.success = True
                best_result = result
                continue
            row_text = best_candidate["row_text"]
            exp_date = first_date_near_label(row_text, ["Expiration Date", "Expiration", "Expires"])
            suspended_match = re.search(r"\bSuspended\b", row_text, re.I)
            revoked_match = re.search(r"\bRevoked\b", row_text, re.I)
            if not exp_date:
                if suspended_match:
                    result.status = "Suspended"
                    result.raw_status_text = "Status: Suspended"
                    result.source_note = "FL uses the registration status shown next to the Check-A-Charity registration number."
                    result.matched_registry_name = clean_fl_registry_name(best_candidate["row_name"])
                    id_match = re.search(r"\bCH\d+\b", row_text, re.I)
                    result.matched_registry_identifier = id_match.group(0).upper() if id_match else ""
                    result.success = True
                    return result
                if revoked_match:
                    result.status = "Revoked"
                    result.raw_status_text = "Status: Revoked"
                    result.source_note = "FL uses the registration status shown next to the Check-A-Charity registration number."
                    result.matched_registry_name = clean_fl_registry_name(best_candidate["row_name"])
                    id_match = re.search(r"\bCH\d+\b", row_text, re.I)
                    result.matched_registry_identifier = id_match.group(0).upper() if id_match else ""
                    result.success = True
                    return result
                best_result = result
                continue
            if suspended_match:
                result.status = "Suspended"
                result.raw_status_text = f"Status: Suspended | Expiration Date {format_date(exp_date)}"
            elif revoked_match:
                result.status = "Revoked"
                result.raw_status_text = f"Status: Revoked | Expiration Date {format_date(exp_date)}"
            else:
                result.status = classify_expiration_date(exp_date)
                result.raw_status_text = f"Expiration Date {format_date(exp_date)}"
            result.source_note = "FL uses the expiration date shown by Check-A-Charity."
            result.matched_registry_name = clean_fl_registry_name(best_candidate["row_name"])
            id_match = re.search(r"\bCH\d+\b", row_text, re.I)
            result.matched_registry_identifier = id_match.group(0).upper() if id_match else ""
            result.success = True
            return result
        except Exception as exc:
            last_error = exc
            result.error = f"FL error: {exc}"
            if (
                not final_exact_retry_added
                and normalized_match_name(original_name) != normalized_match_name(variant)
                and remaining_seconds() > 4
            ):
                search_variants.append(original_name)
                final_exact_retry_added = True
            if deadline_expired():
                break
            continue
    if best_result:
        if deadline_expired():
            best_result.source_note = " ".join(
                part for part in [
                    best_result.source_note,
                    "Florida Check-A-Charity reached the bounded lookup window before all generated name variants were attempted.",
                ] if part
            )
        return best_result
    if last_error:
        return checker.StateResult(
            original_name,
            org.ein,
            "FL",
            checker.STATUS_NOT_REGISTERED,
            url,
            raw_status_text="No usable Florida Check-A-Charity result within bounded lookup window",
            source_note="Florida Check-A-Charity did not return a usable search result within CharityClarity's bounded lookup window; no safely matching Florida registration record was confirmed.",
            success=True,
            error="",
        )
    return checker.StateResult(original_name, org.ein, "FL", checker.STATUS_NOT_REGISTERED, url, raw_status_text="No matching organization record", source_note="Florida Check-A-Charity returned no matching record for the generated name variants.", success=True)


def mn_status_from_fiscal_year(year: int | None) -> str:
    if not year:
        return checker.STATUS_UNKNOWN
    try:
        next_report_due = date(year + 1, 12, 31)
    except ValueError:
        return checker.STATUS_UNKNOWN
    return status_from_calendar_date(next_report_due)


def search_mn(page, org):
    url = "https://www.ag.state.mn.us/Charity/Search/"
    result = checker.StateResult(org.organization_name, org.ein, "MN", checker.STATUS_UNKNOWN, url)
    ein_digits = re.sub(r"\D", "", org.ein or "")
    formatted_ein = format_ein(org.ein)
    search_values = []
    for value in [ein_digits, formatted_ein, org.ein]:
        value = (value or "").strip()
        if value and value not in search_values:
            search_values.append(value)
    try:
        for search_value in search_values:
            page.goto(url, wait_until="domcontentloaded", timeout=30000)
            checker.safe_wait_for_network_idle(page, timeout=8000)
            input_box = checker.find_visible_input(page, [
                '#txtEIN',
                'input[name*="EIN" i]',
                'input[id*="EIN" i]',
                'input[name*="FEIN" i]',
                'input[type="text"]',
            ])
            if not input_box:
                result.error = "MN: Could not find EIN input"
                return result
            input_box.fill("")
            input_box.fill(search_value)
            try:
                page.locator('input[name="cmdSearch"], input[type="submit"]').last.click(timeout=5000)
            except Exception:
                page.keyboard.press("Enter")
            checker.safe_wait_for_network_idle(page, timeout=10000)
            time.sleep(1)
            text = readable_page_text(page)
            if no_registry_results_seen(text):
                result.status = checker.STATUS_NOT_REGISTERED
                result.raw_status_text = "No matching EIN result"
                result.source_note = "Minnesota Attorney General charity search returned no matching EIN record."
                result.success = True
                continue
            detail_link = None
            if ein_digits:
                detail_link = page.locator(f'a[href*="FederalID={ein_digits}"]').first
                try:
                    if detail_link.count() == 0:
                        detail_link = page.locator(f'a[href*="{formatted_ein}"]').first
                except Exception:
                    pass
            try:
                if not detail_link or detail_link.count() == 0:
                    detail_link = page.locator("a[href*='FederalID=']").first
            except Exception:
                detail_link = None
            if not detail_link or detail_link.count() == 0:
                result.status = checker.STATUS_NOT_REGISTERED
                result.raw_status_text = "No matching EIN result"
                result.source_note = "Minnesota Attorney General charity search did not expose a matching FederalID detail link for the requested EIN."
                result.success = True
                continue
            try:
                detail_link.click(timeout=5000)
                checker.safe_wait_for_network_idle(page, timeout=10000)
                time.sleep(1)
            except Exception:
                pass
            detail_text = readable_page_text(page)
            if ein_digits and ein_digits not in re.sub(r"\D", "", detail_text):
                result.status = checker.STATUS_NOT_REGISTERED
                result.raw_status_text = "No matching EIN result"
                result.source_note = "Minnesota search returned a possible record, but the public detail did not confirm the requested EIN."
                result.success = True
                continue
            year_match = re.search(r"(?:Fiscal\s+Year\s+Ending|For\s+Fiscal\s+Year\s+Ending)\s*:?\s*(?:\d{1,2}[/-]\d{1,2}[/-])?(20\d{2})", detail_text, re.I)
            year = int(year_match.group(1)) if year_match else None
            result.status = mn_status_from_fiscal_year(year)
            result.raw_status_text = f"Fiscal Year Ending {year}" if year else "Minnesota registry record found"
            result.source_note = "MN uses the latest fiscal year ending shown by the Attorney General charity search. CharityClarity tried both undashed and dashed EIN formats when needed."
            result.matched_registry_name = useful_registry_name(checker.extract_labeled_value_from_text(detail_text, ["Organization Name", "Charity Name", "Name"]))
            result.matched_registry_identifier = checker.extract_registry_identifier_from_text(detail_text, org.ein) if hasattr(checker, "extract_registry_identifier_from_text") else ""
            result.success = True
            return result
        safe_targets = organization_match_target_variants(org.organization_name, org.ein)
        name_fallback_started = time.perf_counter()
        for index, variant in enumerate(organization_name_variants(
            org.organization_name,
            org.ein,
            include_ein_aliases=True,
            include_name_segments=True,
            include_compact_legal_suffixes=True,
            include_leading_article_variants=True,
            include_broad_query_prefixes=False,
        )[:MN_NAME_FALLBACK_MAX_VARIANTS]):
            if index > 0 and (time.perf_counter() - name_fallback_started) >= MN_NAME_FALLBACK_MAX_SECONDS:
                break
            page.goto(url, wait_until="domcontentloaded", timeout=30000)
            checker.safe_wait_for_network_idle(page, timeout=5000)
            org_box = checker.find_visible_input(page, ["#txtOrg", 'input[name="txtOrg"]'])
            if not org_box:
                break
            org_box.fill("")
            org_box.fill(variant)
            try:
                page.locator('input[name="cmdSearch"], input[type="submit"]').last.click(timeout=5000)
            except Exception:
                page.keyboard.press("Enter")
            checker.safe_wait_for_network_idle(page, timeout=7000)
            time.sleep(0.5)
            text = readable_page_text(page)
            if no_registry_results_seen(text):
                continue
            try:
                row_candidates = page.evaluate(
                    """
                    () => Array.from(document.querySelectorAll('table tr, tr')).map((row, index) => {
                        const text = (row.innerText || row.textContent || '').replace(/\\s+/g, ' ').trim();
                        const link = row.querySelector('a[href*="CHR_GeneralInfo"]');
                        return { index, text, linkText: link ? (link.innerText || link.textContent || '').replace(/\\s+/g, ' ').trim() : '' };
                    }).filter((row) => row.linkText && row.text);
                    """
                )
            except Exception:
                row_candidates = []
            best_index = None
            best_score = -10000
            best_name = ""
            safe_target_norms = [normalized_match_name(target) for target in safe_targets]
            short_exact_targets = {
                target_norm for target_norm in safe_target_norms
                if target_norm and len(target_norm.split()) <= 1 and len(target_norm) <= 8
            }
            for candidate in row_candidates:
                row_text = candidate.get("text") or ""
                link_text = candidate.get("linkText") or ""
                if short_exact_targets and normalized_match_name(link_text) not in short_exact_targets:
                    continue
                score = target_name_score(link_text, safe_targets)
                try:
                    checker_score = checker.candidate_selection_score_for_targets(row_text, safe_targets, row_text)
                    if checker_score[0] >= 0:
                        score = max(score, 520 + checker_score[0] * 20 + checker_score[1])
                except Exception:
                    pass
                if score > best_score:
                    best_score = score
                    best_index = candidate.get("index")
                    best_name = candidate.get("linkText") or ""
            if best_index is None or best_score < 450:
                continue
            try:
                link = page.get_by_role("link", name=re.compile(re.escape(best_name), re.I)).first
            except Exception:
                link = page.locator("a[href*='CHR_GeneralInfo']").first
            try:
                link.click(timeout=5000)
                checker.safe_wait_for_network_idle(page, timeout=7000)
                time.sleep(0.5)
            except Exception:
                continue
            detail_text = readable_page_text(page)
            year_match = re.search(r"(?:Fiscal\s+Year\s+Ending|For\s+Fiscal\s+Year\s+Ending)\s*:?\s*(?:\d{1,2}[/-]\d{1,2}[/-])?(20\d{2})", detail_text, re.I)
            year = int(year_match.group(1)) if year_match else None
            status_line = text_between_labels(detail_text, "Status", ["Extension", "Financial Information", "For Fiscal Year Ending"])
            if re.search(r"\binactive|closed|withdrawn|cancel", status_line or "", re.I):
                result.status = "Closed / Withdrawn / Canceled"
            else:
                result.status = mn_status_from_fiscal_year(year)
            result.raw_status_text = " | ".join(item for item in [
                f"Status: {status_line}" if status_line else "",
                f"Fiscal Year Ending {year}" if year else "",
                "Matched by organization name after EIN search returned no exact result",
            ])
            result.source_note = "MN tried EIN search first, then used the public organization-name search when the EIN field returned no exact result."
            result.matched_registry_name = clean_registry_name(best_name or checker.extract_labeled_value_from_text(detail_text, ["Organization Name", "Charity Name", "Name"]))
            federal_match = re.search(r"FEDERAL\s+ID#?\s*([0-9-]+)", detail_text, re.I)
            result.matched_registry_identifier = federal_match.group(1) if federal_match else ""
            result.success = True
            return result
        return result
    except Exception as exc:
        result.error = f"MN error: {exc}"
        return result


def ohio_due_date(most_recent_filing_year: int, fiscal_year_end_month: int) -> date:
    next_fiscal_year = most_recent_filing_year + 1
    _, fiscal_end_day = calendar.monthrange(next_fiscal_year, fiscal_year_end_month)
    fiscal_end_date = date(next_fiscal_year, fiscal_year_end_month, fiscal_end_day)
    due_month_index = fiscal_end_date.month - 1 + 5
    due_year = fiscal_end_date.year + due_month_index // 12
    due_month = due_month_index % 12 + 1
    return date(due_year, due_month, 15)


def ohio_detail_url(page_name: str, detail_id: str) -> str:
    page_name = str(page_name or "").strip()
    detail_id = str(detail_id or "").strip()
    if page_name in {"109", "1716"}:
        return (
            "https://charitableregistration.ohioago.gov/Charities/"
            f"PartiallyExemptOrganization?Id={quote(detail_id)}&ExemptionStatus={quote(page_name)}"
        )
    page_name = page_name or "OrganizationDetails"
    return f"https://charitableregistration.ohioago.gov/Charities/{quote(page_name)}?Id={quote(detail_id)}"


def search_oh(page, org):
    url = "https://charitableregistration.ohioago.gov/Charities/ResearchCharities"
    result = checker.StateResult(org.organization_name or format_ein(org.ein), org.ein, "OH", checker.STATUS_UNKNOWN, url)
    ein_digits = re.sub(r"\D", "", org.ein or "")
    formatted_ein = format_ein(org.ein)
    month_names = {name.lower(): index for index, name in enumerate(calendar.month_name) if name}
    month_names.update({name.lower(): index for index, name in enumerate(calendar.month_abbr) if name})
    search_summary_text = ""
    if len(ein_digits) != 9:
        result.error = "OH: EIN search requires a 9-digit EIN."
        return result
    try:
        page.goto(url, wait_until="domcontentloaded", timeout=45000)
        checker.safe_wait_for_network_idle(page, timeout=8000)
        page.locator("#EIN").fill("")
        page.locator("#EIN").fill(formatted_ein)
        try:
            page.locator("#ddlEINFilterCriteriaList").select_option(label=re.compile("Equals", re.I))
        except Exception:
            try:
                page.locator("#ddlEINFilterCriteriaList").select_option(value="Equals")
            except Exception:
                pass
        page.locator("#OnSubmit").click(timeout=10000)
        try:
            page.wait_for_load_state("domcontentloaded", timeout=15000)
        except Exception:
            pass
        checker.safe_wait_for_network_idle(page, timeout=12000)
        time.sleep(2)
        text = readable_page_text(page)
        search_summary_text = text
        if no_registry_results_seen(text):
            result.status = checker.STATUS_NOT_REGISTERED
            result.raw_status_text = "No matching EIN result"
            result.source_note = "Ohio EIN search returned no matching record."
            result.success = True
            return result
        detail_ref = page.evaluate(
            """
            (einDigits) => {
                const rows = Array.from(document.querySelectorAll('tr'));
                for (const row of rows) {
                    const rowText = (row.innerText || row.textContent || '').replace(/\\D/g, '');
                    if (!rowText.includes(einDigits)) continue;
                    const links = Array.from(row.querySelectorAll('a'));
                    for (const link of links) {
                        const onclick = link.getAttribute('onclick') || '';
                        const match = onclick.match(/OpenDetailsLink\\('([^']+)','(\\d+)'\\)/i);
                        if (match) return { pageName: match[1], id: match[2] };
                    }
                }
                const body = document.body ? document.body.innerHTML : '';
                const match = body.match(/OpenDetailsLink\\('([^']+)','(\\d+)'\\)/i);
                return match ? { pageName: match[1], id: match[2] } : null;
            }
            """,
            ein_digits,
        )
        if not detail_ref:
            safe_targets = organization_match_target_variants(org.organization_name, org.ein)
            for variant in organization_name_variants(
                org.organization_name,
                org.ein,
                include_ein_aliases=True,
                include_name_segments=True,
                include_compact_legal_suffixes=True,
                include_leading_article_variants=True,
                include_broad_query_prefixes=False,
            )[:10]:
                page.goto(url, wait_until="domcontentloaded", timeout=45000)
                checker.safe_wait_for_network_idle(page, timeout=8000)
                page.locator("#OrgNameOrDBAName").fill("")
                page.locator("#OrgNameOrDBAName").fill(variant)
                try:
                    page.locator("#ddlOrgNameFilterCriteriaList").select_option(label="Contains")
                except Exception:
                    pass
                page.locator("#OnSubmit").click(timeout=10000)
                try:
                    page.wait_for_load_state("domcontentloaded", timeout=15000)
                except Exception:
                    pass
                checker.safe_wait_for_network_idle(page, timeout=12000)
                time.sleep(2)
                search_summary_text = readable_page_text(page)
                detail_ref = page.evaluate(
                    """
                    ({ einDigits, targets }) => {
                        const normalize = (value) => (value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\\b(the|a|an|inc|incorporated|corp|corporation|llc|ltd)\\b/g, ' ').replace(/\\s+/g, ' ').trim();
                        const targetNorms = (targets || []).map(normalize).filter(Boolean);
                        const rows = Array.from(document.querySelectorAll('tr'));
                        let best = null;
                        let bestScore = -1;
                        for (const row of rows) {
                            const text = (row.innerText || row.textContent || '').replace(/\\s+/g, ' ').trim();
                            if (!text) continue;
                            const digits = text.replace(/\\D/g, '');
                            let score = digits.includes(einDigits) ? 1000 : -1;
                            const cells = Array.from(row.querySelectorAll('td')).map((cell) => (cell.innerText || cell.textContent || '').replace(/\\s+/g, ' ').trim());
                            const rowName = cells[0] || text;
                            const rowNorm = normalize(rowName);
                            for (const target of targetNorms) {
                                if (rowNorm && (rowNorm === target || rowNorm.includes(target) || target.includes(rowNorm))) {
                                    score = Math.max(score, 500 + Math.min(rowNorm.length, target.length));
                                }
                            }
                            if (score < bestScore) continue;
                            const link = Array.from(row.querySelectorAll('a')).find((a) => /View Details/i.test((a.innerText || a.textContent || '')));
                            const onclick = link ? (link.getAttribute('onclick') || '') : '';
                            const match = onclick.match(/OpenDetailsLink\\('([^']+)','(\\d+)'\\)/i);
                            if (match) {
                                best = { pageName: match[1], id: match[2] };
                                bestScore = score;
                            }
                        }
                        return best || null;
                    }
                    """,
                    {"einDigits": ein_digits, "targets": safe_targets},
                )
                if detail_ref:
                    break
            if not detail_ref:
                result.status = checker.STATUS_NOT_REGISTERED
                result.raw_status_text = "No matching EIN or organization-name result"
                result.source_note = "Ohio EIN search did not return a detail link, and the organization-name fallback did not find a matching Ohio record."
                result.success = True
                return result
        detail_id = str((detail_ref or {}).get("id") or "")
        detail_page_name = str((detail_ref or {}).get("pageName") or "OrganizationDetails")
        detail_url = ohio_detail_url(detail_page_name, detail_id)
        page.goto(detail_url, wait_until="domcontentloaded", timeout=45000)
        checker.safe_wait_for_network_idle(page, timeout=10000)
        time.sleep(1)
        detail_text = readable_page_text(page)
        if ein_digits not in re.sub(r"\D", "", detail_text):
            result.status = checker.STATUS_NOT_REGISTERED
            result.raw_status_text = "No matching EIN result"
            result.source_note = "Ohio detail page did not confirm the requested EIN."
            result.success = True
            return result
        site_name = text_between_labels(detail_text, "Organization Name", ["Organization Phone", "EIN", "Registration Status"])
        registration_status = text_between_labels(detail_text, "Registration Status", ["Annual Reports Filed", "Most Recent Report Filing Year", "Fiscal Year End"])
        exemption_status = text_between_labels(detail_text, "Exemption Status", ["Annual Reports Filed", "Most Recent Report Filing Year", "Fiscal Year End", "Street Address", "Organization Phone"])
        filing_year_raw = text_between_labels(detail_text, "Most Recent Report Filing Year", ["The financial information below", "Fiscal Year End", "Total Revenue"])
        fiscal_year_end_raw = text_between_labels(detail_text, "Fiscal Year End", ["Street Address", "Organization Phone", "Most Recent Report Filing Year"])
        filing_year_match = re.search(r"\b(20\d{2})\b", filing_year_raw or "")
        fiscal_month = month_names.get((fiscal_year_end_raw or "").split()[0].lower()) if fiscal_year_end_raw else None
        result.source_url = detail_url
        result.matched_registry_name = clean_registry_name(site_name)
        result.matched_registry_identifier = detail_id
        result.raw_status_text = (
            f"Registration Status: {registration_status or 'N/A'} | "
            f"Exemption Status: {exemption_status or 'N/A'} | "
            f"Most Recent Report Filing Year: {filing_year_raw or 'N/A'} | "
            f"Fiscal Year End: {fiscal_year_end_raw or 'N/A'}"
        )
        if re.search(r"\bexempt\b", " ".join([exemption_status or "", registration_status or ""]), re.I):
            result.status = "Exempt"
        elif re.search(r"\bpending\b", registration_status or "", re.I):
            result.status = "Pending"
        elif re.search(r"\b(revoked|suspended)\b", registration_status or "", re.I):
            result.status = registration_status.title()
        elif filing_year_match and fiscal_month:
            due = ohio_due_date(int(filing_year_match.group(1)), fiscal_month)
            result.status = classify_expiration_date(due)
            result.raw_status_text += f" | Next Due: {format_date(due)}"
        elif re.search(r"\bregistered\b|\bin\s+compliance\b|\byes\b", registration_status or "", re.I):
            result.status = checker.STATUS_CURRENT
        else:
            result.status = checker.STATUS_UNKNOWN
        result.source_note = "OH uses EIN search first and computes the next base annual-report due date from the public detail page."
        result.success = True
        return result
    except Exception as exc:
        result.error = f"OH error: {exc}"
        return result


def find_ak_print_link_relaxed(page, org):
    formatted_ein = checker.format_ein_with_dash(org.ein)
    ein_digits = re.sub(r"\D", "", org.ein or "")
    variants = organization_name_variants(org.organization_name, org.ein)
    found = page.evaluate(
        """
        ({ formattedEin, einDigits, names }) => {
            const normalize = (value) => (value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
            const normalizedNames = (names || []).map(normalize).filter(Boolean);
            const rows = Array.from(document.querySelectorAll('table.DocTable tbody tr, table tbody tr'));
            let nameOnlyCandidate = null;
            for (const row of rows) {
                const rowText = (row.innerText || row.textContent || '').trim().replace(/\\s+/g, ' ');
                const cells = Array.from(row.querySelectorAll('td')).map((cell) => (cell.innerText || cell.textContent || '').trim().replace(/\\s+/g, ' ')).filter(Boolean);
                const rowDigits = rowText.replace(/\\D/g, '');
                const rowNorm = normalize(rowText);
                const einSeen = (formattedEin && rowText.includes(formattedEin)) || (einDigits && rowDigits.includes(einDigits));
                const nameSeen = normalizedNames.length && normalizedNames.some((name) => rowNorm.includes(name) || name.includes(rowNorm));
                if (!einSeen && !nameSeen) continue;
                const links = Array.from(row.querySelectorAll('a'));
                for (const link of links) {
                    const text = (link.innerText || link.textContent || '').trim();
                    const rect = link.getBoundingClientRect();
                    const style = window.getComputedStyle(link);
                    const visible = !!(rect.width && rect.height) && style.display !== 'none' && style.visibility !== 'hidden';
                    if (/^Print$/i.test(text) && visible) {
                        const candidate = { found: true, rowText, cells, x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
                        if (einSeen) return candidate;
                        if (!nameOnlyCandidate) nameOnlyCandidate = candidate;
                    }
                }
            }
            return nameOnlyCandidate;
        }
        """,
        {"formattedEin": formatted_ein, "einDigits": ein_digits, "names": variants},
    )
    if found:
        return found
    for variant in variants:
        try:
            found = checker.find_ak_print_link(page, org_with_name(org, variant))
            if found:
                return found
        except Exception:
            pass
    return None


def wait_ak_search_results(page, timeout: float = 3.5) -> None:
    deadline = time.perf_counter() + timeout
    while time.perf_counter() < deadline:
        try:
            text = page.locator("#Dv-l").inner_text(timeout=600)
            if re.search(r"\bPrint\b|There are no charitable organizations", text or "", re.I):
                return
        except Exception:
            pass
        time.sleep(0.2)


def fill_ak_search_form_ein_fast(page, org, year: int) -> None:
    submission = page.locator("#Dq-8")
    if submission.count() == 0:
        submission = page.get_by_label(re.compile(r"Submission\s+type", re.I)).first
    submission.wait_for(state="visible", timeout=10000)
    submission.select_option(label="Charitable Organization")
    try:
        submission.dispatch_event("change")
    except Exception:
        pass
    time.sleep(0.25)
    year_select = page.locator("#Dq-9")
    if year_select.count() == 0:
        year_select = page.get_by_label(re.compile(r"Year", re.I)).first
    year_select.wait_for(state="visible", timeout=8000)
    try:
        year_select.select_option(label=str(year))
    except Exception:
        year_select.select_option(value=str(year))
    try:
        year_select.dispatch_event("change")
    except Exception:
        pass
    time.sleep(0.25)
    name_input = page.locator("#Dq-a")
    if name_input.count() == 0:
        name_input = page.get_by_label(re.compile(r"^Name$", re.I)).first
    try:
        name_input.fill("")
    except Exception:
        pass
    fein_input = page.locator("#Dq-b")
    if fein_input.count() == 0:
        fein_input = page.get_by_label(re.compile(r"FEIN", re.I)).first
    fein_input.wait_for(state="visible", timeout=8000)
    fein_input.fill("")
    fein_input.type(checker.format_ein_with_dash(org.ein), delay=20)
    try:
        fein_input.dispatch_event("input")
        fein_input.dispatch_event("change")
    except Exception:
        pass
    time.sleep(0.2)
    search_button = page.locator("#Dq-c")
    if search_button.count() == 0:
        search_button = page.get_by_role("button", name=re.compile(r"^Search$", re.I)).first
    search_button.click(timeout=10000, force=True)
    wait_ak_search_results(page)


def fill_ak_search_form_name_only(page, org, year: int, variant: str) -> None:
    submission = page.locator("#Dq-8")
    if submission.count() == 0:
        submission = page.get_by_label(re.compile(r"Submission\s+type", re.I)).first
    submission.wait_for(state="visible", timeout=10000)
    submission.select_option(label="Charitable Organization")
    try:
        submission.dispatch_event("change")
    except Exception:
        pass
    time.sleep(0.5)
    year_select = page.locator("#Dq-9")
    if year_select.count() == 0:
        year_select = page.get_by_label(re.compile(r"Year", re.I)).first
    year_select.wait_for(state="visible", timeout=8000)
    selected_year = False
    try:
        year_select.select_option(label=str(year))
        selected_year = True
    except Exception:
        try:
            year_select.select_option(value=str(year))
            selected_year = True
        except Exception:
            pass
    if not selected_year:
        try:
            year_select.select_option(index=0)
        except Exception:
            pass
    try:
        year_select.dispatch_event("change")
    except Exception:
        pass
    time.sleep(0.5)
    name_input = page.locator("#Dq-a")
    if name_input.count() == 0:
        name_input = page.get_by_label(re.compile(r"^Name$", re.I)).first
    name_input.wait_for(state="visible", timeout=8000)
    name_input.fill("")
    name_input.type(variant, delay=25)
    try:
        name_input.dispatch_event("input")
        name_input.dispatch_event("change")
    except Exception:
        pass
    time.sleep(0.5)
    fein_input = page.locator("#Dq-b")
    if fein_input.count() == 0:
        fein_input = page.get_by_label(re.compile(r"FEIN", re.I)).first
    try:
        fein_input.fill("")
    except Exception:
        pass
    search_button = page.locator("#Dq-c")
    if search_button.count() == 0:
        search_button = page.get_by_role("button", name=re.compile(r"^Search$", re.I)).first
    search_button.click(timeout=10000, force=True)
    wait_ak_search_results(page)


def ak_name_fallback_variants(original_name: str, ein: str = "") -> list[str]:
    variants: list[str] = []

    def add(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip(" ,;-"))
        if not cleaned:
            return
        normalized = normalized_match_name(cleaned)
        if len(normalized.split()) <= 1 and len(normalized) <= 4:
            return
        if cleaned.lower() not in {existing.lower() for existing in variants}:
            variants.append(cleaned)

    def add_internal_hyphen_variants(value: str) -> None:
        words = re.findall(r"[A-Za-z0-9&']+", value or "")
        if len(words) < 3:
            return
        # Prefer non-leading internal joins first: "Sloan-Kettering" is much
        # more likely to be a registry spelling than "Memorial-Sloan".
        for index in range(1, len(words) - 1):
            add(" ".join(words[:index] + [f"{words[index]}-{words[index + 1]}"] + words[index + 2:]))
        add(" ".join([f"{words[0]}-{words[1]}"] + words[2:]))

    def add_suffix_reductions(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip())
        suffixes = [
            "national medical center",
            "medical center",
            "hospital center",
            "hospital",
            "foundation",
            "incorporated",
            "inc",
        ]
        for suffix in suffixes:
            match = re.search(rf"\s+{re.escape(suffix)}\.?$", cleaned, re.I)
            if match:
                add(cleaned[: match.start()])

    def add_light_preposition_reduction(value: str) -> None:
        words = re.findall(r"[A-Za-z0-9&']+", value or "")
        if len(words) >= 4:
            reduced = " ".join(word for word in words if word.lower() not in {"of", "for"})
            if reduced and reduced.lower() != re.sub(r"\s+", " ", value or "").strip().lower():
                add(reduced)

    for alias in known_names_for_ein(ein):
        if compatible_ein_alias_for_name(original_name, alias):
            alias_words = normalized_match_name(alias).split()
            if len(alias_words) >= 3 and 2 <= len(alias_words[0]) <= 5:
                rest = " ".join(alias_words[1:]).title()
                add(f"{alias_words[0].upper()}: {rest}")
                add(rest)
            add(alias)
    add(original_name)
    add_internal_hyphen_variants(original_name)
    add_suffix_reductions(original_name)
    add_light_preposition_reduction(original_name)
    for variant in organization_name_variants(
        original_name,
        ein,
        include_ein_aliases=False,
        include_name_segments=False,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
        include_broad_query_prefixes=False,
        include_institutional_reductions=True,
    ):
        add(variant)
        if len(variants) >= 8:
            break
    return variants[:8]


def ak_row_has_wrong_ein(row_text: str, expected_ein: str) -> bool:
    expected_digits = re.sub(r"\D", "", expected_ein or "")
    if len(expected_digits) != 9:
        return False
    # Alaska row text also contains street/ZIP digits; only dashed FEIN-shaped
    # values should be treated as registry EINs here.
    seen = re.findall(r"\b\d{2}-\d{7}\b", row_text or "")
    for value in seen:
        if re.sub(r"\D", "", value) != expected_digits:
            return True
    return False


def ak_registry_name_from_print_row(print_link: dict, row_text: str, original_name: str, ein: str = "") -> str:
    skip_pattern = re.compile(r"^(?:print|\d{4}|\d{2}[-\s]?\d{7})$", re.I)
    cells = print_link.get("cells") if isinstance(print_link, dict) else None
    if isinstance(cells, list):
        for cell in cells:
            candidate = useful_registry_name(str(cell))
            if not candidate or skip_pattern.match(candidate):
                continue
            if re.match(r"^\d+\s+", candidate):
                continue
            if registry_name_is_safe_for_org(candidate, original_name, ein):
                return candidate
    ein_match = re.search(r"\b\d{2}[-\s]?\d{7}\b", row_text or "")
    if ein_match:
        tail = row_text[ein_match.end():]
        tail = re.split(r"\bPrint\b", tail, maxsplit=1, flags=re.I)[0]
        candidate = re.split(r"\s+\d{1,6}\s+[A-Za-z0-9]", tail, maxsplit=1)[0]
        candidate = useful_registry_name(candidate)
        if candidate and registry_name_is_safe_for_org(candidate, original_name, ein):
            return candidate
    return ""


def ak_registry_identifier_from_print_row(print_link: dict, row_text: str) -> str:
    cells = print_link.get("cells") if isinstance(print_link, dict) else None
    if isinstance(cells, list):
        for cell in cells:
            match = re.search(r"\b\d{2}[-\s]?\d{7}\b", str(cell) or "")
            if match:
                return format_ein(match.group(0))
    match = re.search(r"\b\d{2}[-\s]?\d{7}\b", row_text or "")
    return format_ein(match.group(0)) if match else ""


def ak_last_year_from_print_row(print_link: dict, row_text: str) -> int | None:
    cells = print_link.get("cells") if isinstance(print_link, dict) else None
    candidates = []
    if isinstance(cells, list):
        candidates.extend(str(cell or "") for cell in cells[:2])
    candidates.append(row_text or "")
    for value in candidates:
        match = re.match(r"\s*(20\d{2})\b", value or "")
        if match:
            try:
                return int(match.group(1))
            except Exception:
                pass
    return None


def ak_newer_year_result_from_retry(page, lookup_org, original_org, original_name: str, found_year: int, name_fallback: bool = False) -> tuple[int | None, str, str, str]:
    current_year = date.today().year
    if found_year >= current_year:
        return None, "", "", ""
    for newer_year in range(current_year, found_year, -1):
        try:
            if name_fallback:
                fill_ak_search_form_name_only(page, lookup_org, newer_year, lookup_org.organization_name)
            else:
                fill_ak_search_form_ein_fast(page, lookup_org, newer_year)
            print_link = find_ak_print_link_relaxed(page, lookup_org)
            if not print_link:
                continue
            row_text = re.sub(r"\s+", " ", (print_link.get("rowText") or "")).strip() if isinstance(print_link, dict) else ""
            row_year = ak_last_year_from_print_row(print_link, row_text)
            if row_year and row_year != newer_year:
                continue
            if ak_row_has_wrong_ein(row_text, original_org.ein):
                continue
            row_name = ak_registry_name_from_print_row(print_link, row_text, original_name, original_org.ein) if row_text else ""
            if row_name and not registry_name_is_safe_for_org(row_name, original_name, original_org.ein):
                continue
            return newer_year, row_name, ak_registry_identifier_from_print_row(print_link, row_text), registry_page_body(page)
        except Exception:
            try:
                checker.open_ak_public_search(page)
            except Exception:
                pass
    return None, "", "", ""


def fetch_ak_registration_pdf(page, context, print_link: dict, org_name: str) -> tuple[str, str]:
    popup = None
    pdf_url = ""
    try:
        print_locator = page.locator("a[data-linkid^='Dq-t']").first
        try:
            with page.expect_download(timeout=8000) as download_info:
                print_locator.click(timeout=3000, force=True)
                page.keyboard.press("Enter")
            download = download_info.value
            path = ak_registration_pdf_path(org_name)
            path.parent.mkdir(parents=True, exist_ok=True)
            download.save_as(str(path))
            if PdfReader is not None:
                reader = PdfReader(path)
                pdf_text = "\n".join(pdf_page.extract_text() or "" for pdf_page in reader.pages)
                return pdf_text, download.url or ""
            return "", download.url or ""
        except Exception:
            pass
        try:
            with page.expect_popup(timeout=8000) as popup_info:
                try:
                    print_locator.click(timeout=3000, force=True)
                    page.keyboard.press("Enter")
                except Exception:
                    page.mouse.click(print_link["x"], print_link["y"])
                    page.keyboard.press("Enter")
            popup = popup_info.value
            popup.wait_for_load_state("domcontentloaded", timeout=10000)
            pdf_url = popup.url
            try:
                popup.keyboard.press("End")
                time.sleep(0.5)
                popup.mouse.wheel(0, 8000)
                time.sleep(0.5)
                popup.screenshot(path=str(evidence_png_path("AK", org_name)), full_page=False)
            except Exception:
                pass
        except Exception:
            page.mouse.click(print_link["x"], print_link["y"])
            time.sleep(1)
            pdf_url = page.url
            try:
                page.keyboard.press("End")
                time.sleep(0.5)
                page.mouse.wheel(0, 8000)
                time.sleep(0.5)
                page.screenshot(path=str(evidence_png_path("AK", org_name)), full_page=False)
            except Exception:
                pass
        if not pdf_url:
            return "", ""
        response = context.request.get(pdf_url, timeout=15000)
        pdf_bytes = response.body()
        if not pdf_bytes.startswith(b"%PDF"):
            return "", pdf_url
        path = ak_registration_pdf_path(org_name)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(pdf_bytes)
        if PdfReader is None:
            return "", pdf_url
        reader = PdfReader(io.BytesIO(pdf_bytes))
        pdf_text = "\n".join(pdf_page.extract_text() or "" for pdf_page in reader.pages)
        return pdf_text, pdf_url
    except Exception:
        return "", pdf_url
    finally:
        if popup:
            try:
                popup.close()
            except Exception:
                pass


def ak_last_year_on_record_from_pdf_text(pdf_text: str) -> int | None:
    try:
        extracted = checker.extract_ak_accounting_end_year(pdf_text)
        if extracted:
            return extracted
    except Exception:
        pass
    for pattern in [
        r"\bLast\s+Year\s+(?:on\s+)?Record\s*:?\s*(20\d{2})\b",
        r"\bLatest\s+(?:Report|Filing|Accounting)\s+Year\s*:?\s*(20\d{2})\b",
    ]:
        match = re.search(pattern, pdf_text or "", re.I)
        if match:
            try:
                return int(match.group(1))
            except Exception:
                pass
    return None


def apply_ak_registration_status_from_best_evidence(
    result,
    page,
    context,
    print_link: dict,
    org_name: str,
    registration_year: int,
    source_note_prefix: str = "",
    last_year_on_record: int | None = None,
) -> str:
    pdf_text = ""
    pdf_url = ""
    last_year = last_year_on_record
    if not last_year:
        try:
            pdf_text, pdf_url = fetch_ak_registration_pdf(page, context, print_link, org_name)
        except Exception:
            pdf_text, pdf_url = "", ""
        last_year = ak_last_year_on_record_from_pdf_text(pdf_text)
    if last_year:
        due_date = date(last_year, 9, 1)
        result.status = status_from_calendar_date(due_date)
        result.raw_status_text = " | ".join(part for part in [
            f"Last Year on Record: {last_year}",
            f"Annual Registration Expiration: {format_date(due_date)}",
            f"Registration Year Searched: {registration_year}",
            f"PDF: {pdf_url}" if pdf_url else "",
        ] if part)
        evidence_note = (
            "Alaska registry evidence includes the last year on record; "
            "CharityClarity treats that registry year as expiring on Alaska's September 1 annual registration date."
        )
    else:
        result.status, result.raw_status_text, evidence_note = checker.classify_ak_registration_year(registration_year, None)
    result.source_note = " ".join(part for part in [source_note_prefix, evidence_note] if part).strip()
    result.success = True
    return result.raw_status_text


def search_ak_with_registration_evidence(browser, org, artifact_name: str) -> tuple[object, str]:
    result = checker.StateResult(org.organization_name, org.ein, "AK", checker.STATUS_UNKNOWN, checker.AK_SEARCH_URL)
    if len(re.sub(r"\D", "", org.ein or "")) != 9:
        result.error = "AK search requires 9-digit EIN"
        return result, ""
    years_to_try = list(range(date.today().year, 2018, -1))
    original_name = getattr(org, "organization_name", "") or ""
    search_names = []

    def add_search_name(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip())
        if cleaned and cleaned.lower() not in {existing.lower() for existing in search_names}:
            search_names.append(cleaned)

    # Alaska's public form is driven by FEIN. Repeating the same FEIN search
    # under aliases only slows down no-record cases; aliases are still used by
    # find_ak_print_link_relaxed once result rows are present.
    add_search_name(original_name)
    ak_context = browser.new_context(viewport={"width": 1365, "height": 900}, accept_downloads=True)
    configure_browser_context(ak_context)
    ak_page = ak_context.new_page()
    try:
        if not checker.open_ak_public_search(ak_page):
            result.error = "Could not open Alaska Public Search form"
            return result, ""
        first_ein_years = years_to_try[:2]
        remaining_ein_years = years_to_try[2:]
        for search_name in search_names or [original_name]:
            lookup_org = org_with_name(org, search_name)
            for year in first_ein_years:
                page_body = ""
                try:
                    fill_ak_search_form_ein_fast(ak_page, lookup_org, year)
                    print_link = find_ak_print_link_relaxed(ak_page, lookup_org)
                    page_body = registry_page_body(ak_page)
                    if not print_link:
                        continue
                    row_text = re.sub(r"\s+", " ", (print_link.get("rowText") or "")).strip() if isinstance(print_link, dict) else ""
                    last_year_on_record = ak_last_year_from_print_row(print_link, row_text)
                    if ak_row_has_wrong_ein(row_text, org.ein):
                        continue
                    if row_text:
                        row_name = ak_registry_name_from_print_row(print_link, row_text, original_name, org.ein)
                        if row_name and registry_name_is_safe_for_org(row_name, original_name, org.ein):
                            result.matched_registry_name = row_name
                            result.matched_registry_identifier = ak_registry_identifier_from_print_row(print_link, row_text)
                        elif row_name:
                            continue
                    if search_name != original_name:
                        result.source_note = f"Matched using EIN-resolved compatible name variant: {search_name}."
                    newer_year, newer_name, newer_identifier, newer_body = ak_newer_year_result_from_retry(
                        ak_page,
                        lookup_org,
                        org,
                        original_name,
                        year,
                    )
                    if newer_year:
                        year = newer_year
                        page_body = newer_body or page_body
                        if newer_name:
                            result.matched_registry_name = newer_name
                        if newer_identifier:
                            result.matched_registry_identifier = newer_identifier
                        refreshed_print_link = find_ak_print_link_relaxed(ak_page, lookup_org)
                        if refreshed_print_link:
                            print_link = refreshed_print_link
                            row_text = re.sub(r"\s+", " ", (print_link.get("rowText") or "")).strip() if isinstance(print_link, dict) else ""
                            last_year_on_record = ak_last_year_from_print_row(print_link, row_text)
                    apply_ak_registration_status_from_best_evidence(
                        result,
                        ak_page,
                        ak_context,
                        print_link,
                        original_name,
                        year,
                        getattr(result, "source_note", "") or "",
                        last_year_on_record or year,
                    )
                    return result, page_body
                except Exception as e:
                    result.error = f"AK error: {e}"
                    try:
                        checker.open_ak_public_search(ak_page)
                    except Exception:
                        pass
                    continue
        name_deadline = time.perf_counter() + 54.0
        name_fallback_years = list(range(date.today().year, max(2018, date.today().year - 5), -1))
        for search_name in ak_name_fallback_variants(original_name, org.ein):
            lookup_org = org_with_name(org, search_name)
            for year in name_fallback_years:
                if time.perf_counter() >= name_deadline:
                    break
                page_body = ""
                try:
                    fill_ak_search_form_name_only(ak_page, lookup_org, year, search_name)
                    print_link = find_ak_print_link_relaxed(ak_page, lookup_org)
                    page_body = registry_page_body(ak_page)
                    if not print_link:
                        continue
                    row_text = re.sub(r"\s+", " ", (print_link.get("rowText") or "")).strip() if isinstance(print_link, dict) else ""
                    last_year_on_record = ak_last_year_from_print_row(print_link, row_text)
                    row_name = ""
                    if row_text:
                        row_name = ak_registry_name_from_print_row(print_link, row_text, original_name, org.ein)
                        if row_name and not registry_name_is_safe_for_org(row_name, original_name, org.ein):
                            continue
                    wrong_ein = ak_row_has_wrong_ein(row_text, org.ein)
                    if wrong_ein:
                        continue
                    newer_year, newer_name, newer_identifier, newer_body = ak_newer_year_result_from_retry(
                        ak_page,
                        lookup_org,
                        org,
                        original_name,
                        year,
                        name_fallback=True,
                    )
                    if newer_year:
                        year = newer_year
                        page_body = newer_body or page_body
                        if newer_name:
                            row_name = newer_name
                        if newer_identifier:
                            result.matched_registry_identifier = newer_identifier
                        refreshed_print_link = find_ak_print_link_relaxed(ak_page, lookup_org)
                        if refreshed_print_link:
                            print_link = refreshed_print_link
                            row_text = re.sub(r"\s+", " ", (print_link.get("rowText") or "")).strip() if isinstance(print_link, dict) else ""
                            if ak_row_has_wrong_ein(row_text, org.ein):
                                continue
                            last_year_on_record = ak_last_year_from_print_row(print_link, row_text)
                    result.matched_registry_name = row_name or search_name
                    if not result.matched_registry_identifier:
                        result.matched_registry_identifier = ak_registry_identifier_from_print_row(print_link, row_text)
                    apply_ak_registration_status_from_best_evidence(
                        result,
                        ak_page,
                        ak_context,
                        print_link,
                        original_name,
                        year,
                        " ".join(part for part in [
                            f"Matched using Alaska name fallback after EIN search returned no rows: {search_name}.",
                        ] if part),
                        last_year_on_record or year,
                    )
                    return result, page_body
                except Exception as e:
                    result.error = f"AK name fallback error: {e}"
                    try:
                        checker.open_ak_public_search(ak_page)
                    except Exception:
                        pass
                    continue
        for search_name in search_names or [original_name]:
            lookup_org = org_with_name(org, search_name)
            for year in remaining_ein_years:
                if time.perf_counter() >= name_deadline:
                    break
                page_body = ""
                try:
                    fill_ak_search_form_ein_fast(ak_page, lookup_org, year)
                    print_link = find_ak_print_link_relaxed(ak_page, lookup_org)
                    page_body = registry_page_body(ak_page)
                    if not print_link:
                        continue
                    row_text = re.sub(r"\s+", " ", (print_link.get("rowText") or "")).strip() if isinstance(print_link, dict) else ""
                    last_year_on_record = ak_last_year_from_print_row(print_link, row_text)
                    if ak_row_has_wrong_ein(row_text, org.ein):
                        continue
                    if row_text:
                        row_name = ak_registry_name_from_print_row(print_link, row_text, original_name, org.ein)
                        if row_name and registry_name_is_safe_for_org(row_name, original_name, org.ein):
                            result.matched_registry_name = row_name
                            result.matched_registry_identifier = ak_registry_identifier_from_print_row(print_link, row_text)
                        elif row_name:
                            continue
                    apply_ak_registration_status_from_best_evidence(
                        result,
                        ak_page,
                        ak_context,
                        print_link,
                        original_name,
                        year,
                        getattr(result, "source_note", "") or "",
                        last_year_on_record or year,
                    )
                    return result, page_body
                except Exception as e:
                    result.error = f"AK error: {e}"
                    try:
                        checker.open_ak_public_search(ak_page)
                    except Exception:
                        pass
                    continue
    finally:
        ak_context.close()
    checked_years = ", ".join(str(year) for year in years_to_try)
    result.raw_status_text = f"No Alaska registration found for checked years {checked_years}"
    result.status = "Not registered"
    result.source_note = f"No Alaska registration found in public search for years {checked_years}"
    result.success = True
    return result, ""


def ca_detail_body(page, org) -> str:
    pieces = [registry_page_body(page)]
    try:
        detail_links = page.locator('a[href*="Details.aspx"]')
        link_count = detail_links.count()
        target_href = ""
        best_score = -10_000
        ein_digits = re.sub(r"\D", "", org.ein or "")
        wanted_name = getattr(checker, "normalize_name", lambda value: re.sub(r"\s+", " ", (value or "").lower()).strip())(
            org.organization_name
        )
        for i in range(min(link_count, 20)):
            link = detail_links.nth(i)
            try:
                row_text = ""
                row = link.locator("xpath=ancestor::tr[1]")
                if row.count():
                    row_text = re.sub(r"\s+", " ", row.first.inner_text(timeout=1500)).strip()
                href = link.get_attribute("href", timeout=1500) or ""
                if not href:
                    continue
                row_digits = re.sub(r"\D", "", row_text)
                row_name = getattr(checker, "normalize_name", lambda value: re.sub(r"\s+", " ", (value or "").lower()).strip())(
                    row_text
                )
                score = 0
                if ein_digits and ein_digits in row_digits:
                    score += 40
                if wanted_name and wanted_name in row_name:
                    score += 12
                if re.search(r"\bcharity\s+registration\b", row_text, re.I):
                    score += 10
                if re.search(r"\b(current|active|exempt|registered)\b", row_text, re.I):
                    score += 8
                if re.search(r"\b(merged\s+out|withdrawn|dissolved|closed)\b", row_text, re.I):
                    score -= 35
                if score > best_score:
                    best_score = score
                    target_href = href
            except Exception:
                continue
        if target_href:
            page.goto(urljoin(page.url, target_href), wait_until="domcontentloaded", timeout=45000)
            checker.safe_wait_for_network_idle(page, timeout=8000)
            time.sleep(0.75)
    except Exception:
        pass

    for text in ["Annual Renewal Data", "Renewal Data", "Annual Filings"]:
        try:
            page.get_by_text(re.compile(text, re.I)).first.scroll_into_view_if_needed(timeout=4000)
            page.locator("body").evaluate("window.scrollBy(0, -80)")
            time.sleep(0.5)
            break
        except Exception:
            continue
    try:
        current_body = registry_page_body(page)
        if not scroll_to_latest_year_evidence(page, "CA", current_body):
            page.locator("body").evaluate("window.scrollTo(0, Math.max(0, document.body.scrollHeight * 0.28))")
            time.sleep(0.5)
    except Exception:
        pass
    pieces.append(registry_page_body(page))
    return "\n".join(piece for piece in pieces if piece)


def me_detail_body(page, org) -> str:
    pieces = [registry_page_body(page)]
    target_name = getattr(checker, "normalize_name", lambda value: re.sub(r"\s+", " ", (value or "").lower()).strip())(
        org.organization_name
    )

    def current_text() -> str:
        try:
            return page.locator("body").inner_text(timeout=8000)
        except Exception:
            return ""

    def detail_visible(text: str) -> bool:
        return bool(
            re.search(r"\bLicense\s+Number\b", text, re.I)
            and re.search(r"\bStatus\b", text, re.I)
        )

    body_text = current_text()
    if not detail_visible(body_text):
        best_href = ""
        best_score = -1
        best_status_score = -999
        try:
            links = page.locator("a[href*='ShowDetail.aspx']")
            for i in range(min(links.count(), 80)):
                link = links.nth(i)
                try:
                    link_text = re.sub(r"\s+", " ", link.inner_text(timeout=1500)).strip()
                    link_name = getattr(checker, "normalize_name", lambda value: re.sub(r"\s+", " ", (value or "").lower()).strip())(
                        link_text
                    )
                    score = -1
                    if link_name == target_name:
                        score = 3
                    elif target_name and (target_name in link_name or link_name in target_name):
                        score = 2
                    elif link_text:
                        score = 1
                    status_score = 0
                    try:
                        row_text = re.sub(r"\s+", " ", link.locator("xpath=ancestor::tr[1]").inner_text(timeout=1500)).strip()
                        if re.search(r"\bACTIVE\b", row_text, re.I):
                            status_score = 5
                        elif re.search(r"\b(CURRENT|GOOD\s+STANDING)\b", row_text, re.I):
                            status_score = 4
                        elif re.search(r"\b(FAILED\s+TO\s+RENEW|EXPIRED|REVOKED|SUSPENDED|INACTIVE)\b", row_text, re.I):
                            status_score = -5
                    except Exception:
                        status_score = 0
                    if score > best_score or (score == best_score and status_score > best_status_score):
                        best_score = score
                        best_status_score = status_score
                        best_href = (link.get_attribute("href") or "").strip()
                except Exception:
                    continue
        except Exception:
            pass
        if best_href:
            try:
                page.goto(urljoin(page.url, best_href), wait_until="domcontentloaded", timeout=60000)
                checker.safe_wait_for_network_idle(page, timeout=20000)
                time.sleep(2)
            except Exception:
                pass

    try:
        page.get_by_text(re.compile(r"License\s+Number|Expiration\s+Date|Status", re.I)).first.scroll_into_view_if_needed(timeout=5000)
        page.locator("body").evaluate("window.scrollBy(0, -160)")
        time.sleep(1)
    except Exception:
        try:
            page.locator("a[href*='ShowDetail.aspx']").first.scroll_into_view_if_needed(timeout=3000)
            page.locator("body").evaluate("window.scrollBy(0, -120)")
            time.sleep(1)
        except Exception:
            pass

    pieces.append(registry_page_body(page))
    return "\n".join(piece for piece in pieces if piece)


def hi_detail_body(page) -> str:
    pieces = [registry_page_body(page)]
    try:
        page.get_by_text(re.compile(r"\bDocuments\b", re.I)).first.scroll_into_view_if_needed(timeout=5000)
        page.locator("body").evaluate("window.scrollBy(0, -120)")
        time.sleep(1)
    except Exception:
        try:
            page.locator("body").evaluate("window.scrollTo(0, document.body.scrollHeight)")
            time.sleep(1)
        except Exception:
            pass
    pieces.append(registry_page_body(page))
    return "\n".join(piece for piece in pieces if piece)


def ma_detail_body(page) -> str:
    pieces = []
    for _ in range(3):
        time.sleep(2)
        body = registry_page_body(page)
        pieces.append(body)
        if latest_year_from_text(body, "MA"):
            break
        try:
            page.get_by_text(re.compile(r"Annual\s+Filings(?:\s+and\s+Documents)?", re.I)).first.scroll_into_view_if_needed(timeout=3000)
        except Exception:
            pass
    return "\n".join(piece for piece in pieces if piece)


def repair_ma_false_not_registered(page, org, result, body: str):
    """Massachusetts EIN results often show the charity name without exposing EIN text."""
    if public_status(result) != "Not Registered":
        return result, body
    readable = re.sub(r"\s+", " ", body or "")
    if re.search(r"No\s+Charity\s+Found", readable, re.I):
        return result, body
    if not (re.search(r"Select\s+a\s+Charity", readable, re.I) and re.search(r"Get\s+Filings", readable, re.I)):
        return result, body

    for label in ["Get filings", "Get Filings"]:
        try:
            page.get_by_role("button", name=re.compile(label, re.I)).click(timeout=4000)
            break
        except Exception:
            pass
        try:
            page.get_by_text(re.compile(label, re.I)).click(timeout=4000)
            break
        except Exception:
            pass

    try:
        checker.safe_wait_for_network_idle(page, timeout=10000)
    except Exception:
        pass
    for attempt in range(10):
        time.sleep(0.75)
        try:
            refreshed = registry_page_body(page)
        except Exception:
            continue
        if re.search(r"Form[\s-]*PC", refreshed, re.I):
            body = refreshed
            break
        if attempt >= 5 and re.search(
            r"Annual\s+Filings(?:\s+and\s+Documents)?[\s\S]{0,1200}(?:No documents found|No rows available)",
            refreshed,
            re.I,
        ):
            body = refreshed
            break
    try:
        page.locator("body").evaluate("window.scrollTo(0, document.body.scrollHeight)")
    except Exception:
        pass
    body = ma_detail_body(page) or body
    latest_year = latest_year_from_text(body, "MA")
    if latest_year:
        result.raw_status_text = str(latest_year)
        classifier = getattr(checker, "classify_ma_visible_filing_year", None)
        result.status = classifier(latest_year) if classifier else checker.STATUS_DELINQUENT
        result.source_note = (
            "Massachusetts EIN search returned a charity record; CharityClarity uses the latest visible Form PC year "
            "from Annual Filings because the search result does not expose EIN text in the visible page."
        )
    else:
        result.raw_status_text = "Annual Filings not visible"
        result.status = checker.STATUS_DELINQUENT
        result.source_note = (
            "Massachusetts EIN search returned a charity record, but did not expose a visible Form PC filing year after Get Filings."
        )
    result.success = True
    return result, body


def validate_ma_positive_record(org, result, body: str):
    if public_status(result) in {"Not Registered", "Site Not Reachable"}:
        return result
    readable = re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", body or ""))).strip()
    ein_digits = re.sub(r"\D", "", getattr(org, "ein", "") or "")
    registry_name = useful_registry_name(
        checker.extract_labeled_value_from_text(readable, ["Organization Name", "Charity Name", "Legal Name", "Name"])
    )
    if registry_name and registry_name_is_safe_for_org(registry_name, org.organization_name, org.ein):
        result.matched_registry_name = registry_name
        return result
    has_visible_filing = bool(re.search(r"\bForm[\s-]*PC\b|\b20\d{2}\b", " ".join([result.raw_status_text or "", readable]), re.I))
    ein_confirmed = bool(ein_digits and ein_digits in re.sub(r"\D", "", readable))
    if not has_visible_filing and not ein_confirmed and not registry_name:
        replacement = checker.StateResult(org.organization_name, org.ein, "MA", checker.STATUS_NOT_REGISTERED, getattr(result, "source_url", "") or "")
        replacement.raw_status_text = "No confirmed Massachusetts charity record"
        replacement.source_note = "Massachusetts returned a possible record, but CharityClarity could not confirm the requested EIN, a safe registry name, or a visible Form PC filing year."
        replacement.success = True
        return replacement
    if registry_name and not registry_name_is_safe_for_org(registry_name, org.organization_name, org.ein):
        replacement = checker.StateResult(org.organization_name, org.ein, "MA", checker.STATUS_NOT_REGISTERED, getattr(result, "source_url", "") or "")
        replacement.raw_status_text = "Massachusetts registry name did not safely match"
        replacement.source_note = "Massachusetts returned a record, but its registry name did not safely match the requested organization."
        replacement.success = True
        return replacement
    return result


def search_hi_precise(page, org):
    url = "https://charity.ehawaii.gov/charity/new-search.html"
    result = checker.StateResult(org.organization_name, org.ein, "HI", checker.STATUS_UNKNOWN, url)
    try:
        ein_digits = re.sub(r"\D", "", org.ein or "")
        page.goto(url, wait_until="domcontentloaded", timeout=45000)
        checker.safe_wait_for_network_idle(page, timeout=6000)
        time.sleep(1)
        try:
            page.locator("#nameFilter").select_option(label="Contains...")
        except Exception:
            pass
        name_input = checker.find_visible_input(page, ["#name", 'input[name="name"]', 'input[id="name"]'])
        fein_input = checker.find_visible_input(page, ["#fein", 'input[name="fein"]', 'input[id="fein"]'])
        if not name_input or not fein_input:
            result.error = "Could not find HI search fields"
            return result
        body = ""
        clicked_result = False
        attempts = []
        if ein_digits:
            for ein_value in [checker.format_ein_with_dash(org.ein), ein_digits]:
                if ein_value and ("", ein_value) not in attempts:
                    attempts.append(("", ein_value))
        for variant in organization_name_variants(org.organization_name, org.ein):
            if variant:
                for ein_value in ([checker.format_ein_with_dash(org.ein), ein_digits, ""] if ein_digits else [""]):
                    if (variant, ein_value) not in attempts:
                        attempts.append((variant, ein_value))
        clicked_result_name = ""
        clicked_result_identifier = ""
        for variant, ein_value in attempts[:4]:
            name_input.fill("")
            name_input.fill(variant)
            fein_input.fill("")
            if ein_value:
                fein_input.fill(ein_value)
            clicked = False
            for sel in ["#trigger-organization-search", 'button[id="trigger-organization-search"]', 'button[type="submit"]', "button"]:
                try:
                    buttons = page.locator(sel)
                    for i in range(min(buttons.count(), 10)):
                        button = buttons.nth(i)
                        try:
                            text = re.sub(r"\s+", " ", button.inner_text(timeout=1000)).strip()
                        except Exception:
                            text = (button.get_attribute("value") or "").strip()
                        if button.is_visible(timeout=750) and re.search(r"\bSearch\b", text, re.I):
                            button.click(timeout=5000)
                            clicked = True
                            break
                    if clicked:
                        break
                except Exception:
                    continue
            if not clicked:
                result.error = "Could not click HI Search button"
                return result
            checker.safe_wait_for_network_idle(page, timeout=7000)
            time.sleep(1.25)
            wanted_variants = [checker.normalize_name(item) for item in organization_name_variants(org.organization_name, org.ein)]
            for selector in ["#searchOrgTable tbody tr", "#searchResultTable tbody tr", "table tbody tr", "a[href]"]:
                try:
                    rows = page.locator(selector)
                    for i in range(min(rows.count(), 100)):
                        row = rows.nth(i)
                        try:
                            if not row.is_visible(timeout=750):
                                continue
                            row_text = re.sub(r"\s+", " ", row.inner_text(timeout=1500)).strip()
                            if not row_text or re.search(r"no data available", row_text, re.I):
                                continue
                            row_digits = re.sub(r"\D", "", row_text)
                            row_name = checker.normalize_name(row_text)
                            name_match = any(name and (name in row_name or row_name in name) for name in wanted_variants)
                            if ein_digits and ein_digits not in row_digits:
                                continue
                            if not ein_digits and not name_match:
                                continue
                            links = row.locator("a[href]")
                            clicked_result_identifier = ein_digits if ein_digits and ein_digits in row_digits else ""
                            candidate_name = re.sub(r"^\s*\d{9}\s+", "", row_text).strip()
                            candidate_name = re.split(r"\s+\d{2,6}\s+", candidate_name, maxsplit=1)[0].strip()
                            clicked_result_name = clean_registry_name(candidate_name)
                            if selector == "a[href]":
                                row.click(timeout=5000)
                            elif links.count():
                                links.first.click(timeout=5000)
                            else:
                                row.click(timeout=5000)
                            clicked_result = True
                            break
                        except Exception:
                            continue
                    if clicked_result:
                        break
                except Exception:
                    continue
            if clicked_result:
                break
            body = page.locator("body").inner_text(timeout=15000)
            if re.search(r"no results|no records|0 results|showing 0 to 0 of 0 entries|no data available in table|not registered in our system", body, re.I):
                continue
        if not clicked_result:
            result.raw_status_text = "No record found" if re.search(r"no results|no records|0 results|showing 0 to 0 of 0 entries|no data available in table|not registered in our system", body, re.I) else "No matching organization result"
            result.status = "Not registered"
            result.source_note = "Hawaii search results did not contain a matching organization/EIN row."
            result.success = True
            return result
        page.wait_for_load_state("domcontentloaded", timeout=30000)
        checker.safe_wait_for_network_idle(page, timeout=6000)
        time.sleep(1)
        detail_text = page.locator("body").inner_text(timeout=12000)
        detail_ein = (
            checker.extract_labeled_value(page, ["FEIN", "Federal Tax ID (EIN)", "Federal Tax ID", "EIN"])
            or checker.extract_labeled_value_from_text(detail_text, ["FEIN", "Federal Tax ID (EIN)", "Federal Tax ID", "EIN"])
        )
        if ein_digits and detail_ein and re.sub(r"\D", "", detail_ein) != ein_digits:
            return checker.reject_wrong_ein_result(result, "Hawaii")
        status_text = checker.extract_labeled_value(page, ["Registration Status", "Status"]) or checker.extract_labeled_value_from_text(detail_text, ["Registration Status", "Status"])
        registration_type = checker.extract_labeled_value(page, ["Registration Type"]) or checker.extract_labeled_value_from_text(detail_text, ["Registration Type"])
        result.matched_registry_name = useful_registry_name(
            checker.extract_labeled_value(page, ["Primary Name", "Organization Name", "Charity Name", "Legal Name"])
            or checker.extract_labeled_value_from_text(detail_text, ["Primary Name", "Organization Name", "Charity Name", "Legal Name"])
            or clicked_result_name
        )
        result.matched_registry_identifier = detail_ein or clicked_result_identifier
        if not result_registry_name_is_safe(result, org.organization_name, org.ein):
            result.raw_status_text = "No matching organization record"
            result.status = checker.STATUS_NOT_REGISTERED
            result.source_note = "Hawaii search found a row, but the registry name did not safely match the requested organization."
            result.success = True
            return result
        result.raw_status_text = " | ".join(part for part in [
            f"Registration Status: {status_text}" if status_text else "",
            f"Registration Type: {registration_type}" if registration_type else "",
        ]) or status_text
        result.status = status_text if status_text else checker.STATUS_UNKNOWN
        result.source_note = "Registration status and filings from Hawaii detail page."
        result.success = True
        return result
    except Exception as e:
        result.error = f"HI error: {e}"
        return result


def html_to_text(source: str) -> str:
    return re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", source or ""))).strip()


def html_input_value(source: str, name: str) -> str:
    match = re.search(
        r"<input[^>]+name=[\"']" + re.escape(name) + r"[\"'][^>]*value=[\"']([^\"']*)[\"']",
        source or "",
        re.I,
    )
    return html.unescape(match.group(1)) if match else ""


def html_hidden_inputs(source: str) -> dict[str, str]:
    values: dict[str, str] = {}
    for match in re.finditer(r"<input\b[^>]*>", source or "", re.I):
        tag = match.group(0)
        type_match = re.search(r"\btype=[\"']?([^\"'\s>]+)", tag, re.I)
        if type_match and type_match.group(1).lower() != "hidden":
            continue
        name_match = re.search(r"\bname=[\"']([^\"']+)[\"']", tag, re.I)
        if not name_match:
            name_match = re.search(r"\bname=([^\"'\s>]+)", tag, re.I)
        if not name_match:
            continue
        value_match = re.search(r"\bvalue=[\"']([^\"']*)[\"']", tag, re.I)
        if not value_match:
            value_match = re.search(r"\bvalue=([^\"'\s>]*)", tag, re.I)
        values[html.unescape(name_match.group(1))] = html.unescape(value_match.group(1)) if value_match else ""
    return values


def html_table_cells(row_html: str) -> list[str]:
    values = []
    for cell_match in re.finditer(r"<t[dh][^>]*>([\s\S]*?)</t[dh]>", row_html or "", re.I):
        values.append(html_to_text(cell_match.group(1)))
    return values


def wi_http_detail_status(detail_href: str) -> str:
    if not detail_href:
        return ""
    try:
        detail_url = urljoin(WI_SEARCH_URL, html.unescape(detail_href))
        request = urllib.request.Request(detail_url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(request, timeout=WI_HTTP_TIMEOUT_SECONDS) as response:
            detail_html = response.read().decode("utf-8", errors="replace")
        detail_text = html_to_text(detail_html)
        status_match = re.search(r"\bStatus\s+(License\s+is\s+(?:not\s+)?current\s*\([^)]+\))", detail_text, re.I)
        return re.sub(r"\s+", " ", status_match.group(1)).strip() if status_match else ""
    except Exception:
        return ""


def wi_reader_url(source_url: str) -> str:
    return f"{WI_READER_BASE_URL}{source_url}"


def wi_reader_text(source_url: str, no_cache: bool = False) -> str:
    for attempt in range(3):
        try:
            headers = {
                "User-Agent": "Mozilla/5.0 CharityClarity-WI/1.0",
                "Accept": "text/markdown,text/plain,text/html;q=0.8,*/*;q=0.5",
            }
            if no_cache or attempt:
                headers["X-No-Cache"] = "true"
            request = urllib.request.Request(wi_reader_url(source_url), headers=headers)
            with urllib.request.urlopen(request, timeout=WI_READER_TIMEOUT_SECONDS) as response:
                return response.read().decode("utf-8", errors="replace")
        except Exception:
            if attempt < 2:
                time.sleep(0.35 * (attempt + 1))
                continue
            return ""


def wi_reader_detail_status(detail_href: str) -> str:
    if not detail_href:
        return ""
    detail_url = urljoin(WI_SEARCH_URL, html.unescape(detail_href))
    detail_text = wi_reader_text(detail_url)
    status_match = re.search(r"\bStatus\s+(License\s+is\s+(?:not\s+)?current\s*\([^)]+\))", detail_text, re.I)
    return re.sub(r"\s+", " ", status_match.group(1)).strip() if status_match else ""


def wi_markdown_link_parts(value: str) -> tuple[str, str]:
    match = re.search(r"\[([^\]]+)\]\(([^)]+)\)", value or "")
    if match:
        return html.unescape(match.group(1)).strip(), html.unescape(match.group(2)).strip()
    return html.unescape(value or "").strip(), ""


def wi_status_from_detail_status(detail_status: str) -> str:
    text = detail_status or ""
    if re.search(r"\bvoluntar(?:y|ily)\s+surrender(?:ed)?\b", text, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(r"\brevoked\b", text, re.I):
        return "Revoked"
    if re.search(r"\bsuspended\b", text, re.I):
        return "Suspended"
    if re.search(r"\bLicense\s+is\s+not\s+current\b", text, re.I):
        return "Delinquent"
    if re.search(r"\bLicense\s+is\s+current\s*\(\s*Active\s*\)", text, re.I):
        return "Current"
    return ""


def wi_status_severity(detail_status: str) -> int:
    status = wi_status_from_detail_status(detail_status)
    return {
        "Closed / Withdrawn / Canceled": 50,
        "Revoked": 50,
        "Suspended": 45,
        "Delinquent": 30,
        "Upcoming Filing": 20,
        "Current": 10,
    }.get(status, 0)


def wi_expiration_suffix(expiration_date: date | None) -> str:
    return f"; License current through {format_date(expiration_date)}" if expiration_date else ""


def wi_request_headers(referer: str = WI_SEARCH_URL) -> dict[str, str]:
    return {
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
            "AppleWebKit/537.36 (KHTML, like Gecko) "
            "Chrome/124.0.0.0 Safari/537.36"
        ),
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "en-US,en;q=0.9",
        "Referer": referer,
    }


def wi_result_html_requires_verification(source: str) -> bool:
    text = html_to_text(source or "")
    return bool(re.search(r"Verification\s+Type\s+the\s+characters\s+you\s+see", text, re.I))


def wi_search_names_for_org(org) -> list[str]:
    names: list[str] = []

    def add_many(values) -> None:
        for value in values:
            value = re.sub(r"\s+", " ", (value or "").strip())
            if value and value not in names:
                names.append(value)

    original_name = getattr(org, "organization_name", "")
    add_many([original_name])
    add_many(known_names_for_ein(getattr(org, "ein", "")))
    seed_names = list(names)
    seed_has_hyphen = any(re.search(r"[-\u2010-\u2015]", seed or "") for seed in seed_names)

    def generated_hyphen_variant_is_safe(value: str) -> bool:
        if seed_has_hyphen:
            return True
        normalized_value = re.sub(r"\s+", " ", value or "").strip()
        if not re.search(r"[-\u2010-\u2015]", normalized_value):
            return True
        seed_tokens = [
            re.findall(r"[A-Za-z0-9]+", seed or "")
            for seed in seed_names
            if seed
        ]
        value_tokens = re.findall(r"[A-Za-z0-9]+", normalized_value)
        if not value_tokens:
            return False
        generic = {
            "the", "a", "an", "of", "for", "and", "to", "in", "on", "at",
            "by", "inc", "incorporated", "corp", "corporation", "llc",
            "ltd", "limited", "foundation", "fund", "association", "society",
            "center", "centre", "institute", "organization", "charity",
            "charitable", "trust",
        }
        hyphen_pairs = [
            tuple(part for part in re.split(r"[-\u2010-\u2015]+", token) if part)
            for token in re.split(r"\s+", normalized_value)
            if re.search(r"[-\u2010-\u2015]", token)
        ]
        for pair in hyphen_pairs:
            if len(pair) != 2:
                continue
            left, right = pair
            if left.lower() in generic or right.lower() in generic:
                continue
            if left.isupper() or right.isupper():
                continue
            for tokens in seed_tokens:
                for index in range(len(tokens) - 1):
                    if tokens[index].lower() == left.lower() and tokens[index + 1].lower() == right.lower():
                        return True
        return False

    for seed in list(names):
        add_many(organization_name_variants(
            seed,
            "",
            include_ein_aliases=False,
            include_name_segments=True,
            include_compact_legal_suffixes=True,
            include_leading_article_variants=True,
            include_broad_query_prefixes=False,
        ))
    expanded_names: list[str] = []
    for value in names:
        cleaned = re.sub(r"\s+", " ", (value or "").strip())
        if cleaned and cleaned not in expanded_names:
            expanded_names.append(cleaned)
        structural = cleaned
        structural = re.sub(r"^(?:the|a|an)\s+", "", structural, flags=re.I).strip()
        structural = re.sub(r",\s*(?:the|a|an)\s*$", "", structural, flags=re.I).strip()
        structural = re.sub(r",\s*(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\s*$", "", structural, flags=re.I).strip()
        structural = re.sub(r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\s*$", "", structural, flags=re.I).strip()
        no_punct = re.sub(r"[^\w\s]", " ", structural)
        no_punct = re.sub(r"\s+", " ", no_punct).strip()
        substantive = [
            word for word in re.findall(r"[A-Za-z0-9]+", no_punct)
            if word.lower() not in {"the", "a", "an", "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited"}
        ]
        if len(substantive) >= 2 and no_punct and no_punct.lower() != cleaned.lower() and no_punct not in expanded_names:
            expanded_names.append(no_punct)
        national_prefix_removed = re.sub(
            r"^(?:the\s+)?(?:u\.?\s*s\.?|us|united\s+states)\s+",
            "",
            cleaned,
            flags=re.I,
        ).strip()
        if len(national_prefix_removed.split()) >= 2 and national_prefix_removed.lower() != cleaned.lower() and national_prefix_removed not in expanded_names:
            expanded_names.append(national_prefix_removed)
        us_compacted = re.sub(
            r"^(?:the\s+)?(?:u\.?\s*s\.?|us)\s+",
            "US ",
            cleaned,
            flags=re.I,
        ).strip()
        us_compacted = re.sub(r"\s+", " ", us_compacted)
        if len(us_compacted.split()) >= 2 and us_compacted.lower() != cleaned.lower() and us_compacted not in expanded_names:
            expanded_names.append(us_compacted)
        aids_tb_variant = re.sub(
            r"\b(AIDS?)\s+Tuberculosis\s+(?:And|&)\s+Malaria\b",
            r"\1, Tuberculosis & Malaria",
            cleaned,
            flags=re.I,
        )
        if aids_tb_variant.lower() != cleaned.lower() and aids_tb_variant not in expanded_names:
            expanded_names.append(aids_tb_variant)
        connector_core_variants = connector_light_name_variants(cleaned)
        for core_variant in connector_core_variants[:3]:
            if core_variant not in expanded_names:
                expanded_names.append(core_variant)
        hyphen_parts = [
            part.strip(" ,;")
            for part in re.split(r"[-\u2010-\u2015]+", cleaned)
            if part.strip(" ,;")
        ]
        if len(hyphen_parts) >= 2:
            for part in hyphen_parts[1:]:
                part_words = [
                    word for word in re.findall(r"[A-Za-z0-9]+", part)
                    if word.lower() not in {
                        "the", "a", "an", "inc", "incorporated", "corp", "corporation",
                        "llc", "ltd", "limited", "hospital", "center", "centre",
                        "foundation", "fund", "association", "society",
                    }
                ]
                if part_words:
                    core_part = part_words[-1]
                    if len(core_part) >= 5 and core_part not in expanded_names:
                        expanded_names.append(core_part)

    seed_key_names = {re.sub(r"\s+", " ", (seed or "").strip()).lower() for seed in seed_names if seed}
    original_seed_key = re.sub(r"\s+", " ", (original_name or "").strip()).lower()
    original_substantive_count = len([
        word for word in re.findall(r"[A-Za-z0-9]+", original_name or "")
        if word.lower() not in {
            "the", "a", "an", "of", "for", "to", "and",
            "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited",
        }
    ])

    def priority(value: str) -> tuple[int, int, str]:
        cleaned = re.sub(r"\s+", " ", (value or "").strip())
        if not cleaned:
            return (99, 99, "")
        has_punctuation = bool(re.search(r"[-,/\.]", cleaned))
        has_safe_hyphen = bool(re.search(r"[-\u2010-\u2015]", cleaned)) and generated_hyphen_variant_is_safe(cleaned)
        starts_article = bool(re.match(r"^(?:the|a|an)\s+", cleaned, re.I))
        exact_seed = cleaned.lower() in seed_key_names
        word_rank = -min(len(cleaned.split()), 8)
        if original_seed_key and cleaned.lower() == original_seed_key:
            return (-2, word_rank, cleaned.lower())
        if exact_seed:
            return (-1, word_rank, cleaned.lower())
        if len(cleaned.split()) == 1 and re.search(r"[-\u2010-\u2015]", original_name or ""):
            return (0, -9, cleaned.lower())
        if not has_punctuation and not re.search(r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\b", cleaned, re.I):
            return (0, word_rank, cleaned.lower())
        if has_safe_hyphen:
            return (1, word_rank, cleaned.lower())
        compact = re.sub(r"[^A-Za-z0-9]+", "", cleaned)
        if 2 <= len(compact) <= 8 and compact.upper() == compact:
            if original_substantive_count > 3 and not exact_seed:
                return (5, word_rank, cleaned.lower())
            return (0, word_rank, cleaned.lower())
        if re.search(r"\bAIDS?,\s+Tuberculosis\s+&\s+Malaria\b", cleaned, re.I):
            return (0, word_rank, cleaned.lower())
        if re.search(r"\bChildren['\u2019]s\s+Hospital\s+Foundation\b", cleaned, re.I):
            return (0, word_rank, cleaned.lower())
        if re.match(r"^(?:u\.?\s*s\.?|us)\s+", cleaned, re.I):
            noisy_us_query = bool(re.search(r"[-,/]", cleaned)) or bool(re.match(r"^u\.", cleaned, re.I))
            return (0 if not noisy_us_query else 1, word_rank, cleaned.lower())
        if re.fullmatch(r"(?i)(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited|the|a|an)", cleaned):
            return (90, 99, cleaned.lower())
        has_legal_suffix = bool(re.search(r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\b", cleaned, re.I))
        return (
            1 if not (has_punctuation or has_legal_suffix or starts_article) else 2,
            word_rank,
            cleaned.lower(),
        )

    filtered_names = []
    def add_wi_structural_variant(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip())
        if cleaned and cleaned not in expanded_names:
            expanded_names.append(cleaned)

    for value in list(expanded_names):
        cleaned = re.sub(r"\s+", " ", (value or "").strip())
        if not cleaned:
            continue
        add_wi_structural_variant(re.sub(r"[-\u2010-\u2015]+", " ", cleaned))
        add_wi_structural_variant(re.sub(r"\bSt\.?\s+", "Saint ", cleaned, flags=re.I))
        add_wi_structural_variant(re.sub(r"\bSaint\s+", "St ", cleaned, flags=re.I))
        add_wi_structural_variant(re.sub(r"['\u2019]s\b", "s", cleaned, flags=re.I))
        add_wi_structural_variant(re.sub(r"['\u2019]s\b", "", cleaned, flags=re.I))
        add_wi_structural_variant(re.sub(r"\bHospital\s+Center\b", "Hospital", cleaned, flags=re.I))
        add_wi_structural_variant(re.sub(r"\bMedical\s+Center\b", "Medical", cleaned, flags=re.I))

    for value in expanded_names:
        if re.search(r"[-\u2010-\u2015]", value or "") and not generated_hyphen_variant_is_safe(value):
            continue
        substantive = [
            word for word in re.findall(r"[A-Za-z0-9]+", value or "")
            if word.lower() not in {"the", "a", "an", "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited"}
        ]
        compact = re.sub(r"[^A-Za-z0-9]+", "", value or "")
        is_short_acronym = 2 <= len(compact) <= 8 and compact.upper() == compact
        is_compact_alnum_name = bool(re.fullmatch(r"(?=.*[A-Za-z])(?=.*\d)[A-Za-z0-9]{4,}", compact or ""))
        is_hyphen_core = bool(seed_has_hyphen and len(substantive) == 1 and len(compact) >= 5)
        if (len(substantive) >= 2 or is_short_acronym or is_compact_alnum_name or is_hyphen_core) and value not in filtered_names:
            filtered_names.append(value)
    filtered_names.sort(key=priority)
    return filtered_names


def wi_snapshot_generated_datetime(snapshot: dict) -> datetime | None:
    generated_at = str(snapshot.get("generated_at") or "").strip()
    if not generated_at:
        return None
    try:
        return datetime.fromisoformat(generated_at)
    except Exception:
        return None


def wi_snapshot_load() -> tuple[dict | None, str]:
    if not WI_USE_SNAPSHOT:
        return None, "Wisconsin snapshot use is disabled"
    try:
        stat = WI_SNAPSHOT_PATH.stat()
    except FileNotFoundError:
        return None, f"Wisconsin snapshot file is missing: {WI_SNAPSHOT_PATH}"
    except Exception as exc:
        return None, f"Wisconsin snapshot file could not be inspected: {exc}"

    cached_snapshot = WI_SNAPSHOT_CACHE.get("snapshot")
    cached_mtime = float(WI_SNAPSHOT_CACHE.get("mtime") or 0.0)
    if cached_snapshot is not None and cached_mtime == stat.st_mtime:
        return cached_snapshot, str(WI_SNAPSHOT_CACHE.get("error") or "")

    with WI_SNAPSHOT_LOCK:
        cached_snapshot = WI_SNAPSHOT_CACHE.get("snapshot")
        cached_mtime = float(WI_SNAPSHOT_CACHE.get("mtime") or 0.0)
        if cached_snapshot is not None and cached_mtime == stat.st_mtime:
            return cached_snapshot, str(WI_SNAPSHOT_CACHE.get("error") or "")
        try:
            snapshot = json.loads(WI_SNAPSHOT_PATH.read_text(encoding="utf-8"))
            if WI_REQUIRE_COMPLETE_SNAPSHOT and not snapshot.get("complete"):
                error = "Wisconsin snapshot is present but marked incomplete"
                WI_SNAPSHOT_CACHE.update({"loaded_at": time.time(), "mtime": stat.st_mtime, "snapshot": None, "error": error})
                return None, error
            records = snapshot.get("records") or []
            if not isinstance(records, list) or not records:
                error = "Wisconsin snapshot contains no records"
                WI_SNAPSHOT_CACHE.update({"loaded_at": time.time(), "mtime": stat.st_mtime, "snapshot": None, "error": error})
                return None, error
            WI_SNAPSHOT_CACHE.update({"loaded_at": time.time(), "mtime": stat.st_mtime, "snapshot": snapshot, "error": ""})
            return snapshot, ""
        except Exception as exc:
            error = f"Wisconsin snapshot could not be loaded: {exc}"
            WI_SNAPSHOT_CACHE.update({"loaded_at": time.time(), "mtime": stat.st_mtime, "snapshot": None, "error": error})
            return None, error


def wi_snapshot_record_names(record: dict) -> list[str]:
    names: list[str] = []
    for key in ("registry_names", "other_names"):
        values = record.get(key) or []
        if isinstance(values, str):
            values = [values]
        for value in values:
            value = re.sub(r"\s+", " ", str(value or "").strip())
            if value and value not in names:
                names.append(value)
    for key in ("registry_name", "full_name"):
        value = re.sub(r"\s+", " ", str(record.get(key) or "").strip())
        if value and value not in names:
            names.append(value)
    return names


def wi_snapshot_has_distinctive_leading_prefix(candidate: str, target: str) -> bool:
    if wrapped_supporting_foundation_match(candidate, target):
        return False
    candidate_norm = normalized_match_name(candidate)
    target_norm = normalized_match_name(target)
    if not candidate_norm or not target_norm or candidate_norm == target_norm or target_norm not in candidate_norm:
        return False
    before = candidate_norm.split(target_norm, 1)[0].strip()
    if not before:
        return False
    generic_prefix_words = {
        "the", "a", "an", "of", "for", "to", "and", "dba", "aka", "also", "as",
        "soliciting", "doing", "business",
    }
    return any(word not in generic_prefix_words for word in before.split())


def wi_snapshot_canonical_name(value: str) -> str:
    canonical = normalized_match_name(value)
    if not canonical:
        return ""
    canonical = re.sub(r"\bst\b", "saint", canonical)
    canonical = re.sub(r"\b([a-z]{3,})\s+s\b", r"\1s", canonical)
    canonical = re.sub(r"\bhospital\s+center\b", "hospital", canonical)
    canonical = re.sub(r"\bmedical\s+center\b", "medical", canonical)
    return re.sub(r"\s+", " ", canonical).strip()


def wi_snapshot_canonical_target_match(candidate: str, targets: list[str]) -> bool:
    candidate_key = wi_snapshot_canonical_name(candidate)
    if not candidate_key:
        return False
    for target in targets or []:
        target_key = wi_snapshot_canonical_name(target)
        if not target_key:
            continue
        if candidate_key == target_key:
            return True
        shorter = min(len(candidate_key.split()), len(target_key.split()))
        if shorter >= 3 and (candidate_key.startswith(target_key) or target_key.startswith(candidate_key)):
            return True
        if shorter >= 4 and (target_key in candidate_key or candidate_key in target_key):
            return True
    return False


def wi_snapshot_name_is_safe(candidate: str, targets: list[str], original_name: str, ein: str) -> bool:
    for target in targets or []:
        if wi_snapshot_has_distinctive_leading_prefix(candidate, target):
            return False
    if wi_snapshot_canonical_target_match(candidate, targets):
        return True
    if registry_name_is_safe_against_targets(candidate, targets, original_name, ein):
        return True
    return wi_contains_full_target_name(candidate, targets)


def wi_snapshot_record_match(record: dict, org, targets: list[str]) -> tuple[int, int, str] | None:
    original_name = getattr(org, "original_organization_name", org.organization_name)
    best: tuple[int, int, str] | None = None
    for registry_name in wi_snapshot_record_names(record):
        if not wi_snapshot_name_is_safe(registry_name, targets, original_name, getattr(org, "ein", "")):
            continue
        priority = checker.name_match_priority_for_targets(registry_name, targets)
        if wi_snapshot_canonical_target_match(registry_name, targets):
            priority = max(priority, 5)
        full_target = wi_contains_full_target_name(registry_name, targets)
        if priority < 4 and not full_target:
            continue
        score = target_name_score(registry_name, targets)
        composite = (priority, score, registry_name)
        if best is None or composite[:2] > best[:2]:
            best = composite
    return best


def wi_snapshot_better_candidate(candidate: dict, best: dict | None) -> bool:
    if not best:
        return True
    if candidate["priority"] != best["priority"]:
        return candidate["priority"] > best["priority"]
    if candidate["score"] != best["score"]:
        return candidate["score"] > best["score"]
    candidate_name = normalized_match_name(candidate.get("matched_name", ""))
    best_name = normalized_match_name(best.get("matched_name", ""))
    if candidate_name and best_name and candidate_name == best_name:
        candidate_date = candidate.get("expiration_date") or date.min
        best_date = best.get("expiration_date") or date.min
        if candidate_date != best_date:
            return candidate_date > best_date
    candidate_severity = wi_status_severity(str(candidate["record"].get("detail_status") or ""))
    best_severity = wi_status_severity(str(best["record"].get("detail_status") or ""))
    if candidate_severity != best_severity:
        return candidate_severity > best_severity
    return (candidate.get("expiration_date") or date.min) > (best.get("expiration_date") or date.min)


def wi_snapshot_note(snapshot: dict) -> str:
    generated_at = str(snapshot.get("generated_at") or "").strip()
    scan = snapshot.get("scan") or {}
    record_count = scan.get("record_count") or len(snapshot.get("records") or [])
    note = (
        "Wisconsin is checked from CharityClarity's Sunday-refreshed local snapshot built from official Wisconsin DFI "
        f"Charitable Organization credential pages. Snapshot generated: {generated_at or 'unknown'}; records: {record_count}."
    )
    generated_dt = wi_snapshot_generated_datetime(snapshot)
    if generated_dt:
        age_seconds = max(0.0, time.time() - generated_dt.timestamp())
        if age_seconds > WI_SNAPSHOT_MAX_AGE_SECONDS:
            note += " Snapshot is older than the preferred freshness window, but CharityClarity used it instead of live WI scraping to avoid transient verification blocks."
    return note


def wi_snapshot_result_from_candidate(org, snapshot: dict, candidate: dict):
    record = candidate["record"]
    expiration_date = candidate.get("expiration_date")
    detail_status = str(record.get("detail_status") or "")
    detail_status_result = wi_status_from_detail_status(detail_status)
    if detail_status_result in {"Revoked", "Suspended", "Closed / Withdrawn / Canceled"}:
        status = detail_status_result
    elif expiration_date:
        status = status_from_calendar_date(expiration_date)
    else:
        status = detail_status_result or checker.STATUS_UNKNOWN
    result = checker.StateResult(
        org.organization_name,
        org.ein,
        "WI",
        status,
        str(record.get("detail_url") or WI_SEARCH_URL),
    )
    expiration_text = str(record.get("expiration_date") or "")
    result.raw_status_text = " | ".join(part for part in [
        detail_status,
        f"Expiration Date: {expiration_text}" if expiration_text else "",
        f"WI License: {record.get('license_number') or ''}" if record.get("license_number") else "",
    ] if part)
    result.source_note = wi_snapshot_note(snapshot)
    result.matched_registry_name = candidate.get("matched_name", "")
    result.matched_registry_identifier = str(record.get("license_number") or "")
    result.success = True
    result.error = ""
    return result


def search_wi_snapshot(org):
    snapshot, load_error = wi_snapshot_load()
    if not snapshot:
        return None
    targets = organization_match_target_variants(org.organization_name, org.ein)
    for wi_name in wi_search_names_for_org(org):
        cleaned = re.sub(r"\s+", " ", (wi_name or "").strip())
        if cleaned and cleaned.lower() not in {target.lower() for target in targets}:
            targets.append(cleaned)
    best: dict | None = None
    for record in snapshot.get("records") or []:
        if not isinstance(record, dict):
            continue
        match = wi_snapshot_record_match(record, org, targets)
        if not match:
            continue
        priority, score, matched_name = match
        expiration_date = parse_due_date(str(record.get("expiration_date") or ""))
        candidate = {
            "record": record,
            "priority": priority,
            "score": score,
            "matched_name": matched_name,
            "expiration_date": expiration_date,
        }
        if wi_snapshot_better_candidate(candidate, best):
            best = candidate
    if best:
        return wi_snapshot_result_from_candidate(org, snapshot, best)
    result = checker.StateResult(org.organization_name, org.ein, "WI", checker.STATUS_NOT_REGISTERED, WI_SEARCH_URL)
    result.raw_status_text = "No matching Wisconsin charitable organization credential in the local snapshot"
    result.source_note = wi_snapshot_note(snapshot)
    if load_error:
        result.source_note += f" Snapshot load note: {load_error}"
    result.success = True
    result.error = ""
    return result


def wi_separator_retry_names(org) -> list[str]:
    original_name = re.sub(r"\s+", " ", (getattr(org, "organization_name", "") or "").strip())
    if not re.search(r"[/|;]|(?:\s+-\s+)|\b(?:d/?b/?a|aka|also\s+soliciting\s+as|doing\s+business\s+as)\b", original_name, re.I):
        return []
    retries: list[str] = []

    def add(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip(" ,;/|-"))
        if not cleaned or cleaned.lower() == original_name.lower():
            return
        compact = re.sub(r"[^A-Za-z0-9]+", "", cleaned)
        words = re.findall(r"[A-Za-z0-9]+", cleaned)
        if len(words) < 2 and not (2 <= len(compact) <= 8 and compact.upper() == compact):
            return
        if cleaned.lower() not in {item.lower() for item in retries}:
            retries.append(cleaned)

    for target in organization_match_target_variants(original_name, getattr(org, "ein", "")):
        add(target)

    def priority(value: str) -> tuple[int, int, str]:
        compact = re.sub(r"[^A-Za-z0-9]+", "", value or "")
        is_acronym = 2 <= len(compact) <= 8 and compact.upper() == compact
        word_count = len(re.findall(r"[A-Za-z0-9]+", value or ""))
        still_has_separator = bool(re.search(r"[/|;]|(?:\s+-\s+)", value or ""))
        return (1 if still_has_separator else 0, 1 if is_acronym else 0, -word_count, value.lower())

    retries.sort(key=priority)
    return retries[:4]


def search_wi_with_separator_retries(org, current_result):
    if public_status(current_result) != "Not Registered":
        return current_result
    for retry_name in wi_separator_retry_names(org):
        retry_org = org_with_name(org, retry_name)
        retry_result = search_wi_snapshot(retry_org)
        if WI_SIDECAR_URL and WI_LOOKUP_SECRET and (
            retry_result is None
            or (
                WI_CONFIRM_SIDECAR_NO_MATCH
                and public_status(retry_result) == "Not Registered"
            )
        ):
            sidecar_result = search_wi_sidecar(retry_org)
            if retry_result is None or public_status(sidecar_result) != "Not Registered":
                retry_result = sidecar_result
        if retry_result is not None and public_status(retry_result) == "Not Registered":
            direct_result = search_wi(None, retry_org)
            if public_status(direct_result) != "Not Registered":
                retry_result = direct_result
        if retry_result is not None and public_status(retry_result) not in {"Not Registered", "Site Not Reachable"}:
            retry_result.organization_name = org.organization_name
            retry_result.source_note = " ".join(part for part in [
                retry_result.source_note or "",
                f"Matched after retrying separator-delimited name segment: {retry_name}.",
            ]).strip()
            return retry_result
    return current_result


def wi_contains_full_target_name(registry_name: str, target_names: list[str]) -> bool:
    """Allow WI rows where the full target is embedded in a longer legal name."""
    normalize = getattr(checker, "normalize_name", lambda value: re.sub(r"\W+", " ", (value or "").lower()).strip())
    candidate_values = {
        normalize(registry_name),
        normalized_match_name(registry_name),
    }
    candidate_values = {value for value in candidate_values if value}
    if not candidate_values:
        return False
    for target_name in target_names or []:
        target_values = {
            normalize(target_name),
            normalized_match_name(target_name),
        }
        for target in {value for value in target_values if value}:
            target_words = target.split()
            if len(target_words) >= 4 and any(target in candidate for candidate in candidate_values):
                return True
            if len(target_words) >= 3:
                target_core = " ".join(
                    word for word in target_words
                    if word not in {"the", "a", "an", "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited"}
                )
                if target_core and len(target_core.split()) >= 3 and any(target_core in candidate for candidate in candidate_values):
                    return True
    return False


def wi_candidate_from_row_html(row_html: str, target_names: list[str]) -> dict | None:
    values = html_table_cells(row_html)
    if len(values) < 6:
        return None
    license_number, profession, registry_name, location, granted_date, expiration_text = values[:6]
    if not re.search(r"Charitable\s+Organization", profession, re.I):
        return None
    score = checker.name_match_priority_for_targets(registry_name, target_names)
    if score < 4 and not wi_contains_full_target_name(registry_name, target_names):
        return None
    href_match = re.search(r"<a[^>]+href=[\"']([^\"']+)[\"']", row_html, re.I)
    href = html.unescape(href_match.group(1)) if href_match else ""
    expiration_date = parse_due_date(expiration_text)
    detail_status = wi_http_detail_status(href)
    if not expiration_date and not wi_status_from_detail_status(detail_status):
        return None
    return {
        "score": score,
        "expiration_date": expiration_date,
        "license_number": license_number,
        "registry_name": registry_name,
        "location": location,
        "granted_date": granted_date,
        "detail_href": href,
        "detail_status": detail_status,
    }


def wi_candidate_from_markdown_row(row_text: str, target_names: list[str]) -> dict | None:
    cells = [cell.strip() for cell in (row_text or "").strip().strip("|").split("|")]
    if len(cells) < 6:
        return None
    license_number, profession, registry_cell, location, granted_date, expiration_text = cells[:6]
    if not re.search(r"Charitable\s+Organization", profession, re.I):
        return None
    if re.match(r"^-+$", license_number) or re.match(r"license#?$", license_number, re.I):
        return None
    registry_name, detail_href = wi_markdown_link_parts(registry_cell)
    score = checker.name_match_priority_for_targets(registry_name, target_names)
    if score < 4 and not wi_contains_full_target_name(registry_name, target_names):
        return None
    expiration_date = parse_due_date(expiration_text)
    detail_status = wi_reader_detail_status(detail_href)
    if not expiration_date and not wi_status_from_detail_status(detail_status):
        return None
    return {
        "score": score,
        "expiration_date": expiration_date,
        "license_number": license_number,
        "registry_name": registry_name,
        "location": location,
        "granted_date": granted_date,
        "detail_href": detail_href,
        "detail_status": detail_status,
    }


def wi_better_candidate(candidate: dict, best_match: dict | None) -> bool:
    if not best_match:
        return True
    if candidate["score"] > best_match["score"]:
        return True
    if candidate["score"] == best_match["score"]:
        candidate_name = normalized_match_name(candidate.get("registry_name", ""))
        best_name = normalized_match_name(best_match.get("registry_name", ""))
        if candidate_name and candidate_name == best_name:
            candidate_date = candidate.get("expiration_date") or date.min
            best_date = best_match.get("expiration_date") or date.min
            if candidate_date != best_date:
                return candidate_date > best_date
        candidate_severity = wi_status_severity(candidate.get("detail_status", ""))
        best_severity = wi_status_severity(best_match.get("detail_status", ""))
        if candidate_severity != best_severity:
            return candidate_severity > best_severity
    return (
        candidate["score"] == best_match["score"]
        and (candidate["expiration_date"] or date.min) > (best_match["expiration_date"] or date.min)
    )


def wi_is_decisive_candidate(candidate: dict | None) -> bool:
    if not candidate:
        return False
    if int(candidate.get("score") or 0) < 5:
        return False
    return bool(wi_status_from_detail_status(candidate.get("detail_status", "")))


def wi_best_match_from_html(result_html: str, target_names: list[str], best_match: dict | None = None) -> dict | None:
    table_match = re.search(
        r"<table[^>]+id=[\"']ctl00_cphMainContent_OrgCredentialSearch_gvCredentialSearchResults[\"'][^>]*>([\s\S]*?)</table>",
        result_html,
        re.I,
    )
    if not table_match:
        return best_match

    for row_match in re.finditer(r"<tr[^>]*>([\s\S]*?)</tr>", table_match.group(1), re.I):
        row_html = row_match.group(1)
        if re.search(r"<th\b", row_html, re.I):
            continue
        candidate = wi_candidate_from_row_html(row_html, target_names)
        if candidate and wi_better_candidate(candidate, best_match):
            best_match = candidate
    return best_match


def wi_best_match_from_markdown(result_text: str, target_names: list[str], best_match: dict | None = None) -> dict | None:
    for line in (result_text or "").splitlines():
        if not line.strip().startswith("|"):
            continue
        candidate = wi_candidate_from_markdown_row(line, target_names)
        if candidate and wi_better_candidate(candidate, best_match):
            best_match = candidate
    return best_match


def wi_reader_search_best_match(search_names: list[str], target_names: list[str], deadline: float | None = None) -> tuple[dict | None, bool]:
    best_match = None
    reader_reached = False
    for search_name in search_names:
        if deadline and time.perf_counter() >= deadline:
            break
        source_url = f"{WI_RESULTS_URL}?{urlencode({'CredentialType': '800', 'FirmName': search_name, 'LicenseNumber': ''})}"
        result_text = wi_reader_text(source_url)
        if re.search(r"Organization Search Results|Search Parameters|Total Search Results", result_text or "", re.I):
            reader_reached = True
        best_match = wi_best_match_from_markdown(result_text, target_names, best_match)
    return best_match, reader_reached


def wi_http_search_best_match(search_names: list[str], target_names: list[str], deadline: float | None = None) -> tuple[dict | None, bool]:
    best_match = None
    http_reached = False
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))
    try:
        base_request = urllib.request.Request(WI_SEARCH_URL, headers=wi_request_headers())
        with opener.open(base_request, timeout=WI_HTTP_TIMEOUT_SECONDS) as response:
            base_html = response.read().decode("utf-8", errors="replace")
    except Exception:
        return None, http_reached

    for search_name in search_names:
        if deadline and time.perf_counter() >= deadline:
            break
        try:
            direct_url = f"{WI_RESULTS_URL}?{urlencode({'CredentialType': '800', 'LicenseNumber': '', 'FirmName': search_name})}"
            request = urllib.request.Request(direct_url, headers=wi_request_headers())
            with opener.open(request, timeout=WI_HTTP_TIMEOUT_SECONDS) as response:
                result_html = response.read().decode("utf-8", errors="replace")
            if wi_result_html_requires_verification(result_html):
                continue
            http_reached = True
            best_match = wi_best_match_from_html(result_html, target_names, best_match)
        except Exception:
            pass

        form_data = {
            **html_hidden_inputs(base_html),
            "ctl00$cphMainContent$ddlProfesionalList": "800",
            "ctl00$cphMainContent$txtFirmName": search_name,
            "ctl00$cphMainContent$btnSearch": "Search",
        }
        try:
            request = urllib.request.Request(
                WI_SEARCH_URL,
                data=urlencode(form_data).encode("utf-8"),
                headers={
                    "Content-Type": "application/x-www-form-urlencoded",
                    **wi_request_headers(),
                    "Origin": "https://apps.dfi.wi.gov",
                },
                method="POST",
            )
            with opener.open(request, timeout=WI_HTTP_TIMEOUT_SECONDS) as response:
                result_html = response.read().decode("utf-8", errors="replace")
            if wi_result_html_requires_verification(result_html):
                continue
            http_reached = True
        except Exception:
            continue

        best_match = wi_best_match_from_html(result_html, target_names, best_match)
    return best_match, http_reached


def search_wi(page, org):
    result = checker.StateResult(org.organization_name, org.ein, "WI", checker.STATUS_UNKNOWN, WI_SEARCH_URL)
    searched_names = wi_search_names_for_org(org) or [org.organization_name]
    started = time.perf_counter()
    deadline = started + WI_LOOKUP_MAX_SECONDS
    direct_names = searched_names[:WI_DIRECT_VARIANT_LIMIT]

    best_match = None
    last_body = ""
    wi_reader_reached = False
    wi_http_reached = False
    target_names = organization_match_target_variants(org.organization_name, org.ein)
    try:
        best_match, wi_reader_reached = wi_reader_search_best_match(direct_names, target_names, deadline)
        if not best_match:
            best_match, wi_http_reached = wi_http_search_best_match(direct_names, target_names, deadline)

        if not best_match and page is not None and time.perf_counter() < deadline and WI_BROWSER_VARIANT_LIMIT > 0:
            for search_name in searched_names[:WI_BROWSER_VARIANT_LIMIT]:
                if time.perf_counter() >= deadline:
                    break
                page.goto(WI_SEARCH_URL, wait_until="domcontentloaded", timeout=min(30000, int(max(5000, (deadline - time.perf_counter()) * 1000))))
                try:
                    checker.safe_wait_for_network_idle(page, timeout=3000)
                except Exception:
                    pass
                try:
                    page.locator("#ctl00_cphMainContent_ddlProfesionalList").select_option(value="800")
                except Exception:
                    page.locator("select").first.select_option(label="Charitable Organization (800)")

                input_box = checker.find_visible_input(page, [
                    "#ctl00_cphMainContent_txtFirmName",
                    'input[name*="FirmName" i]',
                    'input[id*="FirmName" i]',
                    'input[type="text"]',
                ])
                if not input_box:
                    result.error = "WI: Could not find Firm Name input"
                    return result
                input_box.fill("")
                input_box.fill(search_name)

                try:
                    page.locator("#ctl00_cphMainContent_btnSearch").click(timeout=5000)
                except Exception:
                    page.get_by_role("button", name=re.compile("search", re.I)).click(timeout=5000)
                page.wait_for_load_state("domcontentloaded", timeout=min(30000, int(max(5000, (deadline - time.perf_counter()) * 1000))))
                try:
                    checker.safe_wait_for_network_idle(page, timeout=3000)
                except Exception:
                    pass
                last_body = registry_page_body(page)

                rows = page.locator("#ctl00_cphMainContent_OrgCredentialSearch_gvCredentialSearchResults tr")
                for i in range(1, min(rows.count(), 100)):
                    cells = rows.nth(i).locator("th,td")
                    if cells.count() < 6:
                        continue
                    values = [
                        re.sub(r"\s+", " ", cells.nth(index).inner_text(timeout=1500)).strip()
                        for index in range(6)
                    ]
                    license_number, profession, registry_name, location, granted_date, expiration_text = values
                    if not re.search(r"Charitable\s+Organization", profession, re.I):
                        continue
                    score = checker.name_match_priority_for_targets(registry_name, target_names)
                    if score < 4 and not wi_contains_full_target_name(registry_name, target_names):
                        continue
                    href = ""
                    try:
                        href = rows.nth(i).locator("a").first.get_attribute("href") or ""
                    except Exception:
                        href = ""
                    expiration_date = parse_due_date(expiration_text)
                    detail_status = wi_http_detail_status(href)
                    if not expiration_date and not wi_status_from_detail_status(detail_status):
                        continue
                    candidate = {
                        "score": score,
                        "expiration_date": expiration_date,
                        "license_number": license_number,
                        "registry_name": registry_name,
                        "location": location,
                        "granted_date": granted_date,
                        "detail_href": href,
                        "detail_status": detail_status,
                    }
                    if (
                        not best_match
                        or wi_better_candidate(candidate, best_match)
                    ):
                        best_match = candidate

        if not best_match and time.perf_counter() < deadline and not (wi_reader_reached or wi_http_reached):
            best_match, reached = wi_reader_search_best_match(direct_names, target_names, deadline)
            if not best_match:
                best_match, reached_http = wi_http_search_best_match(direct_names, target_names, deadline)
                wi_http_reached = wi_http_reached or reached_http
            wi_reader_reached = wi_reader_reached or reached

        if not best_match:
            if wi_reader_reached or wi_http_reached:
                result.raw_status_text = "No matching Wisconsin charitable organization credential"
                result.status = checker.STATUS_NOT_REGISTERED
                result.source_note = "Wisconsin DFI returned no matching Charitable Organization credential for the organization name searched."
                result.success = True
                return result
            if re.search(r"\b403\b|forbidden|access\s+is\s+denied", last_body or "", re.I):
                result.raw_status_text = "Wisconsin registry returned 403 Forbidden"
                result.status = "Site Not Reachable"
                result.source_note = "Wisconsin DFI blocked or denied the registry result page during lookup."
                result.success = False
                return result
            result.raw_status_text = "Wisconsin registry did not return a usable result page"
            result.status = "Site Not Reachable"
            result.source_note = "Wisconsin DFI did not return a usable registry result page, so CharityClarity did not treat the transient response as a clean no-record finding."
            result.success = False
            return result

        detail_status = best_match.get("detail_status", "")
        if best_match.get("detail_href") and page is not None:
            try:
                page.goto(
                    urljoin(WI_SEARCH_URL, best_match["detail_href"]),
                    wait_until="domcontentloaded",
                    timeout=min(30000, int(max(5000, (deadline - time.perf_counter()) * 1000))),
                )
                try:
                    checker.safe_wait_for_network_idle(page, timeout=3000)
                except Exception:
                    pass
                detail_text = registry_page_body(page)
                detail_status_match = re.search(r"\bStatus\s+(License\s+is\s+(?:not\s+)?current\s*\([^)]+\))", detail_text, re.I)
                if detail_status_match:
                    detail_status = re.sub(r"\s+", " ", detail_status_match.group(1)).strip()
                    if re.search(r"\brevoked\b", detail_status, re.I):
                        result.status = "Revoked"
                        result.raw_status_text = f"{detail_status}{wi_expiration_suffix(best_match.get('expiration_date'))}"
                        result.source_note = "Wisconsin DFI credential detail page shows the license is not current (Revoked), which CharityClarity treats as an adverse status."
                        result.matched_registry_name = best_match["registry_name"]
                        result.matched_registry_identifier = best_match["license_number"]
                        result.success = True
                        return result
            except Exception:
                pass

        detail_status_result = wi_status_from_detail_status(detail_status)
        if detail_status_result in {"Revoked", "Suspended", "Closed / Withdrawn / Canceled"}:
            result.status = "Closed / Withdrawn / Canceled"
            if detail_status_result != "Closed / Withdrawn / Canceled":
                result.status = detail_status_result
            result.raw_status_text = f"{detail_status}{wi_expiration_suffix(best_match.get('expiration_date'))}"
            result.source_note = (
                "Wisconsin DFI credential detail page shows an adverse credential status, "
                "which CharityClarity gives priority over expiration-date timing."
            )
            result.matched_registry_name = best_match["registry_name"]
            result.matched_registry_identifier = best_match["license_number"]
            result.success = True
            return result

        expiration_date = best_match.get("expiration_date")
        if not expiration_date:
            result.status = detail_status_result or checker.STATUS_UNKNOWN
            result.raw_status_text = detail_status or "Wisconsin credential matched without a parseable expiration date"
            result.source_note = "Wisconsin DFI public registry returned a matching Charitable Organization credential, but no parseable expiration date was available."
            result.matched_registry_name = best_match["registry_name"]
            result.matched_registry_identifier = best_match["license_number"]
            result.success = bool(detail_status_result)
            return result

        result.status = status_from_calendar_date(expiration_date)
        result.raw_status_text = (
            f"{detail_status}; License current through {format_date(expiration_date)}"
            if detail_status
            else f"Expiration Date {format_date(expiration_date)}"
        )
        result.source_note = (
            "Wisconsin DFI public registry shows a Charitable Organization credential "
            f"expiration date of {format_date(expiration_date)}."
        )
        result.matched_registry_name = best_match["registry_name"]
        result.matched_registry_identifier = best_match["license_number"]
        result.success = True
        return result
    except Exception as e:
        result.error = f"WI error: {e}"
        result.source_note = "Wisconsin DFI public registry lookup could not be completed."
        if last_body:
            result.raw_status_text = "Wisconsin lookup ended after reaching the public registry"
        return result


def search_wi_sidecar(org):
    acquired = WI_SIDECAR_SEMAPHORE.acquire(timeout=WI_SIDECAR_ACQUIRE_SECONDS)
    if not acquired:
        result = checker.StateResult(org.organization_name, org.ein, "WI", "Site Not Reachable", WI_SEARCH_URL)
        result.raw_status_text = "Wisconsin lookup lanes were busy"
        result.source_note = "Wisconsin DFI lookup could not start before the lane-acquire timeout."
        result.success = False
        return result
    try:
        return _search_wi_sidecar_unlocked(org)
    finally:
        WI_SIDECAR_SEMAPHORE.release()


def _search_wi_sidecar_unlocked(org):
    result = checker.StateResult(org.organization_name, org.ein, "WI", "Site Not Reachable", WI_SEARCH_URL)
    if not (WI_SIDECAR_URL and WI_LOOKUP_SECRET):
        result.raw_status_text = "Wisconsin sidecar is not configured"
        result.source_note = "Wisconsin DFI sidecar lookup is not configured for this environment."
        result.success = False
        return result
    search_names = wi_search_names_for_org(org) or [org.organization_name]
    sidecar_search_names = []

    def add_sidecar_name(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip())
        if cleaned and cleaned.lower() not in {existing.lower() for existing in sidecar_search_names}:
            sidecar_search_names.append(cleaned)

    for search_name in search_names[:4]:
        add_sidecar_name(search_name)
        national_prefix_removed = re.sub(
            r"^(?:the\s+)?(?:u\.?\s*s\.?|us|united\s+states)\s+",
            "",
            search_name,
            flags=re.I,
        ).strip()
        if len(national_prefix_removed.split()) >= 2:
            add_sidecar_name(national_prefix_removed)
    for search_name in search_names:
        add_sidecar_name(search_name)
        if len(sidecar_search_names) >= WI_DIRECT_VARIANT_LIMIT:
            break
    sidecar_search_names = sidecar_search_names[:WI_DIRECT_VARIANT_LIMIT]
    target_names = organization_match_target_variants(org.organization_name, org.ein)
    for wi_name in search_names:
        cleaned = re.sub(r"\s+", " ", (wi_name or "").strip())
        if cleaned and cleaned.lower() not in {target.lower() for target in target_names}:
            target_names.append(cleaned)
    payload = {
        "organization_name": org.organization_name,
        "ein": org.ein,
        "search_names": sidecar_search_names,
        "target_names": target_names,
        "max_seconds": WI_SIDECAR_TIMEOUT_SECONDS,
        "app_version": APP_VERSION,
    }

    def direct_then_browser_fallback(note: str, site_result=None):
        sidecar_status = public_status(site_result) if site_result is not None else str((data or {}).get("status") or "")
        sidecar_confirmed_no_match = sidecar_status == checker.STATUS_NOT_REGISTERED
        direct_result = search_wi(None, org)
        direct_status = public_status(direct_result)
        if direct_status not in {"Site Not Reachable", checker.STATUS_NOT_REGISTERED}:
            direct_result.source_note = note
            return direct_result
        if direct_status == checker.STATUS_NOT_REGISTERED:
            if sidecar_confirmed_no_match:
                direct_result.source_note = (
                    f"{note} Wisconsin DFI returned no matching credential after sidecar "
                    "and backend-direct confirmation."
                )
                return direct_result
            best_terminal = direct_result
            for attempt_index in range(WI_NO_MATCH_CONFIRMATION_ATTEMPTS):
                if WI_NO_MATCH_CONFIRMATION_DELAY_SECONDS > 0:
                    time.sleep(min(WI_NO_MATCH_CONFIRMATION_DELAY_SECONDS * (attempt_index + 1), 5.0))
                confirmed_result = search_wi(None, org)
                confirmed_status = public_status(confirmed_result)
                if confirmed_status not in {"Site Not Reachable", checker.STATUS_NOT_REGISTERED}:
                    confirmed_result.source_note = (
                        f"{note} A delayed Wisconsin confirmation lookup replaced an initial "
                        "backend no-record response."
                    )
                    return confirmed_result
                if confirmed_status == checker.STATUS_NOT_REGISTERED:
                    best_terminal = confirmed_result
                    best_terminal.source_note = (
                        f"{note} Wisconsin DFI returned no matching credential after "
                        "backend-direct confirmation."
                    )
                    return best_terminal

        for attempt_index in range(WI_NO_MATCH_CONFIRMATION_ATTEMPTS):
            if WI_NO_MATCH_CONFIRMATION_DELAY_SECONDS > 0:
                time.sleep(min(WI_NO_MATCH_CONFIRMATION_DELAY_SECONDS * (attempt_index + 1), 5.0))
            confirmed_result = search_wi(None, org)
            confirmed_status = public_status(confirmed_result)
            if confirmed_status not in {"Site Not Reachable", checker.STATUS_NOT_REGISTERED}:
                confirmed_result.source_note = (
                    f"{note} A delayed Wisconsin reachability retry found the matching credential."
                )
                return confirmed_result
            if confirmed_status == checker.STATUS_NOT_REGISTERED:
                confirmed_result.source_note = (
                    f"{note} Wisconsin DFI returned no matching credential after "
                    "backend-direct reachability retry."
                )
                return confirmed_result
            direct_result = confirmed_result

        if not WI_USE_BACKEND_BROWSER_FALLBACK:
            return site_result or direct_result

        browser_result = search_wi_backend_browser_fallback(org)
        browser_status = public_status(browser_result)
        if browser_status not in {"Site Not Reachable", checker.STATUS_NOT_REGISTERED}:
            browser_result.source_note = (
                f"{note} The backend browser fallback found the matching Wisconsin credential "
                "after the direct fallback did not return a match."
            )
            return browser_result
        best_terminal = browser_result if browser_status == checker.STATUS_NOT_REGISTERED else direct_result
        if browser_status == checker.STATUS_NOT_REGISTERED:
            for attempt_index in range(WI_NO_MATCH_CONFIRMATION_ATTEMPTS):
                if WI_NO_MATCH_CONFIRMATION_DELAY_SECONDS > 0:
                    time.sleep(min(WI_NO_MATCH_CONFIRMATION_DELAY_SECONDS * (attempt_index + 1), 5.0))
                confirmed_result = search_wi(None, org)
                confirmed_status = public_status(confirmed_result)
                if confirmed_status not in {"Site Not Reachable", checker.STATUS_NOT_REGISTERED}:
                    confirmed_result.source_note = (
                        f"{note} A delayed Wisconsin confirmation lookup replaced an initial "
                        "backend no-record response."
                    )
                    return confirmed_result
                if confirmed_status == checker.STATUS_NOT_REGISTERED:
                    best_terminal = confirmed_result
            if public_status(best_terminal) == checker.STATUS_NOT_REGISTERED:
                best_terminal.source_note = (
                    f"{note} Wisconsin DFI returned no matching credential after direct, "
                    "backend-browser, and delayed confirmation attempts."
                )
                return best_terminal
        if browser_status == checker.STATUS_NOT_REGISTERED and direct_status == "Site Not Reachable":
            browser_result.source_note = (
                f"{note} The backend browser fallback reached Wisconsin DFI and returned no matching "
                "Charitable Organization credential."
            )
            return browser_result
        if direct_status != "Site Not Reachable":
            direct_result.source_note = note
            return direct_result
        return site_result or direct_result

    data = None
    last_exception = None
    for attempt_index in range(WI_SIDECAR_ATTEMPTS):
        try:
            request = urllib.request.Request(
                WI_SIDECAR_URL,
                data=json.dumps(payload).encode("utf-8"),
                headers={
                    "Content-Type": "application/json",
                    "Accept": "application/json",
                    "X-CE-WI-Lookup-Secret": WI_LOOKUP_SECRET,
                    "User-Agent": f"CharityClarity/{APP_VERSION}",
                },
                method="POST",
            )
            with urllib.request.urlopen(request, timeout=WI_SIDECAR_TIMEOUT_SECONDS + 5) as response:
                response_body = response.read().decode("utf-8", errors="replace")
            candidate_data = json.loads(response_body)
        except Exception as exc:
            last_exception = exc
            if attempt_index + 1 < WI_SIDECAR_ATTEMPTS:
                time.sleep(0.4 * (attempt_index + 1))
            continue

        data = candidate_data
        if candidate_data.get("status") == "Not Registered":
            if WI_CONFIRM_SIDECAR_NO_MATCH and attempt_index + 1 < WI_SIDECAR_ATTEMPTS:
                time.sleep(0.4 * (attempt_index + 1))
                continue
            break
        if candidate_data.get("success") or candidate_data.get("status") != "Site Not Reachable":
            break
        if attempt_index + 1 < WI_SIDECAR_ATTEMPTS:
            time.sleep(0.4 * (attempt_index + 1))

    if data is None:
        result.raw_status_text = "Wisconsin sidecar lookup failed"
        result.source_note = "Wisconsin DFI sidecar lookup could not be completed."
        result.error = str(last_exception or "WI sidecar returned no response")
        result.success = False
        return direct_then_browser_fallback(
            "Wisconsin DFI lookup used backend fallbacks after the sidecar returned no response.",
            result,
        )

    if data.get("status") == "Site Not Reachable" and not data.get("success"):
        fallback_result = direct_then_browser_fallback(
            "Wisconsin DFI lookup used backend fallbacks after the sidecar could not reach the registry."
        )
        if public_status(fallback_result) != "Site Not Reachable":
            return fallback_result

    if data.get("status") == "Not Registered" and WI_CONFIRM_SIDECAR_NO_MATCH:
        fallback_result = direct_then_browser_fallback(
            "Wisconsin DFI lookup used backend fallbacks to confirm the sidecar no-match result."
        )
        return fallback_result

    result.status = data.get("status") or "Site Not Reachable"
    result.source_url = data.get("source_url") or WI_SEARCH_URL
    result.raw_status_text = data.get("raw_status_text") or result.status
    result.source_note = data.get("source_note") or "Wisconsin DFI lookup was performed through the CharityClarity Wisconsin sidecar."
    result.matched_registry_name = data.get("matched_registry_name") or ""
    result.matched_registry_identifier = data.get("matched_registry_identifier") or ""
    result.error = data.get("error") or ""
    result.success = bool(data.get("success", public_status(result) != "Site Not Reachable"))
    return result


def search_wi_backend_browser_fallback(org):
    acquired = WI_BACKEND_BROWSER_SEMAPHORE.acquire(timeout=WI_BACKEND_BROWSER_ACQUIRE_SECONDS)
    if not acquired:
        result = checker.StateResult(org.organization_name, org.ein, "WI", "Site Not Reachable", WI_SEARCH_URL)
        result.raw_status_text = "Wisconsin backend fallback lanes were busy"
        result.source_note = "Wisconsin DFI backend fallback could not start before the lane-acquire timeout."
        result.success = False
        return result
    with checker.sync_playwright() as p:
        browser = None
        context = None
        try:
            browser = p.chromium.launch(headless=True)
            context = browser.new_context(user_agent=BROWSER_USER_AGENT, locale="en-US")
            configure_browser_context(context)
            page = context.new_page()
            global WI_BROWSER_VARIANT_LIMIT
            previous_browser_variant_limit = WI_BROWSER_VARIANT_LIMIT
            WI_BROWSER_VARIANT_LIMIT = max(previous_browser_variant_limit, 3)
            try:
                return search_wi(page, org)
            finally:
                WI_BROWSER_VARIANT_LIMIT = previous_browser_variant_limit
        except Exception as exc:
            result = checker.StateResult(org.organization_name, org.ein, "WI", "Site Not Reachable", WI_SEARCH_URL)
            result.raw_status_text = "Wisconsin backend fallback failed"
            result.source_note = "Wisconsin DFI backend fallback could not be completed."
            result.error = str(exc)
            result.success = False
            return result
        finally:
            if context:
                try:
                    context.close()
                except Exception:
                    pass
            if browser:
                try:
                    browser.close()
                except Exception:
                    pass
            WI_BACKEND_BROWSER_SEMAPHORE.release()


def response_data_for_lookup(result, body: str, org, organization_name: str, ein: str, state: str, lookup_started: float) -> dict:
    if result is None:
        result = checker.StateResult(organization_name or f"EIN {format_ein(ein)}", format_ein(ein), state, "Site Not Reachable", "")
        result.raw_status_text = "Lookup did not produce a registry result"
        result.source_note = "Public registry lookup could not produce a result."
        result.error = "No result"
        result.success = False
    correction_body = apply_confirmed_feedback_correction(result)
    if correction_body:
        body = " ".join(part for part in [body or "", correction_body] if part)
    if public_status(result) != "Not Registered":
        fill_registry_match_from_text(result, body, org)
    normalize_registry_match_fields(result, org)
    result.source_note = source_note_for_result(result)
    data = checker.asdict(result)
    if organization_name:
        data["organization_name"] = organization_name
        result.organization_name = organization_name
    elif (data.get("matched_registry_name") or "").strip():
        data["organization_name"] = (data.get("matched_registry_name") or "").strip()
        result.organization_name = data["organization_name"]
    elif not (data.get("organization_name") or "").strip():
        data["organization_name"] = "Organization not identified"
        result.organization_name = data["organization_name"]
    data["status"] = true_status_from_body(result, body)
    data["comments"] = comments_for_result(result, body, data["status"])
    data["evidence_url"] = ""
    data["lookup_seconds"] = round(time.perf_counter() - lookup_started, 2)
    data["checked_at_epoch"] = int(time.time())
    data["app_version"] = APP_VERSION
    log_event(f"{state} lookup for {format_ein(ein)} finished in {data['lookup_seconds']}s with status {data.get('status')}")
    return data


def enrich_me_result_from_body(result, body: str) -> None:
    existing_status = " ".join([result.status or "", result.raw_status_text or ""])
    if re.search(r"\bACTIVE\b", existing_status, re.I) and not re.search(r"\b(FAILED\s+TO\s+RENEW|EXPIRED|REVOKED|SUSPENDED|INACTIVE)\b", existing_status, re.I):
        result.raw_status_text = result.raw_status_text or "Active"
        result.status = "Current" if re.search(r"\bunknown\b|^\s*active\s*$", result.status or "", re.I) else (result.status or "Current")
        result.source_note = result.source_note or "Registration status with definition (ME)"
        result.error = ""
        result.success = True
        return
    readable = html.unescape(re.sub(r"<[^>]+>", " ", body or ""))
    readable = re.sub(r"\s+", " ", readable).strip()
    if re.search(r"0 records found|no records|no results|no companies found|no data", readable, re.I):
        result.raw_status_text = "No record found"
        result.status = "Not Registered"
        result.source_note = "Maine search returned no matching organization result."
        result.error = ""
        result.success = True
        return

    status_text = ""
    if re.search(r"\bLicense\s+Number\b", readable, re.I):
        status_match = re.search(r"\bStatus\s*:?\s*([A-Za-z][A-Za-z /-]+?)\s+Expiration\s+Date\s*:?\s*([0-9/.-]+)", readable, re.I)
        if status_match:
            status_text = status_match.group(1).strip()
            expiration_text = status_match.group(2).strip()
        else:
            status_text = checker.extract_labeled_value_from_text(readable, ["Status", "Registration Status"])
            expiration_text = checker.extract_labeled_value_from_text(readable, ["Expiration Date", "Expiration"])
        if expiration_text and expiration_text not in status_text:
            status_text = f"{status_text}; expiration date {expiration_text}".strip("; ")
    if not status_text and re.search(r"\bCHARITABLE\s+ORGANIZATION\b[\s\S]{0,80}\bACTIVE\b", readable, re.I):
        status_text = "Active"
    if not status_text and re.search(r"\bACTIVE\b", readable, re.I) and re.search(r"ShowDetail\.aspx|Licensees|CHARITABLE", body or "", re.I):
        status_text = "Active"

    if status_text:
        result.raw_status_text = status_text
        result.status = status_text
        result.source_note = "Maine public registry record or search result status."
        result.error = ""
        result.success = True


def nj_detail_body(page, org) -> str:
    pieces = [registry_page_body(page)]
    ein_digits = re.sub(r"\D", "", org.ein or "")
    normalize_name = getattr(checker, "normalize_name", lambda value: re.sub(r"\s+", " ", (value or "").lower()).strip())
    wanted_name = normalize_name(org.organization_name)
    clicked = False
    candidates = []

    def score_nj_candidate(row_text: str, label_text: str = "", index: int = 0) -> tuple[int, int, int, int]:
        haystack = re.sub(r"\s+", " ", f"{row_text} {label_text}").strip()
        row_digits = re.sub(r"\D", "", haystack)
        row_name = normalize_name(haystack)
        if ein_digits and ein_digits not in row_digits and wanted_name not in row_name:
            return (-999, -999, -index)
        try:
            status_priority = checker.active_row_priority(haystack)
        except Exception:
            status_priority = 40
        try:
            name_priority = checker.name_match_priority(haystack, org.organization_name)
        except Exception:
            name_priority = 0
        ein_priority = 3 if ein_digits and ein_digits in row_digits else 0
        return (ein_priority, name_priority, status_priority, -index)

    for selector in ["button.ms-Link", "button[role='link']", "[data-automation-key='name'] button"]:
        try:
            buttons = page.locator(selector)
            for i in range(min(buttons.count(), 20)):
                button = buttons.nth(i)
                try:
                    row = button.locator("xpath=ancestor::*[@role='row'][1]")
                    row_text = re.sub(r"\s+", " ", row.inner_text(timeout=1500)).strip() if row.count() else ""
                    button_text = re.sub(r"\s+", " ", button.inner_text(timeout=1500)).strip()
                    score = score_nj_candidate(row_text, button_text, i)
                    if score[0] < 0:
                        continue
                    candidates.append((score, button))
                except Exception:
                    continue
        except Exception:
            continue

    for selector in ["tbody tr", "tr", "[role='row']", ".card", ".search-result", "a[href]"]:
        try:
            rows = page.locator(selector)
            for i in range(min(rows.count(), 80)):
                row = rows.nth(i)
                try:
                    if not row.is_visible(timeout=750):
                        continue
                    row_text = re.sub(r"\s+", " ", row.inner_text(timeout=1500)).strip()
                    score = score_nj_candidate(row_text, "", i)
                    if score[0] < 0:
                        continue
                    target = row
                    links = row.locator("a[href]")
                    if selector != "a[href]" and links.count():
                        target = links.first
                    candidates.append((score, target))
                except Exception:
                    continue
        except Exception:
            continue

    if candidates:
        candidates.sort(key=lambda item: item[0], reverse=True)
        try:
            candidates[0][1].click(timeout=5000)
            clicked = True
        except Exception:
            clicked = False

    if clicked:
        try:
            checker.safe_wait_for_network_idle(page, timeout=20000)
        except Exception:
            pass
        time.sleep(3)
        for label in ["Filings", "Annual Filings", "Financial", "Documents", "View Details"]:
            try:
                page.get_by_text(re.compile(label, re.I)).first.click(timeout=3000)
                time.sleep(2)
                break
            except Exception:
                continue
        try:
            page.locator("body").evaluate("window.scrollTo(0, document.body.scrollHeight)")
            time.sleep(1)
        except Exception:
            pass
        for selector in ["[role='dialog']", ".ms-Dialog-main", ".ms-Modal-scrollableContent", ".ms-Panel-scrollableContent", ".modal-content"]:
            try:
                containers = page.locator(selector)
                for i in range(min(containers.count(), 5)):
                    container = containers.nth(i)
                    try:
                        if not container.is_visible(timeout=750):
                            continue
                        container.evaluate("el => { el.scrollTop = el.scrollHeight; }")
                        time.sleep(1)
                    except Exception:
                        continue
            except Exception:
                continue
        try:
            page.get_by_text(re.compile(r"20\d{2}|Filing|Annual|Renewal|Financial", re.I)).last.scroll_into_view_if_needed(timeout=5000)
            page.locator("body").evaluate("window.scrollBy(0, -140)")
            time.sleep(1)
        except Exception:
            pass
        pieces.append(registry_page_body(page))

    return "\n".join(piece for piece in pieces if piece)


def search_nj_direct(page, org):
    url = "https://charportal.dca.njoag.gov/Charity-Registration/CHR-Public-Search-Page/"
    result = checker.StateResult(org.organization_name, org.ein, "NJ", checker.STATUS_UNKNOWN, url)
    try:
        ein_digits = re.sub(r"\D", "", org.ein or "")
        page.goto(url, wait_until="domcontentloaded", timeout=60000)
        time.sleep(1)
        input_box = None
        for selector in [
            "#SearchBox28",
            'input[placeholder="Search"]',
            'input[aria-label*="partial text" i]',
            'input[id^="SearchBox"]',
            'input[type="search"]',
            'input[type="text"]',
        ]:
            try:
                candidate = page.locator(selector).first
                candidate.wait_for(state="visible", timeout=5000)
                input_box = candidate
                break
            except Exception:
                continue
        if not input_box:
            result.error = "Could not find NJ search box"
            return result

        input_box.fill("")
        input_box.fill(ein_digits or org.organization_name)
        page.keyboard.press("Enter")
        body = ""
        deadline = time.time() + 12
        while time.time() < deadline:
            body = page.locator("body").inner_text(timeout=5000)
            body_digits = re.sub(r"\D", "", body)
            if (ein_digits and ein_digits in body_digits) or re.search(r"no records found|no records|no matching|0 results", body, re.I):
                break
            time.sleep(0.75)
        if re.search(r"no records found|no records|no matching|0 results", body, re.I):
            result.raw_status_text = "No record found"
            result.status = checker.STATUS_NOT_REGISTERED
            result.source_note = "New Jersey search returned no matching record."
            result.success = True
            return result
        if ein_digits and ein_digits not in re.sub(r"\D", "", body or ""):
            result.raw_status_text = "Requested EIN not found in New Jersey public search results"
            result.status = checker.STATUS_NOT_REGISTERED
            result.source_note = "New Jersey public search did not return the requested EIN within CharityClarity's bounded lookup window."
            result.success = True
            return result

        status = ""
        status_patterns = [
            ("Noncompliant", r"\bnon\W*compliant\b"),
            ("Exempt", r"\bexempt\b"),
            ("Delinquent", r"\bdelinquent\b"),
            ("Retired", r"\bretired\b"),
            ("Withdrawn", r"\bwithdrawn\b"),
            ("Revoked", r"\brevoked\b"),
            ("Suspended", r"\bsuspended\b"),
            ("Expired", r"\bexpired\b"),
            ("Pending", r"\bpending\b"),
            ("Compliant", r"\bcompliant\b"),
            ("Active", r"\bactive\b"),
            ("Current", r"\bcurrent\b"),
        ]
        if ein_digits and ein_line_has_registry_pattern(body, org.ein, r"\bnon\W*compliant\b"):
            status = "Noncompliant"
        if not status and ein_digits and ein_digits in re.sub(r"\D", "", body):
            compact_body = re.sub(r"\s+", " ", body)
            for match in re.finditer(r"\bnon\W*compliant\b", compact_body, re.I):
                start = max(0, match.start() - 260)
                end = min(len(compact_body), match.end() + 260)
                window = compact_body[start:end]
                if ein_digits in re.sub(r"\D", "", window):
                    status = "Noncompliant"
                    break
        if not status and ein_digits and ein_digits in re.sub(r"\D", "", body):
            try:
                rows = page.locator("tr")
                best_status = ""
                best_score = (-999, -999, -999)
                for i in range(min(rows.count(), 80)):
                    row_text = re.sub(r"\s+", " ", rows.nth(i).inner_text(timeout=1500)).strip()
                    if ein_digits not in re.sub(r"\D", "", row_text):
                        continue
                    row_status = ""
                    for label, pattern in status_patterns:
                        if re.search(pattern, row_text, re.I):
                            row_status = label
                            break
                    if not row_status:
                        continue
                    try:
                        name_priority = checker.name_match_priority(row_text, org.organization_name)
                    except Exception:
                        name_priority = -1
                    status_priority = checker.active_row_priority(row_text)
                    row_score = (name_priority, status_priority, -i)
                    if row_score > best_score:
                        best_score = row_score
                        best_status = row_status
                if best_status:
                    status = best_status
            except Exception:
                pass
        if not status and ein_digits and ein_digits in re.sub(r"\D", "", body):
            body_candidates = []
            compact_body = re.sub(r"\s+", " ", body)
            for label, pattern in status_patterns:
                for match in re.finditer(pattern, compact_body, re.I):
                    start = max(0, match.start() - 220)
                    end = min(len(compact_body), match.end() + 220)
                    window = compact_body[start:end]
                    if ein_digits not in re.sub(r"\D", "", window):
                        continue
                    try:
                        name_priority = checker.name_match_priority(window, org.organization_name)
                    except Exception:
                        name_priority = -1
                    status_priority = checker.active_row_priority(label)
                    body_candidates.append((status_priority, name_priority, -match.start(), label))
            if body_candidates:
                body_candidates.sort(reverse=True)
                status = body_candidates[0][3]
        if not status:
            status_match = re.search(r"Status\s+([A-Za-z][A-Za-z /-]+?)\s+Federal\s+EIN", re.sub(r"\s+", " ", body), re.I)
            if status_match:
                status = status_match.group(1).strip()
        registry_name = useful_registry_name(checker.extract_labeled_value_from_text(body, ["Organization Name", "Charity Name", "Legal Name", "Name"]))
        if not registry_name and ein_digits:
            for line in re.split(r"[\r\n]+", body or ""):
                line_text = re.sub(r"\s+", " ", line).strip()
                if ein_digits not in re.sub(r"\D", "", line_text):
                    continue
                registry_name = useful_registry_name(re.split(r"\b(?:Federal\s+EIN|EIN|Status|Registration)\b", line_text, maxsplit=1, flags=re.I)[0])
                if registry_name:
                    break
        result.matched_registry_name = registry_name
        result.raw_status_text = status or "Status not found"
        if re.search(r"\b(retired|withdrawn|terminated|cancelled|canceled|closed)\b", status, re.I):
            result.status = "Closed / Withdrawn / Canceled"
        elif re.search(r"\bnon\W*compliant\b", status, re.I):
            result.status = "Delinquent"
        else:
            result.status = status or checker.STATUS_UNKNOWN
        result.source_note = "New Jersey uses the public search result Status value."
        result.success = True
        return result
    except Exception as exc:
        result.error = f"NJ error: {exc}"
        return result


def search_nj_with_name_fallback(page, org):
    result = search_nj_direct(page, org)
    if public_status(result) != "Not Registered":
        return result
    fallback_started = time.monotonic()
    try:
        fallback_budget_seconds = float(os.environ.get("CE_NJ_NAME_FALLBACK_SECONDS", "32"))
    except Exception:
        fallback_budget_seconds = 32.0
    for variant in organization_name_variants(
        org.organization_name,
        org.ein,
        include_ein_aliases=True,
        include_name_segments=True,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
        include_broad_query_prefixes=False,
    )[:4]:
        if time.monotonic() - fallback_started > fallback_budget_seconds:
            result.source_note = (
                (result.source_note or "New Jersey search returned no matching record.")
                + " New Jersey name fallback was bounded to preserve bulk reliability."
            )
            return result
        fallback_org = SimpleNamespace(organization_name=variant, ein="")
        fallback = search_nj_direct(page, fallback_org)
        if public_status(fallback) == "Site Not Reachable":
            return copy_name_fallback_result(org, fallback)
        if public_status(fallback) == "Not Registered":
            continue
        if result_registry_name_is_safe(fallback, org.organization_name, org.ein):
            fallback.source_note = (
                (fallback.source_note or "New Jersey public search found a matching organization-name record.")
                + " CharityClarity used a name fallback after the EIN search returned no matching record."
            )
            return copy_name_fallback_result(org, fallback)
    return result


def search_pa_with_name_fallback(page, org):
    result = checker.search_pa(page, org)
    if public_status(result) != "Not Registered":
        return result
    url = "https://www.charities.pa.gov/#/page/searchCharities"
    safe_targets = organization_match_target_variants(org.organization_name, org.ein)
    fallback_started = time.monotonic()
    try:
        fallback_budget_seconds = float(os.environ.get("CE_PA_NAME_FALLBACK_SECONDS", "20"))
    except Exception:
        fallback_budget_seconds = 20.0
    for variant in organization_name_variants(
        org.organization_name,
        org.ein,
        include_ein_aliases=True,
        include_name_segments=True,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
        include_broad_query_prefixes=False,
    )[:4]:
        if time.monotonic() - fallback_started > fallback_budget_seconds:
            result.source_note = (
                (result.source_note or "PA search results did not contain a matching EIN row.")
                + " Pennsylvania name fallback was bounded to preserve bulk reliability."
            )
            return result
        fallback = checker.StateResult(org.organization_name, org.ein, "PA", checker.STATUS_UNKNOWN, url)
        try:
            page.goto(url, wait_until="domcontentloaded", timeout=12000)
            checker.safe_wait_for_network_idle(page, timeout=2500)
            time.sleep(0.4)
            name_input = checker.find_visible_input(page, [
                'input[name*="CharityName" i]',
                'input[ng-model*="name" i]',
                'input[placeholder*="Name" i]',
                'input[name*="name" i]',
                'input[id*="name" i]',
                'input[type="text"]',
            ])
            if not name_input:
                continue
            name_input.fill("")
            name_input.fill(variant)
            if not checker.click_pa_search_button(page):
                continue
            checker.safe_wait_for_network_idle(page, timeout=5000)
            time.sleep(0.8)
            candidates = []
            for selector in ["tbody tr", "tr", "[role='row']"]:
                try:
                    rows = page.locator(selector)
                    for index in range(min(rows.count(), 100)):
                        row = rows.nth(index)
                        try:
                            if not row.is_visible(timeout=750):
                                continue
                            row_text = re.sub(r"\s+", " ", row.inner_text(timeout=1500)).strip()
                            if not row_text:
                                continue
                            cells = row.locator("td")
                            row_name = ""
                            expiration_raw = ""
                            if cells.count() >= 5:
                                row_name = cells.nth(0).inner_text(timeout=1500).strip()
                                expiration_raw = cells.nth(4).inner_text(timeout=1500).strip()
                            if not row_name:
                                row_name = clean_registry_name(re.split(r"\bEIN\b|\bExpiration\b|\bStatus\b", row_text, maxsplit=1, flags=re.I)[0])
                            score = target_name_score(row_name, safe_targets)
                            if score < 450 and not compatible_ein_alias_for_name(org.organization_name, row_name):
                                continue
                            if not expiration_raw:
                                expiration_raw = checker.extract_labeled_value_from_text(row_text, ["Expiration Date", "Expiration"]) if hasattr(checker, "extract_labeled_value_from_text") else ""
                            candidates.append((score, row_name, row_text, expiration_raw))
                        except Exception:
                            continue
                except Exception:
                    continue
            if not candidates:
                continue
            candidates.sort(key=lambda item: item[0], reverse=True)
            _, row_name, row_text, expiration_raw = candidates[0]
            fallback.matched_registry_name = clean_registry_name(row_name)
            expiration_date = parse_due_date(expiration_raw)
            if re.search(r"\bexempt\b", row_text or "", re.I):
                fallback.raw_status_text = "Exempt"
                fallback.status = "Exempt"
            elif expiration_date:
                fallback.raw_status_text = expiration_raw
                fallback.status = status_from_calendar_date(expiration_date)
            else:
                status_text = checker.extract_labeled_value_from_text(row_text, ["Status", "Registration Status"]) if hasattr(checker, "extract_labeled_value_from_text") else ""
                fallback.raw_status_text = status_text or "Pennsylvania name result found"
                fallback.status = status_text or checker.STATUS_UNKNOWN
            fallback.source_note = "Pennsylvania name search found a matching row after the EIN search returned no matching record."
            fallback.success = True
            return fallback
        except Exception as exc:
            fallback.error = f"PA name fallback error: {exc}"
            continue
    return result


def md_filing_context(result, body: str) -> dict:
    return filing_context(result, body)


def fiscal_year_end_from_body(body: str, state: str = "") -> tuple[int, int] | None:
    readable_body = html.unescape(re.sub(r"<[^>]+>", " ", body))
    state = (state or "").upper()
    if state == "CA":
        annual_match = re.search(
            r"Annual\s+Renewal\s+Data([\s\S]{0,12000}?)(?:Fundraising\s+Platform\s+Data|Related\s+Registration|Filing\s+and\s+Correspondence|$)",
            readable_body,
            re.I,
        )
        if not annual_match:
            return None
        annual_section = annual_match.group(1)
        ca_patterns = [
            r"Accounting\s+Period\s+End\s+Date\s*:?\s*(\d{1,2}[/-]\d{1,2}[/-]\d{2,4})",
            r"Accounting\s+Period\s+End\s+Date\s*:?\s*([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})",
            r"Fiscal\s+Year\s+End(?:ing)?\s*:?\s*(\d{1,2}[/-]\d{1,2}[/-]\d{2,4})",
            r"Fiscal\s+Year\s+End(?:ing)?\s*:?\s*([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})",
        ]
        for pattern in ca_patterns:
            matches = [parse_due_date(match.group(1)) for match in re.finditer(pattern, annual_section, re.I)]
            parsed_dates = [value for value in matches if value]
            if parsed_dates:
                latest_period_end = max(parsed_dates)
                return latest_period_end.month, latest_period_end.day
        return None
    if state == "HI":
        annual_match = re.search(
            r"Annual\s+filing\s+documents([\s\S]{0,5000}?)(?:Registration\s+documents|Other\s+Filed\s+Documents|$)",
            readable_body,
            re.I,
        )
        annual_section = annual_match.group(1) if annual_match else readable_body
        hi_patterns = [
            r"Fiscal\s+year\s+end\s*:?\s*(\d{1,2}[/-]\d{1,2}[/-]\d{2,4})",
            r"Fiscal\s+year\s+end\s*:?\s*([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})",
            r"Accounting\s+Period\s+End\s+Date\s*:?\s*(\d{1,2}[/-]\d{1,2}[/-]\d{2,4})",
            r"Accounting\s+Period\s+End\s+Date\s*:?\s*([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})",
        ]
        for pattern in hi_patterns:
            matches = [parse_due_date(match.group(1)) for match in re.finditer(pattern, annual_section, re.I)]
            parsed_dates = [value for value in matches if value]
            if parsed_dates:
                latest_period_end = max(parsed_dates)
                return latest_period_end.month, latest_period_end.day
        if re.search(r"Fiscal\s+year\s+end", annual_section, re.I):
            parsed_dates = [
                value
                for value in (parse_due_date(match.group(0)) for match in re.finditer(r"\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b", annual_section))
                if value
            ]
            if parsed_dates:
                latest_period_end = max(parsed_dates)
                return latest_period_end.month, latest_period_end.day
        return None
    patterns = [
        r"(?:Accounting\s+Period\s+End\s+Date|Fiscal\s+Year\s+End|FYE|Fiscal\s+Period\s+End|Period\s+End(?:ing)?)[\s\S]{0,140}?([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})",
        r"(?:Accounting\s+Period\s+End\s+Date|Fiscal\s+Year\s+End|FYE|Fiscal\s+Period\s+End|Period\s+End(?:ing)?)[\s\S]{0,140}?(\d{1,2}[/-]\d{1,2}[/-]\d{2,4})",
        r"(?:Accounting\s+Period\s+End\s+Date|Fiscal\s+Year\s+End|FYE|Fiscal\s+Period\s+End|Period\s+End(?:ing)?)\s*:?\s*([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})",
        r"(?:Accounting\s+Period\s+End\s+Date|Fiscal\s+Year\s+End|FYE|Fiscal\s+Period\s+End|Period\s+End(?:ing)?)\s*:?\s*(\d{1,2}[/-]\d{1,2}[/-]\d{2,4})",
    ]
    for pattern in patterns:
        for match in re.finditer(pattern, readable_body, re.I):
            parsed = parse_due_date(match.group(1))
            if parsed:
                return parsed.month, parsed.day
    return None


def combined_result_text(result, body: str) -> str:
    return " ".join([
        result.status or "",
        result.raw_status_text or "",
        result.source_note or "",
        result.error or "",
        body or "",
    ])


def indicates_exempt_registration(text: str) -> bool:
    return any(
        re.search(pattern, text or "", re.I)
        for pattern in [
            r"\b(?:registry\s+status|status|public\s+status|registration\s+status)\b[\s\S]{0,160}\bexempt\b",
            r"\bregistration\s+type\b[\s\S]{0,120}\bexempt\b",
            r"\bregistration\s+filing\s+status\b[\s\S]{0,160}\bexempt\b",
            r"\bexempt\s+registration\b",
            r"\bexempt\s+from\s+(charitable\s+|annual\s+)?registration\b",
            r"\bexempt\s*-\s*[A-Za-z0-9 /-]+",
            r"^\s*exempt\b",
        ]
    )


def hi_indicates_exempt_registration(text: str) -> bool:
    readable = html.unescape(re.sub(r"<[^>]+>", " ", text or ""))
    readable = re.sub(r"\s+", " ", readable)
    return any(
        re.search(pattern, readable, re.I)
        for pattern in [
            r"\bRegistration\s+Type\b[\s\S]{0,80}\bExempt\b",
            r"\bExempt\s+Registration\b",
        ]
    )


def result_explicitly_exempt(result) -> bool:
    """Only trust exemption when it comes from the matched result fields."""
    status_text = " ".join([
        result.status or "",
        result.raw_status_text or "",
        result.source_note or "",
    ])
    return bool(re.search(
        r"\b(exempt|exempt\s+registration|exempt\s+from\s+(?:charitable\s+|annual\s+)?registration)\b",
        status_text,
        re.I,
    ))


def result_fields_indicate_exempt(result) -> bool:
    """Use this for states where the page body has generic exemption language."""
    status_text = " ".join([
        result.status or "",
        result.raw_status_text or "",
        result.source_note or "",
    ])
    return bool(re.search(r"\bexempt\b", status_text, re.I))


def md_detail_page_matched(result, text: str) -> bool:
    readable = html.unescape(re.sub(r"<[^>]+>", " ", text or ""))
    readable = re.sub(r"\s+", " ", readable)
    ein_digits = re.sub(r"\D", "", result.ein or "")
    readable_digits = re.sub(r"\D", "", readable)
    source_note = result.source_note or ""
    if re.search(r"EIN-confirmed public registry search", source_note, re.I):
        return bool(re.search(r"SOS\s+Charity\s+Organization\s+Record|Charity\s+Name|Registration\s+Status", readable, re.I))
    if re.search(r"exact-name public registry search", source_note, re.I):
        normalize = getattr(checker, "normalize_name", lambda value: re.sub(r"\s+", " ", (value or "").lower()).strip())
        raw_name = re.sub(r"\s+", " ", result.organization_name or "").strip()
        name_variants = [
            raw_name,
            re.sub(r",\s*the\s*$", "", raw_name, flags=re.I).strip(),
            re.sub(r"^the\s+", "", raw_name, flags=re.I).strip(),
            re.sub(r"\bincorporated\b", "inc", raw_name, flags=re.I).strip(),
        ]
        names = [normalize(value) for value in name_variants if normalize(value)]
        readable_name = normalize(readable)
        return bool(
            re.search(r"SOS\s+Charity\s+Organization\s+Record|Charity\s+Name|Registration\s+Status", readable, re.I)
            and any(name and name in readable_name for name in names)
        )
    if ein_digits and ein_digits not in readable_digits:
        return False
    exposes_ein = bool(
        re.search(r"\b(?:EIN|FEIN|Federal\s+Tax|Tax\s+ID|Employer\s+Identification)\b", readable, re.I)
        or re.search(r"\b\d{2}[-\s]?\d{7}\b|\b\d{9}\b", readable)
    )
    if exposes_ein and ein_digits and ein_digits not in readable_digits:
        return False
    if re.search(r"\b[1-9]\d*\s+records?\b", readable, re.I) and not re.search(r"No\s+results\s+found|0\s+records?", readable, re.I):
        return True
    if not re.search(r"SOS\s+Charity\s+Organization\s+Record|Charity\s+Name|Registration\s+Status", readable, re.I):
        return False
    if re.search(r"SoS\s+Charities\s+-\s+Public\s+Registry[\s\S]{0,600}No\s+results\s+found", readable, re.I):
        return False
    if re.search(r"SOS\s+Charity\s+Organization\s+Record\s+for", readable, re.I):
        return True
    normalize = getattr(checker, "normalize_name", lambda value: re.sub(r"\s+", " ", (value or "").lower()).strip())
    name = normalize(result.organization_name)
    return bool(
        (ein_digits and ein_digits in re.sub(r"\D", "", readable))
        or (name and name in normalize(readable))
    )


def status_from_calendar_date(value: date) -> str:
    today = date.today()
    upcoming_cutoff = today + timedelta(days=183)
    if value < today:
        return "Delinquent"
    if value <= upcoming_cutoff:
        return "Upcoming Filing"
    return "Current"


def repair_ny_not_registered_with_due_date(org, result):
    """Promote a NY row when the registry text includes a safe match and due date."""
    if public_status(result) != "Not Registered":
        return result
    registry_name = clean_registry_name(getattr(result, "matched_registry_name", "") or "")
    registry_identity_name = re.split(
        r"\b(?:Registration\s+type|Registration\s+category|Federal\s+tax\s+ID|County)\b",
        registry_name,
        maxsplit=1,
        flags=re.I,
    )[0].strip()
    identifier = getattr(result, "matched_registry_identifier", "") or ""
    evidence_text = " ".join(part for part in [
        registry_name,
        identifier,
        getattr(result, "raw_status_text", "") or "",
        getattr(result, "source_note", "") or "",
    ] if part)
    requested_ein = re.sub(r"\D", "", getattr(org, "ein", "") or "")
    evidence_digits = re.sub(r"\D", "", evidence_text)
    safe_identity = bool(
        registry_name
        and (
            registry_name_is_safe_for_org(registry_name, org.organization_name, org.ein)
            or (registry_identity_name and registry_name_is_safe_for_org(registry_identity_name, org.organization_name, org.ein))
            or (requested_ein and requested_ein in evidence_digits)
        )
    )
    if not safe_identity:
        return result
    if re.search(r"\bNo\s+filings?\s+found\b", evidence_text, re.I):
        result.status = checker.STATUS_DELINQUENT
        result.source_note = " ".join(part for part in [
            getattr(result, "source_note", "") or "",
            "New York returned a safe matching organization row but no annual filings were exposed; CharityClarity treats the non-exempt matched record as Delinquent.",
        ]).strip()
        result.success = True
        return result
    due_match = re.search(r"\bDue\s*:?\s*(\d{4}-\d{2}-\d{2}|\d{1,2}[/-]\d{1,2}[/-]\d{2,4}|[A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})", evidence_text, re.I)
    if not due_match:
        return result
    due_date = parse_due_date(due_match.group(1))
    if not due_date:
        return result
    result.status = status_from_calendar_date(due_date)
    result.source_note = " ".join(part for part in [
        getattr(result, "source_note", "") or "",
        "New York returned a safe matching organization row with an annual-report due date; CharityClarity classified the status from that due date.",
    ]).strip()
    result.success = True
    return result


def labeled_due_dates_from_text(text: str) -> list[date]:
    dates = []
    due_patterns = [
        r"(?:due date|report due|renewal due|filing due|annual report due|registration expires|registration expiration|expiration date|expires on|expired on|expires|expired)\s*:?\s*([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})",
        r"(?:due date|report due|renewal due|filing due|annual report due|registration expires|registration expiration|expiration date|expires on|expired on|expires|expired)\s*:?\s*(\d{1,2}[/-]\d{1,2}[/-]\d{4})",
    ]
    for pattern in due_patterns:
        for match in re.finditer(pattern, text or "", re.I):
            parsed = parse_due_date(match.group(1))
            if parsed:
                dates.append(parsed)
    return dates


def ak_next_filing_due_from_result(result) -> date | None:
    text = " ".join([
        getattr(result, "raw_status_text", "") or "",
        getattr(result, "source_note", "") or "",
    ])
    match = re.search(
        r"\b(?:next\s+filing\s+due|annual\s+filing\s+deadline)\s*:?\s*"
        r"(September\s+1,\s+20\d{2}|9/1/20\d{2}|09/01/20\d{2})",
        text,
        re.I,
    )
    if not match:
        return None
    return parse_due_date(match.group(1))


def explicit_registry_date(result, body: str) -> date | None:
    text = combined_result_text(result, body)
    focused = " ".join([result.raw_status_text or "", result.source_note or ""])
    raw_date = parse_due_date(result.raw_status_text or "")
    if raw_date and re.fullmatch(r"\s*(?:\d{1,2}[/-]\d{1,2}[/-]\d{2,4}|\d{1,2}-[A-Za-z]{3}-\d{2,4})\s*", result.raw_status_text or ""):
        return raw_date
    patterns = [
        rf"(?:expires|expired|expired on|expiration date|registration expires|registration expiration|current registration expires|automatic extension)\s*:?\s*([A-Za-z]{{3,9}}\s+\d{{1,2}},\s+\d{{4}})",
        rf"(?:expires|expired|expired on|expiration date|registration expires|registration expiration|current registration expires|automatic extension)\s*:?\s*(\d{{1,2}}[/-]\d{{1,2}}[/-]\d{{2,4}})",
        rf"(?:expires|expired|expired on|expiration date|registration expires|registration expiration|current registration expires|automatic extension)\s*:?\s*(\d{{1,2}}-[A-Za-z]{{3}}-\d{{2,4}})",
        r"^\s*(\d{1,2}[/-]\d{1,2}[/-]\d{4})\s*$",
    ]
    for source in [focused, text]:
        for pattern in patterns:
            for match in re.finditer(pattern, source or "", re.I):
                parsed = parse_due_date(match.group(1))
                if parsed:
                    return parsed
    return None


def nh_effective_report_due_date(result, body: str) -> tuple[date | None, date | None]:
    """Return NH base/effective report due dates for Good Standing snapshot rows."""
    if (getattr(result, "state", "") or "").upper() != "NH":
        return None, None
    text = combined_result_text(result, body)
    raw = " ".join([result.raw_status_text or "", result.source_note or ""])
    report_due_match = re.search(r"\bReport\s+Due\s*:\s*(\d{1,2}[/-]\d{1,2}[/-]\d{4})", text, re.I)
    good_standing = bool(re.search(r"^\s*G\s*\|", raw, re.I)) or (
        bool(re.search(r"\bGood\s+Standing\b", raw, re.I))
        and not bool(re.search(r"\bNot\s+in\s+Good\s+Standing\b", raw, re.I))
    )
    if not report_due_match or not good_standing:
        return None, None
    base_due = parse_due_date(report_due_match.group(1))
    if not base_due:
        return None, None
    today = date.today()
    effective_due = base_due
    if re.search(r"\bextension\b", raw, re.I) and base_due < today and (today - base_due).days <= 210:
        effective_due = add_months(base_due, 6)
    return base_due, effective_due


NO_ORGANIZATION_RECORD_PATTERN = (
    r"no matching|no match|no record found|no records found|no records|not found|"
    r"no results found|0 records|0 results|showing 0 to 0 of 0 entries|"
    r"no data available in table|not registered in our system"
)


def result_indicates_no_record(result) -> bool:
    return public_status(result) == "Not Registered" or bool(re.search(NO_ORGANIZATION_RECORD_PATTERN, " ".join([
        result.status or "",
        result.raw_status_text or "",
        result.source_note or "",
    ]), re.I))


def body_indicates_no_organization_record(body: str) -> bool:
    readable = html.unescape(re.sub(r"<[^>]+>", " ", body or ""))
    readable = re.sub(r"\s+", " ", readable)
    return bool(re.search(NO_ORGANIZATION_RECORD_PATTERN, readable, re.I))


def organization_record_confirmed(result, body: str) -> bool:
    if result_indicates_no_record(result):
        return False
    readable = html.unescape(re.sub(r"<[^>]+>", " ", body or ""))
    readable = re.sub(r"\s+", " ", readable)
    if not readable:
        return False
    ein_digits = re.sub(r"\D", "", result.ein or "")
    body_digits = re.sub(r"\D", "", readable)
    normalize = getattr(checker, "normalize_name", lambda value: re.sub(r"\s+", " ", (value or "").lower()).strip())
    name = normalize(result.organization_name)
    identity_seen = bool((ein_digits and ein_digits in body_digits) or (name and name in normalize(readable)))
    record_marker_seen = bool(re.search(
        r"AG\s+Account\s+Number|Tax\s+ID|Charity\s+Details|Charity\s+Name|Charity\s+EIN|"
        r"Registration\s+(?:Status|Number|Type)|Organization\s+ID|Organization\s+name|"
        r"Entity\s+Name|Certificate\s+#|Annual\s+Filing",
        readable,
        re.I,
    ))
    return identity_seen and record_marker_seen


def annual_filings_absent(text: str) -> bool:
    readable = html.unescape(re.sub(r"<[^>]+>", " ", text or ""))
    readable = re.sub(r"\s+", " ", readable)
    filing_evidence_patterns = [
        r"Annual\s+filings?(?:\s+and\s+documents)?[\s\S]{0,4000}\bForm[\s-]*PC\b[\s\S]{0,4000}\b20\d{2}\b",
        r"Annual\s+filings?(?:\s+and\s+documents)?[\s\S]{0,4000}\b20\d{2}\b[\s\S]{0,4000}\bForm[\s-]*PC\b",
        r"Annual\s+filing\s+documents[\s\S]{0,4000}\bFiscal\s+Year\s+End\b[\s\S]{0,4000}\b20\d{2}\b",
        r"Annual\s+renewal\s+data[\s\S]{0,4000}\bStatus\s+of\s+Filing\b[\s\S]{0,4000}\b20\d{2}\b",
        r"Year\s+Represented\s*:?\s*20\d{2}",
        r"Latest\s+FYE\s*:?\s*20\d{2}",
    ]
    if any(re.search(pattern, readable, re.I) for pattern in filing_evidence_patterns):
        return False
    annual_section_patterns = [
        r"Annual\s+filing\s+documents[\s\S]{0,500}?No\s+rows\s+available",
        r"Annual\s+filing\s+documents[\s\S]{0,500}?No\s+documents\s+found",
        r"Annual\s+filing\s+documents[\s\S]{0,500}?No\s+filings?\s+found",
        r"Annual\s+filing\s+documents[\s\S]{0,500}?No\s+results\s+found",
        r"Annual\s+filings?(?:\s+and\s+documents)?[\s\S]{0,500}?No\s+rows\s+available",
        r"Annual\s+filings?(?:\s+and\s+documents)?[\s\S]{0,500}?No\s+documents\s+found",
        r"Annual\s+filings?(?:\s+and\s+documents)?[\s\S]{0,500}?No\s+filings?\s+found",
        r"Annual\s+filings?(?:\s+and\s+documents)?[\s\S]{0,500}?No\s+results\s+found",
        r"Annual\s+Filing\s+Documents\s+did\s+not\s+expose\s+any\s+Fiscal\s+Year\s+End\s+values",
        r"\bNo\s+filings?\s+found\b",
        r"Annual\s+renewal\s+data[\s\S]{0,500}?No\s+rows\s+available",
        r"Annual\s+renewal\s+data[\s\S]{0,500}?No\s+documents\s+found",
        r"Annual\s+renewal\s+data[\s\S]{0,500}?No\s+results\s+found",
    ]
    return any(re.search(pattern, readable, re.I) for pattern in annual_section_patterns)


def source_note_for_result(result) -> str:
    state = (result.state or "").upper()
    if state == "MA":
        return (
            "Massachusetts public portal exposes Annual Filings only. Fiscal year end is not always visible in the portal, "
            "so the filing year should be interpreted against the organization's confirmed fiscal year end and any applicable extension window."
        )
    return result.source_note or ""


def ein_near_registry_pattern(text: str, ein: str, pattern: str, radius: int = 320) -> bool:
    compact = re.sub(r"\s+", " ", text or "")
    ein_digits = re.sub(r"\D", "", ein or "")
    if not ein_digits:
        return False
    for match in re.finditer(pattern, compact, re.I):
        window = compact[max(0, match.start() - radius):match.end() + radius]
        if ein_digits in re.sub(r"\D", "", window):
            return True
    return False


def ein_line_has_registry_pattern(text: str, ein: str, pattern: str) -> bool:
    ein_digits = re.sub(r"\D", "", ein or "")
    if not ein_digits:
        return False
    for line in re.split(r"[\r\n]+", text or ""):
        if ein_digits in re.sub(r"\D", "", line) and re.search(pattern, line, re.I):
            return True
    return False


def explicit_adverse_registry_status(result, body: str) -> str:
    """Return registry-adverse statuses that should trump filing-year math."""
    state = (result.state or "").upper()
    text = combined_result_text(result, body)
    raw_fields = " ".join([
        result.raw_status_text or "",
        result.source_note or "",
    ])
    fields = raw_fields
    primary_status_fields = " ".join([
        result.status or "",
        result.raw_status_text or "",
    ])
    if (
        state == "NJ"
        and re.search(r"\b(active|current|compliant|good\s+standing)\b", primary_status_fields, re.I)
        and not re.search(
            r"\b(non\W*compliant|not\s+current|revoked|suspended|not\s+authorized\s+to\s+solicit|may\s+not\s+(?:solicit|raise\s+funds|operate)|cease\s+and\s+desist|pending|failed\s+to\s+renew|withdrawn|retired|terminated|cancelled|canceled|voluntar(?:y|ily)\s+deactivat(?:ed|ion)|closed|inactive)\b",
            primary_status_fields,
            re.I,
        )
    ):
        return ""
    if (
        state != "NJ"
        and
        re.search(r"\b(active|current|compliant|good\s+standing)\b", primary_status_fields, re.I)
        and not re.search(
            r"\b(not\s+current|revoked|suspended|not\s+authorized\s+to\s+solicit|may\s+not\s+(?:solicit|raise\s+funds|operate)|cease\s+and\s+desist|pending|failed\s+to\s+renew|withdrawn|retired|terminated|cancelled|canceled|voluntar(?:y|ily)\s+deactivat(?:ed|ion)|closed|inactive)\b",
            primary_status_fields,
            re.I,
        )
    ):
        return ""
    labeled_status_text = " ".join(
        match.group(0)
        for match in re.finditer(
            r"\b(?:registry\s+status|registration\s+status|registration\s+filing\s+status|status)\b[\s\S]{0,160}",
            text,
            re.I,
        )
    )
    status_evidence = " ".join([raw_fields, labeled_status_text])
    if result_explicitly_exempt(result):
        return ""
    withdrawn_pattern = r"\b(withdrawn|retired|terminated|cancelled|canceled|voluntar(?:y|ily)\s+(?:deactivat(?:ed|ion)|surrender(?:ed)?))\b"
    closed_pattern = r"\bclosed\b"
    inactive_pattern = r"\binactive\b"
    terminal_pattern = rf"(?:{withdrawn_pattern}|{closed_pattern}|{inactive_pattern})"
    pending_pattern = r"\bpending\b"
    failed_to_renew_pattern = r"\bfailed\s+to\s+renew\b"
    if re.search(inactive_pattern, primary_status_fields, re.I):
        return "Closed / Withdrawn / Canceled"
    if state == "NJ":
        def nj_status_confirmed(pattern: str) -> bool:
            return bool(re.search(pattern, raw_fields, re.I) or ein_line_has_registry_pattern(text, result.ein, pattern))

        if nj_status_confirmed(r"\bnon\W*compliant\b"):
            return "Delinquent"
        if nj_status_confirmed(r"\brevoked\b"):
            return "Revoked"
        if nj_status_confirmed(pending_pattern):
            return "Pending"
        if nj_status_confirmed(r"\b(suspended|not\s+authorized\s+to\s+solicit|may\s+not\s+(?:solicit|raise\s+funds|operate)|cease\s+and\s+desist)\b"):
            return "Suspended"
        if nj_status_confirmed(inactive_pattern):
            return "Closed / Withdrawn / Canceled"
        if nj_status_confirmed(failed_to_renew_pattern):
            return "Failed to Renew"
        if nj_status_confirmed(withdrawn_pattern) or nj_status_confirmed(closed_pattern):
            return "Closed / Withdrawn / Canceled"
    confirmed = organization_record_confirmed(result, text) or md_detail_page_matched(result, text)
    expired_pattern = r"\bexpired\b"
    if not confirmed and not re.search(r"\b(not\s+current|revoked|suspended|not\s+authorized\s+to\s+solicit|may\s+not\s+(?:solicit|raise\s+funds|operate)|cease\s+and\s+desist|pending)\b|" + terminal_pattern + "|" + failed_to_renew_pattern + "|" + expired_pattern, status_evidence, re.I):
        return ""
    if state == "NJ":
        def nj_status_confirmed(pattern: str) -> bool:
            return bool(re.search(pattern, raw_fields, re.I) or ein_line_has_registry_pattern(text, result.ein, pattern))

        if nj_status_confirmed(r"\bnon\W*compliant\b"):
            return "Delinquent"
        if nj_status_confirmed(r"\brevoked\b"):
            return "Revoked"
        if nj_status_confirmed(pending_pattern):
            return "Pending"
        if nj_status_confirmed(r"\b(suspended|not\s+authorized\s+to\s+solicit|may\s+not\s+(?:solicit|raise\s+funds|operate)|cease\s+and\s+desist)\b"):
            return "Suspended"
        if nj_status_confirmed(inactive_pattern):
            return "Closed / Withdrawn / Canceled"
        if nj_status_confirmed(failed_to_renew_pattern):
            return "Failed to Renew"
        if nj_status_confirmed(withdrawn_pattern):
            return "Closed / Withdrawn / Canceled"
        if nj_status_confirmed(closed_pattern):
            return "Closed / Withdrawn / Canceled"
        return ""
    if re.search(r"\brevoked\b", status_evidence, re.I):
        return "Revoked"
    if re.search(pending_pattern, status_evidence, re.I):
        return "Pending"
    if re.search(r"\b(suspended|not\s+authorized\s+to\s+solicit|may\s+not\s+(?:solicit|raise\s+funds|operate)|cease\s+and\s+desist)\b", status_evidence, re.I):
        return "Suspended"
    if re.search(inactive_pattern, status_evidence, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(withdrawn_pattern, status_evidence, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(closed_pattern, status_evidence, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(failed_to_renew_pattern, status_evidence, re.I):
        return "Failed to Renew"
    if re.search(r"\bnot\s+current\b", status_evidence, re.I) or re.search(expired_pattern, status_evidence, re.I):
        return "Delinquent"
    return ""


def explicit_no_registration_status(result, body: str) -> bool:
    """Return true when the matched registry response clearly says no registration exists."""
    text = combined_result_text(result, body)
    fields = " ".join([
        result.status or "",
        result.raw_status_text or "",
        result.source_note or "",
    ])
    no_registration_pattern = (
        r"\b(not\s+registered|not\s+found|no\s+(?:matching\s+)?(?:registration\s+)?record|"
        r"no\s+(?:matching\s+)?results?|0\s+records?|0\s+results?)\b"
    )
    if re.search(no_registration_pattern, fields, re.I):
        return True
    return bool(re.search(
        r"\b(?:registry\s+status|registration\s+status|registration\s+filing\s+status|status)\b"
        r"[\s\S]{0,140}"
        r"\b(not\s+registered|not\s+found|no\s+(?:matching\s+)?(?:registration\s+)?record)\b",
        text,
        re.I,
    ))


def true_status_from_body(result, body: str) -> str:
    base_status = public_status(result)
    normalized = base_status.lower()
    state = (result.state or "").upper()
    combined = combined_result_text(result, body)
    combined_lower = combined.lower()

    if "site not reachable" in normalized:
        return base_status
    confirmed_status = getattr(result, "_cc_confirmed_feedback_status", "")
    if confirmed_status:
        return confirmed_status
    if state == "MI":
        solicitation_status = classify_mi_solicitation_status(mi_solicitation_raw_from_combined(result.raw_status_text or ""))
        if solicitation_status:
            return solicitation_status
    if (
        state == "MD"
        and re.fullmatch(r"\s*pending\s*", result.raw_status_text or "", re.I)
        and not re.search(r"\b(current|active|expired|delinquent|closed|withdrawn|cancel(?:ed|led)|inactive)\b", result.status or "", re.I)
    ):
        return "Pending"
    if state == "MI" and re.search(r"Solicitation\s+Registration\s+Status\s*:\s*Registered", result.raw_status_text or "", re.I):
        registry_date = explicit_registry_date(result, result.raw_status_text or "")
        return status_from_calendar_date(registry_date) if registry_date else base_status
    if result_explicitly_exempt(result):
        return "Exempt"
    if (
        state == "NY"
        and annual_filings_absent(combined)
        and (
            normalized_ein_key(result.ein) in re.sub(r"\D", "", combined)
            or registry_name_is_safe_for_org(result.matched_registry_name or "", result.organization_name, result.ein)
        )
        and not body_indicates_no_organization_record(combined)
    ):
        return "Delinquent"
    if state == "NY" and normalized == "not registered":
        repaired_result = repair_ny_not_registered_with_due_date(result, combined)
        repaired_status = public_status(repaired_result)
        if repaired_status != "Not Registered":
            return repaired_status
    if explicit_no_registration_status(result, combined):
        return "Not Registered"
    if state == "MS":
        ms_status_text = " ".join([result.status or "", result.raw_status_text or "", result.source_note or ""])
        if re.search(r"\b(closed|withdrawn|cancel(?:ed|led)|revoked|terminated|inactive)\b", ms_status_text, re.I):
            return "Closed / Withdrawn / Canceled"
        ms_registry_date = explicit_registry_date(result, combined)
        if ms_registry_date and not result_indicates_no_record(result):
            return status_from_calendar_date(ms_registry_date)
    if state == "AR":
        ar_status = explicit_ar_registry_status(result)
        if ar_status:
            return ar_status
    if state == "OK" and re.search(r"Oklahoma annual registration is tied to the Form 990 filing deadline", result.source_note or "", re.I):
        return base_status
    if state == "NH":
        _, effective_report_due = nh_effective_report_due_date(result, body)
        if effective_report_due:
            return status_from_calendar_date(effective_report_due)
    if state == "AK":
        ak_next_due = ak_next_filing_due_from_result(result)
        if ak_next_due:
            return status_from_calendar_date(ak_next_due)
    if state == "SC" and re.search(r"^\s*Registered\b", " ".join([result.status or "", result.raw_status_text or ""]), re.I):
        registry_date = explicit_registry_date(result, combined)
        return status_from_calendar_date(registry_date) if registry_date else "Current"
    if state == "CT":
        ct_status_fields = " ".join([
            result.raw_status_text or "",
            result.error or "",
        ])
        if re.search(r"\b(closed|withdrawn|cancel(?:ed|led))\b", ct_status_fields, re.I):
            return "Closed / Withdrawn / Canceled"
        if re.search(r"\binactive\b", ct_status_fields, re.I):
            return "Closed / Withdrawn / Canceled"
        ct_registry_date = explicit_registry_date(result, combined)
        if ct_registry_date and re.search(r"\bPUBLIC\s+CHARITY\b", result.raw_status_text or "", re.I):
            return status_from_calendar_date(ct_registry_date)
        if re.search(r"\bStatus:\s*ACTIVE\b", ct_status_fields, re.I) and re.search(r"\bStatus Reason:\s*ACTIVE\b", ct_status_fields, re.I):
            return "Current"
    if state == "MD":
        md_status_fields = " ".join([
            result.status or "",
            result.raw_status_text or "",
            result.source_note or "",
        ])
        if re.search(r"\b(closed|inactive|withdrawn|cancel(?:ed|led)|terminated)\b", md_status_fields, re.I):
            return "Closed / Withdrawn / Canceled"
    early_context = filing_context(result, body) if state == "MD" else None
    if state == "MD" and md_detail_page_matched(result, combined) and early_context:
        early_due_date = early_context["due_date"]
        early_represented_year = early_context["represented_year"]
        early_registry_date = explicit_registry_date(result, combined)
        early_filed_cycle_status = status_for_filed_cycle(state, early_context, early_registry_date)
        if early_filed_cycle_status:
            return early_filed_cycle_status
        if stale_represented_year_is_delinquent(early_represented_year):
            return "Delinquent"
        if early_due_date and early_represented_year:
            return status_from_calendar_date(early_due_date)
        if re.search(r"Registration\s+Status\s+Current|Registration\s+Status[^A-Za-z0-9]{0,40}Current", combined, re.I):
            inferred_due = next_base_due_from_fiscal_end(state, early_context.get("fiscal_end"))
            if inferred_due:
                return status_from_calendar_date(inferred_due)
    adverse_status = explicit_adverse_registry_status(result, combined)
    if adverse_status:
        return adverse_status
    primary_registry_fields = " ".join([result.raw_status_text or "", result.source_note or ""])
    if re.search(r"\b(non\W*compliant|delinquent)\b", primary_registry_fields, re.I):
        return "Delinquent"
    if (
        state == "NY"
        and annual_filings_absent(combined)
        and re.search(r"Annual\s+Filing\s+Documents\s+did\s+not\s+expose\s+any\s+Fiscal\s+Year\s+End\s+values", combined, re.I)
        and not result_indicates_no_record(result)
    ):
        return "Delinquent"
    if normalized == "delinquent" and annual_filings_absent(combined) and not result_indicates_no_record(result):
        return "Delinquent"
    if state == "ME" and re.search(r"\bACTIVE\b", " ".join([result.status or "", result.raw_status_text or ""]), re.I) and not explicit_registry_date(result, combined):
        return "Current"
    if normalized == "suspended":
        return "Suspended"
    if normalized == "revoked":
        return "Revoked"
    if normalized == "pending":
        return "Pending"
    if normalized == "failed to renew":
        return "Failed to Renew"
    if normalized in {"withdrawn", "closed", "closed / withdrawn / canceled"}:
        return "Closed / Withdrawn / Canceled"
    context = filing_context(result, body)
    due_date = context["due_date"]
    represented_year = context["represented_year"]
    registry_date = explicit_registry_date(result, body)
    use_registry_date = bool(
        registry_date
        and (
            state in {"AK", "CO", "PA", "VA"}
            or re.search(r"due date|next report|renewal|expiration|expires|automatic extension", " ".join([result.raw_status_text or "", result.source_note or ""]), re.I)
        )
    )

    if state == "MD" and md_detail_page_matched(result, combined):
        filed_cycle_status = status_for_filed_cycle(state, context, registry_date)
        if filed_cycle_status:
            return filed_cycle_status
        if stale_represented_year_is_delinquent(represented_year):
            return "Delinquent"
        if due_date and represented_year:
            return status_from_calendar_date(due_date)
        if re.search(r"Registration\s+Status\s+Current|Registration\s+Status[^A-Za-z0-9]{0,40}Current", combined, re.I):
            inferred_due = next_base_due_from_fiscal_end(state, context.get("fiscal_end"))
            if inferred_due:
                return status_from_calendar_date(inferred_due)
            return "Current"

    record_confirmed = organization_record_confirmed(result, combined) or (state == "MD" and md_detail_page_matched(result, combined))
    if (
        state == "NY"
        and annual_filings_absent(combined)
        and (
            normalized_ein_key(result.ein) in re.sub(r"\D", "", combined)
            or registry_name_is_safe_for_org(result.matched_registry_name or "", result.organization_name, result.ein)
        )
        and not body_indicates_no_organization_record(combined)
    ):
        return "Delinquent"

    if result_indicates_no_record(result):
        return "Not Registered"
    if state == "MS" and record_confirmed:
        ms_status_text = " ".join([result.status or "", result.raw_status_text or "", result.source_note or ""])
        ms_registry_date = explicit_registry_date(result, body)
        if re.search(r"\b(closed|withdrawn|cancel(?:ed|led)|revoked|terminated)\b", ms_status_text, re.I):
            return "Closed / Withdrawn / Canceled"
        if re.search(r"\b(expired|suspended)\b", ms_status_text, re.I):
            return "Delinquent"
        if re.search(r"\bcurrent\s*-\s*registered\b|\bcurrent\b|\bregistered\b", result.raw_status_text or "", re.I):
            return status_from_calendar_date(ms_registry_date) if ms_registry_date else "Current"
    if state == "CT" and record_confirmed and registry_date and re.search(r"\bPUBLIC\s+CHARITY\b", result.raw_status_text or "", re.I):
        return status_from_calendar_date(registry_date)
    if state == "HI" and record_confirmed and (result_fields_indicate_exempt(result) or hi_indicates_exempt_registration(combined)):
        return "Exempt"
    if state not in {"HI", "NJ", "NY"} and record_confirmed and indicates_exempt_registration(combined):
        return "Exempt"
    if state == "NY" and record_confirmed and result_fields_indicate_exempt(result):
        return "Exempt"
    if state == "PA" and use_registry_date:
        return status_from_calendar_date(registry_date)
    if state == "PA" and record_confirmed and not use_registry_date:
        return "Delinquent"
    if state == "AK" and registry_date:
        return status_from_calendar_date(registry_date)
    if state == "AK" and represented_year and due_date:
        return status_from_calendar_date(due_date)
    if state == "CA":
        ca_years = ca_annual_renewal_years_from_text(body)
        latest_pending_year = ca_years.get("latest_pending_year")
        latest_not_submitted_year = ca_years.get("latest_not_submitted_year")
        latest_submitted_year = ca_years.get("latest_submitted_year")
        if latest_pending_year and (not latest_submitted_year or latest_pending_year > latest_submitted_year):
            return "Pending"
        if latest_not_submitted_year and (not latest_submitted_year or latest_not_submitted_year > latest_submitted_year):
            return "Delinquent"
    if state in {"MA", "NY"} and represented_year and due_date and not result_indicates_no_record(result):
        return status_from_calendar_date(due_date)
    if state in EXTENSION_SCENARIO_STATES and record_confirmed and represented_year and due_date:
        return status_from_calendar_date(due_date)
    if state == "AK" and re.search(r"\b20\d{2}\s+registration\s+found\b", combined, re.I):
        found_years = [int(match.group(1)) for match in re.finditer(r"\b(20\d{2})\s+registration\s+found\b", combined, re.I)]
        if found_years and current_cycle_already_filed(state, max(found_years), registry_date):
            return status_for_filed_cycle(state, context, registry_date) or "Current"
    if represented_year_is_registry_evidenced(result, body, represented_year) and current_cycle_already_filed(state, represented_year, registry_date):
        if not re.search(r"\b(delinquent|expired|revoked|suspended|closed|inactive|overdue|non[- ]?compliant)\b", combined_lower, re.I):
            return status_for_filed_cycle(state, context, registry_date) or "Current"
    if state == "HI" and record_confirmed and represented_year and represented_year >= date.today().year - 1 and re.search(r"\bActive\b", combined, re.I):
        return status_for_filed_cycle(state, context, registry_date) or "Current"
    if state == "HI" and record_confirmed and not represented_year and re.search(r"\bActive\b", combined, re.I):
        return "Delinquent"
    if state == "MA" and record_confirmed and represented_year and represented_year >= date.today().year - 1 and re.search(r"Annual\s+Filings?\s+not\s+visible", combined, re.I):
        return status_for_filed_cycle(state, context, registry_date) or "Current"
    if use_registry_date:
        return status_from_calendar_date(registry_date)
    labeled_dates = [] if state == "CA" else labeled_due_dates_from_text(combined)
    if labeled_dates:
        return status_from_calendar_date(labeled_dates[0])
    if annual_filings_absent(combined):
        return "Delinquent" if record_confirmed else "Not Registered"
    if body_indicates_no_organization_record(combined) and not record_confirmed:
        return "Not Registered"
    if record_confirmed and stale_represented_year_is_delinquent(represented_year):
        return "Delinquent"

    if state in EXTENSION_SCENARIO_STATES and due_date and represented_year and not result_indicates_no_record(result):
        return status_from_calendar_date(due_date)

    if "not registered" in normalized:
        return base_status
    if state == "PA" and re.search(r"no matching|no record|no result|not found|0 results", combined, re.I):
        return "Not Registered"

    if state == "MD" and re.search(r"Registration\s+Status\s+Current|Registration\s+Status[^A-Za-z0-9]{0,40}Current", combined, re.I):
        if due_date and represented_year:
            return status_from_calendar_date(due_date)
        return "Current"

    if due_date and represented_year:
        return status_from_calendar_date(due_date)

    if state == "NJ" and re.search(r"\b(compliant|current|active)\b", combined, re.I):
        return "Current"

    if "delinquent" in normalized or "non-compliant" in normalized:
        return "Delinquent"

    return "Current" if "current" in normalized else base_status


def md_status_from_body(result, body: str) -> str:
    return true_status_from_body(result, body)


def comments_for_result_base(result, body: str, public_facing_status: str) -> str:
    normalized_status = public_facing_status.lower()
    state = (result.state or "the selected state").upper()
    context = filing_context(result, body)
    if normalized_status == "site not reachable":
        technical_error = " ".join([result.error or "", result.source_note or "", result.raw_status_text or ""])
        if re.search(r"ERR_NAME_NOT_RESOLVED|remote name could not be resolved|getaddrinfo failed|Name or service not known", technical_error, re.I):
            return "Local DNS/network resolution failed while trying to reach the public registry host. This is usually a local network/DNS issue; rerun CharityClarity after the connection stabilizes."
        if re.search(r"timed out|timeout", technical_error, re.I):
            return "The public registry did not respond before the lookup timed out. Rerun CharityClarity to confirm whether this was temporary."
        return "Public registry site could not be reached at the time of the CharityClarity check."
    if normalized_status == "not registered":
        return f"The {state} public registry was reachable, but no matching registration record was found for the organization/EIN searched."
    if normalized_status == "unknown":
        if state == "ME" and re.search(r"\bACTIVE\b", " ".join([result.status or "", result.raw_status_text or ""]), re.I):
            return "The ME public registry returned an active matching organization record, but CharityClarity did not identify an expiration or renewal date needed for the interpreted status."
        if state == "PA" and organization_record_confirmed(result, combined_result_text(result, body)):
            return "The PA public registry returned a matching record, but CharityClarity did not identify a usable expiration date or final interpreted status from the available page."
        return f"The {state} public registry was reachable, but CharityClarity could not confirm a final interpreted status from the available registry page."
    if normalized_status == "exempt":
        return f"The {state} public registry indicates the organization is exempt from charitable registration or annual filing requirements in that state."
    if normalized_status == "revoked":
        return f"The {state} public registry shows the organization registration status as Revoked, which CharityClarity treats as an adverse status."
    if normalized_status == "suspended":
        if state == "VA" and re.search(r"not\s+authorized\s+to\s+solicit", combined_result_text(result, body), re.I):
            return "The VA public registry shows the organization is not authorized to solicit in Virginia, which CharityClarity treats as Suspended."
        return f"The {state} public registry shows the organization registration status as Suspended."
    if normalized_status in {"withdrawn", "closed", "closed / withdrawn / canceled"}:
        if re.search(r"voluntar(?:y|ily)\s+deactivat(?:ed|ion)", combined_result_text(result, body), re.I):
            return (
                f"The {state} public registry shows the organization registration status as Voluntarily Deactivated. "
                "CharityClarity treats that as Closed / Withdrawn / Canceled instead of calculating status from older annual filing records."
            )
        if re.search(r"\bcancell?ed\b", combined_result_text(result, body), re.I):
            return (
                f"The {state} public registry shows the organization registration status as Canceled. "
                "CharityClarity treats that as Closed / Withdrawn / Canceled instead of calculating status from older annual filing records."
            )
        return (
            f"The {state} public registry shows the organization registration status as Closed, Withdrawn, Canceled, or inactive. "
            "CharityClarity uses that registry status instead of calculating status from older annual filing records."
        )
    if state == "CA" and normalized_status == "current" and not context.get("due_date"):
        return "The CA public registry shows Registry Status Current. CharityClarity did not identify a delinquency in this quick check."
    if state == "CA" and normalized_status == "pending":
        ca_years = ca_annual_renewal_years_from_text(body)
        latest_pending_year = ca_years.get("latest_pending_year")
        latest_pending_status = ca_years.get("latest_pending_status") or "In Process"
        latest_submitted_year = ca_years.get("latest_submitted_year")
        submitted_sentence = (
            f" The latest accepted annual renewal year identified is {latest_submitted_year}."
            if latest_submitted_year else
            " CharityClarity did not identify a later accepted annual renewal year."
        )
        if latest_pending_year:
            return (
                f"The CA Annual Renewal Data shows the {latest_pending_year} annual renewal with Status of Filing: {latest_pending_status}. "
                f"CharityClarity treats that as Pending because the public registry indicates the filing is still being processed.{submitted_sentence}"
            )
        return (
            "The CA public registry shows an In Process or Pending registration/filing status. "
            "CharityClarity treats that registry status as Pending because the filing appears to still be under review."
        )
    if normalized_status == "pending":
        return (
            f"The {state} public registry shows the organization registration status as Pending. "
            "CharityClarity uses that registry status instead of calculating status from annual filing records."
        )
    if normalized_status == "failed to renew":
        return (
            f"The {state} public registry shows the organization registration status as Failed to Renew. "
            "CharityClarity uses that registry status instead of calculating status from annual filing records."
        )
    if state == "KY" and normalized_status in {"current", "upcoming filing", "delinquent"} and useful_registry_name(result.matched_registry_name or ""):
        identifier = f" (ID: {result.matched_registry_identifier})" if result.matched_registry_identifier else ""
        filed_year = context.get("represented_year")
        filed_text = f" The most recent filing year identified in that row is {filed_year}." if filed_year else ""
        return (
            f"The KY downloadable registry snapshot includes a strict name match for {result.matched_registry_name}{identifier}. "
            "The Kentucky source does not expose EIN in the downloaded public list, so CharityClarity accepts only exact or confirmed-safe name matches for KY."
            f"{filed_text}"
        )
    if state == "NH" and normalized_status in {"current", "upcoming filing", "delinquent"}:
        base_due, effective_due = nh_effective_report_due_date(result, body)
        if base_due and effective_due:
            timing = "within 6 months" if normalized_status == "upcoming filing" else ("overdue" if normalized_status == "delinquent" else "not within the next 6 months")
            if effective_due != base_due:
                return (
                    f"The NH public registry shows Good Standing with base report due date {format_date(base_due)}. "
                    f"CharityClarity applies the six-month extension window and uses {format_date(effective_due)}, which is {timing}."
                )
            return f"The NH public registry shows Good Standing with report due date {format_date(base_due)}, which is {timing}."
    if state == "SC" and normalized_status == "current" and re.search(r"^\s*Registered\b", " ".join([result.status or "", result.raw_status_text or ""]), re.I):
        return "The SC public registry shows the organization registration status as Registered. CharityClarity treats that as Current."
    if state == "CT" and normalized_status == "delinquent":
        registry_date = explicit_registry_date(result, body)
        if registry_date:
            return f"The CT public registry shows an expiration date of {format_date(registry_date)}, which is overdue."
    if state == "MD" and normalized_status == "current" and not context.get("represented_year"):
        return (
            "The MD public registry shows Registration Status: Current. CharityClarity did not identify a Maryland filing-year value "
            "from the public snapshot, so this quick check treats the registry status as Current without citing a specific annual filing year."
        )
    if normalized_status == "delinquent" and re.search(r"\b(closed|inactive)\b", " ".join([result.status or "", result.raw_status_text or ""]), re.I):
        return f"The {state} public registry shows a found organization record with a closed or inactive registration status."
    if normalized_status == "delinquent" and state == "VA" and re.search(r"not\s+authorized\s+to\s+solicit", " ".join([result.status or "", result.raw_status_text or "", result.source_note or ""]), re.I):
        return "The VA public registry shows the organization is not authorized to solicit in Virginia, which CharityClarity treats as Delinquent."
    if state == "AK" and normalized_status in {"upcoming filing", "current", "delinquent"}:
        ak_next_due = ak_next_filing_due_from_result(result)
        if ak_next_due:
            timing = "within 6 months" if normalized_status == "upcoming filing" else ("overdue" if normalized_status == "delinquent" else "not within the next 6 months")
            return f"The AK public registry shows the next Alaska charitable registration renewal is due {format_date(ak_next_due)}, which is {timing}."
        registry_date = explicit_registry_date(result, body)
        if registry_date:
            timing = "within 6 months" if normalized_status == "upcoming filing" else ("overdue" if normalized_status == "delinquent" else "not within the next 6 months")
            return f"The AK public registry shows a charitable registration expiration date of {format_date(registry_date)}, which is {timing}."
        if context.get("represented_year") and context.get("due_date"):
            timing = "within 6 months" if normalized_status == "upcoming filing" else ("overdue" if normalized_status == "delinquent" else "not within the next 6 months")
            return (
                f"The AK public registry shows the {context['represented_year']} charitable organization registration/renewal is on file. "
                f"The next Alaska charitable registration renewal is due {format_date(context.get('due_date'))}, which is {timing}."
            )
    registry_noncompliant_text = " ".join([result.raw_status_text or "", result.source_note or "", body or ""])
    if normalized_status == "delinquent" and re.search(r"\bnon\W*compliant\b", registry_noncompliant_text, re.I):
        return f"The {state} public registry shows a Noncompliant status, which CharityClarity treats as Delinquent."
    registry_status_text = " ".join([result.raw_status_text or "", result.source_note or ""])
    if normalized_status == "delinquent" and re.search(r"\bexpired\b", registry_status_text, re.I):
        return f"The {state} public registry shows the organization registration status as Expired, which CharityClarity treats as Delinquent."
    if normalized_status == "delinquent" and state == "PA" and organization_record_confirmed(result, combined_result_text(result, body)) and not explicit_registry_date(result, body):
        return "The PA public registry returned a matching organization record but did not show a current usable expiration date, so CharityClarity treats the record as Delinquent."
    if state == "CO" and normalized_status == "delinquent" and re.search(r"\b(expired|may not solicit)\b", combined_result_text(result, body), re.I):
        registry_date = explicit_registry_date(result, body)
        if registry_date:
            return f"The CO public registry shows an expiration date of {format_date(registry_date)}, which is overdue."
        return "The CO public registry shows an expired registration status, which CharityClarity treats as Delinquent."
    if (
        state == "NY"
        and normalized_status == "delinquent"
        and re.search(r"Annual\s+Filing\s+Documents\s+did\s+not\s+expose\s+any\s+Fiscal\s+Year\s+End\s+values", combined_result_text(result, body), re.I)
    ):
        return (
            "The NY public registry detail page shows the organization record, but the annual filing section shows no annual filings available. "
            "Because the record does not show an exempt registration status, CharityClarity treats the organization as Delinquent."
        )
    if state == "CA" and normalized_status == "delinquent":
        context = filing_context(result, body)
        ca_years = ca_annual_renewal_years_from_text(body)
        latest_not_submitted_year = ca_years.get("latest_not_submitted_year")
        latest_not_submitted_status = ca_years.get("latest_not_submitted_status") or "Not Submitted"
        latest_submitted_year = ca_years.get("latest_submitted_year")
        if latest_not_submitted_year and (not latest_submitted_year or latest_not_submitted_year > latest_submitted_year):
            fiscal_end = context.get("fiscal_end") or fiscal_year_end_for_ein(result.ein)
            due_sentence = ""
            if fiscal_end:
                due_options = filing_due_date_options("CA", latest_not_submitted_year, fiscal_end)
                base_due = due_options.get("base_due") or due_options.get("effective_due")
                extended_due = due_options.get("extended_due")
                if base_due:
                    due_sentence = (
                        f" Based on a {fiscal_end[0]}/{fiscal_end[1]} fiscal year end, the "
                        f"{latest_not_submitted_year} annual renewal initial due date is {format_date(base_due)}."
                    )
                if extended_due:
                    extended_status = status_from_calendar_date(extended_due)
                    due_sentence += (
                        f" If a six-month extension was applied for and approved, the due date becomes "
                        f"{format_date(extended_due)} and the status becomes {extended_status}."
                    )
            submitted_sentence = (
                f" The latest accepted annual renewal year identified is {latest_submitted_year}."
                if latest_submitted_year else
                " CharityClarity did not identify a later accepted annual renewal year."
            )
            return (
                f"The CA Annual Renewal Data shows the {latest_not_submitted_year} annual renewal with Status of Filing: {latest_not_submitted_status}."
                f"{submitted_sentence}{due_sentence} CharityClarity treats the organization as Delinquent."
            )
    if normalized_status == "delinquent" and not context.get("represented_year") and annual_filings_absent(combined_result_text(result, body)):
        return (
            f"The {state} public registry detail page shows the organization record, but the annual filing section shows no annual filings available "
            "and the CharityClarity check does not show an exempt registration status."
        )
    if normalized_status == "delinquent" and state == "HI" and not context.get("represented_year"):
        return (
            "The HI public registry shows an active organization record, but CharityClarity did not identify a visible annual filing year "
            "from the annual filing/document section and the record does not show an exempt registration status."
        )
    if normalized_status == "delinquent" and stale_represented_year_is_delinquent(context.get("represented_year")) and not context.get("due_date"):
        return (
            f"The {state} public registry detail page shows the organization record and the most recent fiscal/filing year identified is "
            f"{context.get('represented_year')}. The available CharityClarity check did not provide enough fiscal year-end information to calculate a precise due date, "
            "but the filing record appears more than one annual cycle behind."
        )
    registry_date = explicit_registry_date(result, body)
    use_registry_date = bool(
        registry_date
        and (
            state in {"AK", "CO", "PA", "VA"}
            or re.search(r"due date|next report|renewal|expiration|expires|automatic extension", " ".join([result.raw_status_text or "", result.source_note or ""]), re.I)
        )
    )
    if state == "PA" and use_registry_date and normalized_status in {"upcoming filing", "current", "delinquent"}:
        registry_status = status_from_calendar_date(registry_date).lower()
        if registry_status == "upcoming filing":
            return f"The PA public registry shows an expiration date of {format_date(registry_date)}, which is within 6 months."
        if registry_status == "current":
            return f"The PA public registry shows an expiration date of {format_date(registry_date)}, which is not within the next 6 months."
        return f"The PA public registry shows an expiration date of {format_date(registry_date)}, which is overdue."
    if normalized_status == "current" and current_cycle_already_filed(state, context.get("represented_year"), registry_date):
        if state == "AK":
            return (
                f"The AK public registry shows the {context['represented_year']} charitable organization registration/renewal is on file. "
                f"The next Alaska charitable registration renewal is due {format_date(context.get('due_date'))}, which is not within the next 6 months."
            )
        filing_label = "annual filing"
        if state == "MA":
            filing_label = "Form PC"
        elif state == "MD":
            filing_label = "annual filing"
        elif state == "CA":
            filing_label = "annual renewal"
        elif state == "HI":
            filing_label = "annual filing"
        if context.get("due_date") and context.get("fiscal_end"):
            extension_sentence = ""
            extended_due = context.get("extended_due_date")
            if extended_due:
                extended_status = status_from_calendar_date(extended_due)
                if state == "MD":
                    extension_sentence = f" If Maryland's automatic extension applies, the due date becomes {format_date(extended_due)} and the status becomes {extended_status}."
                elif state in EXTENSION_SCENARIO_STATES:
                    extension_sentence = f" If a six-month extension was applied for and approved, the due date becomes {format_date(extended_due)} and the status becomes {extended_status}."
            due_label = "extended due date" if state == "MA" and context.get("uses_extension_scenario") else "initial due date"
            return (
                f"{context['represented_year']} appears to be the most recent {state} {filing_label} year identified in the CharityClarity check. "
                f"Based on a {context['fiscal_end'][0]}/{context['fiscal_end'][1]} fiscal year end, the {context['next_report_year']} {filing_label} due date used by CharityClarity is {format_date(context['due_date'])}. "
                f"CE Status is Current based on the {due_label}.{extension_sentence}"
            )
        return (
            f"The {state} public registry shows a {context['represented_year']} {filing_label} on record. "
            f"Based on the filing year identified in this CharityClarity check, no {state} charitable filing appears overdue for the period reviewed, so CharityClarity treats the organization as Current."
        )
    if normalized_status == "upcoming filing" and current_cycle_already_filed(state, context.get("represented_year"), registry_date) and context.get("due_date"):
        extension_sentence = ""
        extended_due = context.get("extended_due_date")
        if extended_due:
            extended_status = status_from_calendar_date(extended_due)
            if state == "MD":
                extension_sentence = f" If Maryland's automatic extension applies, the due date becomes {format_date(extended_due)} and the status becomes {extended_status}."
            elif state in EXTENSION_SCENARIO_STATES:
                extension_sentence = f" If a six-month extension was applied for and approved, the due date becomes {format_date(extended_due)} and the status becomes {extended_status}."
        if state == "AK":
            return (
                f"The AK public registry shows the {context['represented_year']} charitable organization registration/renewal is on file. "
                f"The next Alaska charitable registration renewal is due {format_date(context.get('due_date'))}, which is within 6 months."
            )
        return (
            f"The {state} public registry shows a {context.get('represented_year')} filing or renewal on record. "
            f"The next required filing is due {format_date(context.get('due_date'))}, which is within 6 months.{extension_sentence}"
        )
    if use_registry_date and normalized_status in {"upcoming filing", "current", "delinquent"}:
        descriptor = "expiration or renewal date"
        if state == "AK":
            descriptor = "registration expiration date"
        elif state == "VA":
            descriptor = "registration extended-until date" if re.search(r"Registration\s+Extended\s+Until", result.source_note or "", re.I) else "registration expiration date"
        elif state in {"CO", "PA", "WI"}:
            descriptor = "expiration date"
        elif re.search(r"due date|next report", result.source_note or "", re.I):
            descriptor = "due date"
        article = "an" if descriptor[0].lower() in "aeiou" else "a"
        if normalized_status == "upcoming filing":
            return f"The {state} public registry shows {article} {descriptor} of {format_date(registry_date)}, which is within 6 months."
        if normalized_status == "current":
            return f"The {state} public registry shows {article} {descriptor} of {format_date(registry_date)}, which is not within the next 6 months."
        return f"The {state} public registry shows {article} {descriptor} of {format_date(registry_date)}, which is overdue."
    labeled_dates = [] if state == "CA" else labeled_due_dates_from_text(combined_result_text(result, body))
    if labeled_dates and normalized_status in {"upcoming filing", "current", "delinquent"}:
        due_date = labeled_dates[0]
        if normalized_status == "upcoming filing":
            return f"The {state} public registry shows a due or expiration date of {format_date(due_date)}, which is within 6 months."
        if normalized_status == "current":
            return f"The {state} public registry shows a due or expiration date of {format_date(due_date)}, which is not within the next 6 months."
        return f"The {state} public registry shows a due or expiration date of {format_date(due_date)}, which is overdue."
    if result.state in SUPPORTED_STATES:
        if context.get("due_date"):
            if context.get("uses_extension_scenario"):
                base_due = context.get("base_due_date")
                extended_due = context.get("extended_due_date")
                base_status = status_from_calendar_date(base_due) if base_due else "Unknown"
                extended_status = status_from_calendar_date(extended_due) if extended_due else public_facing_status
                filing_name = "annual filing"
                if state == "MA":
                    filing_name = "Form PC"
                elif state == "NY":
                    filing_name = "CHAR500 annual filing"
                elif state == "PA":
                    filing_name = "annual renewal"
                if state == "NJ":
                    nj_status = status_from_calendar_date(base_due)
                    fiscal_end = context["fiscal_end"]
                    report_year = context["next_report_year"]
                    fy_end = date(report_year, fiscal_end[0], fiscal_end[1])
                    return (
                        f"{context['represented_year']} appears to be the most recent New Jersey filing year identified in the CharityClarity check. "
                        f"Based on a {fiscal_end[0]}/{fiscal_end[1]} fiscal year end, the next New Jersey annual filing is for FY ending {format_date(fy_end)} "
                        f"and is due {format_date(base_due)}. CE Status is {nj_status}."
                    )
                if state == "MD":
                    extension_label = "Maryland automatic extension"
                elif state == "MA":
                    extension_label = "Massachusetts six-month extension"
                else:
                    extension_label = "six-month extension"
                if state == "MD":
                    status_sentence = (
                        f"CE Status is {base_status} based on the initial due date. "
                        f"If Maryland's automatic extension was processed, the due date would be {format_date(extended_due)} "
                        f"and the status would be {extended_status} under that extension scenario."
                    )
                elif state == "NY":
                    status_sentence = (
                        f"CE Status is {base_status} based on the base due date. "
                        f"If the {extension_label} was granted, the extended deadline would be {format_date(extended_due)} and the status would be {extended_status}."
                    )
                else:
                    status_sentence = (
                        f"CE Status is {base_status} based on the base due date. "
                        f"If the {extension_label} was granted, the extended deadline would be {format_date(extended_due)} and the status would be {extended_status}."
                    )
                return (
                    f"{context['represented_year']} appears to be the most recent {state} filing year identified in the CharityClarity check. "
                    f"Based on a {context['fiscal_end'][0]}/{context['fiscal_end'][1]} fiscal year end, the {context['next_report_year']} {filing_name} initial due date is {format_date(base_due)}. "
                    f"{status_sentence}"
                )
            if state == "MA":
                fiscal_end = context["fiscal_end"]
                report_year = context["next_report_year"]
                fy_end = date(report_year, fiscal_end[0], fiscal_end[1])
                base_due = fifteenth_day_after_fiscal_year_end(fy_end, 5)
                extended_due = add_months(base_due, 6)
                return (
                    f"{context['represented_year']} Form PC appears to be the most recent annual charity filing on record. "
                    f"Based on a {fiscal_end[0]}/{fiscal_end[1]} fiscal year end, the {report_year} Form PC base due date is {format_date(base_due)}. "
                    f"If the organization remains registered and in compliance, Massachusetts generally allows a 6 month extension, "
                    f"making the extended deadline {format_date(extended_due)}."
                )
            if state == "NY":
                fiscal_end = context["fiscal_end"]
                report_year = context["next_report_year"]
                fy_end = date(report_year, fiscal_end[0], fiscal_end[1])
                base_due = fifteenth_day_after_fiscal_year_end(fy_end, 5)
                extended_due = add_months(base_due, 6)
                return (
                    f"{context['represented_year']} appears to be the most recent New York annual filing on record. "
                    f"Based on a {fiscal_end[0]}/{fiscal_end[1]} fiscal year end, the {report_year} CHAR500 annual filing base due date is {format_date(base_due)}. "
                    f"If an extension applies, the extended deadline is approximately {format_date(extended_due)}."
                )
            if state == "NJ":
                due_date = context["due_date"]
                calculated_status = status_from_calendar_date(due_date)
                fiscal_end = context["fiscal_end"]
                report_year = context["next_report_year"]
                fy_end = date(report_year, fiscal_end[0], fiscal_end[1])
                return (
                    f"{context['represented_year']} appears to be the most recent New Jersey filing year identified in the CharityClarity check. "
                    f"Based on a {fiscal_end[0]}/{fiscal_end[1]} fiscal year end, the next New Jersey annual filing is for FY ending {format_date(fy_end)} "
                    f"and is due {format_date(due_date)}. CE Status is {calculated_status}."
                )
            return context["comment"]
    if normalized_status == "upcoming filing":
        return "A filing or renewal appears to be due soon based on the CharityClarity check."
    if normalized_status == "current":
        return "No delinquency was identified in the CharityClarity check."
    if "delinquent" in normalized_status or "non-compliant" in normalized_status:
        return "The CharityClarity check indicates a delinquency."
    return "Review the CharityClarity result for additional details."


def append_registry_match_comment(result, comment: str, public_facing_status: str) -> str:
    match_name = useful_registry_name(getattr(result, "matched_registry_name", ""))
    match_identifier = (getattr(result, "matched_registry_identifier", "") or "").strip()
    if public_facing_status.lower() in {"not registered", "site not reachable"}:
        return comment
    if re.search(r"\bRegistry\s+match\s*:", comment or "", re.I):
        return comment
    if not match_name and not match_identifier:
        return comment
    spacer = "" if (comment or "").endswith((" ", "\n")) else " "
    if not match_name:
        return f"{comment}{spacer}Registry match ID: {match_identifier}."
    id_text = f" (ID: {match_identifier})" if match_identifier else ""
    return f"{comment}{spacer}Registry match: {match_name}{id_text}."


def comments_for_result(result, body: str, public_facing_status: str) -> str:
    comment = append_registry_match_comment(
        result,
        comments_for_result_base(result, body, public_facing_status),
        public_facing_status,
    )
    footer = DOWNLOADABLE_DATA_COMMENT_FOOTERS.get((getattr(result, "state", "") or "").upper(), "")
    if footer and footer not in comment:
        return "\n\n".join([comment, footer])
    return comment


def load_ky_snapshot_records() -> list[tuple[str, str, str, str]]:
    global KY_SNAPSHOT_RECORDS
    if KY_SNAPSHOT_RECORDS is not None:
        return KY_SNAPSHOT_RECORDS
    records = load_ky_live_pdf_records()
    if records:
        KY_SNAPSHOT_RECORDS = records
        return KY_SNAPSHOT_RECORDS
    modules = state_batch_modules(["KY"])
    bundle = load_state_batch_bundle()
    module = modules[bundle.STATE_TO_MODULE["KY"]]
    encoded = getattr(module, "EMBEDDED_SNAPSHOT_B64", "")
    records = []
    if encoded:
        try:
            snapshot = json.loads(zlib.decompress(base64.b64decode(encoded)).decode("utf-8-sig"))
            for item in snapshot.get("records", []):
                record_text = item[1] if isinstance(item, (list, tuple)) and len(item) > 1 else item
                registry_id, registry_name, filed_year = parse_ky_snapshot_record(record_text)
                if registry_id and registry_name:
                    records.append((registry_id, registry_name, filed_year, re.sub(r"\s+", " ", str(record_text or "")).strip()))
        except Exception as exc:
            log_event(f"KY snapshot decode failed: {exc}")
    KY_SNAPSHOT_RECORDS = records
    return records


def load_ky_live_pdf_records() -> list[tuple[str, str, str, str]]:
    global KY_LIVE_PDF_RECORDS, KY_LIVE_PDF_LOADED_AT
    now = time.time()
    if KY_LIVE_PDF_RECORDS is not None and now - KY_LIVE_PDF_LOADED_AT < KY_LIVE_PDF_MAX_AGE_SECONDS:
        return KY_LIVE_PDF_RECORDS
    if PdfReader is None:
        return []
    with KY_LIVE_PDF_LOCK:
        now = time.time()
        if KY_LIVE_PDF_RECORDS is not None and now - KY_LIVE_PDF_LOADED_AT < KY_LIVE_PDF_MAX_AGE_SECONDS:
            return KY_LIVE_PDF_RECORDS
        records: list[tuple[str, str, str, str]] = []
        try:
            request = urllib.request.Request(
                KY_LIVE_PDF_URL,
                headers={
                    "User-Agent": (
                        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                        f"AppleWebKit/537.36 (KHTML, like Gecko) CharityClarity/{APP_VERSION}"
                    ),
                    "Accept": "application/pdf,*/*",
                    "Referer": "https://www.ag.ky.gov/Resources/Consumer-Resources/charity/Pages/registered-charities.aspx",
                },
            )
            with urllib.request.urlopen(request, timeout=45) as response:
                pdf_bytes = response.read()
            reader = PdfReader(io.BytesIO(pdf_bytes))
            text = "\n".join(page.extract_text() or "" for page in reader.pages)
            record_pattern = re.compile(
                r"(?:^|\n)\s*(?P<id>\d{1,6})\s*\n(?P<body>[\s\S]{3,700}?)\n\s*"
                r"\$[\d,]+(?:\.\d{2})?\s*\n\s*\$[\d,]+(?:\.\d{2})?\s*\n\s*(?P<year>20\d{2})\b",
                re.I,
            )
            for match in record_pattern.finditer(text):
                registry_id = match.group("id")
                filed_year = match.group("year")
                body_lines = [
                    re.sub(r"\s+", " ", line).strip()
                    for line in (match.group("body") or "").splitlines()
                    if re.sub(r"\s+", " ", line).strip()
                ]
                if not body_lines:
                    continue
                shifted_id = re.match(r"^(\d{1,6})\s+([A-Za-z].*)$", body_lines[0])
                if shifted_id:
                    registry_id = shifted_id.group(1)
                    body_lines[0] = shifted_id.group(2).strip()
                elif len(body_lines) >= 2 and re.fullmatch(r"\d{1,6}", body_lines[0]) and re.search(r"[A-Za-z]", body_lines[1]):
                    registry_id = body_lines[0]
                    body_lines = body_lines[1:]
                else:
                    joined_body = " ".join(body_lines)
                    embedded_ids = list(re.finditer(r"\b(\d{3,6})\s+([A-Za-z][A-Za-z0-9&',()./\-\s]{4,})$", joined_body))
                    for embedded in reversed(embedded_ids):
                        candidate_name = useful_registry_name(embedded.group(2))
                        if candidate_name and len(normalized_match_name(candidate_name).split()) >= 2:
                            registry_id = embedded.group(1)
                            body_lines = [candidate_name]
                            break
                registry_name = useful_registry_name(" ".join(body_lines))
                if not registry_name or re.search(r"^\d+$", registry_name):
                    continue
                record_text = f"{registry_id} {registry_name} Yr Last Filed {filed_year}"
                records.append((registry_id, registry_name, filed_year, record_text))
        except Exception as exc:
            log_event(f"KY live PDF load failed: {exc}")
            records = []
        KY_LIVE_PDF_RECORDS = records
        KY_LIVE_PDF_LOADED_AT = time.time()
        return records


def parse_ky_snapshot_record(record_text) -> tuple[str, str, str]:
    text = re.sub(r"\s+", " ", str(record_text or "")).strip()
    id_match = re.match(r"^(\d{1,8})\s+(.+)$", text)
    if not id_match:
        return "", "", ""
    registry_id = id_match.group(1)
    rest = id_match.group(2).strip()
    year_match = re.search(r"\b(20\d{2})\b", rest)
    filed_year = year_match.group(1) if year_match else ""
    name_part = re.split(r"\s+\$[0-9,]+(?:\.\d{2})?\b", rest, maxsplit=1)[0].strip()
    if not name_part and filed_year:
        name_part = rest.split(filed_year, 1)[0].strip()
    return registry_id, useful_registry_name(name_part), filed_year


def ky_strict_name_score(registry_name: str, target_norms: set[str], original_name: str) -> int:
    registry_norm = normalized_match_name(registry_name)
    if not registry_norm:
        return -1000
    best = -1000
    registry_words = set(registry_norm.split())
    for target_norm in target_norms:
        if not target_norm:
            continue
        target_words = set(target_norm.split())
        if registry_words and target_words and len(registry_words & target_words) == 0:
            continue
        if registry_norm == target_norm:
            best = max(best, 1000)
        elif registry_norm.startswith(target_norm) and min(len(registry_norm.split()), len(target_norm.split())) >= 4:
            best = max(best, 800 + min(50, len(target_norm.split())))
        elif target_norm.startswith(registry_norm) and min(len(registry_norm.split()), len(target_norm.split())) >= 4:
            coverage = len(registry_norm.split()) / max(1, len(target_norm.split()))
            if coverage >= 0.8:
                best = max(best, 760 + min(40, len(registry_norm.split())))
    if best >= 800:
        return best
    original_word_count = len(normalized_match_name(original_name).split())
    registry_word_count = len(registry_norm.split())
    if min(original_word_count, registry_word_count) >= 2 and compatible_ein_alias_for_name(original_name, registry_name):
        return 700
    return best


def saint_university_canonical(value: str) -> tuple[str, ...]:
    tokens = normalized_match_name(value).split()
    if not tokens:
        return ()
    tokens = ["saint" if token == "st" else token for token in tokens]
    tokens = [token[:-1] if token.endswith("s") and len(token) > 3 else token for token in tokens]
    if len(tokens) >= 4 and tokens[0] == "university" and tokens[1] == "of":
        tokens = [tokens[0], *tokens[2:]]
    if len(tokens) >= 3 and tokens[-1] == "university" and tokens[-2].endswith("s"):
        tokens = [*tokens[:-2], tokens[-2][:-1], tokens[-1]]
    if len(tokens) >= 3 and tokens[0] == "saint" and tokens[-1] == "university":
        return ("university", "saint", *tokens[1:-1])
    if len(tokens) >= 3 and tokens[0] == "university" and tokens[1] == "saint":
        return ("university", "saint", *tokens[2:])
    return ()


def search_ky_strict_snapshot(org):
    result = checker.StateResult(
        org.organization_name,
        org.ein,
        "KY",
        checker.STATUS_NOT_REGISTERED,
        "",
    )
    result.raw_status_text = "No safely matching organization row"
    result.source_note = (
        "Kentucky is checked from a downloadable public charity registration snapshot. "
        "CharityClarity requires an exact or confirmed-safe registry-name match before using a row."
    )
    result.success = True
    targets = organization_match_target_variants(org.organization_name, org.ein)
    target_norms = {normalized_match_name(target) for target in targets}
    target_first_words = {target.split()[0] for target in target_norms if target.split()}
    best = None
    best_score = (-1000, -1000, 0)
    for registry_id, registry_name, filed_year, record_text in load_ky_snapshot_records():
        registry_norm = normalized_match_name(registry_name)
        if target_first_words and registry_norm.split() and registry_norm.split()[0] not in target_first_words:
            continue
        score = ky_strict_name_score(registry_name, target_norms, org.organization_name)
        match_score = target_name_score(registry_name, targets)
        composite_score = (score, match_score, len(registry_norm.split()))
        if composite_score > best_score:
            best_score = composite_score
            best = (registry_id, registry_name, filed_year, record_text)
    if not best or best_score[0] < 700:
        return result
    registry_id, registry_name, filed_year, record_text = best
    result.status = checker.STATUS_CURRENT
    result.raw_status_text = " | ".join(part for part in [
        f"Yr Last Filed: {filed_year}" if filed_year else "",
        f"KY ID: {registry_id}",
    ] if part) or record_text
    result.matched_registry_name = registry_name
    result.matched_registry_identifier = registry_id
    result.source_note = (
        "Kentucky downloadable public charity registration snapshot matched the organization name under strict master-code validation."
    )
    return result


def nh_excel_column_index(ref: str) -> int:
    letters = re.sub(r"[^A-Za-z]", "", ref or "").upper()
    value = 0
    for char in letters:
        value = value * 26 + (ord(char) - ord("A") + 1)
    return value - 1


def nh_excel_date(value) -> date | None:
    if isinstance(value, date):
        return value
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if not text:
        return None
    parsed = parse_due_date(text)
    if parsed:
        return parsed
    try:
        serial = float(text)
    except Exception:
        return None
    if serial <= 0:
        return None
    try:
        return (datetime(1899, 12, 30) + timedelta(days=serial)).date()
    except Exception:
        return None


def nh_load_xlsx_rows(path: Path) -> list[list[str]]:
    ns = {"main": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
    with zipfile.ZipFile(path) as archive:
        shared_strings: list[str] = []
        if "xl/sharedStrings.xml" in archive.namelist():
            root = ET.fromstring(archive.read("xl/sharedStrings.xml"))
            for item in root.findall("main:si", ns):
                parts = [node.text or "" for node in item.findall(".//main:t", ns)]
                shared_strings.append("".join(parts))

        workbook = ET.fromstring(archive.read("xl/workbook.xml"))
        rels = ET.fromstring(archive.read("xl/_rels/workbook.xml.rels"))
        rel_map = {
            rel.attrib.get("Id"): rel.attrib.get("Target", "")
            for rel in rels
        }
        sheet_id = None
        sheets = workbook.find("main:sheets", ns)
        if sheets is not None:
            sheet = sheets.find("main:sheet", ns)
            if sheet is not None:
                sheet_id = sheet.attrib.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        target = rel_map.get(sheet_id or "", "worksheets/sheet1.xml")
        target = target.lstrip("/")
        sheet_path = target if target.startswith("xl/") else f"xl/{target}"
        sheet_xml = ET.fromstring(archive.read(sheet_path))
        rows: list[list[str]] = []
        for row in sheet_xml.findall(".//main:sheetData/main:row", ns):
            cells: dict[int, str] = {}
            max_index = -1
            for cell in row.findall("main:c", ns):
                ref = cell.attrib.get("r", "")
                index = nh_excel_column_index(ref)
                max_index = max(max_index, index)
                cell_type = cell.attrib.get("t", "")
                value_node = cell.find("main:v", ns)
                inline_node = cell.find("main:is/main:t", ns)
                raw = value_node.text if value_node is not None else (inline_node.text if inline_node is not None else "")
                if cell_type == "s":
                    try:
                        raw = shared_strings[int(raw)]
                    except Exception:
                        raw = ""
                cells[index] = str(raw or "").strip()
            if max_index >= 0:
                rows.append([cells.get(index, "") for index in range(max_index + 1)])
    return rows


def nh_download_xlsx_records() -> tuple[list[dict], str]:
    candidates = []
    if NH_ENV_XLSX_PATH is not None:
        candidates.append(NH_ENV_XLSX_PATH)
    candidates.append(NH_BUNDLED_XLSX_PATH)
    snapshot_path = next((path for path in candidates if path.exists()), None)
    if snapshot_path is None:
        return [], ""
    rows = nh_load_xlsx_rows(snapshot_path)
    header_index = -1
    for index, row in enumerate(rows):
        normalized = [re.sub(r"\s+", " ", cell or "").strip().lower() for cell in row]
        if "reg. no." in normalized and "charity name" in normalized and "report due" in normalized:
            header_index = index
            break
    if header_index < 0:
        return [], ""
    headers = [re.sub(r"\s+", " ", cell or "").strip().lower() for cell in rows[header_index]]
    def column(name: str) -> int:
        return headers.index(name)
    reg_col = column("reg. no.")
    name_col = column("charity name")
    status_col = column("status")
    due_col = column("report due")
    address_col = headers.index("address") if "address" in headers else -1
    city_col = headers.index("city") if "city" in headers else -1
    state_col = headers.index("state") if "state" in headers else -1
    zip_col = headers.index("zip") if "zip" in headers else -1

    records: list[dict] = []
    seen_record_keys: set[tuple[str, str, str, str]] = set()
    for row in rows[header_index + 1:]:
        def get(col: int) -> str:
            return row[col].strip() if 0 <= col < len(row) else ""
        registry_id = get(reg_col)
        registry_name = useful_registry_name(get(name_col))
        status_code = get(status_col).upper()
        due_date = nh_excel_date(get(due_col))
        if not registry_id or not registry_name or not status_code or not due_date:
            continue
        due_raw = format_date(due_date)
        body = " ".join(part for part in [
            registry_name,
            get(address_col),
            get(city_col),
            get(state_col),
            get(zip_col),
        ] if part)
        registry_norm = normalized_match_name(registry_name)
        key = (registry_id, registry_name, status_code, due_raw)
        if key in seen_record_keys:
            continue
        seen_record_keys.add(key)
        records.append({
            "registry_id": registry_id,
            "body": re.sub(r"\s+", " ", body).strip(),
            "registry_name": registry_name,
            "registry_words": set(registry_norm.split()),
            "status_code": status_code,
            "due_raw": due_raw,
            "due_date": due_date,
        })
    label = f"{snapshot_path.name} structured NH weekly snapshot"
    return records, label


def nh_should_try_xlsx_before_pdf() -> bool:
    if os.environ.get("CE_NH_PREFER_XLSX", "").strip().lower() not in {"1", "true", "yes"}:
        return False
    if NH_ENV_XLSX_PATH is not None and NH_ENV_XLSX_PATH.exists():
        xlsx_path = NH_ENV_XLSX_PATH
    elif NH_BUNDLED_XLSX_PATH.exists():
        xlsx_path = NH_BUNDLED_XLSX_PATH
    else:
        return False

    pdf_candidates = []
    if NH_PREFER_ENV_PDF and NH_ENV_PDF_PATH is not None:
        pdf_candidates.append(NH_ENV_PDF_PATH)
    pdf_candidates.append(NH_BUNDLED_PDF_PATH)
    if not NH_PREFER_ENV_PDF and NH_ENV_PDF_PATH is not None:
        pdf_candidates.append(NH_ENV_PDF_PATH)
    pdf_path = next((path for path in pdf_candidates if path.exists()), None)
    if pdf_path is None:
        return True

    try:
        return xlsx_path.stat().st_mtime >= pdf_path.stat().st_mtime
    except Exception:
        return False


def nh_download_live_pdf_records() -> tuple[list[dict], str]:
    if nh_should_try_xlsx_before_pdf():
        try:
            xlsx_records, xlsx_label = nh_download_xlsx_records()
            if xlsx_records:
                return xlsx_records, xlsx_label
        except Exception:
            pass
    if PdfReader is None:
        return [], ""
    pdf_source = NH_LIVE_PDF_URL
    try:
        local_candidates = []
        if NH_PREFER_ENV_PDF and NH_ENV_PDF_PATH is not None:
            local_candidates.append(NH_ENV_PDF_PATH)
        local_candidates.append(NH_BUNDLED_PDF_PATH)
        if not NH_PREFER_ENV_PDF and NH_ENV_PDF_PATH is not None:
            local_candidates.append(NH_ENV_PDF_PATH)
        local_path = next((path for path in local_candidates if path.exists()), None)
        if local_path is not None:
            pdf_bytes = local_path.read_bytes()
            pdf_source = str(local_path)
        else:
            request = urllib.request.Request(
                NH_LIVE_PDF_URL,
                headers={
                    "User-Agent": (
                        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                        f"AppleWebKit/537.36 (KHTML, like Gecko) CharityClarity/{APP_VERSION}"
                    ),
                    "Accept": "application/pdf,*/*",
                    "Referer": "https://www.doj.nh.gov/bureaus/charitable-trusts/registered-charities",
                },
            )
            with urllib.request.urlopen(request, timeout=30) as response:
                pdf_bytes = response.read()
    except Exception:
        if not NH_BUNDLED_PDF_PATH.exists():
            raise
        pdf_bytes = NH_BUNDLED_PDF_PATH.read_bytes()
        pdf_source = str(NH_BUNDLED_PDF_PATH)
    reader = PdfReader(io.BytesIO(pdf_bytes))
    text_parts = []
    for page in reader.pages:
        try:
            text_parts.append(page.extract_text() or "")
        except Exception:
            continue
    text = "\n".join(text_parts)
    text = re.sub(r"(\d{1,2}/\d{1,2}/\d{4})(?=\d{3,6}\s+[A-Z])", r"\1\n", text)
    updated_match = re.search(r"\bUpdated:\s*([A-Za-z]+\s+\d{1,2},\s+\d{4})", text, re.I)
    updated_label = updated_match.group(1) if updated_match else ""
    records = []
    seen_record_keys = set()

    def add_nh_record(registry_id: str, body_text: str, status_code: str, due_raw: str) -> None:
        body = re.sub(r"\s+", " ", body_text or "").strip()
        due_date = parse_due_date(due_raw)
        if not body or not due_date:
            return
        registry_name = nh_registry_name_from_live_body(body)
        registry_norm = normalized_match_name(registry_name)
        key = (registry_id, registry_name, status_code.upper(), due_raw)
        if key in seen_record_keys:
            return
        seen_record_keys.add(key)
        records.append({
            "registry_id": registry_id,
            "body": body,
            "registry_name": registry_name,
            "registry_words": set(registry_norm.split()),
            "status_code": status_code.upper(),
            "due_raw": due_raw,
            "due_date": due_date,
        })

    row_pattern = re.compile(
        r"^\s*(?P<reg>\d{3,6})\s+(?P<body>.*?)\s+(?P<status>[GXS])\s+"
        r"(?P<due>\d{1,2}/\d{1,2}/\d{4})\s*$",
        re.I,
    )
    pending_row = ""
    for raw_line in text.splitlines():
        line = re.sub(r"\s+", " ", raw_line or "").strip()
        if not line:
            continue
        if re.search(r"\b(?:Updated:|Registered Charities List|Good Standing|Charitable Trusts Unit|Reg\. No\.)\b", line, re.I):
            continue
        starts_record = bool(re.match(r"^\d{3,6}\s+\S", line))
        if starts_record:
            pending_row = line
        elif pending_row:
            pending_row = f"{pending_row} {line}"
        else:
            continue
        row_match = row_pattern.match(pending_row)
        if row_match:
            add_nh_record(
                row_match.group("reg"),
                row_match.group("body"),
                row_match.group("status"),
                row_match.group("due"),
            )
            pending_row = ""

    if not records:
        record_pattern = re.compile(
            r"^\s*(?P<reg>\d{3,6})\s+(?P<body>[\s\S]*?)\s+(?P<status>[GXS])\s+"
            r"(?P<due>\d{1,2}/\d{1,2}/\d{4})(?=\s*(?:\n\s*\d{3,6}\s+[A-Z]|\n\s*Updated:|\Z))",
            re.I | re.M,
        )
        for match in record_pattern.finditer(text):
            add_nh_record(
                match.group("reg"),
                match.group("body"),
                match.group("status"),
                match.group("due"),
            )
    if not records:
        try:
            xlsx_records, xlsx_label = nh_download_xlsx_records()
            if xlsx_records:
                return xlsx_records, xlsx_label
        except Exception:
            pass
    if pdf_source != NH_LIVE_PDF_URL and updated_label:
        updated_label = f"{updated_label} from bundled NH PDF"
    return records, updated_label


def nh_live_pdf_records() -> tuple[list[dict], str]:
    global NH_LIVE_PDF_RECORDS, NH_LIVE_PDF_LOADED_AT, NH_LIVE_PDF_UPDATED_LABEL
    now = time.time()
    if NH_LIVE_PDF_RECORDS is not None and now - NH_LIVE_PDF_LOADED_AT < NH_LIVE_PDF_MAX_AGE_SECONDS:
        return NH_LIVE_PDF_RECORDS, NH_LIVE_PDF_UPDATED_LABEL
    with NH_LIVE_PDF_LOCK:
        now = time.time()
        if NH_LIVE_PDF_RECORDS is not None and now - NH_LIVE_PDF_LOADED_AT < NH_LIVE_PDF_MAX_AGE_SECONDS:
            return NH_LIVE_PDF_RECORDS, NH_LIVE_PDF_UPDATED_LABEL
        records, updated_label = nh_download_live_pdf_records()
        if records:
            NH_LIVE_PDF_RECORDS = records
            NH_LIVE_PDF_LOADED_AT = now
            NH_LIVE_PDF_UPDATED_LABEL = updated_label
    return NH_LIVE_PDF_RECORDS or [], NH_LIVE_PDF_UPDATED_LABEL


def nh_registry_name_from_live_body(body: str) -> str:
    cleaned = re.sub(r"\s+", " ", body or "").strip()
    word_number_street = (
        r"(?:One|Two|Three|Four|Five|Six|Seven|Eight|Nine|Ten|Eleven|Twelve|"
        r"Thirteen|Fourteen|Fifteen|Sixteen|Seventeen|Eighteen|Nineteen|"
        r"Twenty|Thirty|Forty|Fifty|Sixty|Seventy|Eighty|Ninety)"
        r"\s+[A-Za-z][A-Za-z.'-]*(?:\s+[A-Za-z]\.?)?(?:\s+[A-Za-z][A-Za-z.'-]*){0,3}"
        r"\s+(?:Street|St\.?|Avenue|Ave\.?|Road|Rd\.?|Drive|Dr\.?|Lane|Ln\.?|"
        r"Boulevard|Blvd\.?|Way|Place|Pl\.?|Court|Ct\.?|Circle|Cir\.?|"
        r"Parkway|Pkwy\.?|Highway|Hwy\.?|Plaza|Square|Sq\.?)(?=\s|[A-Z]|$)"
    )
    cleaned = re.split(
        rf"\s+(?:P\.?\s*O\.?\s+Box|PO\s+Box|C/O|c/o|{word_number_street}|\d{{1,6}}\s+[A-Za-z][A-Za-z0-9.'#-]*(?:\s|$))",
        cleaned,
        maxsplit=1,
        flags=re.I,
    )[0].strip()
    return useful_registry_name(cleaned)


def search_nh_live_pdf(org):
    result = checker.StateResult(
        org.organization_name,
        org.ein,
        "NH",
        checker.STATUS_NOT_REGISTERED,
        NH_LIVE_PDF_URL,
    )
    result.raw_status_text = "No safely matching New Hampshire charity row in the current downloadable PDF"
    result.source_note = (
        "New Hampshire was checked against the current downloadable registered-charities PDF. "
        "CharityClarity requires a safe registry-name match before using a row."
    )
    result.success = True
    try:
        records, updated_label = nh_live_pdf_records()
    except Exception as exc:
        result.status = "Site Not Reachable"
        result.raw_status_text = f"NH live PDF fetch failed: {exc}"
        result.source_note = "The New Hampshire registered-charities PDF could not be loaded for this lookup."
        result.success = False
        result.error = str(exc)
        return result

    original_name = getattr(org, "original_organization_name", org.organization_name)
    targets = getattr(org, "match_target_names", None) or organization_match_target_variants(original_name, org.ein)
    target_word_sets = [set(normalized_match_name(target).split()) for target in targets if normalized_match_name(target)]
    target_words = set().union(*target_word_sets) if target_word_sets else set()
    minimum_overlap = 1 if len(target_words) <= 2 else 2
    best = None
    best_score = (-1000, -1000)
    for record in records:
        registry_name = record.get("registry_name") or nh_registry_name_from_live_body(record.get("body", ""))
        if not registry_name:
            continue
        registry_words = record.get("registry_words") or set(normalized_match_name(registry_name).split())
        if target_words and len(registry_words & target_words) < minimum_overlap:
            continue
        score = target_name_score(registry_name, targets)
        safe_match = registry_name_is_safe_against_targets(registry_name, targets, original_name, org.ein)
        if score < 450 and not safe_match:
            continue
        if not safe_match:
            continue
        composite = (max(score, 450), len(normalized_match_name(registry_name).split()))
        if composite > best_score:
            best_score = composite
            best = (record, registry_name)
    if not best:
        return result

    record, registry_name = best
    code = record["status_code"]
    due_date = record["due_date"]
    if code == "S":
        status = "Suspended"
        status_label = "Suspended"
    elif code == "X":
        status = "Delinquent"
        status_label = "Not in Good Standing"
    else:
        status = status_from_calendar_date(due_date)
        status_label = "Good Standing"
    result.status = status
    result.raw_status_text = " | ".join(part for part in [
        f"{code} | {status_label}",
        f"Report Due: {record['due_raw']}",
        f"PDF updated: {updated_label}" if updated_label else "",
    ] if part)
    result.matched_registry_name = registry_name
    result.matched_registry_identifier = record["registry_id"]
    result.source_note = (
        "New Hampshire was checked against the current downloadable registered-charities PDF. "
        "The report due date shown in the PDF controls the CharityClarity status."
    )
    return result


def adjudicated_comment_for_status(result, body: str, status: str) -> str:
    state = (result.state or "the selected state").upper()
    normalized = status.lower()
    if normalized == "not registered":
        return f"The {state} public registry was reachable, but no matching registration record was found for the organization/EIN searched."
    if normalized == "suspended":
        return f"The {state} public registry shows the organization registration status as Suspended."
    if normalized == "delinquent":
        if state == "NJ":
            return "The NJ public registry shows a Noncompliant status, which CharityClarity treats as Delinquent."
        if state == "PA":
            return "The PA public registry returned a matching organization record but did not show a current usable expiration date, so CharityClarity treats the record as Delinquent."
        if state == "CA":
            context = filing_context(result, body)
            ca_years = ca_annual_renewal_years_from_text(body)
            latest_not_submitted_year = ca_years.get("latest_not_submitted_year")
            latest_submitted_year = ca_years.get("latest_submitted_year")
            if latest_not_submitted_year and (not latest_submitted_year or latest_not_submitted_year > latest_submitted_year):
                fiscal_end = context.get("fiscal_end") or fiscal_year_end_for_ein(result.ein)
                due_sentence = ""
                if fiscal_end:
                    due_options = filing_due_date_options("CA", latest_not_submitted_year, fiscal_end)
                    base_due = due_options.get("base_due_date") or due_options.get("base_due") or due_options.get("effective_due")
                    extended_due = due_options.get("extended_due")
                    if base_due:
                        due_sentence = (
                            f" Based on a {fiscal_end[0]}/{fiscal_end[1]} fiscal year end, the "
                            f"{latest_not_submitted_year} annual renewal initial due date is {format_date(base_due)}."
                        )
                    if extended_due:
                        extended_status = status_from_calendar_date(extended_due)
                        due_sentence += (
                            f" If a six-month extension was applied for and approved, the due date becomes "
                            f"{format_date(extended_due)} and the status becomes {extended_status}."
                        )
                submitted_sentence = (
                    f" The most recent CA annual renewal CharityClarity identified as submitted/accepted is {latest_submitted_year}."
                    if latest_submitted_year else
                    " CharityClarity did not identify a submitted/accepted CA annual renewal year in the available Annual Renewal Data."
                )
                return (
                    f"The CA Annual Renewal Data shows the {latest_not_submitted_year} annual renewal with Status of Filing: Not Submitted."
                    f"{submitted_sentence}{due_sentence} CharityClarity treats the organization as Delinquent."
                )
            if context.get("represented_year") and context.get("fiscal_end") and context.get("due_date"):
                extension_sentence = ""
                extended_due = context.get("extended_due_date")
                if extended_due:
                    extended_status = status_from_calendar_date(extended_due)
                    extension_sentence = (
                        f" If a six-month extension was applied for and approved, the due date becomes "
                        f"{format_date(extended_due)} and the status becomes {extended_status}."
                    )
                return (
                    f"{context['represented_year']} appears to be the most recent CA annual renewal year identified in the CharityClarity check. "
                    f"Based on a {context['fiscal_end'][0]}/{context['fiscal_end'][1]} fiscal year end, the "
                    f"{context['next_report_year']} annual renewal initial due date is {format_date(context['due_date'])}. "
                    "The CA public registry indicates a delinquency, so CharityClarity treats the organization as Delinquent."
                    f"{extension_sentence}"
                )
            return "The CA public registry indicates a delinquency, so CharityClarity treats the organization as Delinquent."
        return f"The {state} public registry indicates a delinquency."
    return comments_for_result(result, "", status)


def search_snapshot_or_embedded_state(org, state: str):
    state = (state or "").upper()
    original_name = org.organization_name
    if state in {"KY", "NH"}:
        variant_limit = 14 if state == "NH" else 8
        variants = organization_match_target_variants(original_name, org.ein)[:variant_limit]
    elif state == "KS":
        variants = organization_match_target_variants(original_name, org.ein)[:12]
    else:
        variants = organization_name_variants(
            original_name,
            org.ein,
            include_ein_aliases=True,
            include_name_segments=True,
            include_compact_legal_suffixes=True,
            include_leading_article_variants=True,
        )[:24 if state == "KS" else 8]
    if original_name and original_name not in variants:
        variants.insert(0, original_name)
    best_result = None

    def run_variant(variant_name: str):
        variant_org = org_with_name(org, variant_name)
        return _search_snapshot_or_embedded_state_once(variant_org, state)

    for variant in variants or [original_name]:
        result = run_variant(variant)
        if getattr(result, "organization_name", "") != original_name:
            result.organization_name = original_name
        if public_status(result) == "Site Not Reachable":
            return result
        if public_status(result) != "Not Registered":
            if variant != original_name:
                result.source_note = " ".join(part for part in [
                    result.source_note or "",
                    f"Matched using generated name/DBA variant: {variant}.",
                ]).strip()
            return result
        if state in {"KS"} and (getattr(result, "matched_registry_name", "") or getattr(result, "matched_registry_identifier", "")):
            return result
        best_result = result
    return best_result or run_variant(original_name)


def _search_snapshot_or_embedded_state_once(org, state: str):
    state = (state or "").upper()
    if state == "KY":
        return search_ky_strict_snapshot(org)
    if state == "NH":
        return search_nh_live_pdf(org)
    if state == "KS":
        module = load_ks_weekly_checker()
        external_result = module.search_ks_snapshot(org.organization_name, ARTIFACTS_DIR / "KS")
        result = copy_external_result(org, state, external_result)
        if public_status(result) not in {"Not Registered", "Site Not Reachable"}:
            original_name = getattr(org, "original_organization_name", org.organization_name)
            targets = getattr(org, "match_target_names", None) or organization_match_target_variants(original_name, org.ein)
            matched_name = getattr(result, "matched_registry_name", "") or ""
            if not registry_name_is_safe_against_targets(matched_name, targets, original_name, org.ein):
                rejected = checker.StateResult(org.organization_name, org.ein, "KS", checker.STATUS_NOT_REGISTERED, getattr(result, "source_url", "") or "")
                rejected.raw_status_text = "Kansas registry row did not safely match the requested organization"
                rejected.source_note = (
                    "Kansas is checked from weekly downloadable data. CharityClarity rejected the closest row "
                    "because the registry name was too broad or too different from the requested organization."
                )
                rejected.success = True
                return rejected
        return result

    bundle = load_state_batch_bundle()
    modules = state_batch_modules([state])
    bundle_org = bundle.Organization(organization_name=org.organization_name, ein=org.ein)
    external_result = bundle.dispatch_state(modules, state, bundle_org, ARTIFACTS_DIR / state)
    return copy_external_result(org, state, external_result)


def ms_search_variant_too_broad(value: str) -> bool:
    words = [
        word.lower()
        for word in re.findall(r"[A-Za-z0-9]+", value or "")
        if word.lower() not in {"the", "a", "an", "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited"}
    ]
    if not words:
        return True
    if len(words) == 1 and len(words[0]) <= 3:
        return True
    if len(words) <= 2 and all(len(word) <= 2 for word in words):
        return True
    return False


def ms_words_for_match(value: str) -> list[str]:
    return [
        word.lower()
        for word in re.findall(r"[A-Za-z0-9]+", value or "")
        if word.lower() not in {
            "the",
            "a",
            "an",
            "inc",
            "incorporated",
            "corp",
            "corporation",
            "llc",
            "ltd",
            "limited",
            "foundation",
        }
    ]


def ms_short_prefix_name_mismatch(original_name: str, candidate_name: str) -> bool:
    original_words = ms_words_for_match(normalized_match_name(original_name))
    candidate_words = ms_words_for_match(normalized_match_name(candidate_name))
    if len(original_words) < 5 or not candidate_words:
        return False
    if (
        candidate_words[0] in {"of", "for", "and", "or", "to", "in", "on", "at", "by"}
        and (not original_words or original_words[0] != candidate_words[0])
    ):
        return True
    if len(candidate_words) <= 3 and original_words[: len(candidate_words)] == candidate_words:
        return True
    if len(candidate_words) <= 3 and len(original_words) - len(candidate_words) >= 2:
        for start in range(1, len(original_words) - len(candidate_words) + 1):
            if original_words[start : start + len(candidate_words)] == candidate_words:
                return True
    missing = [word for word in original_words if word not in set(candidate_words)]
    return len(candidate_words) <= 3 and len(missing) >= 2 and original_words[: len(candidate_words)] == candidate_words


def ms_registry_name_is_safe(candidate_name: str, original_name: str, ein: str = "") -> bool:
    if ms_short_prefix_name_mismatch(original_name, candidate_name):
        return False
    original_words = ms_words_for_match(normalized_match_name(original_name))
    candidate_words = ms_words_for_match(normalized_match_name(candidate_name))
    if len(original_words) == 1 and len(original_words[0]) <= 3 and len(candidate_words) <= 1:
        return False
    return registry_name_is_safe_for_org(candidate_name, original_name, ein)


def ms_preferred_search_variants(name: str, ein: str = "") -> list[str]:
    variants = []

    def add(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip(" ,;-"))
        if (
            cleaned
            and not ms_search_variant_too_broad(cleaned)
            and not ms_short_prefix_name_mismatch(name, cleaned)
            and cleaned.lower() not in {item.lower() for item in variants}
        ):
            variants.append(cleaned)

    seeds = [name]
    for alias in known_names_for_ein(ein):
        if compatible_ein_alias_for_name(name, alias):
            seeds.append(alias)
    for variant in organization_match_target_variants(name, ein):
        if registry_name_is_safe_for_org(variant, name, ein):
            seeds.append(variant)
    for seed in seeds:
        base = re.sub(r"\s+", " ", (seed or "").strip())
        add(base)
        for part in re.split(
            r"\s*(?:/|\\|\bd/?b/?a\b|\bdoing\s+business\s+as\b|\balso\s+soliciting\s+as\b|\bsoliciting\s+as\b|\balso\s+known\s+as\b|\baka\b|\bfka\b|\bformerly\b)\s*",
            base,
            flags=re.I,
        ):
            part = re.sub(r"\s+", " ", part.strip(" ,;-"))
            if re.fullmatch(r"(?i)(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)", part):
                continue
            if (len(part.split()) >= 2) or len(part) >= 4:
                add(part)
        without_comma_suffix = re.sub(
            r",\s*(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\s*$",
            "",
            base,
            flags=re.I,
        ).strip()
        without_suffix = re.sub(
            r"\s+\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\b\.?\s*$",
            "",
            without_comma_suffix,
            flags=re.I,
        ).strip()
        add(without_suffix)
        us_reduced = re.sub(r"^(?:the\s+)?(?:u\.?\s*s\.?|us|united\s+states)\s+", "", base, flags=re.I).strip()
        add(us_reduced)
        no_article = re.sub(r"^(?:the|a|an)\s+", "", base, flags=re.I).strip()
        add(no_article)
        trailing_the = re.match(r"^(.*?),\s*the\s*$", base, re.I)
        if trailing_the:
            add(f"The {trailing_the.group(1).strip()}")
            add(trailing_the.group(1).strip())
        children_hospital = re.sub(
            r"\b(Children'?s?)\s+Foundation\b",
            r"\1 Hospital Foundation",
            base,
            flags=re.I,
        ).strip()
        add(children_hospital)
        children_hospital_no_apostrophe = re.sub(r"(?i)\bchildren'?s\b", "Childrens", children_hospital)
        add(children_hospital_no_apostrophe)
        children_hospital_plain = re.sub(r"[^\w\s]", " ", children_hospital)
        children_hospital_plain = re.sub(r"\s+", " ", children_hospital_plain).strip()
        add(children_hospital_plain)
    return variants


def ms_result_row_cells(row) -> list[str]:
    cells = []
    try:
        locator = row.locator("td")
        for index in range(min(locator.count(), 12)):
            try:
                text = re.sub(r"\s+", " ", locator.nth(index).inner_text(timeout=1000)).strip()
                if text:
                    cells.append(text)
            except Exception:
                continue
    except Exception:
        pass
    return cells


def ms_registry_name_from_row(row, original_name: str, ein: str = "") -> str:
    skip_pattern = re.compile(
        r"^(?:details?|view|select|file\s*#?\s*\d+|\d{4,}|current|closed|expired|registered|not\s+registered|delinquent|pending)\b",
        re.I,
    )
    for cell in ms_result_row_cells(row):
        candidate = useful_registry_name(cell)
        if not candidate or skip_pattern.search(candidate):
            continue
        if ms_registry_name_is_safe(candidate, original_name, ein):
            return candidate
    try:
        row_text = re.sub(r"\s+", " ", row.inner_text(timeout=1000)).strip()
    except Exception:
        row_text = ""
    for part in re.split(r"\s{2,}|\t|\|", row_text):
        candidate = useful_registry_name(part)
        if not candidate or skip_pattern.search(candidate):
            continue
        if ms_registry_name_is_safe(candidate, original_name, ein):
            return candidate
    return ""


def ms_status_from_row_cells(row) -> str:
    for cell in ms_result_row_cells(row):
        text = re.sub(r"\s+", " ", cell or "").strip()
        if not text:
            continue
        if re.search(r"\b(current|registered|closed|expired|delinquent|pending|not\s+current|revoked|withdrawn|cancel(?:ed|led))\b", text, re.I):
            if not re.search(r"^(?:details?|view|select)$", text, re.I):
                return text
    return ""


def ms_choose_safe_row_from_table(table, original_name: str, ein: str = ""):
    try:
        rows = table.locator("tbody tr")
        row_count = rows.count()
        if row_count == 0:
            rows = table.locator("tr")
            row_count = rows.count()
    except Exception:
        return None
    candidates = []
    for index in range(min(row_count, 80)):
        row = rows.nth(index)
        row_cells = ms_result_row_cells(row)
        if len(row_cells) > 6:
            continue
        try:
            row_text = re.sub(r"\s+", " ", row.inner_text(timeout=1000)).strip()
        except Exception:
            continue
        if not row_text or re.search(r"charity\s+name|filing\s+status|details?", row_text, re.I) and not re.search(r"\b(current|registered|closed|expired|delinquent)\b", row_text, re.I):
            continue
        matched_name = ms_registry_name_from_row(row, original_name, ein)
        if not matched_name:
            continue
        status_priority = 0
        status_text = ms_status_from_row_cells(row) or row_text
        if re.search(r"\b(current|registered|active)\b", status_text, re.I):
            status_priority = 4
        elif re.search(r"\bpending\b", status_text, re.I):
            status_priority = 3
        elif re.search(r"\b(delinquent|expired|not\s+current)\b", status_text, re.I):
            status_priority = 2
        elif re.search(r"\b(closed|withdrawn|cancel(?:ed|led)|terminated|revoked)\b", status_text, re.I):
            status_priority = 1
        date_ordinals = []
        for date_text in re.findall(r"\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b", row_text):
            parsed = parse_due_date(date_text)
            if parsed:
                date_ordinals.append(parsed.toordinal())
        name_score = target_name_score(matched_name, organization_match_target_variants(original_name, ein))
        candidates.append((name_score, status_priority, max(date_ordinals) if date_ordinals else 0, -index, row))
    if not candidates:
        return None
    candidates.sort(key=lambda item: item[:4], reverse=True)
    return candidates[0][4]


def ms_status_from_filing_status(filing_status: str, expiration_date: date | None, classifier) -> str:
    text = filing_status or ""
    if re.search(r"\bexempt(?:ed|ion)?\b", text, re.I):
        return "Exempt"
    if re.search(r"\b(closed|withdrawn|cancel(?:ed|led)|terminated|dissolved)\b", text, re.I):
        return "Closed / Withdrawn / Canceled"
    if expiration_date:
        return status_from_calendar_date(expiration_date)
    return classifier(filing_status, expiration_date)


def search_ms_fast(page, org, navigate: bool = True):
    """Master-level Mississippi path with bounded waits around the embedded checker logic."""
    modules = state_batch_modules(["MS"])
    module = modules[load_state_batch_bundle().STATE_TO_MODULE["MS"]]
    result = module.SearchResult(
        organization_name=org.organization_name,
        status=module.STATUS_UNKNOWN,
        raw_status_text="",
    )
    try:
        if navigate:
            page.goto(module.MS_SEARCH_URL, wait_until="domcontentloaded", timeout=9000)
            safe_wait_for_network_idle(page, timeout=1000)

        input_box = module.find_visible_input(page, [
            "#ContentPlaceHolder1_PortalPageControl1_ctl10_IFSearchControl1_EntityNameTextBox",
            'input[name="ctl00$ContentPlaceHolder1$PortalPageControl1$ctl10$IFSearchControl1$EntityNameTextBox"]',
            'input[aria-label*="Charity Name" i]',
            'input[name*="CharityName" i]',
            'input[id*="CharityName" i]',
            'input[name*="Name" i]',
            'input[id*="Name" i]',
            'input[type="text"]',
        ])
        if not input_box:
            if not navigate:
                page.goto(module.MS_SEARCH_URL, wait_until="domcontentloaded", timeout=9000)
                safe_wait_for_network_idle(page, timeout=1000)
                input_box = module.find_visible_input(page, [
                    "#ContentPlaceHolder1_PortalPageControl1_ctl10_IFSearchControl1_EntityNameTextBox",
                    'input[name="ctl00$ContentPlaceHolder1$PortalPageControl1$ctl10$IFSearchControl1$EntityNameTextBox"]',
                    'input[aria-label*="Charity Name" i]',
                    'input[name*="CharityName" i]',
                    'input[id*="CharityName" i]',
                    'input[name*="Name" i]',
                    'input[id*="Name" i]',
                    'input[type="text"]',
                ])
            if not input_box:
                result.error = "Could not find the Mississippi Charity Name input."
                return result

        input_box.click(timeout=3000)
        input_box.fill("")
        input_box.fill(org.organization_name)
        page.wait_for_timeout(200)

        clicked = False
        for candidate in [
            page.locator("#SearchButton").first,
            page.get_by_role("button", name=re.compile(r"^Search$", re.I)),
            page.locator('input[type="submit"][value*="Search" i]').first,
            page.locator('button:has-text("Search")').first,
        ]:
            try:
                candidate.click(timeout=3000)
                clicked = True
                break
            except Exception:
                continue
        if not clicked:
            result.error = "Could not click the Mississippi Search button."
            return result

        safe_wait_for_network_idle(page, timeout=1500)

        table = None
        page_text = ""
        deadline = time.perf_counter() + 4.0
        while time.perf_counter() < deadline:
            page.wait_for_timeout(500)
            page_text = page.locator("body").inner_text(timeout=4000)
            if re.search(r"no results found|no records found|no matching|0 results", page_text, re.I):
                break
            table = module.find_results_table(page)
            if table:
                break

        if re.search(r"no results found|no records found|no matching|0 results", page_text, re.I):
            result.status = module.STATUS_NOT_FOUND
            result.raw_status_text = "No results found"
            result.success = True
            result.source_note = "Mississippi search returned no matching result row."
            return result

        if not table:
            result.status = module.STATUS_NOT_FOUND
            result.raw_status_text = "No Mississippi result table found within bounded wait"
            result.success = True
            result.source_note = "Mississippi search did not expose a result table within the master bounded wait."
            return result

        original_name = getattr(org, "original_organization_name", org.organization_name)
        name_index, status_index = module.detect_header_indexes(table)
        row = module.choose_matching_row(table, org.organization_name, name_index)
        if row and len(ms_result_row_cells(row)) > 6:
            row = None
        if row and not ms_registry_name_from_row(row, original_name, getattr(org, "ein", "")):
            row = None
        if not row:
            row = ms_choose_safe_row_from_table(table, original_name, getattr(org, "ein", ""))
        if not row:
            result.status = module.STATUS_NOT_FOUND
            result.raw_status_text = "No matching organization row"
            result.success = True
            result.source_note = "Mississippi results table did not contain a matching organization row."
            return result

        row_registry_name = ms_registry_name_from_row(row, original_name, getattr(org, "ein", ""))
        if row_registry_name:
            result.matched_registry_name = row_registry_name

        status_text = module.extract_status_from_row(row, status_index) or ms_status_from_row_cells(row)
        if re.fullmatch(r"\d{5,}", re.sub(r"\D", "", status_text or "")):
            status_text = ""

        clicked_detail = False
        try:
            links = row.locator("a")
            link_count = min(links.count(), 5)
            for i in range(link_count):
                link = links.nth(i)
                try:
                    link_text = re.sub(r"\s+", " ", link.inner_text(timeout=750)).strip()
                except Exception:
                    link_text = ""
                if link_text and not row_registry_name:
                    candidate_name = useful_registry_name(link_text)
                    if candidate_name and registry_name_is_safe_for_org(candidate_name, original_name, getattr(org, "ein", "")):
                        result.matched_registry_name = candidate_name
                if link_text and module.normalize_name(link_text) == module.normalize_name(org.organization_name):
                    link.click(timeout=3000)
                    clicked_detail = True
                    break
            if not clicked_detail and link_count > 0:
                links.first.click(timeout=3000)
                clicked_detail = True
        except Exception:
            clicked_detail = False

        detail_text = ""
        if clicked_detail:
            safe_wait_for_network_idle(page, timeout=1500)
            page.wait_for_timeout(500)
            detail_text = module.body_text(page)

        filing_status = module.extract_labeled_value_from_text(detail_text, ["Filing Status"])
        expiration_raw = module.extract_labeled_value_from_text(detail_text, ["Expiration Date"])
        expiration_date = module.parse_mmddyyyy_date(expiration_raw)
        if expiration_raw and not expiration_date:
            expiration_raw = ""
        if not filing_status:
            filing_status = status_text
        if re.fullmatch(r"\d{5,}", re.sub(r"\D", "", filing_status or "")):
            filing_status = ""
        if not expiration_date:
            fallback_expiration_raw = module.extract_labeled_value_from_text(detail_text, ["Expire Date"])
            expiration_date = module.parse_mmddyyyy_date(fallback_expiration_raw)
            if expiration_date and not expiration_raw:
                expiration_raw = fallback_expiration_raw

        if re.search(r"\bexempt(?:ed|ion)?\b", filing_status or "", re.I):
            result.status = "Exempt"
            result.raw_status_text = module.normalize_ms_filing_status(filing_status)
            result.source_note = (
                "Mississippi matched the organization row and the filing status is exempt; "
                "no expiration-date calculation is required for exempt records."
            )
            result.success = True
            return result

        if (
            not expiration_date
            and re.search(r"\bcurrent\b|\bregistered\b", filing_status or "", re.I)
        ):
            result.status = "Site Not Reachable"
            result.raw_status_text = f"{module.normalize_ms_filing_status(filing_status)} | Expiration Date not visible"
            result.error = "Mississippi matched row but expiration date was not visible"
            result.success = False
            result.source_note = (
                "Mississippi matched the organization row, but the detail page did not expose an expiration date. "
                "CharityClarity did not make a final current/upcoming determination from the row status alone."
            )
            return result

        if not filing_status:
            result.status = module.STATUS_UNKNOWN
            result.raw_status_text = "Status not visible in matched Mississippi result"
            result.success = True
            result.source_note = "Mississippi matched the organization row, but neither the row nor detail page exposed a usable Filing Status."
            return result

        display_filing_status = module.normalize_ms_filing_status(filing_status)
        result.raw_status_text = (
            f"{display_filing_status} | Expiration Date: {expiration_raw}"
            if expiration_raw
            else display_filing_status
        )
        result.status = ms_status_from_filing_status(filing_status, expiration_date, module.classify_ms_registration)
        result.source_note = (
            "Mississippi uses Filing Status and Expiration Date from the matched record; "
            "the master checker uses bounded waits around the public result/detail pages."
        )
        result.success = True
        return result
    except Exception as exc:
        result.error = f"MS error: {exc}"
        return result


def search_batch_browser_state(page, org, state: str):
    state = (state or "").upper()
    modules = state_batch_modules([state])
    module = modules[load_state_batch_bundle().STATE_TO_MODULE[state]]
    if state == "MS":
        variants = ms_preferred_search_variants(org.organization_name, org.ein)
        if org.organization_name and not ms_search_variant_too_broad(org.organization_name) and org.organization_name not in variants:
            variants.insert(0, org.organization_name)
        variants = variants[:6]
        if not variants:
            external_result = module.SearchResult(
                organization_name=org.organization_name,
                status=module.STATUS_NOT_FOUND,
                raw_status_text="Mississippi search term was too broad for safe name-only lookup",
            )
            external_result.success = True
            external_result.source_note = "Mississippi skipped a one-token acronym search because name-only results would be too broad to certify safely."
            return copy_external_result(org, state, external_result)
        best_external = None
        ms_deadline = time.perf_counter() + 32.0
        for attempt_index, variant_name in enumerate(variants or [org.organization_name]):
            if time.perf_counter() >= ms_deadline:
                break
            module_org = module.Organization(organization_name=variant_name)
            module_org.ein = org.ein
            module_org.original_organization_name = getattr(org, "original_organization_name", org.organization_name)
            external_result = search_ms_fast(page, module_org, navigate=True)
            best_external = best_external or external_result
            status = external_status_to_checker_status(getattr(external_result, "status", ""))
            raw_text = " ".join([
                getattr(external_result, "raw_status_text", "") or "",
                getattr(external_result, "source_note", "") or "",
            ])
            if status == "Site Not Reachable":
                best_external = external_result
                break
            if status == "Unknown":
                continue
            if status == "Not Registered" or re.search(r"\b(no matching organization row|no results found)\b", raw_text, re.I):
                continue
            matched_name = getattr(external_result, "matched_registry_name", "") or getattr(external_result, "organization_name", "")
            if matched_name and not ms_registry_name_is_safe(matched_name, org.organization_name, org.ein):
                continue
            if variant_name != org.organization_name:
                external_result.source_note = " ".join(part for part in [
                    getattr(external_result, "source_note", "") or "",
                    f"Matched using generated name/DBA variant: {variant_name}.",
                ]).strip()
            best_external = external_result
            break
        external_result = best_external
    elif state == "OK":
        module_org = module.Organization(organization_name=org.organization_name)
        external_result = search_ok_precise(page, org, module)
    else:
        raise ValueError(f"Unsupported browser batch state adapter: {state}")
    return copy_external_result(org, state, external_result)


def ok_choose_safe_result_row(page, org, module):
    safe_targets = getattr(org, "match_target_names", None) or organization_match_target_variants(
        getattr(org, "organization_name", ""),
        getattr(org, "ein", ""),
    )
    best = None
    best_score = -10000
    try:
        rows = page.locator("tr")
        row_count = min(rows.count(), 100)
    except Exception:
        row_count = 0

    for index in range(row_count):
        row = rows.nth(index)
        try:
            row_text = re.sub(r"\s+", " ", row.inner_text(timeout=1500)).strip()
        except Exception:
            continue
        if not row_text:
            continue
        try:
            links = row.locator("a")
            link_count = min(links.count(), 10)
        except Exception:
            continue

        filing_link = None
        filing_number = ""
        registry_name = ""
        for link_index in range(link_count):
            link = links.nth(link_index)
            try:
                link_text = re.sub(r"\s+", " ", link.inner_text(timeout=1000)).strip()
            except Exception:
                continue
            if not link_text:
                continue
            if re.fullmatch(r"\d+", link_text):
                filing_link = link
                filing_number = link_text
            elif not registry_name:
                registry_name = useful_registry_name(link_text)

        if not filing_link:
            continue
        if not registry_name:
            try:
                cells = row.locator("td")
                cell_count = min(cells.count(), 8)
            except Exception:
                cell_count = 0
            for cell_index in range(cell_count):
                try:
                    cell_text = useful_registry_name(cells.nth(cell_index).inner_text(timeout=750))
                except Exception:
                    continue
                if cell_text and not re.fullmatch(r"\d+", cell_text):
                    registry_name = cell_text
                    break
        if not registry_name:
            continue

        score = target_name_score(registry_name, safe_targets)
        if score > best_score:
            best_score = score
            best = (row, filing_link, registry_name, filing_number)

    if not best or best_score < 450:
        return None
    if not registry_name_is_safe_for_org(best[2], getattr(org, "organization_name", ""), getattr(org, "ein", "")):
        return None
    return best


def ok_latest_filing_from_candidates(candidates: list[str], module) -> str:
    dated: list[tuple[date, str]] = []
    undated: list[str] = []
    for candidate in candidates:
        cleaned = re.sub(r"\s+", " ", candidate or "").strip()
        if not cleaned:
            continue
        parsed = module.parse_ok_filing_date(cleaned)
        if parsed:
            dated.append((parsed, cleaned))
        else:
            undated.append(cleaned)
    if dated:
        return max(dated, key=lambda item: item[0])[1]
    return undated[0] if undated else ""


def ok_terminal_closed_text(*texts: str) -> bool:
    combined = " ".join(text for text in texts if text)
    return bool(
        re.search(
            r"\b(?:notice\s+of\s+cancell?ation|cancell?ed|closed|withdrawn|terminated|inactive|dissolved|revoked)\b",
            combined,
            re.I,
        )
    )


def ok_status_from_latest_filing_date(latest_filing_date: date) -> tuple[str, date | None]:
    today = date.today()
    if latest_filing_date.year >= today.year:
        return "Current", None
    assumed_due_date = date(latest_filing_date.year, 11, 15)
    return status_from_calendar_date(assumed_due_date), assumed_due_date


def ok_search_name_for_org(org) -> str:
    name = re.sub(r"\s+", " ", getattr(org, "organization_name", "") or "").strip()
    name = re.sub(r"\b(inc|corp|ltd)\.$", r"\1", name, flags=re.I).strip()
    reduced = institutional_tail_reduction(name)
    if reduced and reduced.lower() != name.lower() and len(reduced.split()) >= 3:
        return reduced
    without_article = re.sub(r"^the\s+", "", name, flags=re.I).strip()
    if without_article and without_article.lower() != name.lower():
        return without_article
    return name


def search_ok_precise(page, org, module):
    result = module.SearchResult(
        organization_name=org.organization_name,
        status=module.STATUS_UNKNOWN,
        raw_status_text="",
        source_url=module.OK_SEARCH_URL,
        source_note=(
            "Oklahoma uses the latest filing-history entry to classify the annual registration cycle. "
            "CharityClarity searches by organization-name/DBA variants because the public page does not expose EIN search, "
            "then accepts only a safe registry-name match."
        ),
    )
    try:
        page.goto(module.OK_SEARCH_URL, wait_until="domcontentloaded", timeout=45000)
        module.safe_wait_for_network_idle(page, timeout=20000)
        page.wait_for_timeout(2500)

        try:
            page.locator("#ctl00_DefaultContent_CharityNameSearch1_RadioButtonList1_0").click(timeout=5000)
        except Exception:
            try:
                page.get_by_label(re.compile("Search by Name", re.I)).click(timeout=5000)
            except Exception:
                result.error = "Could not select Oklahoma Search by Name."
                return result

        try:
            page.locator("#ctl00_DefaultContent_CharityNameSearch1_buttonOk").click(timeout=5000)
        except Exception:
            try:
                page.get_by_role("button", name=re.compile(r"^Ok$", re.I)).click(timeout=5000)
            except Exception:
                result.error = "Could not click the Oklahoma Ok button."
                return result

        page.wait_for_timeout(1500)
        name_input = module.find_visible_input(page, [
            "#ctl00_DefaultContent_CharityNameSearch1__singlename",
            'input[name="ctl00$DefaultContent$CharityNameSearch1$_singlename"]',
            'input[name*="singlename" i]',
            'input[id*="singlename" i]',
            'input[type="text"]',
        ])
        if not name_input:
            result.error = "Could not find the Oklahoma Entity Name input."
            return result

        search_name = ok_search_name_for_org(org)
        name_input.click(timeout=5000)
        name_input.fill("")
        name_input.type(search_name, delay=40)
        page.wait_for_timeout(500)

        clicked = False
        for candidate in [
            page.locator("#ctl00_DefaultContent_CharityNameSearch1_SearchNameButton").first,
            page.get_by_role("button", name=re.compile(r"^Search$", re.I)),
            page.locator('input[type="submit"][value="Search"]').first,
        ]:
            try:
                candidate.click(timeout=5000)
                clicked = True
                break
            except Exception:
                continue
        if not clicked:
            result.error = "Could not click the Oklahoma Search button."
            return result

        module.safe_wait_for_network_idle(page, timeout=20000)
        page.wait_for_timeout(2500)

        text = module.body_text(page)
        if re.search(r"no records found|no matching|no result", text, re.I):
            result.status = module.STATUS_NOT_FOUND
            result.raw_status_text = "No results found"
            result.success = True
            result.source_note = "Oklahoma search returned no matching entity result."
            return result

        selected = ok_choose_safe_result_row(page, org, module)
        if selected is None:
            result.status = module.STATUS_NOT_FOUND
            result.raw_status_text = "No safely matching filing number link"
            result.success = True
            result.source_note = "Oklahoma results did not contain a safe matching organization row."
            return result

        _, selected_filing_link, matched_name, filing_number = selected
        selected_filing_link.click(timeout=5000)
        module.safe_wait_for_network_idle(page, timeout=20000)
        page.wait_for_timeout(2500)

        detail_text = module.body_text(page, timeout=15000)
        status_text = module.extract_labeled_value_from_text(detail_text, ["Status"])
        if not status_text:
            result.status = module.STATUS_UNKNOWN
            result.raw_status_text = "Status not found on detail page"
            result.success = True
            result.source_note = "Oklahoma detail page was reached, but entity status was not found."
            return result

        history_match = re.search(
            r"FILING HISTORY\s*:?\s*Document Number\s+Filing Type\s+Filing Date\s+Page Count\s+([0-9A-Za-z].*?)(?:Visit Ok\.gov|Accessibility|Disclaimer|$)",
            detail_text,
            re.I | re.S,
        )
        latest_filing = ""
        filing_candidates: list[str] = []
        if history_match:
            lines = [re.sub(r"\s+", " ", line).strip() for line in history_match.group(1).splitlines() if line.strip()]
            filing_candidates.extend(lines)
        if not latest_filing:
            rows = page.locator("tr")
            row_count = min(rows.count(), 200)
            for index in range(row_count):
                try:
                    row_text = re.sub(r"\s+", " ", rows.nth(index).inner_text(timeout=1000)).strip()
                except Exception:
                    continue
                if re.match(r"^\d+\s+", row_text):
                    filing_candidates.append(row_text)
            latest_filing = ok_latest_filing_from_candidates(filing_candidates, module)

        result.matched_registry_name = matched_name
        result.matched_registry_identifier = filing_number
        if ok_terminal_closed_text(status_text, latest_filing, detail_text):
            result.status = "Closed / Withdrawn / Canceled"
            result.raw_status_text = latest_filing or status_text
            result.success = True
            result.source_note = (
                "Oklahoma detail page or filing history shows a terminal closed/canceled status. "
                "CharityClarity uses that registry status instead of calculating status from annual filing dates. "
                "The accepted row safely matched the requested organization."
            )
            return result
        if not latest_filing:
            result.status = status_text
            result.raw_status_text = status_text
            result.success = True
            result.source_note = (
                "Oklahoma detail page status was found, but filing history could not be parsed. "
                "The accepted row safely matched the requested organization."
            )
            return result

        latest_filing_date = module.parse_ok_filing_date(latest_filing)
        if latest_filing_date:
            result.status, assumed_due_date = ok_status_from_latest_filing_date(latest_filing_date)
            due_note = (
                f" For prior-year filing activity, CharityClarity uses the filing-year annual extension deadline ({assumed_due_date.isoformat()}) to classify status."
                if assumed_due_date
                else " Current-year Oklahoma filing-history activity is treated as satisfying the current annual registration cycle."
            )
            result.source_note = (
                "Oklahoma uses the latest filing-history entry to classify the annual registration cycle. "
                f"{due_note} "
                "The accepted row safely matched the requested organization."
            )
        else:
            result.status = status_text
            result.source_note = (
                "Oklahoma detail page status was found, but the latest filing date could not be parsed for classification. "
                "The accepted row safely matched the requested organization."
            )
        result.raw_status_text = latest_filing
        result.success = True
        return result
    except Exception as exc:
        result.error = f"OK error: {exc}"
        return result


def search_bundled_name_state(page, org, state: str):
    if (state or "").upper() == "AR":
        try:
            page.goto(AR_SEARCH_URL, wait_until="domcontentloaded", timeout=30000)
            page.wait_for_timeout(1500)
            body = registry_page_body(page)
            if re.search(r"403\s+ERROR|request could not be satisfied|cloudfront|human verification|verify you are human|captcha", body, re.I):
                result = checker.StateResult(org.organization_name, org.ein, "AR", "Site Not Reachable", AR_SEARCH_URL)
                result.raw_status_text = "Arkansas public charity search returned a bot-verification or block page"
                result.source_note = "Arkansas public charity search could not be reached from this runtime; no no-record determination was made."
                result.error = "AR registry returned bot-verification or block page"
                result.success = False
                return result
        except Exception:
            pass
    return search_bundled_extension_state(page, org, state)


def ar_status_from_text(status_text: str) -> str:
    status = re.sub(r"\s+", " ", status_text or "").strip()
    if re.search(r"\bnot\s+current\b|\b(delinquent|expired|past\s+due|non[-\s]?compliant)\b", status, re.I):
        return "Delinquent"
    if re.search(r"\b(close|closed|withdrawn|cancel(?:ed|led)|terminated|inactive|revoked)\b", status, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(r"\b(current|active|registered)\b", status, re.I):
        return checker.STATUS_CURRENT
    return status or checker.STATUS_UNKNOWN


def ar_status_priority(status_text: str) -> int:
    mapped = ar_status_from_text(status_text)
    return {
        checker.STATUS_CURRENT: 50,
        checker.STATUS_UPCOMING: 40,
        checker.STATUS_DELINQUENT: 30,
        "Closed / Withdrawn / Canceled": 10,
    }.get(mapped, 0)


def ar_registration_date_ordinal(value: str) -> int:
    parsed = parse_due_date(value)
    return parsed.toordinal() if parsed else 0


def ar_result_rows(page) -> list[dict]:
    rows = []
    try:
        locator = page.locator("table tbody tr")
        for index in range(min(locator.count(), 100)):
            row = locator.nth(index)
            try:
                cells = row.locator("td")
                if cells.count() < 4:
                    continue
                row_values = [
                    re.sub(r"\s+", " ", cells.nth(cell_index).inner_text(timeout=1000)).strip()
                    for cell_index in range(4)
                ]
            except Exception:
                continue
            if row_values and not re.search(r"\bNo\s+Results\s+Found\b", " ".join(row_values), re.I):
                rows.append({
                    "name": useful_registry_name(row_values[0]),
                    "type": row_values[1],
                    "status": row_values[2],
                    "registration_date": row_values[3],
                })
    except Exception:
        pass
    return rows


def ar_wait_for_search_form(page, timeout_ms: int) -> bool:
    deadline = time.perf_counter() + max(1.0, timeout_ms / 1000.0)
    while time.perf_counter() < deadline:
        try:
            if page.locator('input[name="name"]').count() > 0:
                page.locator('input[name="name"]').first.wait_for(state="visible", timeout=1000)
                return True
        except Exception:
            pass
        try:
            body = registry_page_body(page)
            if re.search(r"403\s+ERROR|request could not be satisfied|cloudfront", body, re.I):
                return False
        except Exception:
            pass
        page.wait_for_timeout(500)
    return False


def search_ar_precise(page, org):
    result = checker.StateResult(org.organization_name, org.ein, "AR", checker.STATUS_UNKNOWN, AR_SEARCH_URL)
    original_name = getattr(org, "organization_name", "") or ""
    variants = ar_preferred_name_variants(org)
    for variant in organization_name_variants(
        original_name,
        getattr(org, "ein", ""),
        include_ein_aliases=True,
        include_name_segments=True,
        include_compact_legal_suffixes=True,
        include_leading_article_variants=True,
        include_broad_query_prefixes=False,
    ):
        cleaned = re.sub(r"\s+", " ", (variant or "").strip())
        if cleaned and cleaned.lower() not in {existing.lower() for existing in variants}:
            variants.append(cleaned)

    best = None
    best_score = -10000
    first_rejected_row = ""
    reached = False
    deadline = time.perf_counter() + AR_NAME_SEARCH_MAX_SECONDS
    for variant in variants[:AR_NAME_SEARCH_MAX_VARIANTS]:
        remaining = deadline - time.perf_counter()
        if remaining <= 2.0:
            break
        nav_timeout_ms = max(3000, min(12000, int(remaining * 1000)))
        settle_timeout_ms = max(1000, min(2500, int(remaining * 500)))
        try:
            page.goto(AR_SEARCH_URL, wait_until="domcontentloaded", timeout=nav_timeout_ms)
            if not ar_wait_for_search_form(page, nav_timeout_ms):
                body = registry_page_body(page)
                if re.search(r"403\s+ERROR|request could not be satisfied|cloudfront|human verification|verify you are human|captcha", body, re.I):
                    result.status = "Site Not Reachable"
                    result.raw_status_text = "Arkansas public charity search returned a bot-verification or block page"
                    result.source_note = "Arkansas public charity search could not be reached from this runtime; no no-record determination was made."
                    result.error = "AR registry returned bot-verification or block page"
                    result.success = False
                    return result
                raise RuntimeError("Arkansas search form did not become visible")
            body = registry_page_body(page)
            if re.search(r"403\s+ERROR|request could not be satisfied|cloudfront|human verification|verify you are human|captcha", body, re.I):
                result.status = "Site Not Reachable"
                result.raw_status_text = "Arkansas public charity search returned a bot-verification or block page"
                result.source_note = "Arkansas public charity search could not be reached from this runtime; no no-record determination was made."
                result.error = "AR registry returned bot-verification or block page"
                result.success = False
                return result
            page.locator('input[name="name"]').fill("")
            page.locator('input[name="name"]').fill(variant)
            page.get_by_role("button", name=re.compile("search", re.I)).click(timeout=min(5000, nav_timeout_ms))
            page.wait_for_load_state("domcontentloaded", timeout=nav_timeout_ms)
            safe_wait_for_network_idle(page, timeout=settle_timeout_ms)
            page.wait_for_timeout(600)
            body = registry_page_body(page)
            if re.search(r"403\s+ERROR|request could not be satisfied|cloudfront|human verification|verify you are human|captcha", body, re.I):
                result.status = "Site Not Reachable"
                result.raw_status_text = "Arkansas public charity search returned a bot-verification or block page after submit"
                result.source_note = "Arkansas public charity search could not be reached from this runtime after submitting the search; no no-record determination was made."
                result.error = "AR registry returned bot-verification or block page after submit"
                result.success = False
                return result
            if re.search(r"Back\s+to\s+Search\s+Form|Registration\s+Date|No\s+Results\s+Found", body, re.I):
                reached = True
            for row in ar_result_rows(page):
                row_name = row.get("name", "")
                if not row_name:
                    continue
                if not registry_name_is_safe_for_org(row_name, original_name, getattr(org, "ein", "")):
                    if not first_rejected_row:
                        first_rejected_row = " | ".join(
                            part for part in [
                                f"Name: {row.get('name', '')}",
                                f"Type: {row.get('type', '')}",
                                f"Status: {row.get('status', '')}",
                                f"Registration Date: {row.get('registration_date', '')}",
                            ] if part
                        )
                    continue
                name_score = checker.name_match_priority_for_targets(row_name, organization_match_target_variants(original_name, getattr(org, "ein", "")))
                score = (
                    (name_score * 100000000)
                    + (ar_status_priority(row.get("status", "")) * 1000000)
                    + ar_registration_date_ordinal(row.get("registration_date", ""))
                )
                if score > best_score:
                    best_score = score
                    best = row
            if best and best_score >= 300:
                break
        except Exception as exc:
            result.error = f"AR error: {exc}"
            continue

    if not best:
        if not reached:
            result.status = "Site Not Reachable"
            result.raw_status_text = "Arkansas public charity search did not return usable results within the bounded lookup window"
            result.source_note = (
                "Arkansas search stayed inside CharityClarity's per-state time budget and did not expose a usable "
                "result table; no no-record determination was made."
            )
            result.error = "AR bounded lookup did not expose usable rows"
            result.success = False
        else:
            result.status = checker.STATUS_NOT_REGISTERED
            result.raw_status_text = (
                "No matching organization row"
                if not first_rejected_row
                else f"No safely matching organization row. First rejected row: {first_rejected_row}"
            )
            result.source_note = "Arkansas search did not contain a usable charity row after master-code safe-name filtering."
            result.success = True
        return result

    result.matched_registry_name = best.get("name", "")
    result.raw_status_text = f"Type: {best.get('type', '')} | Status: {best.get('status', '')} | Registration Date: {best.get('registration_date', '')}"
    result.status = ar_status_from_text(best.get("status", ""))
    result.source_note = "Arkansas public charity search matched a safe registry name; CharityClarity maps Not Current to Delinquent."
    result.success = True
    return result


def ar_transient_unreachable_result(result) -> bool:
    status = public_status(result)
    if status not in {"Site Not Reachable", "Not Registered"}:
        return False
    text = " ".join([
        getattr(result, "raw_status_text", "") or "",
        getattr(result, "source_note", "") or "",
        getattr(result, "error", "") or "",
    ])
    if status == "Not Registered" and re.search(r"did not return usable results", text, re.I):
        return True
    return bool(re.search(r"bot-verification|human verification|captcha|cloudfront|waf|challenge|block page|preflight", text, re.I))


def ar_preferred_name_variants(org) -> list[str]:
    original = re.sub(r"\s+", " ", (getattr(org, "organization_name", "") or "").strip())
    variants = []

    def too_broad(value: str) -> bool:
        words = [
            word.lower()
            for word in re.findall(r"[A-Za-z0-9]+", value or "")
            if word.lower() not in {
                "the", "a", "an", "of", "for", "to", "and", "in", "on", "at", "by",
                "inc", "incorporated", "corp", "corporation", "llc", "ltd", "limited",
            }
        ]
        return len(words) < 2

    def add(value: str, allow_broad: bool = False) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip())
        if cleaned and (allow_broad or not too_broad(cleaned)) and cleaned.lower() not in {existing.lower() for existing in variants}:
            variants.append(cleaned)

    compact = re.sub(r",\s*(incorporated|inc\.?|corporation|corp\.?|llc|ltd\.?)", r" \1", original, flags=re.I)
    add(re.sub(r"\b(inc|corp|ltd)\.", r"\1", compact, flags=re.I))
    add(compact)
    add(re.sub(r"^(?:the|a|an)\s+", "", compact, flags=re.I))
    if re.search(r"\bto\s+fight\b", compact, re.I):
        add(re.split(r"\bto\s+fight\b", compact, maxsplit=1, flags=re.I)[0])
    if re.search(r"\bmissing\b", compact, re.I) and re.search(r"\bexploited\b", compact, re.I) and re.search(r"\bchildren\b", compact, re.I):
        add("Missing Exploited Children")
        add("Missing and Exploited Children")
    add(re.sub(r"[^\w\s]", " ", compact))
    trustee_reduced = re.sub(r"^(?:the\s+)?trustees\s+of\s+", "", compact, flags=re.I)
    add(trustee_reduced)
    if trustee_reduced != compact:
        trustee_words = [
            word for word in re.findall(r"[A-Za-z0-9]+", trustee_reduced)
            if word.lower() not in {"the", "a", "an", "of", "for", "to", "and", "in", "on", "at", "by", "city"}
        ]
        if trustee_words:
            add(trustee_words[0], allow_broad=True)
    add(re.sub(r"\bcentre\b", "Center", compact, flags=re.I))
    add(re.sub(r"\bcenter\b", "Centre", compact, flags=re.I))
    aids_tb_variant = re.sub(
        r"\b(AIDS?)\s*,?\s+Tuberculosis\s+(?:And|&)\s+Malaria\b",
        r"\1, Tuberculosis & Malaria",
        compact,
        flags=re.I,
    )
    add(aids_tb_variant)
    for connector_variant in connector_light_name_variants(compact):
        add(connector_variant)
    add(re.sub(r"\b(?:local|chapter|affiliate)\b\.?\s*$", "", compact, flags=re.I))
    for alias in known_names_for_ein(getattr(org, "ein", "")):
        if normalized_match_name(alias) != normalized_match_name(original) and compatible_ein_alias_for_name(original, alias):
            add(alias)
            add(re.sub(r"^(?:chc|cfc)\s+", "", alias, flags=re.I))
    add(original)
    return variants


def search_ar_name_variants_once(page, org):
    return search_ar_precise(page, org)


def search_ar_serialized(page, org):
    global AR_LAST_LOOKUP_FINISHED
    with AR_LOOKUP_LOCK:
        elapsed = time.perf_counter() - AR_LAST_LOOKUP_FINISHED
        if elapsed < AR_LOOKUP_MIN_INTERVAL_SECONDS:
            time.sleep(AR_LOOKUP_MIN_INTERVAL_SECONDS - elapsed)

        last_result = None
        for attempt in range(AR_TRANSIENT_RETRY_ATTEMPTS):
            if attempt:
                try:
                    page.context.clear_cookies()
                except Exception:
                    pass
                if AR_TRANSIENT_RETRY_DELAY_SECONDS > 0:
                    time.sleep(AR_TRANSIENT_RETRY_DELAY_SECONDS)
            result = search_ar_name_variants_once(page, org)
            last_result = result
            if not ar_transient_unreachable_result(result):
                AR_LAST_LOOKUP_FINISHED = time.perf_counter()
                return result

        AR_LAST_LOOKUP_FINISHED = time.perf_counter()
        if last_result is not None:
            last_result.source_note = (
                (last_result.source_note or "Arkansas public charity search was not usable from this runtime.")
                + f" CharityClarity retried Arkansas {AR_TRANSIENT_RETRY_ATTEMPTS} time(s) with a serialized browser session before returning this result."
            )
            if public_status(last_result) == "Not Registered" and re.search(
                r"did not return usable results|not contain a usable charity row",
                " ".join([last_result.raw_status_text or "", last_result.source_note or ""]),
                re.I,
            ):
                last_result.status = "Site Not Reachable"
                last_result.error = "AR transient no usable rows after retry"
                last_result.raw_status_text = "Arkansas public charity search did not return usable rows after retry"
                last_result.source_note = (
                    "Arkansas public charity search was reachable, but the result table did not expose usable rows "
                    "after a serialized retry; no no-record determination was made."
                )
                last_result.success = False
        return last_result


def wv_status_from_fields(status_text: str, expiration_text: str) -> str:
    status = re.sub(r"\s+", " ", status_text or "").strip()
    expiration = re.sub(r"\s+", " ", expiration_text or "").strip()
    if re.search(r"\bexempt\b", status, re.I):
        return "Exempt"
    if re.search(r"\b(cancel(?:ed|led)|closed|inactive|withdrawn|terminated)\b", status, re.I):
        return "Closed / Withdrawn / Canceled"
    if re.search(r"\b(expired|delinquent|suspended|revoked)\b", status, re.I):
        return checker.STATUS_DELINQUENT
    exp_date = parse_due_date(expiration)
    if exp_date:
        return classify_expiration_date(exp_date)
    if re.search(r"\b(active|current|registered)\b", status, re.I):
        return checker.STATUS_CURRENT
    return status or checker.STATUS_UNKNOWN


def wv_preferred_query_variants(name: str, ein: str = "") -> list[str]:
    """Search suffix-light WV names first while keeping row acceptance strict."""
    preferred = []

    def add(value: str) -> None:
        cleaned = re.sub(r"\s+", " ", (value or "").strip(" ,;-"))
        if cleaned and cleaned.lower() not in {existing.lower() for existing in preferred}:
            preferred.append(cleaned)

    def add_name_forms(source_name: str) -> None:
        base = re.sub(r"\s+", " ", (source_name or "").strip())
        if not base:
            return
        for segment in re.split(r"\s*/\s*|\s+also\s+soliciting\s+as\s+|\s+d/?b/?a\s+|\s+doing\s+business\s+as\s+", base, flags=re.I):
            segment = re.sub(r"\s+", " ", (segment or "").strip(" ,;-"))
            if segment and segment.lower() != base.lower():
                add_name_forms(segment)
        without_comma_suffix = re.sub(
            r",\s*(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\s*$",
            "",
            base,
            flags=re.I,
        ).strip()
        without_suffix = re.sub(
            r"\b(inc\.?|incorporated|corp\.?|corporation|llc|ltd\.?|limited)\s*$",
            "",
            without_comma_suffix,
            flags=re.I,
        ).strip()
        no_punctuation_without_suffix = re.sub(r"[^\w\s]", " ", without_suffix).strip()
        no_punctuation_without_suffix = re.sub(r"\s+", " ", no_punctuation_without_suffix)
        punctuated_without_leading_article = re.sub(r"^\s*(the|a|an)\s+", "", without_suffix, flags=re.I).strip()
        without_leading_article = re.sub(r"^\s*(the|a|an)\s+", "", no_punctuation_without_suffix or without_suffix, flags=re.I).strip()

        if punctuated_without_leading_article and punctuated_without_leading_article.lower() != base.lower():
            add(punctuated_without_leading_article)
        if without_leading_article and without_leading_article.lower() != base.lower():
            add(without_leading_article)
        if without_suffix and without_suffix.lower() != base.lower():
            add(without_suffix)
        if no_punctuation_without_suffix and no_punctuation_without_suffix.lower() != without_suffix.lower():
            add(no_punctuation_without_suffix)
        add(base)

    add_name_forms(name)
    for alias in known_names_for_ein(ein):
        if compatible_ein_alias_for_name(name, alias):
            add_name_forms(alias)
    for variant in organization_match_target_variants(name, ein):
        if registry_name_is_safe_for_org(variant, name, ein):
            add_name_forms(variant)
    return preferred


def search_wv_precise(page, org):
    result = checker.StateResult(
        org.organization_name,
        org.ein,
        "WV",
        checker.STATUS_UNKNOWN,
        WV_SEARCH_URL,
    )
    result.source_note = (
        "West Virginia does not expose EIN search on the public charity search page. "
        "CharityClarity uses bounded organization-name/DBA variants and requires a safe registry-name match before using a result row."
    )
    try:
        safe_targets = getattr(org, "match_target_names", None) or organization_match_target_variants(org.organization_name, org.ein)
        best = None
        best_score = -10000
        searched_queries: list[str] = []
        saw_result_rows = False
        for query_name in wv_preferred_query_variants(org.organization_name, org.ein):
            page.goto(WV_SEARCH_URL, wait_until="domcontentloaded", timeout=WV_GOTO_TIMEOUT_MS)
            safe_wait_for_network_idle(page, timeout=WV_NETWORK_IDLE_TIMEOUT_MS)
            try:
                page.locator("#ddlType").select_option(label="CHARITABLE ORGANIZATIONS", timeout=5000)
            except Exception:
                pass

            name_input = page.locator("#CharitiesSearch-CharitiesSearch_txtName").first
            name_input.wait_for(state="visible", timeout=5000)
            name_input.fill("")
            name_input.type(query_name, delay=25)
            searched_queries.append(query_name)

            page.locator("#CharitiesSearch-CharitiesSearch_btnSearch").click(timeout=7000)
            safe_wait_for_network_idle(page, timeout=WV_SEARCH_IDLE_TIMEOUT_MS)
            page.wait_for_timeout(WV_RESULTS_SETTLE_MS)

            body = registry_page_body(page)
            if re.search(r"\bNo\s+(?:matching\s+)?(?:records?|results?)\b|records\s+0\s+to\s+0\s+of\s+0", body, re.I):
                continue

            rows = page.locator("tr")
            try:
                row_count = min(rows.count(), 100)
            except Exception:
                row_count = 0
            if row_count:
                saw_result_rows = True
            for index in range(row_count):
                row = rows.nth(index)
                try:
                    cells = row.locator("td")
                    if cells.count() < 5:
                        continue
                    registry_id = re.sub(r"\s+", " ", cells.nth(0).inner_text(timeout=1000)).strip()
                    registry_name = useful_registry_name(cells.nth(1).inner_text(timeout=1000))
                    status_text = re.sub(r"\s+", " ", cells.nth(4).inner_text(timeout=1000)).strip()
                except Exception:
                    continue
                if not registry_id or not registry_name:
                    continue
                score = target_name_score(registry_name, safe_targets)
                if score > best_score:
                    best_score = score
                    best = (row, registry_id, registry_name, status_text)
            if best is not None and best_score >= 450:
                break

        if best is None or best_score < 450:
            result.status = checker.STATUS_NOT_REGISTERED
            if saw_result_rows:
                result.raw_status_text = "No safely matching organization row"
                result.source_note = (
                    "West Virginia returned rows, but none safely matched the requested organization "
                    "or generated DBA/name variants."
                )
            else:
                result.raw_status_text = "No matching organization row"
                result.source_note = (
                    "West Virginia public charity search returned no matching rows for the bounded "
                    f"name variants tried: {', '.join(searched_queries[:4])}."
                )
            result.success = True
            return result

        row, registry_id, registry_name, row_status = best
        link = row.locator("a").first
        link.click(timeout=5000)
        safe_wait_for_network_idle(page, timeout=WV_SEARCH_IDLE_TIMEOUT_MS)
        page.wait_for_timeout(WV_RESULTS_SETTLE_MS)

        detail_text = registry_page_body(page)
        detail_name = useful_registry_name(text_between_labels(detail_text, "Organization Name", ["Expiration Date", "Contact Name", "Status", "Street Address"]))
        matched_name = detail_name or registry_name
        if matched_name and not registry_name_is_safe_for_org(matched_name, org.organization_name, org.ein):
            result.status = checker.STATUS_NOT_REGISTERED
            result.raw_status_text = "Selected West Virginia detail name did not safely match"
            result.source_note = "West Virginia detail page was reached, but CharityClarity rejected it because the registry name did not safely match the requested organization."
            result.success = True
            return result

        status_text = text_between_labels(detail_text, "Status", ["Street Address", "County", "DBA", "Tax Information", "Restrictions"]) or row_status
        expiration_text = text_between_labels(detail_text, "Expiration Date", ["Contact Name", "Status", "Street Address", "County"]) or ""
        result.status = wv_status_from_fields(status_text, expiration_text)
        raw_parts = [part for part in [
            f"Status: {status_text}" if status_text else "",
            f"Expiration Date: {expiration_text}" if expiration_text else "",
            f"WV ID: {registry_id}" if registry_id else "",
        ] if part]
        result.raw_status_text = " | ".join(raw_parts) or re.sub(r"\s+", " ", detail_text or "").strip()[:500]
        result.matched_registry_name = matched_name
        result.matched_registry_identifier = registry_id
        result.success = True
        return result
    except Exception as exc:
        result.error = f"WV error: {exc}"
        result.raw_status_text = "West Virginia lookup could not be completed"
        result.source_note = "West Virginia public charity search could not be completed."
        result.success = False
        return result


def search_wa_nm_state(org, state: str):
    state = (state or "").upper()
    module = load_wa_nm_module()
    external_org = module.Organization(organization_name=org.organization_name, ein=org.ein)
    if state == "WA":
        external_result = module.search_wa(external_org, show_process=False)
        wa_raw = " ".join([
            getattr(external_result, "raw_status_text", "") or "",
            getattr(external_result, "source_note", "") or "",
        ])
        if (
            external_status_to_checker_status(getattr(external_result, "status", "")) == checker.STATUS_UNKNOWN
            and getattr(external_result, "matched_registry_name", "")
            and re.search(r"Renewal\s+Date\s*:\s*CONTACT\s+INFORMATION|Status\s*:\s*No", wa_raw, re.I)
        ):
            external_result.status = "Site Not Reachable"
            external_result.error = "Washington detail page did not expose a usable renewal/status section"
            external_result.success = False
            external_result.raw_status_text = "Washington detail page did not expose a usable renewal/status section"
            external_result.source_note = (
                "Washington returned a registry match, but the detail page exposed the contact-information section "
                "instead of a usable renewal/status section; no final status determination was made."
            )
    elif state == "NM":
        external_result = search_nm_status_history_fallback(org, module)
        if external_status_to_checker_status(getattr(external_result, "status", "")) == checker.STATUS_UNKNOWN:
            hosted_result = module.search_nm(external_org, show_process=False)
            if external_status_to_checker_status(getattr(hosted_result, "status", "")) != checker.STATUS_UNKNOWN:
                external_result = hosted_result
    else:
        raise ValueError(f"Unsupported WA/NM state adapter: {state}")
    return copy_external_result(org, state, external_result)


def nm_status_history_rows_from_text_master(*texts: str) -> list[tuple[int, str, str]]:
    combined = "\n".join(text for text in texts if text)
    if not combined:
        return []
    rows: list[tuple[int, str, str]] = []
    markdown_row_pattern = re.compile(
        r"\|\s*\*{0,2}(20\d{2})\*{0,2}\s*\|\s*(.*?)\s*\|\s*(\d{1,2}/\d{1,2}/\d{4})\s*\|",
        re.I | re.S,
    )
    for row in markdown_row_pattern.finditer(combined):
        detail = re.sub(r"\[[^\]]*\]\([^)]*\)", " ", row.group(2))
        detail = re.sub(r"[*_`]+", "", detail)
        detail = re.sub(r"\s+", " ", detail).strip()
        if detail:
            rows.append((int(row.group(1)), detail, row.group(3)))
    if rows:
        return rows
    combined = html.unescape(re.sub(r"<[^>]+>", " ", combined))
    combined = re.sub(r"\s+", " ", combined).strip()
    status_section_match = re.search(r"Status\s+History(.*)", combined, re.I | re.S)
    section = status_section_match.group(1) if status_section_match else combined
    row_pattern = re.compile(
        r"\b(20\d{2})\s+"
        r"((?:Tax\s+Year\s+Registration\s+Open|Registration\s+Submitted(?:\s+\d{10,})?|"
        r"Extension\s+(?:Granted|Requested)|Reinstatement\s+Issued|Registration\s+Submission\s+Delinquent))"
        r"\s+(\d{1,2}/\d{1,2}/\d{4})",
        re.I,
    )
    for row in row_pattern.finditer(section):
        detail = re.sub(r"\s+", " ", row.group(2)).strip()
        rows.append((int(row.group(1)), detail, row.group(3)))
    if rows:
        return rows
    generic_pattern = re.compile(
        r"\b(20\d{2})\s+(.+?)\s+(\d{1,2}/\d{1,2}/\d{4})(?=\s+20\d{2}\s+|$)",
        re.I | re.S,
    )
    for row in generic_pattern.finditer(section):
        detail = re.sub(r"\s+", " ", row.group(2)).strip()
        if detail:
            rows.append((int(row.group(1)), detail, row.group(3)))
    return rows


def search_nm_status_history_reader(org, module):
    formatted_ein = format_ein(org.ein)
    detail_url = f"https://secure.nmdoj.gov/CharitySearch/CharityDetail.aspx?FEIN={quote(formatted_ein, safe='')}"
    reader_url = f"https://r.jina.ai/http://{detail_url}"
    result = module.SearchResult(
        organization_name=org.organization_name,
        ein=org.ein,
        state="NM",
        status=getattr(module, "STATUS_UNKNOWN", "Unknown"),
        raw_status_text="",
        source_url=detail_url,
        source_note=(
            "New Mexico Status History was read from the public NM DOJ detail page through "
            "the Jina reader after the direct API-host path could not expose usable rows."
        ),
    )
    try:
        if curl_requests is not None:
            response = curl_requests.get(
                reader_url,
                impersonate="chrome136",
                timeout=18,
                headers={"Accept": "text/plain,text/markdown,*/*"},
            )
            if response.status_code != 200:
                raise RuntimeError(f"HTTP {response.status_code}")
            text = response.text or ""
        else:
            request = urllib.request.Request(
                reader_url,
                headers={
                    "Accept": "text/plain,text/markdown,*/*",
                    "User-Agent": f"CharityClarity/{APP_VERSION}",
                },
            )
            with urllib.request.urlopen(request, timeout=18) as response:
                text = response.read().decode("utf-8", errors="replace")
    except Exception as exc:
        result.error = f"NM reader error: {exc}"
        result.raw_status_text = "New Mexico reader lookup could not be completed"
        result.success = False
        return result

    if re.search(r"\bCharity\s+Registration\s+Status\s+is\s+unknown\b", text, re.I) and "Tax Year" not in text:
        result.status = getattr(module, "STATUS_NOT_REGISTERED", "Not registered")
        result.raw_status_text = "No New Mexico charity registration status-history rows found for this FEIN."
        result.success = True
        return result

    name_match = re.search(r"Markdown Content:\s*([^\n\r]+?)\s*\(" + re.escape(formatted_ein) + r"\)", text, re.I)
    if name_match:
        result.matched_registry_name = re.sub(r"\s+", " ", name_match.group(1)).strip()
    rows = nm_status_history_rows_from_text_master(text)
    if not rows:
        result.raw_status_text = "NM reader page reached, but Status History rows were not parsed"
        result.success = True
        return result
    latest_submitted = module.nm_latest_submitted(rows)
    fye_text = module.nm_extract_fye_from_html(
        text,
        preferred_year=latest_submitted[0] if latest_submitted else None,
    )
    return module.apply_nm_rows_to_result(result, rows, fye_text=fye_text)


def search_nm_status_history_sidecar(org, module, note: str = ""):
    result = module.SearchResult(
        organization_name=org.organization_name,
        ein=org.ein,
        state="NM",
        status=getattr(module, "STATUS_UNKNOWN", "Unknown"),
        raw_status_text="",
        source_url=NM_SIDECAR_URL or getattr(module, "NM_SEARCH_URL", "https://secure.nmdoj.gov/CharitySearch/"),
        source_note=(
            "New Mexico Status History was read through the CharityClarity staging sidecar "
            "after the direct API-host lookup could not read usable Status History rows."
        ),
    )
    if not NM_SIDECAR_URL:
        result.raw_status_text = "New Mexico sidecar is not configured"
        result.success = False
        return result
    payload = {
        "organization_name": org.organization_name,
        "ein": org.ein,
        "app_version": APP_VERSION,
        "note": note,
    }
    try:
        request = urllib.request.Request(
            NM_SIDECAR_URL,
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Content-Type": "application/json",
                "Accept": "application/json",
                "User-Agent": f"CharityClarity/{APP_VERSION}",
            },
            method="POST",
        )
        with urllib.request.urlopen(request, timeout=NM_SIDECAR_TIMEOUT_SECONDS + 3) as response:
            response_body = response.read().decode("utf-8", errors="replace")
        data = json.loads(response_body)
    except Exception as exc:
        result.error = f"NM sidecar error: {exc}"
        result.raw_status_text = "New Mexico sidecar lookup could not be completed"
        result.success = False
        return result

    result.status = data.get("status") or getattr(module, "STATUS_UNKNOWN", "Unknown")
    result.raw_status_text = data.get("raw_status_text") or result.status
    result.source_url = data.get("source_url") or result.source_url
    result.source_note = data.get("source_note") or result.source_note
    result.matched_registry_name = data.get("matched_registry_name") or ""
    result.matched_registry_identifier = data.get("matched_registry_identifier") or ""
    result.error = data.get("error") or ""
    result.success = bool(data.get("success", False))
    return result


def search_nm_status_history_fallback(org, module):
    reader_result = search_nm_status_history_reader(org, module)
    if external_status_to_checker_status(getattr(reader_result, "status", "")) != checker.STATUS_UNKNOWN:
        return reader_result

    result = module.SearchResult(
        organization_name=org.organization_name,
        ein=org.ein,
        state="NM",
        status=getattr(module, "STATUS_UNKNOWN", "Unknown"),
        raw_status_text="",
        source_url=getattr(module, "NM_SEARCH_URL", "https://secure.nmdoj.gov/CharitySearch/"),
        source_note=(
            "New Mexico detail page was re-read by the master Status History parser after the primary hosted parser "
            "could not parse rows from the available page text."
        ),
    )
    try:
        with checker.sync_playwright() as p:
            browser = p.chromium.launch(headless=True)
            context = browser.new_context(user_agent=BROWSER_USER_AGENT, locale="en-US")
            page = context.new_page()
            try:
                body = ""
                html = ""
                rows = []
                detail_url = f"https://secure.nmdoj.gov/CharitySearch/CharityDetail.aspx?FEIN={format_ein(org.ein)}"
                for attempt in range(1):
                    page.goto(detail_url, wait_until="domcontentloaded", timeout=30000)
                    safe_wait_for_network_idle(page, timeout=5000)
                    try:
                        page.locator("#MainContent_GridViewStatuses").wait_for(state="attached", timeout=7000)
                    except Exception:
                        try:
                            page.get_by_text(re.compile(r"Status\s+History|Tax\s+Year\s+Registration\s+Details", re.I)).first.wait_for(timeout=3000)
                        except Exception:
                            page.wait_for_timeout(1000)
                    body = page.locator("body").inner_text(timeout=10000)
                    html = page.content()
                    rows = (
                        nm_status_history_rows_from_text_master(body, html)
                        or module.nm_parse_history_rows_from_html(html)
                        or module.nm_parse_history_rows_from_text(body)
                    )
                    if rows or attempt:
                        break
            finally:
                context.close()
                browser.close()
        result.matched_registry_name = module.nm_registry_name_from_html(html)
        if not result.matched_registry_name:
            ein_pattern = re.escape(format_ein(org.ein))
            name_match = re.search(rf"([A-Z][^\n\r]+?)\s*\({ein_pattern}\)", body, re.I)
            if name_match:
                result.matched_registry_name = re.sub(r"\s+", " ", name_match.group(1)).strip()
        if not rows:
            blocked = re.search(r"\b(?:Cloudflare|you have been blocked|unable to access nmdoj\.gov|Ray ID)\b", body or html or "", re.I)
            sidecar_result = search_nm_status_history_sidecar(
                org,
                module,
                note="direct lookup blocked" if blocked else "direct lookup returned no parsed rows",
            )
            if external_status_to_checker_status(getattr(sidecar_result, "status", "")) != checker.STATUS_UNKNOWN:
                return sidecar_result
            result.raw_status_text = "NM detail page reached, but Status History rows were still not parsed"
            if blocked:
                result.raw_status_text = "NM detail page returned an upstream block page before Status History could be read"
            result.success = True
            return result
        latest_submitted = module.nm_latest_submitted(rows)
        fye_text = module.nm_extract_fye_from_html(
            html,
            preferred_year=latest_submitted[0] if latest_submitted else None,
        )
        return module.apply_nm_rows_to_result(result, rows, fye_text=fye_text)
    except Exception as exc:
        result.error = f"NM master Status History fallback error: {exc}"
        return result


def browser_capacity_busy_result(organization_name: str, ein: str, state: str, url: str = ""):
    result = checker.StateResult(
        organization_name or f"EIN {format_ein(ein)}",
        format_ein(ein),
        state,
        "Site Not Reachable",
        url,
    )
    result.raw_status_text = "Browser lookup capacity busy"
    result.source_note = (
        "CharityClarity could not start this public-registry browser lookup before "
        "the capacity guard expired; retrying the state can use another staging lane."
    )
    result.success = False
    return result


def run_state_lookup(organization_name: str, ein: str, state: str, capture_source_snapshot: bool = False, confirm_single_no_match: bool = True) -> dict:
    lookup_started = time.perf_counter()
    artifact_name = organization_name or f"EIN {format_ein(ein)}"
    lookup_name = organization_name
    org = checker.Organization(organization_name=lookup_name, ein=ein)
    if hasattr(org, "evidence_mode"):
        org.evidence_mode = capture_source_snapshot
    body = ""
    proof_url = None
    if state == "WI":
        result = search_wi_snapshot(org)
        if WI_SIDECAR_URL and WI_LOOKUP_SECRET and (
            result is None
            or (
                WI_CONFIRM_SIDECAR_NO_MATCH
                and public_status(result) == "Not Registered"
            )
        ):
            sidecar_result = search_wi_sidecar(org)
            if result is None or public_status(sidecar_result) != "Not Registered":
                result = sidecar_result
        elif result is None:
            result = checker.StateResult(organization_name or f"EIN {format_ein(ein)}", format_ein(ein), state, "Site Not Reachable", WI_SEARCH_URL)
            result.raw_status_text = "Wisconsin snapshot is unavailable and no WI fallback is configured"
            result.source_note = "Wisconsin DFI lookup could not be completed because the local snapshot was unavailable."
            result.success = False
        if result is not None and public_status(result) == "Not Registered":
            direct_result = search_wi(None, org)
            if public_status(direct_result) not in {"Not Registered", "Site Not Reachable"}:
                result = direct_result
        if result is not None and public_status(result) == "Not Registered":
            result = search_wi_with_separator_retries(org, result)
        body = " ".join(part for part in [
            result.raw_status_text or "",
            result.source_note or "",
            result.matched_registry_name or "",
            result.matched_registry_identifier or "",
        ])
        return response_data_for_lookup(result, body, org, organization_name, ein, state, lookup_started)

    if state in {"NH", "KS", "KY", "WA", "NM"}:
        result = None
        lookup_started = time.perf_counter()
        browser_admitted = BROWSER_LOOKUP_SEMAPHORE.acquire(timeout=BROWSER_LOOKUP_ACQUIRE_SECONDS)
        if not browser_admitted:
            result = browser_capacity_busy_result(organization_name, ein, state)
            return response_data_for_lookup(result, result.raw_status_text, org, organization_name, ein, state, lookup_started)
        try:
            if state in {"WA", "NM"}:
                result = search_wa_nm_state(org, state)
            else:
                result = search_snapshot_or_embedded_state(org, state)
            body = " ".join(part for part in [
                result.raw_status_text or "",
                result.source_note or "",
                result.matched_registry_name or "",
                result.matched_registry_identifier or "",
            ]).strip()
        except Exception as exc:
            log_error(f"{state} lookup for {format_ein(ein)} failed before completion: {exc}")
            result = checker.StateResult(organization_name or f"EIN {format_ein(ein)}", format_ein(ein), state, "Site Not Reachable", "")
            result.raw_status_text = "Lookup could not be completed"
            result.source_note = "Public registry lookup could not be completed."
            result.error = str(exc)
            result.success = False
        finally:
            if browser_admitted:
                BROWSER_LOOKUP_SEMAPHORE.release()
        return response_data_for_lookup(result, body, org, organization_name, ein, state, lookup_started)

    if state == "CT":
        lookup_started = time.perf_counter()
        result = search_ct_direct(org)
        if public_status(result) == "Site Not Reachable":
            retried_result = search_ct_direct(org)
            if public_status(retried_result) != "Site Not Reachable":
                retried_result.source_note = " ".join(part for part in [
                    retried_result.source_note or "",
                    "A quick retry replaced an initial Connecticut direct lookup failure.",
                ]).strip()
                result = retried_result
        body = " ".join(part for part in [
            result.raw_status_text or "",
            result.source_note or "",
            result.matched_registry_name or "",
            result.matched_registry_identifier or "",
        ]).strip()
        return response_data_for_lookup(result, body, org, organization_name, ein, state, lookup_started)

    if state == "OR":
        lookup_started = time.perf_counter()
        result = or_snapshot_result_for_ein(org)
        if result is not None:
            body = " ".join(part for part in [
                result.raw_status_text or "",
                result.source_note or "",
                result.matched_registry_name or "",
                result.matched_registry_identifier or "",
            ]).strip()
            return response_data_for_lookup(result, body, org, organization_name, ein, state, lookup_started)

    if state == "FL":
        lookup_started = time.perf_counter()
        reachable, preflight_note = quick_registry_preflight(FL_CHECK_A_CHARITY_URL, FL_PREFLIGHT_TIMEOUT_SECONDS)
        if not reachable:
            print(f"FL preflight did not respond; continuing to bounded browser lookup: {preflight_note}", flush=True)

    result = None
    lookup_started = time.perf_counter()
    browser_admitted = BROWSER_LOOKUP_SEMAPHORE.acquire(timeout=BROWSER_LOOKUP_ACQUIRE_SECONDS)
    if not browser_admitted:
        result = browser_capacity_busy_result(organization_name, ein, state)
        return response_data_for_lookup(result, result.raw_status_text, org, organization_name, ein, state, lookup_started)
    with checker.sync_playwright() as p:
        browser = None
        context = None
        page = None
        try:
            launch_kwargs = {}
            if state == "AR":
                launch_kwargs["args"] = [
                    "--disable-blink-features=AutomationControlled",
                    "--no-sandbox",
                    "--disable-dev-shm-usage",
                ]
            browser = p.chromium.launch(headless=True, **launch_kwargs)
            if state == "AK":
                result = checker.search_ak(browser, org)
                if public_status(result) not in {"Not Registered", "Site Not Reachable"} and not (result.matched_registry_name or "").strip():
                    variant_match = re.search(r"variant\s+'([^']+)'", result.source_note or "", re.I)
                    result.matched_registry_name = (
                        variant_match.group(1).strip()
                        if variant_match
                        else re.sub(r"\s+", " ", organization_name or org.organization_name).strip()
                    )
                body = " ".join(part for part in [
                    result.raw_status_text or "",
                    result.source_note or "",
                    result.matched_registry_name or "",
                    result.matched_registry_identifier or "",
                ]).strip()
            else:
                context_kwargs = {"user_agent": BROWSER_USER_AGENT, "locale": "en-US"}
                if state == "AR":
                    context_kwargs.update({
                        "viewport": {"width": 1366, "height": 768},
                        "timezone_id": "America/New_York",
                    })
                context = browser.new_context(**context_kwargs)
                if state == "AR":
                    context.add_init_script(
                        """
Object.defineProperty(navigator, 'webdriver', {get: () => undefined});
window.chrome = window.chrome || { runtime: {} };
Object.defineProperty(navigator, 'plugins', {get: () => [1, 2, 3, 4, 5]});
Object.defineProperty(navigator, 'languages', {get: () => ['en-US', 'en']});
"""
                    )
                if state not in {"MA", "AR"}:
                    configure_browser_context(context)
                page = context.new_page()
            if state == "AK":
                pass
            elif state == "CA":
                result = checker.search_ca(page, org)
                if public_status(result) != "Not Registered":
                    body = ca_detail_body(page, org)
            elif state == "MA":
                result = checker.search_ma(page, org)
                body = ma_detail_body(page)
                result, body = repair_ma_false_not_registered(page, org, result, body)
                result = validate_ma_positive_record(org, result, body)
            elif state == "MD":
                result = checker.search_md(page, org)
                md_body = registry_page_body(page)
                if public_status(result) != "Not Registered" and not md_detail_page_matched(result, md_body):
                    result.raw_status_text = "No matching EIN result"
                    result.status = checker.STATUS_NOT_REGISTERED
                    result.source_note = "Maryland search did not confirm a public registry record matching the requested EIN."
                    result.success = True
                    body = md_no_results_body(page)
                elif re.search(r"Maryland record found", " ".join([result.raw_status_text or "", result.source_note or ""]), re.I) and not capture_source_snapshot:
                    body = md_body
                elif md_detail_page_matched(result, md_body):
                    result.status = result.raw_status_text if result.raw_status_text and result.raw_status_text != "No matching EIN result" else checker.STATUS_UNKNOWN
                    result.raw_status_text = result.raw_status_text if result.raw_status_text not in {"No matching EIN result", "No record found"} else "Maryland record found"
                    result.source_note = "Maryland detail page was reached from the public registry search."
                    result.success = True
                    body = md_detail_body(page, deep=capture_source_snapshot)
                elif public_status(result) != "Not Registered":
                    body = md_detail_body(page, deep=capture_source_snapshot)
                else:
                    body = md_no_results_body(page)
            elif state == "CO":
                result = search_co_with_name_fallback(page, org)
                body = registry_page_body(page)
                if not (getattr(result, "matched_registry_name", "") or "").strip():
                    co_name = checker.extract_labeled_value_from_text(body, ["Name"])
                    if co_name and useful_registry_name(co_name):
                        result.matched_registry_name = co_name
            elif state == "CT":
                result = search_ct(page, org)
                body = registry_page_body(page)
            elif state == "FL":
                acquired_fl_lane = FL_LOOKUP_SEMAPHORE.acquire(timeout=FL_LOOKUP_ACQUIRE_SECONDS)
                if not acquired_fl_lane:
                    result = checker.StateResult(organization_name or f"EIN {format_ein(ein)}", format_ein(ein), "FL", "Site Not Reachable", "")
                    result.raw_status_text = "Florida lookup lanes were busy"
                    result.source_note = "Florida Check-A-Charity lookup could not start before the lane-acquire timeout."
                    result.success = False
                else:
                    try:
                        result = search_fl(page, org)
                        elapsed_before_confirmation = time.perf_counter() - lookup_started
                        if (
                            confirm_single_no_match
                            and public_status(result) in {"Not Registered", "Site Not Reachable"}
                            and FL_NOT_REGISTERED_CONFIRMATION_DELAY_SECONDS > 0
                            and elapsed_before_confirmation < FL_NOT_REGISTERED_CONFIRMATION_MAX_FIRST_SECONDS
                        ):
                            time.sleep(FL_NOT_REGISTERED_CONFIRMATION_DELAY_SECONDS)
                            confirmed_result = search_fl(page, org)
                            if public_status(confirmed_result) not in {"Not Registered", "Site Not Reachable"}:
                                confirmed_result.source_note = " ".join(part for part in [
                                    confirmed_result.source_note or "",
                                    "A delayed confirmation lookup replaced an initial Florida no-record response.",
                                ]).strip()
                                result = confirmed_result
                    finally:
                        FL_LOOKUP_SEMAPHORE.release()
                body = " ".join(part for part in [
                    result.raw_status_text or "",
                    result.source_note or "",
                    result.matched_registry_name or "",
                    result.matched_registry_identifier or "",
                ]).strip()
            elif state == "NY":
                requested_ein = canonical_ein_digits(org.ein)
                ny_has_ein = bool(requested_ein)
                if ny_has_ein:
                    result = checker.search_ny(page, org)
                else:
                    result = search_with_name_variants(
                        page,
                        org,
                        checker.search_ny,
                        max_variants=12,
                        max_elapsed_seconds=min(max(NAME_SEARCH_VARIANT_MAX_SECONDS, 40.0), 50.0),
                    )
                elapsed_before_ny_confirmation = time.perf_counter() - lookup_started
                clean_ny_ein_no_result = bool(
                    ny_has_ein
                    and public_status(result) == "Not Registered"
                    and re.search(
                        r"\bno\s+results\s+found\b|\bno\s+records?\b|\b0\s+results\b",
                        " ".join([
                            result.raw_status_text or "",
                            result.source_note or "",
                        ]),
                        re.I,
                    )
                )
                if clean_ny_ein_no_result and org.organization_name.strip():
                    name_only_org = checker.Organization(organization_name=org.organization_name, ein="")
                    if hasattr(name_only_org, "original_ein"):
                        name_only_org.original_ein = org.ein
                    name_only_result = search_with_name_variants(
                        page,
                        name_only_org,
                        checker.search_ny,
                        max_variants=10,
                        max_elapsed_seconds=min(max(NAME_SEARCH_VARIANT_MAX_SECONDS, 34.0), 44.0),
                    )
                    name_only_evidence = " ".join(part for part in [
                        getattr(name_only_result, "matched_registry_name", "") or "",
                        getattr(name_only_result, "matched_registry_identifier", "") or "",
                        getattr(name_only_result, "raw_status_text", "") or "",
                        getattr(name_only_result, "source_note", "") or "",
                    ])
                    name_only_digits = re.sub(r"\D", "", name_only_evidence)
                    name_only_exposes_ein = bool(re.search(r"\b(?:EIN|Federal\s+tax\s+ID|Tax\s+ID)\b", name_only_evidence, re.I))
                    name_only_wrong_ein = bool(requested_ein and name_only_exposes_ein and requested_ein not in name_only_digits)
                    if public_status(name_only_result) != "Not Registered" and not name_only_wrong_ein:
                        name_only_result.ein = org.ein
                        name_only_result.source_note = " ".join(part for part in [
                            name_only_result.source_note or "",
                            "New York exact-EIN search returned no results, so CharityClarity retried by generated organization-name variants.",
                        ]).strip()
                        result = name_only_result
                if (
                    public_status(result) == "Not Registered"
                    and not clean_ny_ein_no_result
                    and elapsed_before_ny_confirmation < 48.0
                ):
                    time.sleep(2.0)
                    confirmed_result = search_with_name_variants(
                        page,
                        org,
                        checker.search_ny,
                        max_variants=12,
                        max_elapsed_seconds=min(max(NAME_SEARCH_VARIANT_MAX_SECONDS, 34.0), 44.0),
                    )
                    if public_status(confirmed_result) != "Not Registered":
                        confirmed_result.source_note = " ".join(part for part in [
                            confirmed_result.source_note or "",
                            "Confirmed on a second NY public-registry pass after the first pass returned no record.",
                        ]).strip()
                        result = confirmed_result
                result = repair_ny_not_registered_with_due_date(org, result)
            elif state == "NJ":
                result = search_nj_with_name_fallback(page, org)
                if public_status(result) != "Not Registered":
                    body = nj_detail_body(page, org)
            elif state == "PA":
                result = search_pa_with_name_fallback(page, org)
                elapsed_before_confirmation = time.perf_counter() - lookup_started
                if (
                    confirm_single_no_match
                    and public_status(result) == "Not Registered"
                    and BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS > 0
                    and elapsed_before_confirmation < 35.0
                ):
                    time.sleep(min(BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS, 5.0))
                    confirmed_result = search_pa_with_name_fallback(page, org)
                    if public_status(confirmed_result) != "Not Registered":
                        confirmed_result.source_note = " ".join(part for part in [
                            confirmed_result.source_note or "",
                            "A delayed confirmation lookup replaced an initial Pennsylvania no-record response.",
                        ]).strip()
                        result = confirmed_result
            elif state == "VA":
                result = search_va_direct(org)
                body = " ".join(part for part in [
                    result.raw_status_text or "",
                    result.source_note or "",
                    result.matched_registry_name or "",
                    result.matched_registry_identifier or "",
                ]).strip()
            elif state == "SC":
                result = search_sc_resilient(page, org)
            elif state == "HI":
                result = search_hi_precise(page, org)
                if public_status(result) != "Not Registered":
                    body = hi_detail_body(page)
            elif state == "MI":
                mi_started = time.perf_counter()
                result = search_bundled_extension_state(page, org, "MI")
                mi_elapsed = time.perf_counter() - mi_started
                mi_incomplete_frame = bool(re.search(
                    r"No results frame|Could not find the Michigan results frame|Could not load the Michigan detail page",
                    " ".join([result.raw_status_text or "", result.source_note or "", result.error or ""]),
                    re.I,
                ))
                if (
                    MI_ENABLE_NAME_FALLBACK
                    and public_status(result) == "Not Registered"
                    and mi_elapsed < (LOOKUP_SOFT_MAX_SECONDS - 6)
                ):
                    fallback_result = search_mi_name_fallback(page, org)
                    if public_status(fallback_result) != "Not Registered":
                        result = fallback_result
                if (
                    MI_CONFIRM_NO_RESULTS_FRAME
                    and
                    confirm_single_no_match
                    and public_status(result) in {"Not Registered", "Site Not Reachable"}
                    and BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS > 0
                    and re.search(r"No results frame|Could not find the Michigan results frame|Could not load the Michigan detail page", " ".join([result.raw_status_text or "", result.source_note or "", result.error or ""]), re.I)
                ):
                    time.sleep(min(BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS, 5.0))
                    confirmed_result = search_bundled_extension_state(page, org, "MI")
                    if public_status(confirmed_result) not in {"Not Registered", "Site Not Reachable"}:
                        confirmed_result.source_note = " ".join(part for part in [
                            confirmed_result.source_note or "",
                            "A delayed confirmation lookup replaced an initial Michigan incomplete-results response.",
                        ]).strip()
                        result = confirmed_result
                    elif re.search(r"No results frame|Could not find the Michigan results frame|Could not load the Michigan detail page", " ".join([confirmed_result.raw_status_text or "", confirmed_result.source_note or "", confirmed_result.error or ""]), re.I):
                        result.status = "Site Not Reachable"
                        result.raw_status_text = "Michigan results frame did not load after confirmation"
                        result.source_note = "Michigan's registry search page loaded, but the results/detail frame did not load on two attempts."
                        result.success = False
                body = registry_page_body(page)
            elif state == "MN":
                result = search_mn(page, org)
                body = registry_page_body(page)
            elif state == "OH":
                result = search_oh(page, org)
                body = registry_page_body(page)
            elif state in {"LA", "AR"}:
                if state == "AR":
                    result = search_ar_serialized(page, org)
                else:
                    result = search_with_name_variants(
                        page,
                        org,
                        lambda lookup_page, lookup_org, lookup_state=state: search_bundled_name_state(lookup_page, lookup_org, lookup_state),
                        max_variants=10,
                        max_elapsed_seconds=NAME_SEARCH_VARIANT_MAX_SECONDS,
                        include_ein_aliases=True,
                        include_name_segments=True,
                        include_compact_legal_suffixes=True,
                        include_leading_article_variants=True,
                        prioritize_institution_reductions=True,
                        require_safe_registry_name=True,
                    )
                body = registry_page_body(page)
            elif state == "MS":
                result = search_batch_browser_state(page, org, state)
                body = registry_page_body(page)
            elif state == "OK":
                result = search_with_name_variants(
                    page,
                    org,
                    lambda lookup_page, lookup_org, lookup_state=state: search_batch_browser_state(lookup_page, lookup_org, lookup_state),
                    max_variants=10,
                    max_elapsed_seconds=NAME_SEARCH_VARIANT_MAX_SECONDS,
                    include_ein_aliases=True,
                    include_name_segments=True,
                    include_compact_legal_suffixes=True,
                    include_leading_article_variants=True,
                    prioritize_institution_reductions=False,
                    require_safe_registry_name=True,
                )
                body = registry_page_body(page)
            elif state == "WV":
                reachable, _, preflight_result = preflight_name_search_registry(org, "WV")
                if not reachable:
                    result = preflight_result
                else:
                    result = search_wv_precise(page, org)
                    elapsed_before_wv_confirmation = time.perf_counter() - lookup_started
                    if public_status(result) == "Site Not Reachable" and elapsed_before_wv_confirmation < 45.0:
                        time.sleep(1.0)
                        retried_result = search_wv_precise(page, org)
                        if public_status(retried_result) != "Site Not Reachable":
                            retried_result.source_note = " ".join(part for part in [
                                retried_result.source_note or "",
                                "A quick retry replaced an initial West Virginia transient lookup failure.",
                            ]).strip()
                            result = retried_result
                    if confirm_single_no_match and public_status(result) == "Not Registered" and elapsed_before_wv_confirmation < 40.0:
                        time.sleep(2.0)
                        confirmed_result = search_wv_precise(page, org)
                        if public_status(confirmed_result) not in {"Not Registered", "Site Not Reachable", checker.STATUS_UNKNOWN}:
                            confirmed_result.source_note = " ".join(part for part in [
                                confirmed_result.source_note or "",
                                "A delayed confirmation lookup replaced an initial West Virginia no-record response.",
                            ]).strip()
                            result = confirmed_result
                body = registry_page_body(page)
            elif state == "WI":
                result = search_wi(page, org)
                body = registry_page_body(page)
            elif state == "ME":
                result = search_me_serialized(page, org, confirm_no_match=confirm_single_no_match)
                me_status_source = " ".join([result.raw_status_text or "", result.source_note or ""])
                direct_detail_body = getattr(result, "_cc_detail_body", "")
                if direct_detail_body:
                    body = direct_detail_body
                    enrich_me_result_from_body(result, body)
                elif public_status(result) == "Site Not Reachable":
                    body = ""
                elif re.search(r"Maine uses the Status shown|No matching organization|No record found|no matching", me_status_source, re.I):
                    body = registry_page_body(page)
                else:
                    body = me_detail_body(page, org)
                    enrich_me_result_from_body(result, body)
            elif state == "ND":
                reachable, _, preflight_result = preflight_name_search_registry(org, "ND")
                nd_preferred_variants = connector_light_name_variants(org.organization_name)
                def run_nd_lookup():
                    return search_with_name_variants(
                        page,
                        org,
                        checker.search_nd,
                        max_variants=18,
                        max_elapsed_seconds=NAME_SEARCH_VARIANT_MAX_SECONDS,
                        include_ein_aliases=True,
                        include_name_segments=True,
                        include_compact_legal_suffixes=False,
                        include_leading_article_variants=True,
                        prioritize_institution_reductions=True,
                        preferred_variants=nd_preferred_variants,
                    )

                def run_nd_confirmation_lookup():
                    return search_with_name_variants(
                        page,
                        org,
                        checker.search_nd,
                        max_variants=8,
                        max_elapsed_seconds=22.0,
                        include_ein_aliases=True,
                        include_name_segments=True,
                        include_compact_legal_suffixes=False,
                        include_leading_article_variants=True,
                        prioritize_institution_reductions=True,
                        preferred_variants=nd_preferred_variants,
                    )

                result = run_nd_lookup()
                if (
                    not reachable
                    and preflight_result is not None
                    and public_status(result) in {"Site Not Reachable", "Unknown", ""}
                ):
                    result = preflight_result
                if state_result_has_weak_terminal_name_match(result, org):
                    time.sleep(min(BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS, 5.0))
                    confirmed_result = run_nd_lookup()
                    if state_result_should_replace_weak_match(result, confirmed_result, org):
                        confirmed_result.source_note = " ".join(part for part in [
                            confirmed_result.source_note or "",
                            "A delayed confirmation lookup replaced an initial weaker North Dakota registry-name match.",
                        ]).strip()
                        result = confirmed_result
                elapsed_before_nd_confirmation = time.perf_counter() - lookup_started
                if (
                    public_status(result) == "Not Registered"
                    and BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS > 0
                    and elapsed_before_nd_confirmation < 64.0
                ):
                    time.sleep(min(BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS, 1.0))
                    confirmed_result = run_nd_confirmation_lookup()
                    if public_status(confirmed_result) != "Not Registered":
                        confirmed_result.source_note = " ".join(part for part in [
                            confirmed_result.source_note or "",
                            "A bounded confirmation lookup replaced an initial North Dakota no-record response.",
                        ]).strip()
                        result = confirmed_result
            elif state == "OR":
                result = search_bundled_extension_state(page, org, "OR")
                elapsed_before_confirmation = time.perf_counter() - lookup_started
                clean_no_match_text = " ".join([
                    result.raw_status_text or "",
                    result.source_note or "",
                    registry_page_body(page),
                ])
                has_clean_no_match = bool(re.search(
                    r"no\s+(?:matching\s+)?(?:records?|results?)\s+found|no\s+matching\s+organization|0\s+results",
                    clean_no_match_text,
                    re.I,
                ))
                if (
                    confirm_single_no_match
                    and public_status(result) == "Not Registered"
                    and BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS > 0
                    and elapsed_before_confirmation < 20.0
                    and not (
                        has_clean_no_match
                        and elapsed_before_confirmation >= SINGLE_TRUST_SLOW_CLEAN_NO_MATCH_SECONDS
                    )
                ):
                    time.sleep(min(BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS, 5.0))
                    confirmed_result = search_bundled_extension_state(page, org, "OR")
                    if public_status(confirmed_result) != "Not Registered":
                        confirmed_result.source_note = " ".join(part for part in [
                            confirmed_result.source_note or "",
                            "A delayed confirmation lookup replaced an initial Oregon no-record response.",
                        ]).strip()
                        result = confirmed_result
                body = registry_page_body(page)
            else:
                raise ValueError(f"Unsupported state: {state}")
            if page:
                if not body:
                    body = registry_page_body(page)
                if CAPTURE_EVIDENCE_SCREENSHOTS:
                    checker.save_artifacts(
                        page,
                        ARTIFACTS_DIR,
                        state,
                        artifact_name,
                    )
                    if state in {"CA", "MD", "ME"}:
                        save_focused_viewport_artifact(page, state, artifact_name)
                elif CAPTURE_LIGHTWEIGHT_SOURCE_SNAPSHOT or capture_source_snapshot:
                    save_focused_viewport_artifact(page, state, artifact_name)
        except Exception as exc:
            log_error(f"{state} lookup for {format_ein(ein)} failed before completion: {exc}")
            result = checker.StateResult(organization_name or f"EIN {format_ein(ein)}", format_ein(ein), state, "Site Not Reachable", "")
            result.raw_status_text = "Lookup could not be completed"
            result.source_note = "Public registry lookup could not be completed."
            result.error = str(exc)
            result.success = False
        finally:
            if context:
                context.close()
            if browser:
                browser.close()
            if browser_admitted:
                BROWSER_LOOKUP_SEMAPHORE.release()

    return response_data_for_lookup(result, body, org, organization_name, ein, state, lookup_started)


def fragile_batch_result_needs_confirmation(result: dict) -> bool:
    """Identify results that should not be trusted from a busy multi-state batch alone."""
    state = (result.get("state") or "").upper()
    status = (result.get("status") or "").strip().lower()
    name_registry_states = {
        "AR", "CO", "CT", "FL", "KS", "KY", "LA", "ME", "MI", "MS",
        "ND", "NH", "NM", "NY", "OK", "OR", "SC", "VA", "WA", "WI", "WV",
    }
    if state in BATCH_ISOLATED_STATES and status in {"not registered", "site not reachable", "error", ""}:
        return state in {"AR", "MS", "ND", "NM", "OK", "SC", "VA", "WA", "WV"}
    if weak_terminal_name_match_result(result):
        return True
    if state in BATCH_ISOLATED_STATES and status in {"not registered", "site not reachable", "error", ""}:
        return False
    if state in name_registry_states and status in {"site not reachable", "error", ""}:
        return True
    if status == "not registered" and state not in {"ME", "ND", "OR"} and slow_explicit_no_match_result(result):
        return False
    if state in {"AR", "CO", "FL", "LA", "ME", "MS", "ND", "NM", "NY", "OK", "OR", "SC", "VA", "WA", "WV"}:
        return status == "not registered"
    if state == "MI":
        return status == "not registered"
    if state == "WI":
        return status in {"not registered", "pending", "delinquent", "upcoming filing"}
    return False


def weak_terminal_name_match_result(result: dict) -> bool:
    """Confirm terminal statuses when the selected registry row is not an exact name match."""
    status = (result.get("status") or "").strip().lower()
    if status not in {"closed / withdrawn / canceled", "closed/withdrawn/canceled", "inactive", "revoked", "suspended"}:
        return False
    state = (result.get("state") or "").upper()
    if state not in {"AR", "CT", "FL", "KS", "KY", "LA", "ME", "MS", "ND", "NH", "NM", "OK", "OR", "SC", "VA", "WA", "WI", "WV"}:
        return False
    matched_name = (result.get("matched_registry_name") or "").strip()
    submitted_name = (result.get("organization_name") or "").strip()
    if not matched_name or not submitted_name:
        return False
    return target_name_score(matched_name, organization_match_target_variants(submitted_name, result.get("ein") or "")) < 1000


def state_result_has_weak_terminal_name_match(result, org) -> bool:
    """Detect a terminal state result selected from a weaker-than-exact registry row."""
    status = public_status(result).strip().lower()
    if status not in {"closed / withdrawn / canceled", "closed/withdrawn/canceled", "inactive", "revoked", "suspended"}:
        return False
    matched_name = (getattr(result, "matched_registry_name", "") or "").strip()
    if not matched_name:
        return False
    targets = organization_match_target_variants(getattr(org, "organization_name", ""), getattr(org, "ein", ""))
    return target_name_score(matched_name, targets) < 1000


def state_result_should_replace_weak_match(original, confirmed, org) -> bool:
    """Use a confirmation result when it is a stronger found match than the first result."""
    confirmed_status = public_status(confirmed).strip().lower()
    if confirmed_status in {"site not reachable", "error", "not registered", ""}:
        return False
    original_status = public_status(original).strip()
    targets = organization_match_target_variants(getattr(org, "organization_name", ""), getattr(org, "ein", ""))
    original_score = target_name_score(getattr(original, "matched_registry_name", "") or "", targets)
    confirmed_score = target_name_score(getattr(confirmed, "matched_registry_name", "") or "", targets)
    return confirmed_score > original_score or confirmed_status != original_status.lower()


def confirmed_result_is_better_registry_match(original: dict, confirmed: dict) -> bool:
    """Prefer an isolated confirmation that found a stronger registry-name match."""
    name = (original.get("organization_name") or confirmed.get("organization_name") or "").strip()
    if not name:
        return False
    targets = organization_match_target_variants(name, original.get("ein") or confirmed.get("ein") or "")
    original_score = target_name_score(original.get("matched_registry_name") or "", targets)
    confirmed_score = target_name_score(confirmed.get("matched_registry_name") or "", targets)
    if confirmed_score <= original_score:
        return False
    confirmed_status = (confirmed.get("status") or "").strip().lower()
    return confirmed_status not in {"site not reachable", "error", ""}


def slow_explicit_no_match_result(result: dict) -> bool:
    """Trust a thorough explicit no-record result instead of adding another batch retry."""
    try:
        lookup_seconds = float(result.get("lookup_seconds") or 0)
    except (TypeError, ValueError):
        lookup_seconds = 0.0
    if lookup_seconds < BATCH_TRUST_SLOW_NO_MATCH_SECONDS:
        return False
    no_record_text = " ".join([
        result.get("status") or "",
        result.get("raw_status_text") or "",
        result.get("comments") or "",
        result.get("source_note") or "",
    ])
    return bool(re.search(
        r"no\s+(?:matching\s+)?(?:organization\s+)?(?:registration\s+)?(?:record|result)s?\b|"
        r"no\s+matching\s+(?:ein|organization|wisconsin|charitable)|"
        r"no\s+results?\s+found|0\s+(?:records|results)",
        no_record_text,
        re.I,
    ))


def batch_timeout_lookup_result(organization_name: str, ein: str, state: str) -> dict:
    org = checker.Organization(organization_name=organization_name, ein=ein)
    started = time.perf_counter() - BATCH_STATE_LOOKUP_TIMEOUT_SECONDS
    result = checker.StateResult(
        organization_name or f"EIN {format_ein(ein)}",
        format_ein(ein),
        state,
        "Site Not Reachable",
        "",
    )
    result.raw_status_text = "Batch lookup exceeded the internal state time limit"
    result.source_note = (
        f"The {state} public registry lookup did not finish within the internal batch time limit. "
        "Please rerun this state individually before relying on the batch result."
    )
    result.success = False
    return response_data_for_lookup(result, result.raw_status_text, org, organization_name, ein, state, started)


def run_state_lookup_for_batch(
    organization_name: str,
    ein: str,
    state: str,
    confirm_single_no_match: bool,
) -> dict:
    executor = ThreadPoolExecutor(max_workers=1)
    future = executor.submit(
        run_state_lookup,
        organization_name,
        ein,
        state,
        False,
        confirm_single_no_match,
    )
    try:
        return future.result(timeout=BATCH_STATE_LOOKUP_TIMEOUT_SECONDS)
    except FuturesTimeoutError:
        log_error(
            f"{state} batch lookup for {format_ein(ein)} exceeded "
            f"{BATCH_STATE_LOOKUP_TIMEOUT_SECONDS}s; returning Site Not Reachable."
        )
        return batch_timeout_lookup_result(organization_name, ein, state)
    except Exception as exc:
        log_error(f"{state} batch lookup for {format_ein(ein)} failed: {exc}")
        return batch_timeout_lookup_result(organization_name, ein, state)
    finally:
        executor.shutdown(wait=False, cancel_futures=True)


def run_fanout_state_lookup_for_batch(organization_name: str, ein: str, state: str) -> dict:
    payload = {
        "organization_name": organization_name,
        "ein": ein,
        "states": [state],
        "email": "smoke@compliance-express.com",
        "admin_passcode": ADMIN_PASSCODE,
        "environment": "staging-batch-fanout",
        "origin": "https://staging.compliance-express.com",
        "page_url": "https://staging.compliance-express.com",
        "client_user_agent": f"CharityClarity batch fanout/{APP_VERSION}",
    }

    fanout_urls = BATCH_FANOUT_API_URLS or [BATCH_FANOUT_API_URL]
    lane_start = preferred_lane_index(state, ein, len(fanout_urls))

    def request_once(api_url: str) -> dict | None:
        request = urllib.request.Request(
            api_url,
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Content-Type": "application/json",
                "Origin": "https://staging.compliance-express.com",
                "User-Agent": f"CharityClarity batch fanout/{APP_VERSION}",
            },
            method="POST",
        )
        with urllib.request.urlopen(request, timeout=BATCH_FANOUT_STATE_TIMEOUT_SECONDS) as response:
            data = json.loads(response.read().decode("utf-8"))
        result = (data.get("results") or [None])[0]
        return result if isinstance(result, dict) else None

    try:
        result = request_once(fanout_urls[lane_start])
        if isinstance(result, dict):
            result["batch_fanout"] = "single_state_http"
            fast_unreachable = (
                (result.get("status") or "").strip().lower() == "site not reachable"
                and float(result.get("lookup_seconds") or 0) < 20
            )
            if fast_unreachable and len(fanout_urls) > 1:
                time.sleep(1)
                retry_url = fanout_urls[(lane_start + 1) % len(fanout_urls)]
                retry_result = request_once(retry_url)
                if isinstance(retry_result, dict):
                    retry_result["batch_fanout"] = "single_state_http_retry"
                    if (retry_result.get("status") or "").strip().lower() != "site not reachable":
                        return retry_result
                    result = retry_result
            return result
    except Exception as exc:
        log_error(f"{state} batch fanout lookup for {format_ein(ein)} failed: {exc}")
    return batch_timeout_lookup_result(organization_name, ein, state)


def confirm_fragile_batch_results(results: list[dict]) -> list[dict]:
    if not CONFIRM_FRAGILE_BATCH_RESULTS:
        return results
    jobs = [
        (index, result)
        for index, result in enumerate(results)
        if fragile_batch_result_needs_confirmation(result)
    ]
    if not jobs:
        return results

    def run_confirmation(job: tuple[int, dict]) -> tuple[int, dict | None]:
        index, original = job
        name = (original.get("organization_name") or "").strip()
        ein = original.get("ein") or ""
        state = (original.get("state") or "").upper()
        if not name or not ein or not state:
            return index, None
        try:
            original_status_lower = (original.get("status") or "").strip().lower()
            original_is_no_match = original_status_lower == "not registered"
            original_is_unreachable = original_status_lower == "site not reachable"
            if state in {"AR", "CO", "FL", "ME", "MI", "MS", "ND", "NM", "OK", "SC", "VA", "WA", "WI", "WV"} and (original_is_no_match or original_is_unreachable) and BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS > 0:
                time.sleep(BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS)
            confirmed = run_state_lookup_for_batch(name, ein, state, confirm_single_no_match=(state == "ME"))
            if (
                state in {"AR", "CO", "FL", "ME", "MI", "MS", "NM", "OK", "WA", "WI", "WV"}
                and (original_is_no_match or original_is_unreachable)
                and (confirmed.get("status") or "").strip().lower() in {"not registered", "site not reachable"}
                and BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS > 0
            ):
                time.sleep(min(BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS, 5.0))
                second_confirmed = run_state_lookup_for_batch(name, ein, state, confirm_single_no_match=(state == "ME"))
                if (second_confirmed.get("status") or "").strip().lower() not in {"not registered", "site not reachable"}:
                    confirmed = second_confirmed
            if (
                state == "ME"
                and (original_is_no_match or original_is_unreachable)
                and (confirmed.get("status") or "").strip().lower() in {"not registered", "site not reachable"}
                and BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS > 0
            ):
                time.sleep(min(BATCH_NO_MATCH_CONFIRMATION_DELAY_SECONDS, 5.0))
                third_confirmed = run_state_lookup_for_batch(name, ein, state, confirm_single_no_match=True)
                if (third_confirmed.get("status") or "").strip().lower() not in {"not registered", "site not reachable"}:
                    confirmed = third_confirmed
        except Exception as exc:
            log_error(f"{state} batch confirmation for {format_ein(ein)} failed: {exc}")
            return index, None
        confirmed["batch_confirmation"] = "isolated_retry"
        original_status = (original.get("status") or "").strip()
        confirmed_status = (confirmed.get("status") or "").strip()
        confirmed_is_no_match = confirmed_status.lower() in {"not registered", "site not reachable"}
        if not (original_is_no_match or original_is_unreachable) and confirmed_is_no_match:
            return index, None
        if confirmed_status and confirmed_status.lower() != "site not reachable" and confirmed_status != original_status:
            note = (
                f"Batch reliability note: the initial multi-state result was {original_status or 'blank'}; "
                f"an isolated confirmation lookup returned {confirmed_status}."
            )
            confirmed["comments"] = "\n\n".join(part for part in [confirmed.get("comments") or "", note] if part)
            return index, confirmed
        if confirmed_result_is_better_registry_match(original, confirmed):
            note = (
                "Batch reliability note: an isolated confirmation lookup returned a stronger "
                "registry-name match for the same submitted organization."
            )
            confirmed["comments"] = "\n\n".join(part for part in [confirmed.get("comments") or "", note] if part)
            return index, confirmed
        return index, None

    calm_no_match_states = {"WI"}
    serial_jobs = [
        job for job in jobs
        if (job[1].get("state") or "").upper() in calm_no_match_states
        and (job[1].get("status") or "").strip().lower() in {"not registered", "site not reachable"}
    ]
    parallel_jobs = [job for job in jobs if job not in serial_jobs]

    for index, confirmed in map(run_confirmation, serial_jobs):
        if confirmed is not None:
            results[index] = confirmed

    if parallel_jobs:
        worker_count = min(BATCH_CONFIRMATION_WORKERS, len(parallel_jobs))
        with ThreadPoolExecutor(max_workers=worker_count) as executor:
            for index, confirmed in executor.map(run_confirmation, parallel_jobs):
                if confirmed is not None:
                    results[index] = confirmed
    return results


def run_single_state_lookup_reliably(organization_name: str, ein: str, state: str) -> dict:
    state = (state or "").upper()
    attempts = SINGLE_STATE_SEMANTIC_RETRY_ATTEMPTS if state in SINGLE_STATE_SEMANTIC_RETRY_STATES else 1
    if state == "WA":
        attempts = 1
    result: dict | None = None
    best_reachable_result: dict | None = None
    for attempt in range(1, attempts + 1):
        result = run_state_lookup(organization_name, ein, state)
        result["semantic_attempts"] = attempt
        status = (result.get("status") or "").strip().lower()
        if status != "site not reachable":
            best_reachable_result = dict(result)
        retryable_statuses = {"site not reachable"}
        if state == "WI":
            retryable_statuses.add("not registered")
        retry_text = " ".join([
            result.get("raw_status_text") or "",
            result.get("source_note") or "",
            result.get("comments") or "",
            result.get("error") or "",
        ])
        if state == "WA" and status == "not registered" and re.search(r"No\s+Value\s+Found|zero\s+visible\s+result", retry_text, re.I):
            retryable_statuses.add("not registered")
        if state == "NM" and status == "unknown" and re.search(r"status-history\s+rows\s+were\s+not\s+parsed", retry_text, re.I):
            retryable_statuses.add("unknown")
        if state == "FL" and status == "not registered":
            if re.search(r"bounded\s+lookup\s+window|no\s+usable|could\s+not\s+be\s+completed|could\s+not\s+find\s+business\s+name", retry_text, re.I):
                retryable_statuses.add("not registered")
        if status not in retryable_statuses:
            return result
        if attempt < attempts and SINGLE_STATE_SEMANTIC_RETRY_DELAY_SECONDS > 0:
            time.sleep(SINGLE_STATE_SEMANTIC_RETRY_DELAY_SECONDS)
    if (
        state == "WA"
        and result
        and (result.get("status") or "").strip().lower() == "site not reachable"
        and best_reachable_result
    ):
        best_reachable_result["semantic_attempts"] = result.get("semantic_attempts", best_reachable_result.get("semantic_attempts"))
        best_reachable_result["wa_retry_fallback"] = "kept reachable result after later retry timed out"
        return best_reachable_result
    return result or run_state_lookup(organization_name, ein, state)


def run_state_lookups_parallel(organizations: list[dict], states: list[str]) -> list[dict]:
    lookup_requests = [
        (org["organization_name"], org["ein"], st)
        for org in organizations
        for st in states
    ]
    if len(lookup_requests) <= 1:
        return [run_single_state_lookup_reliably(*lookup_requests[0])]

    if BATCH_FANOUT_SINGLE_STATE_LOOKUPS and BATCH_FANOUT_API_URLS:
        results_by_index: dict[int, dict] = {}

        def run_fanout_request(item: tuple[int, tuple[str, str, str]]) -> tuple[int, dict]:
            index, args = item
            return index, run_fanout_state_lookup_for_batch(*args)

        worker_count = min(BATCH_FANOUT_MAX_WORKERS, len(lookup_requests))
        with ThreadPoolExecutor(max_workers=worker_count) as executor:
            futures = [executor.submit(run_fanout_request, item) for item in enumerate(lookup_requests)]
            for future in as_completed(futures):
                index, result = future.result()
                results_by_index[index] = result
        return [results_by_index[index] for index in range(len(lookup_requests))]

    indexed_requests = list(enumerate(lookup_requests))
    main_requests = [
        (index, args)
        for index, args in indexed_requests
        if (args[2] or "").upper() not in BATCH_ISOLATED_STATES
    ]
    isolated_rank = {state: rank for rank, state in enumerate(BATCH_ISOLATED_STATE_ORDER)}
    isolated_requests = sorted(
        [
            (index, args)
            for index, args in indexed_requests
            if (args[2] or "").upper() in BATCH_ISOLATED_STATES
        ],
        key=lambda item: (item[0] // max(1, len(states)), isolated_rank.get((item[1][2] or "").upper(), 999), item[0]),
    )
    results_by_index: dict[int, dict] = {}

    def run_isolated_request(item: tuple[int, tuple[str, str, str]]) -> tuple[int, dict]:
        index, args = item
        return index, run_state_lookup_for_batch(*args, confirm_single_no_match=True)

    def run_main_request(item: tuple[int, tuple[str, str, str]]) -> tuple[int, dict]:
        index, args = item
        return index, run_state_lookup_for_batch(*args, confirm_single_no_match=False)

    executors: list[ThreadPoolExecutor] = []
    futures = []
    try:
        if isolated_requests:
            isolated_worker_count = min(BATCH_ISOLATED_WORKERS, len(isolated_requests))
            isolated_executor = ThreadPoolExecutor(max_workers=isolated_worker_count)
            executors.append(isolated_executor)
            futures.extend(isolated_executor.submit(run_isolated_request, item) for item in isolated_requests)

        if main_requests:
            worker_count = min(MAX_PARALLEL_LOOKUPS, len(main_requests))
            main_executor = ThreadPoolExecutor(max_workers=worker_count)
            executors.append(main_executor)
            futures.extend(main_executor.submit(run_main_request, item) for item in main_requests)

        for future in as_completed(futures):
            index, result = future.result()
            results_by_index[index] = result
    finally:
        for executor in executors:
            executor.shutdown(wait=True, cancel_futures=False)

    results = [results_by_index[index] for index in range(len(lookup_requests))]

    results = confirm_fragile_batch_results(results)

    submitted_names_by_ein = {
        re.sub(r"\D", "", ein or ""): (name or "").strip()
        for name, ein, _ in lookup_requests
    }
    name_only_states = {"AR", "CT", "FL", "KS", "KY", "LA", "ME", "MS", "ND", "NH", "NM", "OK", "OR", "SC", "VA", "WA", "WI", "WV"}
    trusted_discovery_states = {"AK", "CA", "CO", "HI", "MA", "MD", "MI", "MN", "NJ", "NY", "OH", "PA"}
    discovered_names: dict[str, str] = {}
    for result in results:
        ein_key = re.sub(r"\D", "", result.get("ein") or "")
        state = (result.get("state") or "").upper()
        matched_name = (result.get("matched_registry_name") or "").strip()
        submitted_name = submitted_names_by_ein.get(ein_key, "")
        if (
            ein_key
            and state in trusted_discovery_states
            and matched_name
            and normalized_match_name(matched_name) != normalized_match_name(submitted_name)
        ):
            discovered_names.setdefault(ein_key, matched_name)

    retry_jobs = []
    for index, result in enumerate(results):
        ein_key = re.sub(r"\D", "", result.get("ein") or "")
        original_name = submitted_names_by_ein.get(ein_key, "")
        discovered_name = discovered_names.get(ein_key, "")
        if discovered_name and not (result.get("organization_name") or "").strip():
            result["organization_name"] = discovered_name
        state = (result.get("state") or "").upper()
        if state not in name_only_states or (result.get("status") or "").lower() != "not registered":
            continue
        retry_names = []
        for name in [discovered_name, *known_names_for_ein(result.get("ein") or "")]:
            cleaned = re.sub(r"\s+", " ", (name or "").strip())
            if not cleaned:
                continue
            if normalized_match_name(cleaned) == normalized_match_name(original_name):
                continue
            if cleaned.lower() not in {existing.lower() for existing in retry_names}:
                retry_names.append(cleaned)
        if retry_names:
            retry_jobs.append((index, result.get("ein") or "", state, retry_names))

    if retry_jobs and ENABLE_CROSS_STATE_NAME_RETRY:
        retry_worker_count = min(MAX_PARALLEL_LOOKUPS, len(retry_jobs))

        def run_retry_job(job):
            index, ein, state, retry_names = job
            last_retry = None
            for retry_name in retry_names:
                last_retry = run_state_lookup(retry_name, ein, state)
                if (last_retry.get("status") or "").lower() != "not registered":
                    return index, last_retry
            return index, last_retry

        with ThreadPoolExecutor(max_workers=retry_worker_count) as executor:
            for index, retry_result in executor.map(run_retry_job, retry_jobs):
                if retry_result is not None:
                    results[index] = retry_result
    return results


def proxy_single_state_request_to_overflow(payload: dict) -> tuple[int, dict, dict[str, str]] | None:
    try:
        overflow_hops = int(payload.get("_single_state_overflow_hops") or 0)
    except Exception:
        overflow_hops = 0
    if overflow_hops >= 1:
        return None
    overflow_urls = [url for url in SINGLE_STATE_OVERFLOW_API_URLS if not own_service_url(url)]
    if not overflow_urls:
        return None
    states = payload.get("states") if isinstance(payload.get("states"), list) else [payload.get("state")]
    state = (states[0] if states else "") or ""
    organizations = payload.get("organizations") if isinstance(payload.get("organizations"), list) else []
    ein = payload.get("ein") or ""
    if organizations and isinstance(organizations[0], dict):
        ein = organizations[0].get("ein") or ein
    overflow_url = overflow_urls[preferred_lane_index(state, str(ein), len(overflow_urls))]
    request_payload = dict(payload)
    request_payload["_single_state_overflow_hops"] = overflow_hops + 1
    request_payload["client_user_agent"] = " ".join(part for part in [
        str(payload.get("client_user_agent") or "").strip(),
        f"CharityClarity overflow/{APP_VERSION}",
    ] if part)
    request = urllib.request.Request(
        overflow_url,
        data=json.dumps(request_payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Origin": "https://staging.compliance-express.com",
            "User-Agent": f"CharityClarity overflow/{APP_VERSION}",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=SINGLE_STATE_OVERFLOW_TIMEOUT_SECONDS) as response:
            data = json.loads(response.read().decode("utf-8"))
        if isinstance(data, dict):
            data["single_state_lane"] = "overflow"
            data["single_state_overflow_url"] = overflow_url
            return response.status, data, {}
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        try:
            data = json.loads(body)
        except Exception:
            data = {"error": body or str(exc)}
        headers = {}
        retry_after = exc.headers.get("Retry-After")
        if retry_after:
            headers["Retry-After"] = retry_after
        return exc.code, data, headers
    except Exception as exc:
        log_error(f"Single-state overflow proxy failed: {exc}")
    return None


def normalize_organization_requests(payload: dict, privileged: bool) -> list[dict]:
    organization_name = (payload.get("organization_name") or "").strip()
    raw_organizations = payload.get("organizations")
    organizations = []

    if isinstance(raw_organizations, list):
        for item in raw_organizations:
            if not isinstance(item, dict):
                continue
            ein = format_ein(item.get("ein") or "")
            if len(re.sub(r"\D", "", ein)) != 9:
                continue
            name = resolved_organization_name(ein, item.get("organization_name") or organization_name)
            organizations.append({"organization_name": name, "ein": ein})
    else:
        ein = format_ein(payload.get("ein") or "")
        if len(re.sub(r"\D", "", ein)) == 9:
            name = resolved_organization_name(ein, organization_name)
            organizations.append({"organization_name": name, "ein": ein})

    deduped = []
    seen = set()
    for org in organizations:
        key = re.sub(r"\D", "", org["ein"])
        if key in seen:
            continue
        seen.add(key)
        deduped.append(org)
    return deduped


def payload_missing_required_organization_name(payload: dict) -> bool:
    organization_name = (payload.get("organization_name") or "").strip()
    raw_organizations = payload.get("organizations")
    if isinstance(raw_organizations, list):
        for item in raw_organizations:
            if not isinstance(item, dict):
                continue
            if len(re.sub(r"\D", "", format_ein(item.get("ein") or ""))) != 9:
                continue
            item_name = (item.get("organization_name") or organization_name).strip()
            if not item_name:
                return True
        return False
    if len(re.sub(r"\D", "", format_ein(payload.get("ein") or ""))) == 9:
        return not organization_name
    return False


class RegistrySnapshotHandler(BaseHTTPRequestHandler):
    def _send_json(self, status_code: int, payload: dict, extra_headers: dict[str, str] | None = None) -> None:
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        for name, value in (extra_headers or {}).items():
            self.send_header(name, value)
        self.end_headers()
        self.wfile.write(body)

    def do_OPTIONS(self) -> None:
        self._send_json(200, {"ok": True})

    def _send_evidence_pdf(self, include_body: bool = True) -> bool:
        if not self.path.startswith("/evidence/"):
            return False

        try:
            parsed = urlparse(self.path)
            relative_path = unquote(parsed.path.removeprefix("/evidence/"))
            candidate = (ARTIFACTS_DIR / relative_path).resolve()
            artifacts_root = ARTIFACTS_DIR.resolve()
            if artifacts_root not in candidate.parents or candidate.suffix.lower() != ".pdf":
                self._send_json(404, {"error": "Evidence PDF not found."})
                return True
            try:
                relative_candidate = candidate.relative_to(artifacts_root)
                state = relative_candidate.parts[0].upper()
            except Exception:
                self._send_json(404, {"error": "Evidence PDF not found."})
                return True
            query = parse_qs(parsed.query)
            request_ein = format_ein((query.get("ein") or [""])[0])
            request_org = ((query.get("org") or [""])[0] or candidate.stem.replace("_", " ")).strip()
            metadata_candidate = candidate.with_suffix(".evidence.json")
            if not metadata_candidate.exists() and request_ein:
                prepare_name = request_org or candidate.stem.replace("_", " ")
                run_state_lookup(prepare_name, request_ein, state, capture_source_snapshot=True)
            should_prepare = not candidate.exists()
            if metadata_candidate.exists() and candidate.exists():
                should_prepare = metadata_candidate.stat().st_mtime > candidate.stat().st_mtime
            if ON_DEMAND_EVIDENCE_SCREENSHOT and metadata_candidate.exists() and not evidence_png_path(state, candidate.stem).exists():
                should_prepare = True
            if should_prepare:
                prepare_evidence_pdf(candidate)
            if not candidate.exists():
                self._send_json(404, {"error": "Evidence PDF not found."})
                return True
            body = candidate.read_bytes()
            start = 0
            end = len(body) - 1
            range_header = self.headers.get("Range", "")
            if range_header.startswith("bytes="):
                requested = range_header.removeprefix("bytes=").split("-", 1)
                try:
                    if requested[0]:
                        start = int(requested[0])
                    if len(requested) > 1 and requested[1]:
                        end = int(requested[1])
                except ValueError:
                    start = 0
                    end = len(body) - 1
                start = max(0, min(start, len(body) - 1))
                end = max(start, min(end, len(body) - 1))
                chunk = body[start:end + 1]
                self.send_response(206)
                self.send_header("Content-Range", f"bytes {start}-{end}/{len(body)}")
            else:
                chunk = body
                self.send_response(200)
            self.send_header("Content-Type", "application/pdf")
            self.send_header("Content-Disposition", f'inline; filename="{candidate.name}"')
            self.send_header("Accept-Ranges", "bytes")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(chunk)))
            self.end_headers()
            if include_body:
                self.wfile.write(chunk)
            return True
        except BrokenPipeError:
            return True
        except BaseException as exc:
            log_error(f"Evidence PDF response failed: {exc}")
            self._send_json(500, {"error": "Evidence PDF could not be served."})
            return True

    def _send_lead_log(self, include_body: bool = True) -> bool:
        parsed = urlparse(self.path)
        if parsed.path != "/admin/leads.csv":
            return False

        query = parse_qs(parsed.query)
        email = normalize_email((query.get("email") or [""])[0])
        passcode = (query.get("passcode") or [""])[0]
        if not is_verified_internal_passcode(email, passcode):
            self._send_json(403, {"error": "Verified Compliance Express email required."})
            return True

        if LEAD_LOG_PATH.exists():
            body = LEAD_LOG_PATH.read_bytes()
        else:
            body = b"checked_at,email,domain,organization_name,ein,state,status,comments,evidence_url,source_url\r\n"
        self.send_response(200)
        self.send_header("Content-Type", "text/csv; charset=utf-8")
        self.send_header("Content-Disposition", 'attachment; filename="registry_snapshot_leads.csv"')
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if include_body:
            self.wfile.write(body)
        return True

    def _send_landing_page(self, include_body: bool = True) -> None:
        page_path = Path(__file__).with_name("registry-snapshot-index.html")
        if page_path.exists():
            body = page_path.read_bytes()
            content_type = "text/html; charset=utf-8"
        else:
            body = (
                "<!doctype html><title>CharityClarity API</title>"
                "<h1>CharityClarity API is running.</h1>"
            ).encode("utf-8")
            content_type = "text/html; charset=utf-8"
        self.send_response(200)
        self.send_header("Content-Type", content_type)
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if include_body:
            self.wfile.write(body)

    def _send_healthz(self, include_body: bool = True) -> None:
        body = json.dumps({"ok": True, "app_version": APP_VERSION}).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(body) if include_body else 0))
        self.end_headers()
        if include_body:
            self.wfile.write(body)

    def do_HEAD(self) -> None:
        if self.path in {"/healthz", "/health"}:
            self._send_healthz(include_body=False)
            return

        if self._send_lead_log(include_body=False):
            return

        if self._send_evidence_pdf(include_body=False):
            return

        if self.path in {"/", "/registry-snapshot", "/registry-snapshot/", "/api/check"}:
            self._send_landing_page(include_body=False)
            return

        self._send_json(404, {"error": "Open http://127.0.0.1:8765/ to use the registry snapshot page."})

    def do_GET(self) -> None:
        if self.path in {"/healthz", "/health"}:
            self._send_healthz(include_body=True)
            return

        if self._send_lead_log(include_body=True):
            return

        if self._send_evidence_pdf(include_body=True):
            return

        if self.path in {"/", "/registry-snapshot", "/registry-snapshot/", "/api/check"}:
            self._send_landing_page(include_body=True)
            return

        self._send_json(404, {"error": "Open http://127.0.0.1:8765/ to use the registry snapshot page."})

    def do_POST(self) -> None:
        if self.path != "/api/check":
            self._send_json(404, {"error": "Not found"})
            return

        try:
            length = int(self.headers.get("Content-Length", "0"))
            payload = json.loads(self.rfile.read(length).decode("utf-8"))
            email = normalize_email(payload.get("email") or "")
            device_id = normalize_device_id(payload.get("device_id") or "")
            audit_context = request_audit_context(self, payload)

            requested_states = payload.get("states")
            state = (payload.get("state") or "").strip().upper()
            domain = email_domain(email)
            admin_passcode = (payload.get("admin_passcode") or "").strip()
            staging_error = staging_access_error(email, admin_passcode)
            if staging_error:
                self._send_json(403, {"error": staging_error})
                return
            if is_exempt_domain(domain) and admin_passcode != ADMIN_PASSCODE:
                self._send_json(401, {"error": "Enter the Compliance Express passcode to use internal features."})
                return
            privileged = is_privileged_request(email, domain)
            if payload_missing_required_organization_name(payload):
                self._send_json(400, {"error": "Enter the organization name as registered, if known."})
                return
            organizations = normalize_organization_requests(payload, privileged)

            if isinstance(requested_states, list):
                states = []
                for item in requested_states:
                    state_code = str(item or "").strip().upper()
                    if state_code and state_code not in states:
                        states.append(state_code)
            else:
                states = [state] if state else []
            states = sorted(states)

            if not organizations or not states or any(st not in set(SUPPORTED_STATES) for st in states):
                self._send_json(400, {"error": "Enter a valid 9-digit EIN and select one supported state."})
                return

            if PUBLIC_SINGLE_STATE_ONLY and (len(states) > 1 or len(organizations) > 1):
                self._send_json(400, {"error": "Select one state."})
                return

            state_limit = state_limit_for_request(domain)
            org_limit = org_limit_for_request(email, domain)
            if len(states) > state_limit:
                self._send_json(400, {"error": "Select one state."})
                return
            if len(organizations) > org_limit:
                self._send_json(400, {"error": f"This email can submit up to {org_limit} organization{'s' if org_limit != 1 else ''} at a time."})
                return

            limit_ein = organizations[0]["ein"] if organizations else ""
            is_batch = isinstance(requested_states, list)
            if is_batch and not privileged and domain_is_limited(domain, limit_ein):
                self._send_json(429, {"error": "A complimentary snapshot was already requested for this email domain."})
                return
            if is_batch and not privileged and device_is_limited(device_id, limit_ein):
                self._send_json(429, {"error": "A complimentary snapshot was already requested from this browser."})
                return

            single_state_admitted = False
            is_single_state_request = len(organizations) == 1 and len(states) == 1
            if is_single_state_request:
                single_state_admitted = SINGLE_STATE_REQUEST_SEMAPHORE.acquire(
                    timeout=(
                        SINGLE_STATE_LOCAL_ADMIT_TIMEOUT_SECONDS
                        if SINGLE_STATE_OVERFLOW_API_URL and not PUBLIC_SINGLE_STATE_ONLY
                        else SINGLE_STATE_QUEUE_TIMEOUT_SECONDS
                    )
                )
                if not single_state_admitted and SINGLE_STATE_OVERFLOW_API_URL and not PUBLIC_SINGLE_STATE_ONLY:
                    overflow_response = proxy_single_state_request_to_overflow(payload)
                    if overflow_response is not None:
                        status_code, overflow_payload, overflow_headers = overflow_response
                        self._send_json(status_code, overflow_payload, overflow_headers)
                        return
                    single_state_admitted = SINGLE_STATE_REQUEST_SEMAPHORE.acquire(
                        timeout=SINGLE_STATE_QUEUE_TIMEOUT_SECONDS
                    )
                if not single_state_admitted:
                    self._send_json(
                        429,
                        {
                            "error": "Single-state lookup capacity is busy. Retry this state shortly.",
                            "retry_after_seconds": SINGLE_STATE_RETRY_AFTER_SECONDS,
                            "app_version": APP_VERSION,
                        },
                        {"Retry-After": str(SINGLE_STATE_RETRY_AFTER_SECONDS)},
                    )
                    return

            try:
                append_submission_log(email, organizations, states, audit_context)
                results = run_state_lookups_parallel(organizations, states)
                append_lead_log(email, results, audit_context)
                if is_batch:
                    if not privileged and should_record_domain_check(results):
                        record_domain_check(domain, limit_ein)
                        record_device_check(device_id, limit_ein)
                    self._send_json(200, {"results": results, "checked_at_epoch": int(time.time())})
                else:
                    if (
                        is_single_state_request
                        and results
                        and str(results[0].get("status") or "").strip().lower() == "site not reachable"
                        and not payload.get("_single_state_overflow_hops")
                        and SINGLE_STATE_OVERFLOW_API_URL
                        and not PUBLIC_SINGLE_STATE_ONLY
                    ):
                        overflow_response = proxy_single_state_request_to_overflow(payload)
                        if overflow_response is not None:
                            status_code, overflow_payload, overflow_headers = overflow_response
                            if (
                                status_code == 200
                                and isinstance(overflow_payload, dict)
                                and str(overflow_payload.get("status") or "").strip().lower() != "site not reachable"
                            ):
                                self._send_json(status_code, overflow_payload, overflow_headers)
                                return
                    self._send_json(200, results[0])
            finally:
                if single_state_admitted:
                    SINGLE_STATE_REQUEST_SEMAPHORE.release()
        except BaseException as exc:
            log_error(f"POST /api/check failed: {exc}")
            self._send_json(500, {"error": str(exc)})

    def log_message(self, format: str, *args) -> None:
        return


def main() -> None:
    server = ThreadingHTTPServer((HOST, PORT), RegistrySnapshotHandler)
    print(f"Registry snapshot server running at http://{HOST}:{PORT}")
    server.serve_forever()


if __name__ == "__main__":
    main()


